/* ================= SYMBOL SPECIFICATIONS (pip size / contract size / pip value) ================= */
/**
 * Accurate per-symbol data for lot-size & risk calculations.
 *   type          – "forex" | "commodity" | "synthetic"
 *   pipSize       – smallest meaningful price increment (1 pip)
 *   contractSize  – units per standard lot (forex = 100 000, gold = 100 oz …)
 *   quoteCur      – ISO quote currency (used to determine if pip value is fixed)
 *
 * For forex pairs quoted in USD the pip value per standard lot is a fixed $10.
 * For other quote currencies the pip value is calculated dynamically from
 * the current price: pipValue = contractSize × pipSize / currentPrice.
 *
 * Synthetic indices (Volatility, Boom, Crash, Jump, Step, DEX, DriftSwitch,
 * DailyReset) use the Deriv MT5 server — lot size applies.
 *   contractSize = 1 for most synthetics (PnL = priceMove × lots × contractSize).
 *   lotSize = dollarRisk / (|entry − SL| × contractSize).
 */
const SYMBOL_SPECS = (() => {
  const s = {};

  /* Helper – define a forex / commodity symbol */
  function fx(sym, quoteCur, pipSz, contractSz) {
    s[sym] = { type: "forex", pipSize: pipSz, contractSize: contractSz, quoteCur };
  }

  /* ---------- Forex Majors ---------- */
  fx("frxEURUSD", "USD", 0.0001, 100000);
  fx("frxGBPUSD", "USD", 0.0001, 100000);
  fx("frxAUDUSD", "USD", 0.0001, 100000);
  fx("frxNZDUSD", "USD", 0.0001, 100000);
  fx("frxUSDJPY", "JPY", 0.01,   100000);

  /* ---------- Forex Crosses ---------- */
  fx("frxEURGBP", "GBP", 0.0001, 100000);
  fx("frxEURJPY", "JPY", 0.01,   100000);
  fx("frxEURAUD", "AUD", 0.0001, 100000);
  fx("frxEURNZD", "NZD", 0.0001, 100000);
  fx("frxGBPJPY", "JPY", 0.01,   100000);
  fx("frxGBPAUD", "AUD", 0.0001, 100000);
  fx("frxGBPNZD", "NZD", 0.0001, 100000);
  fx("frxAUDJPY", "JPY", 0.01,   100000);
  fx("frxAUDNZD", "NZD", 0.0001, 100000);
  fx("frxNZDJPY", "JPY", 0.01,   100000);

  /* ---------- Forex Exotics ---------- */
  fx("frxUSDMXN", "MXN", 0.0001, 100000);
  fx("frxUSDSGD", "SGD", 0.0001, 100000);
  fx("frxUSDPLN", "PLN", 0.0001, 100000);

  /* ---------- Commodities ---------- */
  fx("frxXAUUSD", "USD", 0.01,   100);    /* Gold:          100 oz / lot, pip = $0.01 */
  fx("frxXAGUSD", "USD", 0.001,  5000);   /* Silver:       5000 oz / lot, pip = $0.001 */
  fx("frxXPTUSD", "USD", 0.01,   100);    /* Platinum:      100 oz / lot */
  fx("frxXPDUSD", "USD", 0.01,   100);    /* Palladium:     100 oz / lot */

  /* ---------- Synthetics (Deriv MT5 — lot-size applies, contractSize = 1) --- */
  const syntheticSymbols = [
    "1HZ10V","1HZ15V","1HZ25V","1HZ30V","1HZ50V","1HZ75V","1HZ90V",
    "1HZ100V","1HZ150V","1HZ200V","1HZ250V","1HZ300V",
    "R_10","R_25","R_50","R_75","R_100",
    "BOOM300N","BOOM500","BOOM600","BOOM900","BOOM1000",
    "CRASH300N","CRASH500","CRASH600","CRASH900","CRASH1000",
    "JD10","JD25","JD50","JD75","JD100",
    "stpRNG","stpRNG2","stpRNG3","stpRNG4","stpRNG5",
    "RDBULL","RDBEAR"
  ];
  syntheticSymbols.forEach(sym => { s[sym] = { type: "synthetic", contractSize: 1 }; });

  return s;
})();

/* ================= DEPRECATED SYMBOL MIGRATION ================= */
/**
 * Map deprecated/incorrect Deriv API symbol codes to their current equivalents.
 * Used to auto-migrate symbols persisted in localStorage from older versions.
 *
 * NOTE: "STPIDX", "STPIDX100"–"STPIDX500" were invented by this app and are
 * NOT valid Deriv WebSocket symbols. The real Deriv Step Index codes are
 * stpRNG (Step Index 100) through stpRNG5 (Step Index 500).
 */
const DEPRECATED_SYMBOL_MAP = {
  "STPIDX":    "stpRNG",
  "STPIDX100": "stpRNG",
  "STPIDX200": "stpRNG2",
  "STPIDX300": "stpRNG3",
  "STPIDX400": "stpRNG4",
  "STPIDX500": "stpRNG5"
};

/** Return the current symbol code, migrating deprecated names. */
function migrateSymbol(sym) {
  if (!sym || typeof sym !== "string") return sym;
  return DEPRECATED_SYMBOL_MAP[sym] || sym;
}

const STEP_INDEX_LABELS = {
  "stpRNG":  "Step Index 100",
  "stpRNG2": "Step Index 200",
  "stpRNG3": "Step Index 300",
  "stpRNG4": "Step Index 400",
  "stpRNG5": "Step Index 500"
};

/**
 * Resolve the symbol to request from the Deriv feed: migrate any deprecated
 * or invented code to the canonical Deriv code. Returns the canonical symbol.
 */
function resolveFeedSymbol(sym) {
  const resolved = migrateSymbol(sym);
  if (resolved !== sym) {
    addLog(`🔀 Symbol migration: "${sym}" → "${resolved}" (Deriv canonical code)`);
  }
  return resolved;
}

/* ================= CREDENTIAL ENCRYPTION ================= */
/**
 * #13: AES-GCM credential storage using the Web Crypto API.
 *
 * A 256-bit AES-GCM key is derived from a per-install random salt stored in
 * localStorage via PBKDF2. Each encryption uses a fresh 96-bit IV prepended
 * to the ciphertext. This replaces the previous XOR obfuscation, providing
 * genuine confidentiality for credentials at rest in localStorage.
 *
 * Versioning:
 *   "v2:" prefix → AES-GCM ciphertext (base64 of IV || ciphertext)
 *   "v1:" prefix → legacy XOR (decoded synchronously for backward compat)
 *   No prefix    → legacy plain-text
 *
 * Because crypto.subtle operations are async, _encryptCred / _decryptCred are
 * async. Callers that saved with saveSettings() are also made async-aware via
 * the existing await chain. All blocking paths fall back to XOR for safety.
 */
const _CRED_V1 = "v1:";
const _CRED_V2 = "v2:";

/* ── Per-install key material ─────────────────────────────────────────── */
function _getCredSalt() {
  const key = "itguru_cred_salt";
  let salt = localStorage.getItem(key);
  if (!salt) {
    const arr = new Uint8Array(24);
    crypto.getRandomValues(arr);
    salt = Array.from(arr, b => b.toString(36).padStart(2, "0")).join("");
    localStorage.setItem(key, salt);
  }
  return salt;
}

/* Derive an AES-256-GCM CryptoKey from the per-install salt */
async function _getAesKey() {
  const salt = _getCredSalt();
  const enc  = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw", enc.encode(salt), { name: "PBKDF2" }, false, ["deriveKey"]
  );
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt: enc.encode("itguru-cred-v2"), iterations: 100000, hash: "SHA-256" },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

/* ── XOR fallback (synchronous) — used for legacy v1 decoding ─────────── */
function _xorObfuscate(plain) {
  if (!plain) return "";
  const key = _getCredSalt();
  let out = "";
  for (let i = 0; i < plain.length; i++) {
    out += String.fromCharCode(plain.charCodeAt(i) ^ key.charCodeAt(i % key.length));
  }
  return _CRED_V1 + btoa(out);
}
function _xorDeobfuscate(encoded) {
  if (!encoded) return "";
  try {
    const payload = encoded.startsWith(_CRED_V1) ? encoded.slice(_CRED_V1.length) : encoded;
    if (!encoded.startsWith(_CRED_V1)) return encoded;
    const xored = atob(payload);
    const key = _getCredSalt();
    let out = "";
    for (let i = 0; i < xored.length; i++) {
      out += String.fromCharCode(xored.charCodeAt(i) ^ key.charCodeAt(i % key.length));
    }
    return out;
  } catch { return ""; }
}

/* ── AES-GCM encrypt/decrypt ──────────────────────────────────────────── */
async function _encryptCred(plain) {
  if (!plain) return "";
  try {
    const key = await _getAesKey();
    const iv  = crypto.getRandomValues(new Uint8Array(12));
    const enc = new TextEncoder();
    const ct  = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, enc.encode(plain));
    /* Store as base64( IV || ciphertext ) with v2: prefix */
    const combined = new Uint8Array(iv.byteLength + ct.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(ct), iv.byteLength);
    return _CRED_V2 + btoa(String.fromCharCode(...combined));
  } catch (e) {
    /* Fallback to XOR if SubtleCrypto is unavailable (e.g. non-HTTPS) */
    console.warn("AES-GCM encrypt unavailable, using XOR fallback:", e.message);
    return _xorObfuscate(plain);
  }
}

async function _decryptCred(stored) {
  if (!stored) return "";
  /* Legacy plain-text */
  if (!stored.startsWith(_CRED_V1) && !stored.startsWith(_CRED_V2)) return stored;
  /* Legacy XOR */
  if (stored.startsWith(_CRED_V1)) return _xorDeobfuscate(stored);
  /* AES-GCM */
  try {
    const key  = await _getAesKey();
    const raw  = Uint8Array.from(atob(stored.slice(_CRED_V2.length)), c => c.charCodeAt(0));
    const iv   = raw.slice(0, 12);
    const ct   = raw.slice(12);
    const pt   = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ct);
    return new TextDecoder().decode(pt);
  } catch (e) {
    console.warn("AES-GCM decrypt failed:", e.message);
    return "";
  }
}

/* ── Public wrappers (synchronous shim for callers that don't await) ──── */
/* Synchronous obfuscation used only in save paths that cannot be made async.
 * All stored credentials written after this upgrade will be v2 (async path). */
function _obfuscate(plain) { return _xorObfuscate(plain); }
function _deobfuscate(encoded) { return _xorDeobfuscate(encoded); }

/* Multi-panel context tracking (used throughout for context-aware processing) */
let _multiPanelProcessing = null;  /* null = normal mode, otherwise the panel's symbol */
let _multiPanelGran = null;        /* gran (seconds) for the panel currently being processed */
let focusedPanelSymbol = null;     /* which multi-panel drives the main view */
let _historicalProcessing = false; /* true during processAllCandles() to suppress live-only actions */
let _entryModeContext = null;      /* temporary context for aggressive intrabar entries */

/* ================= UI REFS ================= */
const UI = new Proxy({}, {
  get(target, prop) {
    if (typeof prop !== "string") return target[prop];
    if (Object.prototype.hasOwnProperty.call(target, prop)) return target[prop];
    return document.getElementById(prop);
  },
  set(target, prop, value) {
    target[prop] = value;
    return true;
  }
});

function initUI() {
  UI.canvas = document.getElementById("mainChart");
  UI.ctx = UI.canvas ? UI.canvas.getContext("2d") : null;
  UI.exportBtn = document.getElementById("exportSignalsBtn");
  UI.exportPdfBtn = document.getElementById("exportPdfBtn");
}

/* #19: Shared helper — returns the current chart granularity in seconds.
 * When processing a multi-panel, returns that panel's own granularity so
 * lower-TF logic (fast-track confirmation, SL buffer) uses the correct value. */
function getCurrentGranularitySec() {
  if (_multiPanelGran != null) return _multiPanelGran;
  return UI.granSelect ? (parseInt(UI.granSelect.value, 10) || 60) : 60;
}

function clamp01(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

function formatUtcTs(ms) {
  if (!Number.isFinite(ms)) return "--";
  return new Date(ms).toISOString().replace("T", " ").slice(0, 19) + " UTC";
}

function getManualAdaptiveSettings() {
  return {
    minProgressAtr: parseFloat(aggressiveEntryMinAtr),
    minCloseDistanceAtr: parseFloat(entryQualityMinAtr),
    maxEntryDistanceAtr: parseFloat(signalMaxDistanceAtr),
    signalValidityMinutes: parseInt(signalValidityMinutes, 10),
    lossPauseThreshold: parseInt(recentLossPauseCount, 10)
  };
}

function getAdaptiveRuntimeScopeKey() {
  if (typeof ITGuruAuth !== "undefined" && ITGuruAuth && typeof ITGuruAuth.getUser === "function") {
    const user = ITGuruAuth.getUser();
    const rawIdentity = user && (
      user.id ??
      user.user_id ??
      user.userId ??
      user.username ??
      user.email ??
      user.displayName
    );
    const identity = String(rawIdentity || "").trim();
    if (identity) return `user:${identity.toLowerCase()}`;
  }
  return ADAPTIVE_RUNTIME_GUEST_SCOPE;
}

function getAdaptiveRuntimeStorageKey(scopeKey = getAdaptiveRuntimeScopeKey()) {
  return `${ADAPTIVE_STATE_LS_KEY}::${encodeURIComponent(String(scopeKey || ADAPTIVE_RUNTIME_GUEST_SCOPE))}`;
}

function getConfluenceStatsStorageKey(scopeKey = getAdaptiveRuntimeScopeKey()) {
  return `${LS_PREFIX}confStats::${encodeURIComponent(String(scopeKey || ADAPTIVE_RUNTIME_GUEST_SCOPE))}`;
}

function resetAdaptiveRuntimeSyncState() {
  adaptiveRuntimeDbHydrated = false;
  adaptiveIntelligenceBootstrap = null;
  adaptiveIntelligenceBootstrapPromise = null;
  adaptiveIntelligenceBootstrapScopeKey = "";
  adaptiveIntelligenceBootstrapCache.clear();
  adaptiveIntelligenceBootstrapPromises.clear();
  adaptiveIntelligenceBootstrapLatestRequestIds.clear();
}

function initAdaptiveRuntime(force = false) {
  if (typeof AdaptiveEngine !== "function") return;
  const scopeKey = getAdaptiveRuntimeScopeKey();
  if (!force && adaptiveRuntime && adaptiveRuntimeStorageScopeKey === scopeKey) return;
  resetAdaptiveRuntimeSyncState();
  try {
    const raw = localStorage.getItem(getAdaptiveRuntimeStorageKey(scopeKey));
    const parsed = raw ? JSON.parse(raw) : null;
    adaptiveRuntime = new AdaptiveEngine(parsed);
    adaptiveRuntime.setMode(adaptiveMode);
  } catch (err) {
    console.warn("Adaptive runtime init failed:", err.message);
    adaptiveRuntime = new AdaptiveEngine();
    adaptiveRuntime.setMode(adaptiveMode);
  }
  adaptiveRuntimeStorageScopeKey = scopeKey;
  loadConfluenceStats(scopeKey);
  if (typeof renderAdaptiveConfluenceTable === "function") renderAdaptiveConfluenceTable();
}

function ensureAdaptiveRuntimeScope() {
  const scopeKey = getAdaptiveRuntimeScopeKey();
  if (!adaptiveRuntime || adaptiveRuntimeStorageScopeKey !== scopeKey) {
    initAdaptiveRuntime(true);
    return false;
  }
  return true;
}

function persistAdaptiveRuntime() {
  if (!adaptiveRuntime) return;
  ensureAdaptiveRuntimeScope();
  try {
    localStorage.setItem(getAdaptiveRuntimeStorageKey(), JSON.stringify(adaptiveRuntime.exportState()));
  } catch (err) {
    console.warn("Adaptive runtime persist failed:", err.message);
  }
}

/* ── Adaptive Confluence Weights: database persistence ──────────────────
 * The AdaptiveEngine above only mutates in-memory + localStorage state.
 * localStorage is per-browser and is wiped by cache clears/new devices, so
 * without the sync below adaptive learning never truly survives restarts,
 * deployments, or cache clears. These helpers push/pull per
 * symbol+strategy+timeframe+regime profiles to/from the `adaptive_profiles`
 * table via /api/adaptive/profiles so learning is durable and shared across
 * sessions for the logged-in user. */
let adaptiveRuntimeDbHydrated = false;
const _adaptiveAppliedLogCache = new Map();

function syncAdaptiveProfileToDb(ctx, profile) {
  if (!ctx || !profile) return;
  if (!ensureAdaptiveRuntimeScope()) return;
  if (!adaptiveIntelligenceClient) initAdaptiveIntelligenceClient();
  if (!adaptiveIntelligenceClient || !adaptiveIntelligenceClient.isAuthenticated()) return;
  const prevWeights = profile._lastSyncedSettings || {};
  const payload = {
    symbol: ctx.symbol,
    timeframe_sec: ctx.timeframeSec,
    strategy_key: ctx.strategy,
    regime: ctx.regime,
    adaptive_mode: adaptiveMode,
    profile: {
      settings: profile.settings,
      stats: profile.stats,
      history: profile.history,
      lastRecommendation: profile.lastRecommendation
    },
    confidence_score: Number.isFinite(profile.confidence) ? profile.confidence : 0,
    sample_size: Number.isFinite(profile.sampleSize) ? profile.sampleSize : 0
  };
  adaptiveIntelligenceClient.saveAdaptiveProfile(payload)
    .then(() => {
      for (const key of Object.keys(profile.settings || {})) {
        const oldVal = prevWeights[key];
        const newVal = profile.settings[key];
        if (oldVal !== undefined && oldVal !== newVal) {
          console.log(`[Adaptive] Weight updated: strategy=${ctx.strategy} symbol=${ctx.symbol} factor=${key} old=${oldVal} new=${newVal}`);
        }
      }
      profile._lastSyncedSettings = Object.assign({}, profile.settings);
    })
    .catch((err) => console.warn("[Adaptive] Weight sync to database failed:", err.message));
}

async function hydrateAdaptiveRuntimeFromDb() {
  ensureAdaptiveRuntimeScope();
  if (adaptiveRuntimeDbHydrated) return;
  if (!adaptiveRuntime) return;
  const scopeKey = adaptiveRuntimeStorageScopeKey;
  const runtime = adaptiveRuntime;
  if (!adaptiveIntelligenceClient) initAdaptiveIntelligenceClient();
  if (!adaptiveIntelligenceClient || !adaptiveIntelligenceClient.isAuthenticated()) return;
  adaptiveRuntimeDbHydrated = true;
  try {
    const rows = await adaptiveIntelligenceClient.getAdaptiveProfiles();
    if (adaptiveRuntime !== runtime || adaptiveRuntimeStorageScopeKey !== scopeKey || getAdaptiveRuntimeScopeKey() !== scopeKey) {
      return;
    }
    if (!Array.isArray(rows) || !rows.length) {
      console.log("[Adaptive] Loaded weight: none found in database (starting fresh)");
      return;
    }
    let loaded = 0;
    const strategies = new Set();
    const symbols = new Set();
    for (const row of rows) {
      if (!row || !row.symbol || !row.strategy_key || !row.profile || typeof row.profile !== "object") continue;
      const tf = String(parseInt(row.timeframe_sec, 10) || 60);
      const strategy = String(row.strategy_key);
      const regime = String(row.regime || "TRANSITIONING");
      const symbol = String(row.symbol);
      const remoteUpdatedMs = row.updated_at ? Date.parse(row.updated_at) : 0;

      if (!adaptiveRuntime.state.symbolProfiles[symbol]) adaptiveRuntime.state.symbolProfiles[symbol] = {};
      if (!adaptiveRuntime.state.symbolProfiles[symbol][tf]) adaptiveRuntime.state.symbolProfiles[symbol][tf] = {};
      if (!adaptiveRuntime.state.symbolProfiles[symbol][tf][strategy]) adaptiveRuntime.state.symbolProfiles[symbol][tf][strategy] = {};
      const localProfile = adaptiveRuntime.state.symbolProfiles[symbol][tf][strategy][regime];
      const localUpdatedMs = localProfile ? (localProfile.lastUpdatedAt || 0) : 0;
      /* Ignore corrupted records instead of letting a bad row crash hydration. */
      if (!row.profile.settings || typeof row.profile.settings !== "object") continue;
      if (localProfile && localUpdatedMs > remoteUpdatedMs) continue; // this browser already has newer data

      const confidence = Number.isFinite(Number(row.confidence_score)) ? Number(row.confidence_score) : 0;
      const sampleSize = Number.isFinite(Number(row.sample_size)) ? Number(row.sample_size) : 0;
      const merged = {
        key: [symbol, tf, strategy, regime].join("|"),
        context: { symbol, timeframeSec: parseInt(tf, 10) || 60, strategy, regime },
        settings: row.profile.settings,
        stats: row.profile.stats || {},
        history: row.profile.history || {},
        lastRecommendation: row.profile.lastRecommendation || {},
        confidence,
        sampleSize,
        lastUpdatedAt: Number.isFinite(remoteUpdatedMs) && remoteUpdatedMs > 0 ? remoteUpdatedMs : Date.now(),
        _lastSyncedSettings: Object.assign({}, row.profile.settings)
      };
      adaptiveRuntime.state.symbolProfiles[symbol][tf][strategy][regime] = merged;
      loaded++;
      strategies.add(strategy);
      symbols.add(symbol);
      console.log(`[Adaptive] Loaded weight: strategy=${strategy} symbol=${symbol} regime=${regime} confidence=${confidence.toFixed ? confidence.toFixed(2) : confidence}`);
    }
    if (loaded > 0) persistAdaptiveRuntime();
    console.log(`Adaptive Weights Loaded: Strategies: ${strategies.size} | Symbols: ${symbols.size} | Records: ${loaded}`);
  } catch (err) {
    console.warn("[Adaptive] Failed to load weights from database:", err.message);
  }
}

let adaptiveIntelligenceClient = null;
let adaptiveIntelligenceBootstrap = null;
let adaptiveIntelligenceBootstrapPromise = null;
let adaptiveIntelligenceBootstrapScopeKey = "";
const adaptiveIntelligenceBootstrapCache = new Map();
const adaptiveIntelligenceBootstrapPromises = new Map();
const adaptiveIntelligenceBootstrapLatestRequestIds = new Map();
let adaptiveIntelligenceBootstrapRequestSeq = 0;

function initAdaptiveIntelligenceClient() {
  if (typeof AdaptiveIntelligenceClient !== "function") return;
  adaptiveIntelligenceClient = new AdaptiveIntelligenceClient({
    auth: (typeof ITGuruAuth !== "undefined") ? ITGuruAuth : null
  });
}

function getAdaptiveMarketCategory(symbol, timeframeSec) {
  if (typeof AdaptiveIntelligenceUtils !== "undefined" && AdaptiveIntelligenceUtils.getMarketCategory) {
    return AdaptiveIntelligenceUtils.getMarketCategory(symbol, timeframeSec);
  }
  const mt = getMarketType(symbol);
  if (mt === "boom") return "BOOM_INDICES";
  if (mt === "crash") return "CRASH_INDICES";
  if (mt === "jump") return "JUMP_INDICES";
  if (mt === "step") return "STEP_INDICES";
  if (mt === "commodity") return "COMMODITIES";
  if (mt === "forex") {
    return /^frx(EURUSD|GBPUSD|USDJPY|AUDUSD|NZDUSD|USDCHF|USDCAD)/i.test(symbol || "")
      ? "FOREX_MAJORS"
      : "FOREX_CROSSES";
  }
  return /^1HZ/i.test(symbol || "") ? "VOLATILITY_1S" : "VOLATILITY_STANDARD";
}

function getAdaptiveMtfStatus(signal) {
  if (!signal) return "UNKNOWN";
  if (signal.mtfStatus) return String(signal.mtfStatus).toUpperCase();
  if (signal.type === "mtf_top_down" || signal.strategyType === "mtf_top_down") return "CONFIRMED";
  if (signal.htfTrend && signal.dir && signal.htfTrend === signal.dir) return "CONFIRMED";
  return "UNKNOWN";
}

/* Canonical human-readable strategy labels keyed by both the snake_case
 * `signal.type`/`strategyType` values used internally and the camelCase
 * `strategyName` values used by the auto-trade passthrough layer. Used to
 * make sure every strategy — MTF Top-Down included — is labeled consistently
 * (instead of falling back to a raw internal key) whenever a signal is sent
 * to Telegram or persisted to the adaptive_trade_history / activity log. */
const STRATEGY_DISPLAY_LABELS = Object.freeze({
  mtf_top_down: "MTF Top-Down",
  mtfTopDown: "MTF Top-Down",
  breakout_retest: "Breakout Retest",
  liquidity_sweep: "Liquidity Sweep",
  stop_loss_hunt: "Stop Loss Hunt",
  failed_pin_bar: "Failed Pin Bar",
  fib_scalp: "Fib Golden Zone",
  ny_open_range: "NY Open Range",
  session_range: "Session Range",
  grid_scalper_ma: "Grid Scalper MA",
  gridScalperMA: "Grid Scalper MA",
  grid_scalper_v2: "Grid Scalper V2",
  gridScalperV2: "Grid Scalper V2",
  fvg_strat: "Fair Value Gap",
  fvgStrat: "Fair Value Gap",
  power_of_3: "Power of 3",
  po3: "Power of 3",
  po3_4h: "Power of 3 (4H)",
  tiktok: "TikTok Fibonacci",
  candle_interp: "Candle Interpretation",
  candleInterp: "Candle Interpretation",
  orb: "Opening Range Breakout",
  orderblock: "Orderblock",
  breaker_block: "Breaker Block",
  ote_golden_pocket: "OTE Golden Pocket",
  crt_tbs: "CRT TBS",
  live_scalp: "Live Scalp"
});

function resolveStrategyDisplayLabel(typeOrKey, fallback = "Strategy") {
  const key = String(typeOrKey || "").trim();
  if (!key) return fallback;
  return STRATEGY_DISPLAY_LABELS[key] || fallback;
}

const SIGNAL_FACTOR_DEFAULT_WEIGHTS = Object.freeze({
  "Trend Alignment": 5,
  "MTF Confirmation": 6,
  "RSI Confirmation": 5,
  "MACD Confirmation": 5,
  "Structure Strength": 5,
  "ATR Confirmation": 4,
  "Breakout Quality": 5,
  "Retest Quality": 5,
  "Volume Confirmation": 4,
  "Session Timing": 4,
  "Trend Strength": 5,
  "Market Regime": 5,
  "Momentum Score": 5
});

function resolveSignalFactorGroup(label) {
  const raw = String(label || "").trim();
  if (!raw) return "";
  if (typeof AdaptiveIntelligenceUtils !== "undefined" && AdaptiveIntelligenceUtils.FACTOR_ALIASES && AdaptiveIntelligenceUtils.FACTOR_ALIASES[raw]) {
    return AdaptiveIntelligenceUtils.FACTOR_ALIASES[raw];
  }
  return raw;
}

function normalizeSignalTriggerFactors(factors, mtfStatus = null) {
  const normalized = [];
  for (const factor of (Array.isArray(factors) ? factors : [])) {
    const row = factor && typeof factor === "object" ? factor : null;
    const name = String(row ? (row.factor ?? row.name ?? row.label ?? row.group ?? "") : (factor || "")).trim();
    if (!name) continue;
    const group = resolveSignalFactorGroup(row ? (row.group ?? row.groupKey ?? row.factorGroup ?? name) : name) || name;
    const weight = Number.isFinite(row && row.weight) ? Number(row.weight) : (SIGNAL_FACTOR_DEFAULT_WEIGHTS[group] ?? 5);
    const passed = row ? row.passed !== false : true;
    normalized.push({
      factor: name,
      group,
      passed,
      weight,
      score: Number.isFinite(row && row.score) ? Number(row.score) : (passed ? weight : 0),
      detail: row && row.detail != null ? String(row.detail) : null,
      persist: row && row.persist === false ? false : true
    });
  }
  const mtf = String(mtfStatus || "").trim().toUpperCase();
  if ((mtf === "CONFIRMED" || mtf === "PASS" || mtf === "TRUE")
      && !normalized.some((factor) => factor.group === "MTF Confirmation" && factor.persist !== false && factor.passed !== false)) {
    normalized.push({
      factor: "MTF Bias Aligned",
      group: "MTF Confirmation",
      passed: true,
      weight: SIGNAL_FACTOR_DEFAULT_WEIGHTS["MTF Confirmation"] ?? 6,
      score: SIGNAL_FACTOR_DEFAULT_WEIGHTS["MTF Confirmation"] ?? 6,
      detail: null,
      persist: true
    });
  }
  return normalized;
}

function ensureSignalTriggerFactors(signal, fallbackFactors = null) {
  if (!signal || typeof signal !== "object") return [];
  const source = Array.isArray(signal.triggerFactors) && signal.triggerFactors.length
    ? signal.triggerFactors
    : (Array.isArray(signal.factorBreakdown) && signal.factorBreakdown.length
      ? signal.factorBreakdown
      : (fallbackFactors || signal._confFactors || []));
  const normalized = normalizeSignalTriggerFactors(source, getAdaptiveMtfStatus(signal));
  signal.triggerFactors = normalized;
  signal.factorBreakdown = normalized;
  return normalized;
}

function formatSignalFactorLabel(factor) {
  if (!factor || !factor.factor) return "";
  return factor.detail ? `${factor.factor} (${factor.detail})` : factor.factor;
}

function getAdaptiveConfidenceLabel(signal) {
  const decision = signal && signal._adaptiveDecision;
  if (decision && decision.qualification_band) {
    const band = String(decision.qualification_band).toUpperCase();
    if (band === "HIGH_CONFIDENCE") return "High";
    if (band === "NORMAL") return "Normal";
    if (band === "WATCHLIST") return "Watchlist";
    if (band === "REJECT") return "Rejected";
  }
  const score = decision && Number.isFinite(decision.final_confidence_score)
    ? Number(decision.final_confidence_score)
    : (signal && Number.isFinite(signal.confluenceScore) ? Number(signal.confluenceScore) : null);
  if (!Number.isFinite(score)) return null;
  if (score >= 90) return "High";
  if (score >= 75) return "Normal";
  if (score >= 60) return "Watchlist";
  return "Low";
}

function getAdaptiveBootstrapLatestSignal(symbol) {
  const targetSymbol = symbol || getActiveSymbol();
  const candidates = [];
  const addCandidate = (signal) => {
    if (!signal) return;
    const strategy = signal.strategyType || signal.type;
    if (!strategy) return;
    const signalSymbol = signal.symbol || targetSymbol;
    if (targetSymbol && signalSymbol && signalSymbol !== targetSymbol) return;
    const sortKey = Number.isFinite(signal.epoch)
      ? signal.epoch
      : (signal.time ? (Date.parse(signal.time) || 0) : 0);
    candidates.push({ signal, sortKey });
  };

  const panel = targetSymbol && multiPanels && typeof multiPanels.get === "function"
    ? multiPanels.get(targetSymbol)
    : null;
  const strategySignals = typeof getAggregatedStrategyHistory === "function"
    ? getAggregatedStrategyHistory()
    : [];
  const latestStrategySignal = strategySignals.find((signal) => {
    if (!signal) return false;
    const signalSymbol = signal.symbol || targetSymbol;
    return !targetSymbol || !signalSymbol || signalSymbol === targetSymbol;
  });
  addCandidate(latestStrategySignal);
  const latestGridScalperV2Signal = (gridScalperV2History || []).find((signal) => {
    if (!signal) return false;
    const signalSymbol = signal.symbol || targetSymbol;
    return !targetSymbol || !signalSymbol || signalSymbol === targetSymbol;
  });
  addCandidate(latestGridScalperV2Signal);
  addCandidate(panel ? panel.trade : trade);
  addCandidate(panel ? panel.sessionRangeTrade : sessionRangeTrade);
  addCandidate(panel ? panel.nyOpenRangeTrade : nyOpenRangeTrade);

  if (!candidates.length) return null;
  candidates.sort((a, b) => b.sortKey - a.sortKey);
  return candidates[0].signal;
}

function getAdaptiveBootstrapStrategy(overrides = {}) {
  if (overrides.strategy) return overrides.strategy;
  const signal = getAdaptiveBootstrapLatestSignal(overrides.symbol || getActiveSymbol());
  return (signal && (signal.strategyType || signal.type)) || "breakout_retest";
}

function getAdaptiveBootstrapScope(overrides = {}) {
  const symbol = overrides.symbol || getActiveSymbol();
  const timeframeSec = overrides.timeframeSec || getCurrentGranularitySec();
  const strategy = getAdaptiveBootstrapStrategy({ ...overrides, symbol });
  return {
    symbol,
    timeframeSec,
    strategy,
    key: [symbol || "", timeframeSec || "", strategy || ""].join("|")
  };
}

function mergeRemoteConfluenceStats(data) {
  if (!data) return;
  const factorStats = Array.isArray(data.factor_stats) ? data.factor_stats : [];
  for (const key of Object.keys(confluenceFactorStats)) delete confluenceFactorStats[key];
  for (const row of factorStats) {
    if (!row || row.factor_key == null || confluenceFactorStats[row.factor_key]) continue;
    confluenceFactorStats[row.factor_key] = {
      wins: Number(row.wins || 0),
      losses: Number(row.losses || 0),
      currentWeight: Number(row.current_weight || 0),
      confidenceScore: Number(row.confidence_score || 0),
      sampleSize: Number(row.sample_size || 0)
    };
  }
  renderAdaptiveConfluenceTable();
}

async function bootstrapAdaptiveIntelligence(force = false, overrides = {}) {
  ensureAdaptiveRuntimeScope();
  if (!adaptiveIntelligenceClient) initAdaptiveIntelligenceClient();
  if (!adaptiveIntelligenceClient || !adaptiveIntelligenceClient.isAuthenticated()) return null;
  hydrateAdaptiveRuntimeFromDb();
  const scope = getAdaptiveBootstrapScope(overrides);
  if (!force) {
    const pending = adaptiveIntelligenceBootstrapPromises.get(scope.key);
    if (pending) return pending;
    const cached = adaptiveIntelligenceBootstrapCache.get(scope.key);
    if (cached) {
      if (adaptiveIntelligenceBootstrapScopeKey !== scope.key || adaptiveIntelligenceBootstrap !== cached) {
        adaptiveIntelligenceBootstrap = cached;
        adaptiveIntelligenceBootstrapScopeKey = scope.key;
        mergeRemoteConfluenceStats(cached);
      }
      return Promise.resolve(cached);
    }
  }
  const requestId = ++adaptiveIntelligenceBootstrapRequestSeq;
  adaptiveIntelligenceBootstrapLatestRequestIds.set(scope.key, requestId);
  const request = adaptiveIntelligenceClient.bootstrap({
    symbol: scope.symbol,
    timeframe_sec: scope.timeframeSec,
    strategy_key: scope.strategy
  }).then((data) => {
    if (adaptiveIntelligenceBootstrapLatestRequestIds.get(scope.key) !== requestId) {
      return data;
    }
    adaptiveIntelligenceBootstrapCache.set(scope.key, data);
    if (getAdaptiveBootstrapScope(overrides).key === scope.key) {
      adaptiveIntelligenceBootstrap = data;
      adaptiveIntelligenceBootstrapScopeKey = scope.key;
      mergeRemoteConfluenceStats(data);
      syncPersistentAdaptiveTradeHistory();
    }
    return data;
  }).catch((err) => {
    console.warn("Adaptive intelligence bootstrap failed:", err.message);
    return null;
  }).finally(() => {
    if (adaptiveIntelligenceBootstrapPromises.get(scope.key) === request) {
      adaptiveIntelligenceBootstrapPromises.delete(scope.key);
    }
    if (adaptiveIntelligenceBootstrapPromise === request) {
      adaptiveIntelligenceBootstrapPromise = null;
    }
  });
  adaptiveIntelligenceBootstrapPromises.set(scope.key, request);
  adaptiveIntelligenceBootstrapPromise = request;
  return request;
}

function buildAdaptiveQualificationPayload(signal, strategyLabel, overrides = {}) {
  const s = signal || {};
  if (!s.signalId) stampSignalLifecycle(s);
  const strategy = overrides.strategy || s.strategyType || s.type || "breakout_retest";
  const symbol = overrides.symbol || s.symbol || getActiveSymbol();
  const timeframeSec = overrides.timeframeSec || s.timeframeSec || getCurrentGranularitySec();
  const mtfStatus = overrides.mtfStatus || getAdaptiveMtfStatus(s);
  const factorDetails = ensureSignalTriggerFactors(s);
  const factors = (typeof AdaptiveIntelligenceUtils !== "undefined" && AdaptiveIntelligenceUtils.normalizeFactors)
    ? AdaptiveIntelligenceUtils.normalizeFactors(factorDetails, mtfStatus)
    : factorDetails.filter((factor) => factor && factor.persist !== false && factor.passed !== false).map((factor) => factor.group || factor.factor);
  const rawScore = Number.isFinite(s.confluenceScore) ? s.confluenceScore : (Number.isFinite(s.conf) ? s.conf : (Array.isArray(s._confFactors) ? s._confFactors.length : 0));
  return {
    signal_id: s.signalId,
    symbol,
    market_category: getAdaptiveMarketCategory(symbol, timeframeSec),
    strategy_key: strategy,
    strategy_label: strategyLabel || strategy,
    direction: s.dir || overrides.direction || null,
    signal_timestamp: s.time || new Date().toISOString(),
    timeframe_sec: timeframeSec,
    confluence_score: rawScore,
    confluence_max: Number.isFinite(s.conf) ? 7 : 16,
    confluence_factors_present: factors,
    factor_details: factorDetails,
    mtf_status: mtfStatus
  };
}

function decorateAdaptiveTelegramCaption(caption, decision) {
  if (!decision || !caption) return caption;
  const finalScore = Number.isFinite(decision.final_confidence_score) ? decision.final_confidence_score.toFixed(1) : "0.0";
  let label = "🧠 Qualified";
  if (decision.qualification_band === "HIGH_CONFIDENCE") label = "🔥 High Confidence";
  else if (decision.qualification_band === "WATCHLIST") label = "👀 Watchlist";
  else if (decision.qualification_band === "REJECT") label = "⛔ Rejected";
  return `<b>${label}</b> — ${finalScore}%

${caption}`;
}

async function qualifySignalForTelegram(signal, strategyLabel, force = false, overrides = {}) {
  if (force) return { allowed: true, decision: null };
  if (!adaptiveIntelligenceClient) initAdaptiveIntelligenceClient();
  if (!adaptiveIntelligenceClient || !adaptiveIntelligenceClient.isAuthenticated()) return { allowed: true, decision: null };
  try {
    const decision = await adaptiveIntelligenceClient.qualifySignal(buildAdaptiveQualificationPayload(signal, strategyLabel, overrides));
    if (signal && decision) signal._adaptiveDecision = decision;
    if (!decision) return { allowed: true, decision: null };
    const action = String(decision.telegram_action || "").toUpperCase();
    if (action === "REJECT") {
      addLog(`🧠 Adaptive Intelligence rejected Telegram signal (${decision.final_confidence_score}% confidence)`);
      return { allowed: false, decision };
    }
    if (action === "WATCHLIST_ONLY") {
      addLog(`🧠 Adaptive Intelligence kept signal on watchlist only (${decision.final_confidence_score}% confidence)`);
      return { allowed: false, decision };
    }
    if (action === "SEND_HIGH_CONFIDENCE") {
      addLog(`🧠 Adaptive Intelligence approved HIGH confidence Telegram signal (${decision.final_confidence_score}% confidence)`);
    }
    return { allowed: true, decision };
  } catch (err) {
    console.warn("Adaptive signal qualification failed:", err.message);
    addLog(`🧠 Adaptive Intelligence fallback — ${err.message}`);
    return { allowed: true, decision: null };
  }
}

function shouldSyncAdaptiveTradeSignal(signal, now = Date.now()) {
  if (!signal || signal._adaptiveTradeSynced || signal._adaptiveTradeSyncing || signal._adaptiveTradeLocalOnly) return false;
  if (Number.isFinite(signal._adaptiveTradeNextRetryAt) && now < signal._adaptiveTradeNextRetryAt) return false;
  const result = String(signal.result || "").toUpperCase();
  return ["WIN", "LOSS", "EXPIRED", "CANCELLED"].includes(result);
}

function ensureAdaptiveTradeResolutionTimestamp(signal) {
  if (!signal) return;
  const result = String(signal.result || "").toUpperCase();
  if (!["WIN", "LOSS", "EXPIRED", "CANCELLED"].includes(result) || signal.resolvedAtIso) return;
  const resolvedAtMs = Number.isFinite(signal.resolvedAtMs)
    ? signal.resolvedAtMs
    : (Number.isFinite(signal.closedAt) ? signal.closedAt : Date.now());
  signal.resolvedAtMs = resolvedAtMs;
  signal.resolvedAtIso = new Date(resolvedAtMs).toISOString();
}

function findPendingTradeSignal(symbol) {
  const target = symbol || getActiveSymbol();
  return signalHistory.findLast((s) => s && s.result === "PENDING" && (!target || (s.symbol || getActiveSymbol()) === target));
}

const SIGNAL_LIFECYCLE_STATE_LS_KEY = `${LS_PREFIX}signalLifecycleBySymbol`;
const ACTIVE_TRADE_REGISTRY_LS_KEY = `${LS_PREFIX}activeTradeRegistry`;
const SIGNAL_LIFECYCLE_HEALTH_INTERVAL_MS = 60000;
let lifecycleHealthTimer = null;
const signalLifecycleBySymbol = new Map();
const activeTradeRegistry = new Map();

function buildActiveTradeRegistryKey(symbol, signalId) {
  const sym = String(symbol || "").trim();
  const id = String(signalId || "").trim();
  if (!sym || !id) return "";
  return `${sym}|${id}`;
}

function persistSignalLifecycleState() {
  try {
    const lifecycleRows = Array.from(signalLifecycleBySymbol.entries()).map(([symbol, value]) => ({ symbol, value }));
    localStorage.setItem(SIGNAL_LIFECYCLE_STATE_LS_KEY, JSON.stringify(lifecycleRows));
    localStorage.setItem(ACTIVE_TRADE_REGISTRY_LS_KEY, JSON.stringify(Array.from(activeTradeRegistry.entries())));
  } catch { /* storage unavailable */ }
}

function restoreSignalLifecycleState() {
  signalLifecycleBySymbol.clear();
  activeTradeRegistry.clear();
  try {
    const lifecycleRaw = localStorage.getItem(SIGNAL_LIFECYCLE_STATE_LS_KEY);
    if (lifecycleRaw) {
      const rows = JSON.parse(lifecycleRaw);
      if (Array.isArray(rows)) {
        for (const row of rows) {
          if (!row || !row.symbol || !row.value) continue;
          signalLifecycleBySymbol.set(String(row.symbol), row.value);
        }
      }
    }
    const registryRaw = localStorage.getItem(ACTIVE_TRADE_REGISTRY_LS_KEY);
    if (registryRaw) {
      const entries = JSON.parse(registryRaw);
      if (Array.isArray(entries)) {
        for (const entry of entries) {
          if (!Array.isArray(entry) || entry.length < 2) continue;
          const key = String(entry[0] || "");
          const value = entry[1];
          if (!key || !value || !value.symbol || !value.signalId) continue;
          activeTradeRegistry.set(key, value);
        }
      }
    }
  } catch { /* storage unavailable */ }
}

function transitionSignalLifecycleState(symbol, nextState, details = {}) {
  const sym = symbol || getActiveSymbol() || "UNKNOWN";
  const allowedTransitions = {
    IDLE: new Set(["GENERATED", "SENT", "OPEN", "CLOSED", "IDLE"]),
    GENERATED: new Set(["SENT", "OPEN", "CLOSED", "IDLE", "GENERATED"]),
    SENT: new Set(["OPEN", "CLOSED", "IDLE", "SENT"]),
    OPEN: new Set(["CLOSED", "IDLE", "OPEN"]),
    CLOSED: new Set(["IDLE", "GENERATED", "SENT", "OPEN", "CLOSED"])
  };
  const prev = signalLifecycleBySymbol.get(sym) || { state: "IDLE", updatedAt: null };
  const previousState = String(prev.state || "IDLE").toUpperCase();
  const targetState = String(nextState || "IDLE").toUpperCase();
  const allowed = (allowedTransitions[previousState] || allowedTransitions.IDLE).has(targetState);
  signalLifecycleBySymbol.set(sym, {
    state: targetState,
    previousState,
    updatedAt: new Date().toISOString(),
    signalId: details.signalId || prev.signalId || null,
    reason: details.reason || null
  });
  if (!allowed) {
    logSignalEngineDebug("LIFECYCLE_STATE_TRANSITION_FORCED", {
      symbol: sym,
      previousState,
      targetState,
      details
    });
  } else {
    logSignalEngineDebug("LIFECYCLE_STATE_TRANSITION", {
      symbol: sym,
      previousState,
      targetState
    });
  }
  persistSignalLifecycleState();
}

function registerActiveTradeRecord(symbol, signalId, details = {}) {
  const key = buildActiveTradeRegistryKey(symbol, signalId);
  if (!key) return;
  activeTradeRegistry.set(key, {
    symbol: String(symbol),
    signalId: String(signalId),
    strategyType: details.strategyType || null,
    openedAtIso: details.openedAtIso || new Date().toISOString(),
    entry: Number.isFinite(details.entry) ? details.entry : null
  });
  persistSignalLifecycleState();
}

function unregisterActiveTradeRecord(symbol, signalId = null) {
  const sym = String(symbol || "").trim();
  if (!sym) return;
  if (signalId) {
    const key = buildActiveTradeRegistryKey(sym, signalId);
    if (key) activeTradeRegistry.delete(key);
  } else {
    for (const [key, value] of activeTradeRegistry.entries()) {
      if (value && value.symbol === sym) activeTradeRegistry.delete(key);
    }
  }
  persistSignalLifecycleState();
}

function collectLifecycleHealthReport(options = {}) {
  const now = Number.isFinite(options.now) ? options.now : Date.now();
  const staleAfterMs = Number.isFinite(options.staleAfterMs)
    ? options.staleAfterMs
    : Math.max(30 * 60 * 1000, getSignalValidityMs() * 3);
  const histories = [{ entries: signalHistory, symbol: getActiveSymbol() || null }];
  for (const panel of multiPanels.values()) {
    if (panel && Array.isArray(panel.signalHistory)) {
      histories.push({ entries: panel.signalHistory, symbol: panel.symbol || null });
    }
  }
  const bySymbol = new Map();
  for (const history of histories) {
    for (const entry of (history && history.entries ? history.entries : [])) {
      if (!entry || entry.result !== "PENDING") continue;
      const symbol = entry.symbol || history.symbol || getActiveSymbol() || "UNKNOWN";
      const row = bySymbol.get(symbol) || { symbol, pending: 0, stalePending: 0 };
      row.pending += 1;
      const createdAtMs = getSignalCreatedAtMs(entry);
      if (createdAtMs > 0 && (now - createdAtMs) >= staleAfterMs) row.stalePending += 1;
      bySymbol.set(symbol, row);
    }
  }
  const symbols = Array.from(bySymbol.values()).sort((a, b) => a.symbol.localeCompare(b.symbol));
  return {
    generatedAtIso: new Date(now).toISOString(),
    symbols,
    totalPending: symbols.reduce((sum, row) => sum + row.pending, 0),
    totalStalePending: symbols.reduce((sum, row) => sum + row.stalePending, 0),
    activeTradeRegistryCount: activeTradeRegistry.size
  };
}

function runLifecycleHealthCheck() {
  const report = collectLifecycleHealthReport();
  logSignalEngineDebug("LIFECYCLE_HEALTH", report);
  if (report.totalStalePending > 0) {
    addLog(`⚠️ Lifecycle health: ${report.totalStalePending} stale pending signal(s) across ${report.symbols.length} symbol(s)`);
  }
}

function startLifecycleHealthMonitor() {
  if (lifecycleHealthTimer) clearInterval(lifecycleHealthTimer);
  lifecycleHealthTimer = setInterval(runLifecycleHealthCheck, SIGNAL_LIFECYCLE_HEALTH_INTERVAL_MS);
}

function stopLifecycleHealthMonitor() {
  if (!lifecycleHealthTimer) return;
  clearInterval(lifecycleHealthTimer);
  lifecycleHealthTimer = null;
}

const PIPELINE_DELAY_WARN_MS = 5000; /* flag any pipeline stage delay exceeding 5 seconds */

/**
 * Audit helper for the breakout → signal-created → signal-stored → Telegram-sent
 * pipeline. Computes elapsed time since a prior timestamp and always records it via
 * logSignalEngineDebug; additionally raises a visible addLog() warning once the
 * delay exceeds PIPELINE_DELAY_WARN_MS so late signals are easy to spot in the log.
 */
function logPipelineDelay(stage, sinceMs, extra = {}) {
  if (!Number.isFinite(sinceMs) || sinceMs <= 0) return null;
  const delayMs = Date.now() - sinceMs;
  logSignalEngineDebug("PIPELINE_DELAY", Object.assign({ stage, delayMs }, extra));
  if (delayMs > PIPELINE_DELAY_WARN_MS) {
    addLog(`⏱️ PIPELINE DELAY — ${stage} took ${(delayMs / 1000).toFixed(1)}s (exceeds ${(PIPELINE_DELAY_WARN_MS / 1000).toFixed(0)}s threshold)`);
  }
  return delayMs;
}

function logSignalLifecycleEvent(symbol, stage, details = null) {
  const sym = symbol || getActiveSymbol() || "UNKNOWN";
  const stageName = String(stage || "").trim();
  if (stageName === "Signal Generated") transitionSignalLifecycleState(sym, "GENERATED", details || {});
  else if (stageName === "Signal Sent") transitionSignalLifecycleState(sym, "SENT", details || {});
  else if (stageName === "Trade Opened") {
    transitionSignalLifecycleState(sym, "OPEN", details || {});
    if (details && details.signalId) {
      registerActiveTradeRecord(sym, details.signalId, {
        strategyType: details.strategy || null,
        openedAtIso: details.openedAtIso || null,
        entry: details.entry
      });
    }
  } else if (stageName === "Trade Closed") {
    transitionSignalLifecycleState(sym, "CLOSED", details || {});
    unregisterActiveTradeRecord(sym, details && details.signalId ? details.signalId : null);
  } else if (stageName === "State Reset Complete") {
    transitionSignalLifecycleState(sym, "IDLE", details || {});
    unregisterActiveTradeRecord(sym, details && details.signalId ? details.signalId : null);
  }
  addLog(`[${sym}] ${stage}`);
  logSignalEngineDebug(`LIFECYCLE_${String(stage || "").toUpperCase().replace(/[^A-Z0-9]+/g, "_")}`, Object.assign({ symbol: sym }, details || {}));
}

function cleanupPendingSignalsForSymbol(symbol, strategyType = null, options = {}) {
  const sym = symbol || getActiveSymbol();
  if (!sym) return 0;
  const now = Number.isFinite(options.now) ? options.now : Date.now();
  const staleAfterMs = Number.isFinite(options.staleAfterMs)
    ? options.staleAfterMs
    : Math.max(30 * 60 * 1000, getSignalValidityMs() * 3);
  const keepSignalId = options.keepSignalId || null;
  const histories = [signalHistory];
  for (const panel of multiPanels.values()) {
    if (panel && panel.symbol === sym && Array.isArray(panel.signalHistory)) histories.push(panel.signalHistory);
  }
  let cleaned = 0;
  for (const history of histories) {
    if (!Array.isArray(history) || history.length === 0) continue;
    for (const entry of history) {
      if (!entry || entry.result !== "PENDING") continue;
      if ((entry.symbol || sym) !== sym) continue;
      if (strategyType && (entry.strategyType || entry.type || "breakout_retest") !== strategyType) continue;
      if (keepSignalId && entry.signalId && entry.signalId === keepSignalId) continue;
      const tracksCurrentTrade = monitoringTrade && trade && (
        (trade.signalId && entry.signalId && trade.signalId === entry.signalId)
        || ((!trade.signalId || !entry.signalId) && (trade.symbol || sym) === sym)
      );
      if (tracksCurrentTrade) continue;
      const createdAt = getSignalCreatedAtMs(entry);
      const staleByAge = createdAt > 0 && now - createdAt >= staleAfterMs;
      const staleByOrphan = !monitoringTrade && !trade && createdAt > 0 && now - createdAt >= staleAfterMs;
      if (!staleByAge && !staleByOrphan) continue;
      entry.result = "EXPIRED";
      entry.outcomeCandleIdx = Array.isArray(candles) ? candles.length - 1 : null;
      ensureAdaptiveTradeResolutionTimestamp(entry);
      if (entry.signalId) unregisterActiveTradeRecord(sym, entry.signalId);
      transitionSignalLifecycleState(sym, "CLOSED", {
        signalId: entry.signalId || null,
        reason: "stale_pending_cleanup"
      });
      cleaned++;
    }
  }
  if (cleaned > 0) {
    addLog(`🧹 [${sym}] Cleared ${cleaned} stale pending signal${cleaned === 1 ? "" : "s"}`);
    persistSignalHistory();
  }
  return cleaned;
}

function buildAdaptiveTradePayloadFromSignal(signal, overrides = {}) {
  if (!signal || typeof AdaptiveIntelligenceUtils === "undefined" || !AdaptiveIntelligenceUtils.buildTradePayload) return null;
  const symbol = overrides.symbol || signal.symbol || getActiveSymbol();
  const timeframeSec = overrides.timeframeSec || signal.timeframeSec || getCurrentGranularitySec();
  return AdaptiveIntelligenceUtils.buildTradePayload(signal, signal._adaptiveDecision || null, {
    symbol,
    strategy: overrides.strategy || signal.strategyType || signal.type || "breakout_retest",
    strategyLabel: overrides.strategyLabel || resolveStrategyDisplayLabel(signal.strategyType || signal.type, signal.strategyType || signal.type || "breakout_retest"),
    timeframeSec,
    marketCategory: overrides.marketCategory || getAdaptiveMarketCategory(symbol, timeframeSec),
    mtfStatus: overrides.mtfStatus || getAdaptiveMtfStatus(signal)
  });
}

function syncPersistentAdaptiveTradeHistory() {
  if (!adaptiveIntelligenceClient || !adaptiveIntelligenceClient.isAuthenticated()) return;
  const currentScopeKey = getAdaptiveRuntimeScopeKey();
  const buckets = [
    signalHistory, mtfTopDownHistory, liquiditySweepHistory, stopLossHuntHistory,
    failedPinBarHistory, fibScalpHistory, po3History, nyOpenRangeHistory,
    sessionRangeHistory, gridScalperMAHistory, gridScalperV2History, fvgStratHistory, liveScalpHistory,
    candleInterpHistory, orderblockHistory, tiktokHistory, po3_4hHistory,
    breakerBlockHistory, oteGoldenPocketHistory, orbHistory, crtTbsHistory
  ].filter(Array.isArray);
  const now = Date.now();

  for (const bucket of buckets) {
    for (const signal of bucket) {
      if (!signal) continue;
      const signalScopeKey = String(signal.adaptiveScopeKey || "").trim();
      if (!signalScopeKey || signalScopeKey !== currentScopeKey) continue;
      if (backtestMode) {
        signal._adaptiveTradeLocalOnly = true;
        continue;
      }
      if (!shouldSyncAdaptiveTradeSignal(signal, now)) continue;
      const result = String(signal.result || "").toUpperCase();
      if (!signal.signalId) signal.signalId = generateSignalId(signal.strategyType || signal.type || "sig");
      ensureAdaptiveTradeResolutionTimestamp(signal);
      signal._adaptiveTradeSyncing = true;
      const strategyKey = signal.strategyType || signal.type || "breakout_retest";
      const strategyLabel = resolveStrategyDisplayLabel(strategyKey, strategyKey);
      Promise.resolve(
        signal._adaptiveDecision
          ? (() => {
              const action = String(signal._adaptiveDecision.telegram_action || "").toUpperCase();
              return {
                allowed: action !== "REJECT" && action !== "WATCHLIST_ONLY",
                decision: signal._adaptiveDecision
              };
            })()
          : qualifySignalForTelegram(signal, strategyLabel, false, {
              strategy: strategyKey,
              symbol: signal.symbol || getActiveSymbol(),
              timeframeSec: signal.timeframeSec || getCurrentGranularitySec(),
              mtfStatus: getAdaptiveMtfStatus(signal)
            })
      )
        .catch((err) => {
          console.warn("Adaptive signal qualification before trade sync failed:", err.message);
          return { allowed: false, decision: null };
        })
        .then((qualificationState) => {
          if (!qualificationState || qualificationState.allowed !== true) return false;
          if (qualificationState.decision) signal._adaptiveDecision = qualificationState.decision;
          const cloned = Object.assign({}, signal, { result: result === "EXPIRED" ? "CANCELLED" : result });
          const payload = buildAdaptiveTradePayloadFromSignal(cloned);
          if (!payload) return false;
          return adaptiveIntelligenceClient.recordTrade(payload);
        })
        .then((recordResult) => {
          if (!recordResult) return;
          signal._adaptiveTradeSynced = true;
          signal._adaptiveTradeFailures = 0;
          signal._adaptiveTradeNextRetryAt = 0;
          /* recordResult.learning_applied is only present on a fresh (non-duplicate) trade;
             a duplicate response means this exact trade was already recorded previously, so
             its trust status is whatever was determined the first time and is left untouched. */
          if (!recordResult.duplicate && typeof recordResult.learning_applied === "boolean") {
            signal._adaptiveTradeTrusted = recordResult.learning_applied;
            const scopeLabel = `${signal.strategyType || signal.type || "strategy"} ${signal.symbol || getActiveSymbol()}`;
            console.log(
              recordResult.learning_applied
                ? `[Adaptive] Trade trusted: ${scopeLabel} result=${result} — counted toward DB learning aggregates.`
                : `[Adaptive] Trade NOT trusted: ${scopeLabel} result=${result} — stored as history only, excluded from adaptive learning (no matching qualified signal decision found).`
            );
          }
        })
        .catch((err) => {
          console.warn("Adaptive trade sync failed:", err.message);
          const failures = (Number(signal._adaptiveTradeFailures) || 0) + 1;
          signal._adaptiveTradeFailures = failures;
          signal._adaptiveTradeNextRetryAt = Date.now() + Math.min(300000, 5000 * (2 ** Math.min(failures - 1, 5)));
        })
        .finally(() => {
          signal._adaptiveTradeSyncing = false;
        });
    }
  }
}

function buildAdaptiveContext(overrides = {}) {
  return {
    symbol: overrides.symbol || getActiveSymbol(),
    timeframeSec: overrides.timeframeSec || getCurrentGranularitySec(),
    strategy: overrides.strategy || "breakout_retest",
    regime: overrides.regime || getCurrentRegimeTag()
  };
}

function getAdaptiveResolution(overrides = {}) {
  if (!adaptiveRuntime) return null;
  ensureAdaptiveRuntimeScope();
  if (!adaptiveRuntime) return null;
  return adaptiveRuntime.resolve(buildAdaptiveContext(overrides), getManualAdaptiveSettings());
}

function getAdaptiveAppliedNumber(key, fallback, overrides = {}) {
  const r = getAdaptiveResolution(overrides);
  const n = r && r.applied ? parseFloat(r.applied[key]) : NaN;
  const result = Number.isFinite(n) ? n : fallback;
  if (r && r.mode !== "OFF") {
    const cacheKey = `${r.profileKey}|${key}`;
    if (_adaptiveAppliedLogCache.get(cacheKey) !== result) {
      _adaptiveAppliedLogCache.set(cacheKey, result);
      const base = Number(fallback) || 0;
      const multiplier = base !== 0 ? result / base : 1;
      console.log(`[Adaptive] Applied: strategy=${overrides.strategy || "breakout_retest"} symbol=${overrides.symbol || getActiveSymbol()} factor=${key} base=${base} multiplier=${multiplier.toFixed(3)} final=${result}`);
    }
  }
  return result;
}

function processAdaptiveResolvedSignals() {
  if (!adaptiveRuntime) return;
  if (!ensureAdaptiveRuntimeScope()) return;
  if (!adaptiveRuntime) return;
  const currentScopeKey = getAdaptiveRuntimeScopeKey();
  const buckets = [
    signalHistory, mtfTopDownHistory, liquiditySweepHistory, stopLossHuntHistory,
    failedPinBarHistory, fibScalpHistory, po3History, nyOpenRangeHistory,
    sessionRangeHistory, gridScalperMAHistory, fvgStratHistory, liveScalpHistory,
    candleInterpHistory, orderblockHistory, tiktokHistory, po3_4hHistory,
    breakerBlockHistory, oteGoldenPocketHistory, crtTbsHistory
  ].filter(Array.isArray);

  let touched = false;
  for (const arr of buckets) {
    for (const s of arr) {
      if (!s || (s.result !== "WIN" && s.result !== "LOSS")) continue;
      const signalScopeKey = String(s.adaptiveScopeKey || "").trim();
      if (!signalScopeKey || signalScopeKey !== currentScopeKey) continue;
      if (!s.signalId) stampSignalLifecycle(s);
      const id = s.signalId
        ? `sid:${s.signalId}`
        : [s.time || "", s.symbol || "--", s.strategyType || s.type || "breakout_retest", s.entry || "", s.result].join("|");
      if (adaptiveRuntime.wasProcessed(id) || s._adaptiveProcessed) continue;

      const ctx = buildAdaptiveContext({
        symbol: s.symbol || getActiveSymbol(),
        timeframeSec: s.timeframeSec || getCurrentGranularitySec(),
        strategy: s.strategyType || s.type || "breakout_retest",
        regime: s.adaptiveRegime || s.volatilityRegime || getCurrentRegimeTag()
      });
      s.adaptiveRegime = ctx.regime;

      const isBreakeven = isBreakevenSignal(s);
      const entry = Number.isFinite(s.entry) ? s.entry : null;
      const sl = Number.isFinite(s.sl) ? s.sl : null;
      const exit = Number.isFinite(s.exitPrice)
        ? s.exitPrice
        : (s.result === "WIN" ? (Number.isFinite(s.tp) ? s.tp : null) : (Number.isFinite(s.sl) ? s.sl : null));
      const risk = (entry != null && sl != null) ? Math.abs(entry - sl) : null;
      let rr = Number.isFinite(s.rMultiple) ? s.rMultiple : null;
      if (!Number.isFinite(rr) && risk != null && risk > 0 && exit != null) {
        const pnl = s.dir === "BEAR" ? (entry - exit) : (exit - entry);
        rr = pnl / risk;
      }
      if (!Number.isFinite(rr)) rr = isBreakeven ? 0 : (s.result === "WIN" ? (Number.isFinite(s.rr) ? s.rr : 1) : -1);
      const atrRef = Number.isFinite(s.atrAtSignal) ? s.atrAtSignal : (Number.isFinite(s.atrAtEntry) ? s.atrAtEntry : null);
      const atrExpansion = (Number.isFinite(atrRef) && atrRef > 0 && Number.isFinite(s.exitPrice) && Number.isFinite(s.entry))
        ? Math.abs(s.exitPrice - s.entry) / atrRef
        : null;
      const progressGate = Math.max(0.0001, getAdaptiveAppliedNumber("minProgressAtr", aggressiveEntryMinAtr, ctx));
      const entryEfficiency = Number.isFinite(s.entryProgressAtr) ? clamp01(s.entryProgressAtr / progressGate) : null;
      const confirmationQuality = Number.isFinite(s.confluenceScore) ? clamp01(s.confluenceScore / 16) : null;
      const earlyStopLoss = s.result === "LOSS" && Number.isFinite(s.entryIdx) && Number.isFinite(s.outcomeCandleIdx)
        ? ((s.outcomeCandleIdx - s.entryIdx) <= 3)
        : false;

      adaptiveRuntime.recordOutcome(ctx, {
        result: s.result,
        rMultiple: rr,
        atrExpansionPostSignal: atrExpansion,
        entryEfficiency,
        confirmationQuality,
        retestSuccess: s.result === "WIN",
        earlyStopLoss
      });
      adaptiveRuntime.markProcessed(id);
      s._adaptiveProcessed = true;
      touched = true;
      /* Commit the updated weight/profile to the database immediately after
         this trade outcome is processed, isolated by symbol+strategy+timeframe+regime. */
      syncAdaptiveProfileToDb(ctx, adaptiveRuntime.ensureProfile(ctx));
    }
  }

  if (touched) persistAdaptiveRuntime();
}

function renderAdaptiveSettingsUI() {
  if (!UI.adaptiveSettingsTableBody) return;
  const manual = getManualAdaptiveSettings();
  const dash = adaptiveRuntime
    ? adaptiveRuntime.getDashboard(buildAdaptiveContext(), manual)
    : { mode: adaptiveMode, manual, optimized: manual, recommendations: {}, metrics: { sampleSize: 0, confidence: 0, winRate: 0, cancelRate: 0 }, history: {} };

  if (UI.adaptiveModeSelect) UI.adaptiveModeSelect.value = adaptiveMode;

  const rows = [
    ["minProgressAtr", "Min Progress ATR", 2],
    ["minCloseDistanceAtr", "Min Close Distance ATR", 2],
    ["maxEntryDistanceAtr", "Max Entry Distance ATR", 2],
    ["signalValidityMinutes", "Signal Validity (min)", 0],
    ["lossPauseThreshold", "Loss Pause Threshold", 0]
  ];

  UI.adaptiveSettingsTableBody.innerHTML = rows.map(([key, label, dp]) => {
    const optimized = dash.optimized && Number.isFinite(dash.optimized[key]) ? dash.optimized[key] : manual[key];
    const manualVal = Number.isFinite(manual[key]) ? manual[key] : 0;
    const history = dash.history && dash.history[key] && dash.history[key].length ? dash.history[key][dash.history[key].length - 1].from : manualVal;
    const reason = dash.recommendations && dash.recommendations[key] ? dash.recommendations[key] : "—";
    const fmt = (v) => Number(v).toFixed(dp);
    return `<tr><td>${label}</td><td>${fmt(optimized)}</td><td class="adaptive-row-reason">${reason}</td><td>${fmt(history)}</td><td>${fmt(manualVal)}</td></tr>`;
  }).join("");

  if (UI.adaptiveSummaryBadges) {
    const m = dash.metrics || {};
    const wr = Number.isFinite(m.winRate) ? (m.winRate * 100).toFixed(1) : "0.0";
    const cr = Number.isFinite(m.cancelRate) ? (m.cancelRate * 100).toFixed(1) : "0.0";
    const conf = Number.isFinite(m.confidence) ? m.confidence.toFixed(0) : "0";
    const ss = Number.isFinite(m.sampleSize) ? m.sampleSize : 0;
    UI.adaptiveSummaryBadges.innerHTML = `
      <span class="status-badge enabled">Mode: ${adaptiveMode}</span>
      <span class="status-badge bull">Win Rate: ${wr}%</span>
      <span class="status-badge warning">Cancel Rate: ${cr}%</span>
      <span class="status-badge ${conf >= 60 ? "bull" : "warning"}">Confidence: ${conf}%</span>
      <span class="status-badge">Samples: ${ss}</span>
    `;
  }

  if (UI.adaptiveReasonText) {
    const reasons = Object.values(dash.recommendations || {}).filter(Boolean);
    UI.adaptiveReasonText.textContent = reasons.length
      ? reasons.slice(0, 2).join(" • ")
      : "Adaptive engine is monitoring performance and waiting for enough samples to optimize.";
  }
}

function recordAdaptiveCancellation(reason, overrides = {}) {
  if (!adaptiveRuntime || adaptiveMode === "OFF") return;
  const txt = String(reason || "");
  const ctx = buildAdaptiveContext(overrides);
  adaptiveRuntime.recordCancellation(ctx, {
    missedOpportunity: /confluence|quality|rejected|late/i.test(txt),
    wasWinningCandidate: /winning|profit/i.test(txt)
  });
  persistAdaptiveRuntime();
  syncAdaptiveProfileToDb(ctx, adaptiveRuntime.ensureProfile(ctx));
}

function getSignalValidityMs() {
  const fallback = Math.max(1, parseInt(signalValidityMinutes, 10) || SIGNAL_DEFAULT_VALIDITY_MIN);
  const mins = Math.max(1, Math.round(getAdaptiveAppliedNumber("signalValidityMinutes", fallback)));
  return mins * 60 * 1000;
}

function getSignalDistanceLimitAtr() {
  const n = parseFloat(signalMaxDistanceAtr);
  const fallback = Number.isFinite(n) && n > 0 ? n : SIGNAL_DEFAULT_MAX_DISTANCE_ATR;
  return getAdaptiveAppliedNumber("maxEntryDistanceAtr", fallback);
}

function getAtrReference() {
  if (Number.isFinite(atrValue) && atrValue > 0) return atrValue;
  const valid = (atrValues || []).filter(v => Number.isFinite(v) && v > 0);
  return valid.length ? valid[valid.length - 1] : 0;
}

function getVolatilityAdjustedStopBufferAtr(symbol, granSec, breakoutRef) {
  let extra = EXECUTION_BUFFER_ATR_DEFAULT;
  const mtype = getMarketType(symbol);
  if (granSec <= LOWER_TF_1M_SEC) extra += 0.10;
  else if (granSec <= LOWER_TF_5M_SEC) extra += 0.05;
  if (mtype === "boom" || mtype === "crash" || mtype === "dex") extra += 0.20;
  else if (mtype === "jump") extra += 0.08;
  else if (mtype === "step") extra += 0.04;
  if (breakoutRef && breakoutRef.volumeSpike) extra += 0.05;
  return extra;
}

function getMaxEntryDriftAtr(symbol, granSec, isMtf = false) {
  let maxDrift = isMtf ? MTF_ENTRY_DRIFT_ATR_DEFAULT : ENTRY_DRIFT_ATR_DEFAULT;
  const mtype = getMarketType(symbol);
  if (granSec <= LOWER_TF_1M_SEC) maxDrift -= 0.15;
  if (mtype === "boom" || mtype === "crash") maxDrift -= 0.10;
  if (mtype === "jump") maxDrift += 0.10;
  return Math.max(0.45, maxDrift);
}

function getCurrentEntryMode() {
  return _entryModeContext === "aggressive_intrabar" ? "aggressive_intrabar" : "confirmed_close";
}

function normalizeSignalDir(dir) {
  if (dir === "BUY") return "BULL";
  if (dir === "SELL") return "BEAR";
  return dir;
}

function getEntryProgressMinAtr(symbol, granSec, isAggressive = false) {
  const adaptiveKey = isAggressive ? "minProgressAtr" : "minCloseDistanceAtr";
  const adaptiveFallback = parseFloat(isAggressive ? aggressiveEntryMinAtr : entryQualityMinAtr);
  let minAtr = getAdaptiveAppliedNumber(adaptiveKey, adaptiveFallback, { symbol, timeframeSec: granSec, strategy: "breakout_retest" });
  if (!Number.isFinite(minAtr) || minAtr <= 0) {
    minAtr = isAggressive ? AGGRESSIVE_ENTRY_PROGRESS_ATR_DEFAULT : ENTRY_QUALITY_PROGRESS_ATR_DEFAULT;
  }
  const mtype = getMarketType(symbol);
  if (mtype === "boom" || mtype === "crash" || mtype === "dex") minAtr += 0.06;
  else if (mtype === "jump") minAtr += 0.03;
  else if (mtype === "step") minAtr -= 0.04;
  if (granSec <= LOWER_TF_1M_SEC && isAggressive) minAtr -= 0.02;
  return Math.max(isAggressive ? 0.08 : 0.10, minAtr);
}

function evaluateEntryTimingQuality(dir, candle, level, atrRef, options = {}) {
  const entryMode = options.entryMode || getCurrentEntryMode();
  const isAggressive = entryMode === "aggressive_intrabar";
  if (!entryQualityFilterEnabled && !isAggressive) {
    return { pass: true, progressAtr: null, bodyAtr: null, closeLocation: null, minProgressAtr: null, minBodyAtr: null };
  }
  if (!candle || !Number.isFinite(level) || !Number.isFinite(atrRef) || atrRef <= 0) {
    return { pass: true, progressAtr: null, bodyAtr: null, closeLocation: null, minProgressAtr: null, minBodyAtr: null };
  }
  const symbol = options.symbol || getActiveSymbol();
  const granSec = options.granSec || getCurrentGranularitySec();
  const progressAtr = dir === "BULL" ? (candle.close - level) / atrRef : (level - candle.close) / atrRef;
  const bodyAtr = Math.abs(candle.close - candle.open) / atrRef;
  const range = candle.high - candle.low;
  const closeLocation = range > 0
    ? (dir === "BULL" ? (candle.close - candle.low) / range : (candle.high - candle.close) / range)
    : 0.5;
  const minProgressAtr = getEntryProgressMinAtr(symbol, granSec, isAggressive);
  const minBodyAtr = Math.max(0.08, minProgressAtr * 0.8);
  const minCloseLocation = isAggressive ? 0.55 : 0.60;
  if (progressAtr < minProgressAtr) {
    return {
      pass: false,
      reason: `${isAggressive ? "intrabar trigger" : "confirmation close"} only cleared ${fmt(progressAtr, 2)} ATR from the retest level (min ${fmt(minProgressAtr, 2)} ATR)`,
      progressAtr, bodyAtr, closeLocation, minProgressAtr, minBodyAtr
    };
  }
  if (bodyAtr < minBodyAtr) {
    return {
      pass: false,
      reason: `confirmation body ${fmt(bodyAtr, 2)} ATR is too small (min ${fmt(minBodyAtr, 2)} ATR)`,
      progressAtr, bodyAtr, closeLocation, minProgressAtr, minBodyAtr
    };
  }
  if (closeLocation < minCloseLocation) {
    return {
      pass: false,
      reason: `confirmation closed too far from the candle extreme (${fmt(closeLocation * 100, 0)}% of range)`,
      progressAtr, bodyAtr, closeLocation, minProgressAtr, minBodyAtr
    };
  }
  return { pass: true, progressAtr, bodyAtr, closeLocation, minProgressAtr, minBodyAtr };
}

function getSignalCreatedAtMs(signal) {
  if (!signal || typeof signal !== "object") return 0;
  if (Number.isFinite(signal.createdAtMs)) return signal.createdAtMs;
  if (typeof signal.time === "string") {
    const parsed = Date.parse(signal.time);
    if (Number.isFinite(parsed)) return parsed;
  }
  return 0;
}

function shouldPauseAfterRecentLosses(history, options = {}) {
  if (!recentLossPauseEnabled) return { block: false };
  const fallbackRequired = Math.max(1, parseInt(recentLossPauseCount, 10) || RECENT_LOSS_PAUSE_COUNT_DEFAULT);
  const required = Math.max(1, Math.round(getAdaptiveAppliedNumber("lossPauseThreshold", fallbackRequired, options)));
  const symbol = options.symbol || getActiveSymbol();
  const strategyType = options.strategyType || "breakout_retest";
  const dir = normalizeSignalDir(options.dir);
  const timeframeSec = options.timeframeSec || getCurrentGranularitySec();
  const resolved = (history || [])
    .filter(s => s && (s.result === "WIN" || s.result === "LOSS"))
    .filter(s => (s.symbol || symbol) === symbol)
    .filter(s => normalizeSignalDir(s.dir) === dir)
    .filter(s => (s.strategyType || s.type || "breakout_retest") === strategyType)
    .filter(s => s.timeframeSec == null || timeframeSec == null || s.timeframeSec === timeframeSec)
    .sort((a, b) => getSignalCreatedAtMs(a) - getSignalCreatedAtMs(b));
  if (resolved.length < required) return { block: false };
  const recent = resolved.slice(-required);
  if (recent.every(s => s.result === "LOSS")) {
    return {
      block: true,
      reason: `recent ${required} ${strategyType.replace(/_/g, " ")} ${dir} signal${required === 1 ? "" : "s"} all lost — wait for a cleaner reset`
    };
  }
  return { block: false };
}

function isSymbolEligibleForNewSignal(symbol, strategyType = null) {
  const sym = symbol || getActiveSymbol();
  if (!sym) return true;
  const normalizedType = strategyType || null;
  if (typeof cleanupPendingSignalsForSymbol === "function") {
    cleanupPendingSignalsForSymbol(sym, normalizedType, { keepSignalId: trade && trade.signalId ? trade.signalId : null });
  }
  if (normalizedType === "breakout_retest" && monitoringTrade && trade && (trade.symbol || sym) === sym) return false;
  const hasPending = signalHistory.some((s) => {
    if (!s || s.result !== "PENDING") return false;
    if ((s.symbol || sym) !== sym) return false;
    if (!normalizedType) return true;
    return (s.strategyType || s.type || "breakout_retest") === normalizedType;
  });
  return !hasPending;
}

const SIGNAL_ENGINE_DEBUG_STORAGE_KEY = `${LS_PREFIX}signalEngineDebugMode`;
let signalEngineDebugMode = false;

function loadSignalEngineDebugMode() {
  try {
    const raw = localStorage.getItem(SIGNAL_ENGINE_DEBUG_STORAGE_KEY);
    signalEngineDebugMode = raw === "1";
  } catch {
    signalEngineDebugMode = false;
  }
}

function setSignalEngineDebugMode(enabled) {
  signalEngineDebugMode = enabled === true;
  try {
    localStorage.setItem(SIGNAL_ENGINE_DEBUG_STORAGE_KEY, signalEngineDebugMode ? "1" : "0");
  } catch { /* storage unavailable */ }
  addLog(`🐞 Signal Engine Debug ${signalEngineDebugMode ? "ENABLED" : "DISABLED"}`);
}

function logSignalEngineDebug(stage, details = {}) {
  if (!signalEngineDebugMode) return;
  try {
    const compact = JSON.stringify(details);
    addLog(`🐞 [SignalEngine:${stage}] ${compact}`);
  } catch {
    addLog(`🐞 [SignalEngine:${stage}]`);
  }
}

function buildLifecyclePayloadFromSignal(signal, strategyLabel, channel = "trade", reason = null) {
  if (!signal) return null;
  const atrAtSignal = Number.isFinite(signal.atrAtSignal) ? signal.atrAtSignal : (Number.isFinite(signal.atrAtEntry) ? signal.atrAtEntry : getAtrReference());
  const currentPrice = candles.length > 0 ? candles[candles.length - 1].close : null;
  const triggerFactors = ensureSignalTriggerFactors(signal);
  const rr = Number.isFinite(signal.riskReward) ? signal.riskReward : (Number.isFinite(signal.rr) ? signal.rr : null);
  return {
    signalId: signal.signalId || null,
    channel,
    strategyLabel,
    symbol: signal.symbol || getActiveSymbol(),
    timeframeSec: signal.timeframeSec != null ? signal.timeframeSec : getCurrentGranularitySec(),
    dir: signal.dir,
    level: signal.level,
    entry: signal.entry,
    sl: signal.sl || signal.stopLoss || null,
    tp: signal.tp || signal.takeProfit || null,
    rr,
    atr: Number.isFinite(signal.atr) ? signal.atr : atrAtSignal,
    confidenceScore: signal.confluenceScore != null ? signal.confluenceScore : null,
    adaptiveConfidenceLabel: getAdaptiveConfidenceLabel(signal),
    marketCategory: getAdaptiveMarketCategory(signal.symbol || getActiveSymbol(), signal.timeframeSec != null ? signal.timeframeSec : getCurrentGranularitySec()),
    weightVersion: signal._adaptiveDecision && signal._adaptiveDecision.weight_version ? signal._adaptiveDecision.weight_version : null,
    triggerFactors,
    tradeManagement: signal.tradeManagement || null,
    validUntilMs: signal.validUntilMs,
    maxDistanceAtr: Number.isFinite(signal.maxEntryDistanceAtr) ? signal.maxEntryDistanceAtr : getSignalDistanceLimitAtr(),
    distanceAtr: getSignalDistanceFromEntry({ entry: signal.entry, atrAtSignal }, currentPrice),
    stopBufferAtr: signal.stopBufferAtr,
    entryDriftAtr: signal.entryDriftAtr,
    reason,
    entryMode: signal.entryMode || null
  };
}

function stampSignalLifecycle(signal, options = {}) {
  if (!signal || typeof signal !== "object") return signal;
  if (!signal.signalId) signal.signalId = generateSignalId(signal.strategyType || signal.type || "sig");
  if (options.assignScope !== false && !signal.adaptiveScopeKey) signal.adaptiveScopeKey = getAdaptiveRuntimeScopeKey();
  const createdAt = Number.isFinite(signal.createdAtMs) ? signal.createdAtMs : Date.now();
  const validityMs = Number.isFinite(signal.validityMs) ? signal.validityMs : (options.validityMs || getSignalValidityMs());
  signal.createdAtMs = createdAt;
  signal.validityMs = validityMs;
  signal.validUntilMs = Number.isFinite(signal.validUntilMs) ? signal.validUntilMs : createdAt + validityMs;
  signal.maxEntryDistanceAtr = Number.isFinite(signal.maxEntryDistanceAtr) ? signal.maxEntryDistanceAtr : getSignalDistanceLimitAtr();
  signal.atrAtSignal = Number.isFinite(signal.atrAtSignal) && signal.atrAtSignal > 0
    ? signal.atrAtSignal
    : (Number.isFinite(options.atrAtSignal) && options.atrAtSignal > 0 ? options.atrAtSignal : getAtrReference());
  if (!signal.adaptiveRegime && signal.result === "PENDING") {
    signal.adaptiveRegime = signal.volatilityRegime || getCurrentRegimeTag();
  }
  return signal;
}

function ensureAllKnownSignalIds() {
  const histories = [
    signalHistory,
    liquiditySweepHistory, stopLossHuntHistory, failedPinBarHistory,
    fibScalpHistory, po3History, gridScalperMAHistory, fvgStratHistory,
    mtfTopDownHistory, nyOpenRangeHistory, sessionRangeHistory, tiktokHistory,
    orderblockHistory, candleInterpHistory, po3_4hHistory, breakerBlockHistory,
    oteGoldenPocketHistory, orbHistory, crtTbsHistory
  ];
  let touched = false;
  for (const history of histories) {
    if (!Array.isArray(history)) continue;
    for (const s of history) {
      if (s && typeof s === "object" && (!s.signalId || (s.result === "PENDING" && !s.adaptiveScopeKey))) {
        stampSignalLifecycle(s, { assignScope: s.result === "PENDING" });
        touched = true;
      }
    }
  }
  return touched;
}

function retryDeferredConfluenceOutcomes() {
  if (!adaptiveConfluenceEnabled) return false;
  const currentScopeKey = String(getAdaptiveRuntimeScopeKey() || "").trim();
  if (!currentScopeKey) return false;
  const buckets = [
    signalHistory, mtfTopDownHistory, liquiditySweepHistory, stopLossHuntHistory,
    failedPinBarHistory, fibScalpHistory, po3History, nyOpenRangeHistory,
    sessionRangeHistory, gridScalperMAHistory, fvgStratHistory, liveScalpHistory,
    candleInterpHistory, orderblockHistory, tiktokHistory, po3_4hHistory, orbHistory,
    breakerBlockHistory, oteGoldenPocketHistory, crtTbsHistory
  ].filter(Array.isArray);
  let touched = false;
  for (const arr of buckets) {
    for (const s of arr) {
      if (!s || (s.result !== "WIN" && s.result !== "LOSS") || s._confRecorded) continue;
      if (!Array.isArray(s._confFactors) || s._confFactors.length === 0) continue;
      const signalScopeKey = String(s.adaptiveScopeKey || "").trim();
      if (!signalScopeKey || signalScopeKey !== currentScopeKey) continue;
      if (recordConfluenceOutcome(s._confFactors, s.result, signalScopeKey)) {
        s._confRecorded = true;
        touched = true;
      }
    }
  }
  return touched;
}

function getSignalDistanceFromEntry(signal, currentPrice) {
  if (!signal || signal.entry == null || !Number.isFinite(currentPrice)) return null;
  const atrRef = Number.isFinite(signal.atrAtSignal) && signal.atrAtSignal > 0 ? signal.atrAtSignal : getAtrReference();
  if (!(atrRef > 0)) return null;
  return Math.abs(currentPrice - signal.entry) / atrRef;
}

/* ================= MARKET TYPE DETECTION & TUNING ================= */
/**
 * Market types supported:
 *   "volatility"  – standard/1s volatility indices (R_xx, 1HZxxV)
 *   "boom"        – Boom indices (spike UP direction)
 *   "crash"       – Crash indices (spike DOWN direction)
 *   "jump"        – Jump indices (sudden jumps in either direction)
 *   "step"        – Step Index (fixed-increment moves)
 *   "dailyreset"  – Daily Reset indices (Bull/Bear market trends)
 *   "dex"         – DEX indices (news-event spike simulation)
 *   "driftswitch" – Drift Switch indices (regime-switching trends)
 *   "forex"       – Forex pairs
 *   "commodity"   – Gold/Silver/Platinum/Palladium
 */
function getMarketType(symbol) {
  if (!symbol) symbol = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
  if (/^BOOM/i.test(symbol))  return "boom";
  if (/^CRASH/i.test(symbol)) return "crash";
  if (/^JD/i.test(symbol))    return "jump";
  if (/^stpRNG\d*$/i.test(symbol) || /^STPIDX/i.test(symbol)) return "step";
  if (/^(RDBULL|RDBEAR)/i.test(symbol)) return "dailyreset";
  if (/^DEX/i.test(symbol))   return "dex";
  if (/^DSI/i.test(symbol))   return "driftswitch";
  if (/^1HZ/i.test(symbol) || /^R_/i.test(symbol)) return "volatility";
  if (/^XAUUSD/i.test(symbol))  return "commodity";   /* XAUUSDmicro, XAUUSD.s */
  if (/^frxX/i.test(symbol))    return "commodity";
  if (/^frx/i.test(symbol))     return "forex";
  return "volatility";
}

/**
 * Spike detection for Boom/Crash indices.
 * Boom indices produce large upward spikes; Crash produce downward spikes.
 * A spike candle has a range ≥ SPIKE_RANGE_MULT × ATR and the body is strongly
 * directional (body ≥ 70% of range in the expected direction).
 */
const SPIKE_RANGE_MULT = 2.0;
const SPIKE_BODY_PCT   = 0.70;

function isSpikeCandle(candle, expectedDir) {
  if (atrValue <= 0) return false;
  const range = candle.high - candle.low;
  if (range < atrValue * SPIKE_RANGE_MULT) return false;
  const body = candle.close - candle.open;
  const absBody = Math.abs(body);
  if (absBody < range * SPIKE_BODY_PCT) return false;
  if (expectedDir === "BULL") return body > 0;
  if (expectedDir === "BEAR") return body < 0;
  return true;
}

/**
 * Jump detection for Jump indices.
 * Jumps are sudden price discontinuities — a candle whose open differs from
 * the previous close by ≥ JUMP_GAP_ATR_MULT × ATR, or whose range is
 * extremely large relative to recent candles.
 */
const JUMP_GAP_ATR_MULT   = 1.0;
const JUMP_RANGE_ATR_MULT = 2.5;

function isJumpCandle(idx) {
  if (idx < 1 || idx >= candles.length || atrValue <= 0) return false;
  const c = candles[idx];
  const prev = candles[idx - 1];
  const gap = Math.abs(c.open - prev.close);
  if (gap >= atrValue * JUMP_GAP_ATR_MULT) return true;
  const range = c.high - c.low;
  return range >= atrValue * JUMP_RANGE_ATR_MULT;
}

/**
 * Step Index strategy helpers.
 * Step Index moves in fixed increments, so we look for consecutive steps
 * in the same direction (momentum runs) and mean-reversion after extended runs.
 * Returns the run length (positive = up steps, negative = down steps).
 */
const STEP_RUN_THRESHOLD = 5;   /* consecutive steps to confirm a trend */
const STEP_REVERSAL_BARS = 3;   /* bars of reversal to confirm mean reversion */

function getStepRunLength() {
  if (candles.length < 3) return 0;
  let run = 0;
  for (let i = candles.length - 1; i >= 1; i--) {
    const dir = candles[i].close - candles[i - 1].close;
    if (dir > 0) {
      if (run < 0) break;
      run++;
    } else if (dir < 0) {
      if (run > 0) break;
      run--;
    } else {
      break;
    }
  }
  return run;
}

/**
 * Returns market-type-specific tuning overrides.
 * These affect breakout conviction, tolerance, and trade management.
 */
function getMarketTuning() {
  const mtype = getMarketType();
  switch (mtype) {
    case "boom":
      return {
        /* Boom: directional spikes UP — look for bullish breakouts primarily */
        preferredDir: "BULL",
        breakoutConvictionMult: 0.6,    /* lower conviction threshold (spikes are erratic) */
        volumeSpikeMult: 2.0,           /* require stronger volume spike */
        retestToleranceMult: 0.7,       /* tighter retest (price retraces quickly) */
        trailingATRMult: 2.0,           /* wider trailing for spike momentum */
        rangeDurationMult: 1.0,
        spikeAware: true,
        label: "Boom"
      };
    case "crash":
      return {
        /* Crash: directional spikes DOWN — look for bearish breakouts primarily */
        preferredDir: "BEAR",
        breakoutConvictionMult: 0.6,
        volumeSpikeMult: 2.0,
        retestToleranceMult: 0.7,
        trailingATRMult: 2.0,
        rangeDurationMult: 1.0,
        spikeAware: true,
        label: "Crash"
      };
    case "jump":
      return {
        /* Jump: sudden both-direction jumps — widen tolerance, quick entries */
        preferredDir: null,
        breakoutConvictionMult: 0.5,    /* jumps are instant, body may not fill range */
        volumeSpikeMult: 1.2,           /* lower bar for volume (jumps are inherently volatile) */
        retestToleranceMult: 1.2,       /* wider retest tolerance for gap fills */
        trailingATRMult: 2.5,           /* wider trailing to survive jump volatility */
        rangeDurationMult: 0.67,        /* shorter opening range (10 min for jumps) */
        spikeAware: false,
        label: "Jump"
      };
    case "step":
      return {
        /* Step: fixed increments — tight tolerances, momentum runs */
        preferredDir: null,
        breakoutConvictionMult: 0.4,    /* small bodies are normal */
        volumeSpikeMult: 1.0,           /* volume spike not meaningful */
        retestToleranceMult: 0.5,       /* very tight retest (precise levels) */
        trailingATRMult: 1.0,           /* tight trailing for small moves */
        rangeDurationMult: 1.5,         /* longer range to capture structure */
        spikeAware: false,
        label: "Step"
      };
    case "dailyreset":
      return {
        /* Daily Reset: one-directional daily trends that reset — follow the trend */
        preferredDir: null,
        breakoutConvictionMult: 1.2,    /* require stronger conviction (many false breaks) */
        volumeSpikeMult: 1.5,           /* moderate volume filter for real breakouts */
        retestToleranceMult: 0.8,       /* moderately tight retest */
        trailingATRMult: 1.5,           /* standard trailing */
        rangeDurationMult: 1.5,         /* longer range to capture structure */
        spikeAware: false,
        label: "Daily Reset"
      };
    case "dex":
      return {
        /* DEX: news-event spike simulation — spike-aware like Boom/Crash */
        preferredDir: null,             /* UP/DN variant determines direction in strategy */
        breakoutConvictionMult: 0.7,    /* spikes produce erratic candles */
        volumeSpikeMult: 1.8,           /* strong volume filter for genuine spikes */
        retestToleranceMult: 0.8,       /* tighter retest (fast-moving) */
        trailingATRMult: 2.0,           /* wider trailing for spike momentum */
        rangeDurationMult: 1.0,
        spikeAware: true,
        label: "DEX"
      };
    case "driftswitch":
      return {
        /* Drift Switch: regime-switching trends — follow the current regime */
        preferredDir: null,
        breakoutConvictionMult: 0.8,    /* trends are smooth within regime */
        volumeSpikeMult: 1.0,           /* volume not as meaningful */
        retestToleranceMult: 1.0,       /* standard retest */
        trailingATRMult: 1.5,           /* standard trailing */
        rangeDurationMult: 1.0,
        spikeAware: false,
        label: "Drift Switch"
      };
    default:
      return {
        preferredDir: null,
        breakoutConvictionMult: 1.0,
        volumeSpikeMult: 1.0,
        retestToleranceMult: 1.0,
        trailingATRMult: 1.0,
        rangeDurationMult: 1.0,
        spikeAware: false,
        label: mtype.charAt(0).toUpperCase() + mtype.slice(1)
      };
  }
}

/* ================= PROFIT-OPTIMIZED STRATEGY PARAMETERS (per symbol type) ================= */
/**
 * Returns profit-optimized strategy parameters for Volatility 1s and Standard indices.
 * Other symbols get default (unmodified) values so existing behaviour is preserved.
 *
 * Key optimizations for Volatility indices:
 *  • Higher R:R targets — 1s indices move fast, capture larger swings
 *  • Tighter SL buffers — ATR on 1s is small, avoid giving back too much
 *  • Reduced cooldowns — 1s markets generate opportunities rapidly
 *  • Wider trailing — allow fast moves to breathe without premature exit
 *
 * @param {string} [symbol] – symbol string; defaults to active symbol
 * @returns {{ rrLiquiditySweep: number, rrStopLossHunt: number, rrFailedPinBar: number,
 *             rrGridScalperMA: number, rrFVGFallback: number, rrPO3Fallback: number,
 *             rrMTFMin: number, slBufferMult: number, trailingMult: number,
 *             cooldownReduction: number, minImpulseATR: number }}
 */
function getStrategyProfitParams(symbol) {
  if (!symbol) symbol = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
  const isVol1s  = /^1HZ/i.test(symbol);
  const isVolStd = /^R_/i.test(symbol); /* legacy — R_ symbols deprecated by Deriv API */

  if (isVol1s) {
    /* Volatility 1s: ultra-fast 1-second candles — optimise for quick, high-RR scalps */
    return {
      rrLiquiditySweep: 2.5,    /* raised from 2.0 — fast reversals overshoot */
      rrStopLossHunt:   2.5,    /* raised from 2.0 — hunts snap back aggressively */
      rrFailedPinBar:   2.0,    /* raised from 1.5 — momentum continuation is strong on 1s */
      rrGridScalperMA:  2.5,    /* raised from 2.0 — MA breaks produce clean extensions */
      rrFVGFallback:    2.5,    /* raised from 2.0 — FVG fills extend further on 1s */
      rrPO3Fallback:    2.5,    /* raised from 2.0 — PO3 distribution moves are swift */
      rrMTFMin:         2.5,    /* raised from 2.0 — structural moves are pronounced */
      slBufferMult:     0.8,    /* tighter SL buffer (less ATR slack) — 1s ATR is small */
      trailingMult:     1.8,    /* wider trailing (1.8× vs 1.5×) — survive 1s noise */
      cooldownReduction: 0.5,   /* halve cooldowns — opportunities form every few seconds */
      minImpulseATR:    1.2     /* lower impulse requirement — moves are frequent but shorter */
    };
  }

  if (isVolStd) {
    /* Volatility Standard (R_10–R_100): moderate-speed — optimise for swing capture */
    return {
      rrLiquiditySweep: 2.5,    /* raised from 2.0 — sweeps produce strong reversals */
      rrStopLossHunt:   2.5,    /* raised from 2.0 — hunts are aggressive on standard vol */
      rrFailedPinBar:   2.0,    /* raised from 1.5 — momentum extends well */
      rrGridScalperMA:  2.5,    /* raised from 2.0 — breakouts from MA trend further */
      rrFVGFallback:    2.5,    /* raised from 2.0 — imbalances fill with extension */
      rrPO3Fallback:    2.5,    /* raised from 2.0 — distribution targets are reachable */
      rrMTFMin:         2.5,    /* raised from 2.0 — structural moves have good follow-through */
      slBufferMult:     0.9,    /* slightly tighter SL buffer — reduce unnecessary risk */
      trailingMult:     1.7,    /* slightly wider trailing — let standard vol breathe */
      cooldownReduction: 0.7,   /* 30% cooldown reduction — moderate pace */
      minImpulseATR:    1.3     /* slightly lower impulse threshold — catch more setups */
    };
  }

  /* All other symbols: default (unchanged) behaviour */
  return {
    rrLiquiditySweep: 2.0,
    rrStopLossHunt:   2.0,
    rrFailedPinBar:   1.5,
    rrGridScalperMA:  2.0,
    rrFVGFallback:    2.0,
    rrPO3Fallback:    2.0,
    rrMTFMin:         2.0,
    slBufferMult:     1.0,
    trailingMult:     1.0,
    cooldownReduction: 1.0,
    minImpulseATR:    1.5
  };
}

/* Auto-reconnect */
const RECONNECT_BASE_DELAY = 1000;
const RECONNECT_MAX_DELAY  = 30000;
const MAX_RECONNECT_ATTEMPTS = 50;  /* Allow many reconnect attempts for long-running sessions */
let reconnectAttempts = 0;
let reconnectTimer    = null;
let intentionalClose  = false;

/* Toast notification durations */
const TOAST_WARNING_DURATION_MS = 4000;
const TOAST_ERROR_DURATION_MS = 10000;

/* Ping/keepalive (Deriv WS sessions time out after inactivity) */
const PING_INTERVAL_MS = 30000;
let pingTimer = null;

/* Stream watchdog — detect stale connections that stop delivering OHLC data.
   If no candle/tick data arrives within WATCHDOG_TIMEOUT_MS, force a reconnect.
   This addresses the issue where WebSocket connections stay "open" but the
   Deriv server stops sending market data after extended periods. */
const WATCHDOG_TIMEOUT_MS = 120000; /* 2 minutes without data → reconnect */
let watchdogTimer = null;
let lastDataTimestamp = 0;  /* epoch ms of last OHLC message on the main WS */

/* Debounce */
let reconnectDebounceTimer = null;
const RECONNECT_DEBOUNCE_MS = 400;

/* Pending signal state saved across reconnect (used by remapPendingSignalIndices) */
let _reconnectSavedNyTrade = null;
let _reconnectSavedSessionTrade = null;

/* Chart redraw optimization */
let chartRedrawTimer = null;
const CHART_REDRAW_DEBOUNCE_MS = 16; /* ~60fps */
let chartRedrawPending = false;

/* API rate limiting */
const apiCallTimestamps = new Map(); /* endpoint -> array of timestamps */
const API_RATE_LIMIT_WINDOW_MS = 60000; /* 1 minute window */
const API_RATE_LIMIT_MAX_CALLS = 120; /* max calls per window */

/**
 * Check if an API call is allowed based on rate limiting.
 * @param {string} endpoint - The API endpoint identifier (e.g., "telegram", "contracts_for")
 * @returns {boolean} - True if the call is allowed, false if rate limited
 */
function getApiRateLimitWaitMs(endpoint) {
  const now = Date.now();
  if (!apiCallTimestamps.has(endpoint)) {
    apiCallTimestamps.set(endpoint, []);
  }
  
  const timestamps = apiCallTimestamps.get(endpoint);
  
  /* Remove timestamps outside the window */
  const validTimestamps = timestamps.filter(t => now - t < API_RATE_LIMIT_WINDOW_MS);
  apiCallTimestamps.set(endpoint, validTimestamps);
  
  /* Check if we've exceeded the limit */
  if (validTimestamps.length >= API_RATE_LIMIT_MAX_CALLS) {
    const oldestCall = validTimestamps[0];
    return Math.max(1, API_RATE_LIMIT_WINDOW_MS - (now - oldestCall));
  }
  
  /* Record this call */
  validTimestamps.push(now);
  return 0;
}

function isApiCallAllowed(endpoint) {
  const waitMs = getApiRateLimitWaitMs(endpoint);
  if (waitMs > 0) {
    const waitTime = Math.ceil(waitMs / 1000);
    addLog(`⚠️ Rate limit reached for ${endpoint}. Please wait ${waitTime}s.`);
    return false;
  }
  return true;
}

async function waitForApiCallSlot(endpoint, maxWaitMs = 20000) {
  const deadline = Date.now() + maxWaitMs;
  let warned = false;

  while (true) {
    const waitMs = getApiRateLimitWaitMs(endpoint);
    if (waitMs === 0) return true;
    if (!warned) {
      addLog(`⏳ ${endpoint} rate-limited, queueing send...`);
      if (endpoint === "telegram") recordTelegramDeliveryStat("queued", 1);
      warned = true;
    }
    if (Date.now() + waitMs > deadline) return false;
    await new Promise(resolve => setTimeout(resolve, Math.min(waitMs, 1000)));
  }
}

