  _renderAlertList(UI.po3AlertList, UI.po3Count, po3History, "⚡", "Power of 3");
  /* NY Open Range */
  _renderAlertList(UI.nyOpenRangeAlertList, UI.nyOpenRangeAlertCount, nyOpenRangeHistory, "🕤", "NY Open Range");
  /* Session Range (London Sweep) */
