/* ================= MTF TOP-DOWN STRATEGY (Strategy 11) ================= */
let mtfTopDownEnabled   = false;    /* master toggle */
let mtfTopDownHistory   = [];       /* alert history */
let lastMtfTopDownIdx   = -999;     /* cooldown tracker */
let autoTradeMtfTopDown = true;     /* auto-trade sub-toggle */
let lastMtfSetupAlertKey = "";
let lastMtfApproachAlertKey = "";
let mtfSetupState = null;           /* holds latest qualified setup while waiting for retest */
let mtfTerminalBreakoutEpoch = null;/* suppresses re-arming on already-consumed/expired HTF breakout */

const MTF_TOP_DOWN_COOLDOWN    = 5;   /* min candles between signals */
const MTF_TOP_DOWN_MAX_HISTORY = 30;  /* max stored alerts */
const MTF_TOP_DOWN_MAX_CANDLES = 60;  /* monitoring timeout (candles) */
const MTF_BIAS_TF_MULT         = 16;  /* ×current TF → "4H" synthesis ratio */
const MTF_SETUP_TF_MULT        = 4;   /* ×current TF → "1H" synthesis ratio */
const MTF_BIAS_LOOKBACK        = 6;   /* synthesised 4H bars for bias */
const MTF_SETUP_LOOKBACK       = 12;  /* synthesised 1H bars for setup range */
const MTF_SL_ATR_BUFFER        = 0.3; /* ATR buffer beyond wick for SL */
const MTF_RETEST_LOOKBACK      = 8;   /* current-TF candles to scan for retest */
const MTF_SL_FALLBACK_MODE     = "structure_then_swing";
const MTF_TP_FALLBACK_MODE     = "htf_then_rr";
const MTF_DEBUG_STORAGE_KEY    = `${LS_PREFIX}mtfDebugMode`;
const MTF_REQUIRED_BASE_CANDLES = Math.max(
  (MTF_BIAS_LOOKBACK + 2) * MTF_BIAS_TF_MULT,
  (MTF_SETUP_LOOKBACK + 2) * MTF_SETUP_TF_MULT
) + (Math.max(MTF_BIAS_TF_MULT, MTF_SETUP_TF_MULT) - 1);
const MTF_HISTORY_FETCH_COUNT = Math.max(100, MTF_REQUIRED_BASE_CANDLES + 32);
let mtfDebugMode = false;
let mtfDebugRows = [];
let mtfDebugClock = 0;
const mtfPipelineStats = new Map();

function buildNamedTriggerFactor(factor, detail, group, weight, passed = true, extra = {}) {
  return Object.assign({
    factor,
    detail: detail || null,
    group: group || resolveSignalFactorGroup(factor) || factor,
    weight: Number.isFinite(weight) ? Number(weight) : (SIGNAL_FACTOR_DEFAULT_WEIGHTS[group] ?? 5),
    score: passed ? (Number.isFinite(weight) ? Number(weight) : (SIGNAL_FACTOR_DEFAULT_WEIGHTS[group] ?? 5)) : 0,
    passed,
    persist: extra.persist !== false
  }, extra);
}

function mergeSignalTriggerFactorDetails(signal, factors) {
  if (!signal) return [];
  const merged = ensureSignalTriggerFactors(signal);
  const seen = new Set(merged.map((factor) => `${factor.factor}|${factor.detail || ""}`));
  for (const factor of normalizeSignalTriggerFactors(factors, getAdaptiveMtfStatus(signal))) {
    const key = `${factor.factor}|${factor.detail || ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(factor);
  }
  signal.triggerFactors = merged;
  signal.factorBreakdown = merged;
  return merged;
}

function computeMtfExecutionLevels({ dir, entry, level, idx, retestCandleIdx, currentCandle, atrRef, rrTarget, stopBuffer, biasSlice }) {
  const structureStart = Math.max(0, Math.min(Number.isFinite(retestCandleIdx) ? retestCandleIdx : idx, idx) - 1);
  const structureCandles = candles.slice(structureStart, idx + 1).filter(Boolean);
  const lows = structureCandles.map((c) => c.low).filter(Number.isFinite);
  const highs = structureCandles.map((c) => c.high).filter(Number.isFinite);
  const structureLow = lows.length ? Math.min(...lows, Number.isFinite(level) ? level : Infinity, Number.isFinite(currentCandle && currentCandle.low) ? currentCandle.low : Infinity) : null;
  const structureHigh = highs.length ? Math.max(...highs, Number.isFinite(level) ? level : -Infinity, Number.isFinite(currentCandle && currentCandle.high) ? currentCandle.high : -Infinity) : null;
  const swingStart = Math.max(0, idx - Math.max(12, MTF_RETEST_LOOKBACK * 2));
  const swingCandles = candles.slice(swingStart, idx + 1).filter(Boolean);
  const swingLow = swingCandles.length ? Math.min(...swingCandles.map((c) => c.low).filter(Number.isFinite)) : null;
  const swingHigh = swingCandles.length ? Math.max(...swingCandles.map((c) => c.high).filter(Number.isFinite)) : null;
  const fallbackRisk = Math.max(
    Number.isFinite(currentCandle && currentCandle.high) && Number.isFinite(currentCandle && currentCandle.low)
      ? Math.abs(currentCandle.high - currentCandle.low)
      : 0,
    Number.isFinite(entry) && Number.isFinite(level) ? Math.abs(entry - level) : 0,
    Number.isFinite(atrRef) && atrRef > 0 ? atrRef * 0.75 : 0
  );
  let stopLossMethod = "atr_structure";
  let takeProfitMethod = "htf_projection";
  let fallbackUsed = false;
  let sl = null;
  let tp = null;

  if (dir === "BULL") {
    if (Number.isFinite(structureLow)) sl = structureLow - stopBuffer;
    if (!Number.isFinite(sl) || sl >= entry) {
      sl = Number.isFinite(swingLow) ? swingLow - (Number.isFinite(atrRef) && atrRef > 0 ? atrRef * 0.15 : 0) : null;
      stopLossMethod = "swing_low_fallback";
      fallbackUsed = true;
    }
    if (!Number.isFinite(sl) || sl >= entry) {
      sl = entry - Math.max(fallbackRisk, 0.0001);
      stopLossMethod = "distance_fallback";
      fallbackUsed = true;
    }
    tp = Array.isArray(biasSlice) && biasSlice.length > 0
      ? Math.max(...biasSlice.map((bar) => bar.high).filter(Number.isFinite))
      : null;
    if (!Number.isFinite(tp) || tp <= entry) {
      tp = entry + Math.abs(entry - sl) * Math.max(1, rrTarget);
      takeProfitMethod = "rr_extension_fallback";
      fallbackUsed = true;
    }
  } else {
    if (Number.isFinite(structureHigh)) sl = structureHigh + stopBuffer;
    if (!Number.isFinite(sl) || sl <= entry) {
      sl = Number.isFinite(swingHigh) ? swingHigh + (Number.isFinite(atrRef) && atrRef > 0 ? atrRef * 0.15 : 0) : null;
      stopLossMethod = "swing_high_fallback";
      fallbackUsed = true;
    }
    if (!Number.isFinite(sl) || sl <= entry) {
      sl = entry + Math.max(fallbackRisk, 0.0001);
      stopLossMethod = "distance_fallback";
      fallbackUsed = true;
    }
    tp = Array.isArray(biasSlice) && biasSlice.length > 0
      ? Math.min(...biasSlice.map((bar) => bar.low).filter(Number.isFinite))
      : null;
    if (!Number.isFinite(tp) || tp >= entry) {
      tp = entry - Math.abs(sl - entry) * Math.max(1, rrTarget);
      takeProfitMethod = "rr_extension_fallback";
      fallbackUsed = true;
    }
  }

  const risk = Number.isFinite(entry) && Number.isFinite(sl) ? Math.abs(entry - sl) : NaN;
  if (!(risk > 0) || !Number.isFinite(tp)) {
    return { valid: false, stopLoss: sl, takeProfit: tp, riskReward: null };
  }
  let riskReward = Math.abs(tp - entry) / risk;
  if (!(riskReward > 0) || (Number.isFinite(rrTarget) && rrTarget > 0 && riskReward < rrTarget)) {
    tp = dir === "BULL" ? entry + risk * rrTarget : entry - risk * rrTarget;
    takeProfitMethod = "rr_extension_fallback";
    fallbackUsed = true;
    riskReward = Math.abs(tp - entry) / risk;
  }

  return {
    valid: Number.isFinite(entry) && Number.isFinite(sl) && Number.isFinite(tp) && Number.isFinite(riskReward),
    stopLoss: sl,
    takeProfit: tp,
    riskReward,
    atr: Number.isFinite(atrRef) && atrRef > 0 ? atrRef : null,
    tradeManagement: {
      stopLossMethod,
      takeProfitMethod,
      fallbackMode: `${MTF_SL_FALLBACK_MODE}|${MTF_TP_FALLBACK_MODE}`,
      fallbackUsed,
      riskDistance: risk,
      structureLow: Number.isFinite(structureLow) ? structureLow : null,
      structureHigh: Number.isFinite(structureHigh) ? structureHigh : null,
      swingLow: Number.isFinite(swingLow) ? swingLow : null,
      swingHigh: Number.isFinite(swingHigh) ? swingHigh : null
    }
  };
}

function loadMtfDebugMode() {
  try {
    const raw = localStorage.getItem(MTF_DEBUG_STORAGE_KEY);
    if (raw === null) return;
    mtfDebugMode = raw === "1";
  } catch {
    /* keep existing value */
  }
}

function setMtfDebugMode(enabled) {
  mtfDebugMode = enabled === true;
  try {
    localStorage.setItem(MTF_DEBUG_STORAGE_KEY, mtfDebugMode ? "1" : "0");
  } catch { /* storage unavailable */ }
  if (UI.mtfDebugToggle) UI.mtfDebugToggle.checked = mtfDebugMode;
  if (UI.mtfDebugPanel) UI.mtfDebugPanel.style.display = mtfDebugMode ? "" : "none";
  if (mtfDebugMode) renderMtfDebugPanel();
}

function getMtfPipelineState(symbol) {
  const sym = symbol || getActiveSymbol() || "UNKNOWN";
  if (!mtfPipelineStats.has(sym)) {
    mtfPipelineStats.set(sym, {
      symbol: sym,
      availableTimeframes: [],
      htf: {},
      alignment: {},
      conditions: {},
      rejectionCounts: {},
      lastRejection: null,
      lastSignal: null,
      pipeline: {},
      waitingForClose: null,
      updatedAtMs: 0
    });
  }
  return mtfPipelineStats.get(sym);
}

function markMtfPipelineStage(stage, details = {}) {
  const state = getMtfPipelineState(details.symbol || getActiveSymbol());
  state.pipeline[stage] = {
    at: Date.now(),
    details: Object.assign({}, details)
  };
  state.updatedAtMs = Date.now();
}

function recordMtfRejection(reason, details = {}) {
  const state = getMtfPipelineState(details.symbol || getActiveSymbol());
  state.rejectionCounts[reason] = (state.rejectionCounts[reason] || 0) + 1;
  state.lastRejection = Object.assign({ reason, at: Date.now() }, details);
  if (details.conditions && typeof details.conditions === "object") {
    state.conditions = Object.assign({}, details.conditions);
  }
  markMtfPipelineStage("signal_validation", Object.assign({ status: "rejected", reason }, details));
}

function getMtfRejectionBreakdown(state) {
  const counts = state && state.rejectionCounts ? state.rejectionCounts : {};
  const entries = Object.entries(counts);
  const total = entries.reduce((sum, [, v]) => sum + v, 0);
  return entries.sort((a, b) => b[1] - a[1]).map(([reason, count]) => ({
    reason,
    count,
    percent: total > 0 ? Math.round((count / total) * 100) : 0
  }));
}

function escapeMtfDebugHtml(value) {
  return String(value == null ? "--" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function renderMtfDebugPanel() {
  if (!UI.mtfDebugBody || !UI.mtfDebugPanel) return;
  UI.mtfDebugPanel.style.display = mtfDebugMode ? "" : "none";
  if (!mtfDebugMode) return;
  const rows = mtfDebugRows.length > 0 ? mtfDebugRows.slice(0, 40) : [];
  if (rows.length === 0) {
    UI.mtfDebugBody.innerHTML = '<tr><td colspan="8" class="hint">No MTF diagnostics yet.</td></tr>';
    return;
  }
  UI.mtfDebugBody.innerHTML = rows.map((row) => {
    const htfStatus = escapeMtfDebugHtml(row.htfSummary || "--");
    const reason = escapeMtfDebugHtml(row.rejectionReason || "--");
    return `<tr>
      <td>${escapeMtfDebugHtml(row.symbol || "--")}</td>
      <td>${escapeMtfDebugHtml(row.strategy || "MTF Top-Down")}</td>
      <td>${escapeMtfDebugHtml(row.mtfStatus || "--")}</td>
      <td>${escapeMtfDebugHtml(row.ltfSignal || "--")}</td>
      <td>${htfStatus}</td>
      <td>${reason}</td>
      <td>${escapeMtfDebugHtml(row.alignment || "--")}</td>
      <td>${escapeMtfDebugHtml(row.time || "--")}</td>
    </tr>`;
  }).join("");
}

function pushMtfDebugRow(row) {
  mtfDebugClock++;
  mtfDebugRows.unshift(Object.assign({ _id: mtfDebugClock }, row));
  if (mtfDebugRows.length > 80) mtfDebugRows.length = 80;
  renderMtfDebugPanel();
}

function resetMtfDiagnostics() {
  mtfPipelineStats.clear();
  mtfDebugRows = [];
  renderMtfDebugPanel();
}

function formatMtfTfLabel(sec) {
  if (!Number.isFinite(sec) || sec <= 0) return "--";
  if (sec % 3600 === 0) return `${sec / 3600}h`;
  if (sec % 60 === 0) return `${sec / 60}m`;
  return `${sec}s`;
}

function getMtfTfMap(gran) {
  const baseGran = Number.isFinite(gran) && gran > 0 ? gran : 60;
  const ratios = [1, MTF_SETUP_TF_MULT, MTF_BIAS_TF_MULT];
  return Array.from(new Set(ratios))
    .sort((a, b) => a - b)
    .map((ratio) => {
      const sec = ratio * baseGran;
      return {
        label: formatMtfTfLabel(sec),
        sec,
        ratio
      };
    });
}

function captureMtfHtfDiagnostics(symbol) {
  const state = getMtfPipelineState(symbol);
  const ltf = candles && candles.length > 0 ? candles[candles.length - 1] : null;
  const gran = getCurrentGranularitySec();
  const tfMap = getMtfTfMap(gran);
  state.availableTimeframes = tfMap.map(tf => tf.label);
  state.htf = {};
  state.alignment = {};

  for (const tf of tfMap) {
    const ratio = Math.max(1, tf.ratio || Math.round(tf.sec / gran));
    const bars = ratio === 1
      ? (candles || []).map((c) => Object.assign({ _count: 1 }, c))
      : synthesizeTfCandles(ratio, { includeMeta: true });
    const closedBars = ratio === 1
      ? bars
      : synthesizeTfCandles(ratio, { includeMeta: true, closedOnly: true });
    const lastBar = bars.length > 0 ? bars[bars.length - 1] : null;
    const lastClosed = closedBars.length > 0 ? closedBars[closedBars.length - 1] : null;
    const complete = !!(lastBar && ratio > 1 && lastBar._count >= ratio);
    state.htf[tf.label] = {
      ratio,
      candles: bars.length,
      closedCandles: closedBars.length,
      lastEpoch: lastBar ? lastBar.epoch : null,
      lastClosedEpoch: lastClosed ? lastClosed.epoch : null,
      complete
    };
    const ltfEpoch = ltf && Number.isFinite(ltf.epoch) ? ltf.epoch : null;
    let aligned = false;
    let htfEpoch = null;
    if (ltfEpoch != null) {
      const bucketStart = Math.floor(ltfEpoch / tf.sec) * tf.sec;
      const matched = bars.find(b => b && b.epoch === bucketStart) || null;
      aligned = !!matched;
      htfEpoch = matched ? matched.epoch : bucketStart;
    }
    state.alignment[tf.label] = { ltfEpoch, htfEpoch, aligned };
  }

  state.waitingForClose = {
    enabled: candleCloseOnlyEnabled === true,
    lastLtfEpoch: ltf ? ltf.epoch : null
  };
  markMtfPipelineStage("higher_timeframe_retrieval", {
    symbol: state.symbol,
    availableTimeframes: state.availableTimeframes,
    htf: state.htf,
    waitingForClose: state.waitingForClose
  });
}

function checkMtfFilterFeasibility() {
  const prof = getStrategyProfitParams();
  const rr = prof && Number.isFinite(prof.rrMTFMin) ? prof.rrMTFMin : 0;
  const maxDrift = getMaxEntryDriftAtr(getActiveSymbol(), getCurrentGranularitySec(), true);
  const reasons = [];
  if (!Number.isFinite(rr) || rr <= 0) reasons.push("invalid_rr_threshold");
  if (!Number.isFinite(maxDrift) || maxDrift <= 0) reasons.push("invalid_entry_drift_threshold");
  if (!Number.isFinite(MTF_RETEST_LOOKBACK) || MTF_RETEST_LOOKBACK < 1) reasons.push("invalid_retest_window");
  return { pass: reasons.length === 0, reasons, rr, maxDrift };
}

/**
 * Synthesise higher-timeframe candles by grouping `ratio` consecutive base
 * candles into a single OHLC bar.  Uses the global `candles` array.
 */
/**
 * Synthesise higher-timeframe candles by grouping `ratio` consecutive base
 * candles into a single OHLC bar.
 *
 * #18: Uses epoch-based grouping (floor(epoch / (ratio × gran))) so the
 * synthetic bars align to real clock boundaries (e.g. a ×16 group on a 1-min
 * chart produces true 16-min bars starting on the hour) rather than counting
 * candles from an arbitrary array offset, which produced misaligned bars.
 */
function synthesizeTfCandles(ratio, options = {}) {
  if (!candles || candles.length < ratio || ratio < 2) return candles ? candles.slice() : [];
  const closedOnly = options.closedOnly === true;
  const includeMeta = options.includeMeta === true;
  /* Determine the base granularity from the UI selector (seconds) */
  const gran = getCurrentGranularitySec();
  const bucketSize = ratio * gran;  /* bucket width in seconds */
  const buckets = new Map();  /* key = bucket epoch → OHLC accumulator */
  for (const c of candles) {
    const key = Math.floor(c.epoch / bucketSize) * bucketSize;
    if (!buckets.has(key)) {
      buckets.set(key, { epoch: key, open: c.open, high: c.high, low: c.low, close: c.close, _count: 1 });
    } else {
      const b = buckets.get(key);
      if (c.high > b.high) b.high = c.high;
      if (c.low  < b.low)  b.low  = c.low;
      b.close = c.close;  /* last candle in the bucket becomes the close */
      b._count++;
    }
  }
  /* Return buckets in chronological order */
  const out = Array.from(buckets.values()).sort((a, b) => a.epoch - b.epoch);
  if (closedOnly) {
    while (out.length > 0 && out[out.length - 1]._count < ratio) out.pop();
  }
  if (includeMeta) return out;
  return out.map(({ _count, ...bar }) => bar);
}

/**
 * Determine the higher-timeframe directional bias from the synthesised "4H"
 * candle set.  Compares average highs and lows across first vs second half
 * of the MTF_BIAS_LOOKBACK window.
 *
 * @returns {"BULL"|"BEAR"|"NEUTRAL"}
 */
function computeMtfBias() {
  const biasBars = synthesizeTfCandles(MTF_BIAS_TF_MULT, { closedOnly: true });
  if (biasBars.length < MTF_BIAS_LOOKBACK + 2) return "NEUTRAL";

  const slice = biasBars.slice(-MTF_BIAS_LOOKBACK);
  const highs  = slice.map(c => c.high);
  const lows   = slice.map(c => c.low);
  const n   = highs.length;
  const mid = Math.floor(n / 2);
  if (mid === 0 || mid >= n) return "NEUTRAL"; /* guard against edge cases */

  const avgHighFirst  = highs.slice(0, mid).reduce((a, b) => a + b, 0) / mid;
  const avgHighSecond = highs.slice(mid).reduce((a, b) => a + b, 0) / (n - mid);
  const avgLowFirst   = lows.slice(0, mid).reduce((a, b) => a + b, 0) / mid;
  const avgLowSecond  = lows.slice(mid).reduce((a, b) => a + b, 0) / (n - mid);

  const risingHighs  = avgHighSecond > avgHighFirst;
  const risingLows   = avgLowSecond  > avgLowFirst;
  const fallingHighs = avgHighSecond < avgHighFirst;
  const fallingLows  = avgLowSecond  < avgLowFirst;

  if (risingHighs && risingLows)   return "BULL";
  if (fallingHighs && fallingLows) return "BEAR";
  return "NEUTRAL";
}

/**
 * Detect a 1H-equivalent setup: price consolidates then breaks out in the
 * direction of the 4H bias.
 *
 * @returns {{ dir, level, rangeHigh, rangeLow }|null}
 */
function detectMtfSetup() {
  const bias = computeMtfBias();
  if (bias === "NEUTRAL") {
    recordMtfRejection("neutral_bias", { symbol: getActiveSymbol(), conditions: { bias: "FAIL" } });
    return null;
  }

  const setupBars = synthesizeTfCandles(MTF_SETUP_TF_MULT, { closedOnly: true });
  if (setupBars.length < MTF_SETUP_LOOKBACK + 2) {
    recordMtfRejection("insufficient_htf_setup_bars", {
      symbol: getActiveSymbol(),
      setupBars: setupBars.length,
      required: MTF_SETUP_LOOKBACK + 2,
      conditions: { bias: "PASS", setupBars: "FAIL" }
    });
    return null;
  }

  /* Consolidation range: all but last two bars */
  const rangeBars = setupBars.slice(-MTF_SETUP_LOOKBACK - 2, -2);
  const rangeHigh = Math.max(...rangeBars.map(c => c.high));
  const rangeLow  = Math.min(...rangeBars.map(c => c.low));
  if (rangeHigh <= rangeLow) {
    recordMtfRejection("invalid_setup_range", {
      symbol: getActiveSymbol(),
      rangeHigh,
      rangeLow,
      conditions: { bias: "PASS", setupBars: "PASS", range: "FAIL" }
    });
    return null;
  }

  const last = setupBars[setupBars.length - 1];
  const breakoutEpoch = last ? last.epoch : null;

  if (bias === "BULL" && last.close > rangeHigh) {
    markMtfPipelineStage("mtf_confirmation", {
      symbol: getActiveSymbol(),
      bias,
      rangeHigh,
      rangeLow,
      breakoutEpoch
    });
    return { dir: "BULL", level: rangeHigh, rangeHigh, rangeLow, breakoutEpoch };
  }
  if (bias === "BEAR" && last.close < rangeLow) {
    markMtfPipelineStage("mtf_confirmation", {
      symbol: getActiveSymbol(),
      bias,
      rangeHigh,
      rangeLow,
      breakoutEpoch
    });
    return { dir: "BEAR", level: rangeLow, rangeHigh, rangeLow, breakoutEpoch };
  }
  recordMtfRejection("setup_breakout_not_confirmed", {
    symbol: getActiveSymbol(),
    bias,
    lastClose: last ? last.close : null,
    rangeHigh,
    rangeLow,
    conditions: { bias: "PASS", setupBars: "PASS", breakout: "FAIL" }
  });
  return null;
}

function getMtfSetupState() {
  const latest = detectMtfSetup();
  const idx = candles.length - 1;
  if (mtfSetupState && Number.isFinite(mtfSetupState.expiresAfterIdx) && idx > mtfSetupState.expiresAfterIdx) {
    logSignalEngineDebug("MTF_SETUP_EXPIRED", {
      dir: mtfSetupState.dir,
      level: mtfSetupState.level,
      breakoutEpoch: mtfSetupState.breakoutEpoch,
      idx
    });
    if (mtfSetupState.breakoutEpoch != null) mtfTerminalBreakoutEpoch = mtfSetupState.breakoutEpoch;
    mtfSetupState = null;
  }
  if (latest) {
    const sameSetup = mtfSetupState &&
      mtfSetupState.breakoutEpoch != null &&
      latest.breakoutEpoch != null &&
      mtfSetupState.breakoutEpoch === latest.breakoutEpoch &&
      mtfSetupState.dir === latest.dir;
    if (sameSetup) {
      logSignalEngineDebug("MTF_SETUP_REUSED", {
        dir: mtfSetupState.dir,
        level: mtfSetupState.level,
        breakoutEpoch: mtfSetupState.breakoutEpoch,
        expiresAfterIdx: mtfSetupState.expiresAfterIdx,
        idx
      });
      return mtfSetupState;
    }
    if (latest.breakoutEpoch != null && mtfTerminalBreakoutEpoch != null && latest.breakoutEpoch === mtfTerminalBreakoutEpoch) {
      logSignalEngineDebug("MTF_SETUP_TERMINAL", {
        dir: latest.dir,
        level: latest.level,
        breakoutEpoch: latest.breakoutEpoch,
        idx
      });
      return null;
    }
    mtfSetupState = Object.assign({}, latest, {
      setupDetectedIdx: idx,
      expiresAfterIdx: idx + (MTF_RETEST_LOOKBACK * 4)
    });
    mtfTerminalBreakoutEpoch = null;
    logSignalEngineDebug("MTF_SETUP_DETECTED", {
      dir: latest.dir,
      level: latest.level,
      breakoutEpoch: latest.breakoutEpoch,
      setupDetectedIdx: idx
    });
    return mtfSetupState;
  }
  if (mtfSetupState && Number.isFinite(mtfSetupState.expiresAfterIdx) && idx <= mtfSetupState.expiresAfterIdx) {
    logSignalEngineDebug("MTF_SETUP_REUSED", {
      dir: mtfSetupState.dir,
      level: mtfSetupState.level,
      breakoutEpoch: mtfSetupState.breakoutEpoch,
      expiresAfterIdx: mtfSetupState.expiresAfterIdx,
      idx
    });
    return mtfSetupState;
  }
  return null;
}

/**
 * Detect a current-TF retest of the 1H broken level.
 * A retest: price returns within ATR tolerance of the level then closes
 * back on the breakout side.
 *
 * @returns {{ dir, level, retestCandleIdx }|null}
 */
function detectMtfConfirmation(setupOverride = null) {
  const symbol = getActiveSymbol();
  const diag = getMtfPipelineState(symbol);
  const setup = setupOverride || getMtfSetupState();
  if (!setup) {
    logSignalEngineDebug("MTF_CONFIRMATION_BLOCKED", { reason: "no_setup_state" });
    recordMtfRejection("no_setup_state", { symbol, conditions: { setupState: "FAIL" } });
    return null;
  }

  const len = candles.length;
  if (len < 5) {
    logSignalEngineDebug("MTF_CONFIRMATION_BLOCKED", { reason: "insufficient_base_candles", len });
    recordMtfRejection("insufficient_base_candles", {
      symbol,
      len,
      conditions: { setupState: "PASS", baseCandles: "FAIL" }
    });
    return null;
  }

  const { dir, level } = setup;
  const tolerance = atrValue > 0 ? atrValue * 0.5 : level * 0.002;
  const latest = candles[len - 1];
  const gran = getCurrentGranularitySec();
  const setupRatio = Math.max(1, MTF_SETUP_TF_MULT);
  const htfSec = Math.max(gran, gran * setupRatio);
  const ltfEpoch = latest && Number.isFinite(latest.epoch) ? latest.epoch : null;
  const setupBuckets = setupRatio === 1
    ? (candles || []).map((c) => ({ epoch: c.epoch, _count: 1 }))
    : synthesizeTfCandles(setupRatio, { includeMeta: true });
  const currentBucket = ltfEpoch != null
    ? setupBuckets.find((b) => b && ltfEpoch >= b.epoch && ltfEpoch < (b.epoch + htfSec))
    : null;
  const htfEpoch = currentBucket ? currentBucket.epoch : null;
  const aligned = !!(currentBucket && (setupRatio === 1 || (currentBucket._count || 0) > 0));
  diag.conditions = {
    setupState: "PASS",
    baseCandles: "PASS",
    ltfHtfAlignment: aligned ? "PASS" : "FAIL"
  };
  markMtfPipelineStage("mtf_confirmation", {
    symbol,
    ltfEpoch,
    htfEpoch,
    aligned,
    dir,
    level,
    tolerance
  });
  logSignalEngineDebug("MTF_ALIGNMENT", {
    symbol,
    gran,
    ltfEpoch,
    htfEpoch,
    aligned
  });

  const scanStart = Math.max(0, len - 1 - MTF_RETEST_LOOKBACK);
  for (let i = scanStart; i < len - 1; i++) {
    const c = candles[i];
    if (!c) continue;
    if (dir === "BULL") {
      if (c.low <= level + tolerance && c.close >= level) {
        logSignalEngineDebug("MTF_CONFIRMATION_MATCH", { dir, level, retestCandleIdx: i, tolerance });
        diag.conditions.retestTouch = "PASS";
        diag.conditions.retestClose = "PASS";
        return { dir, level, retestCandleIdx: i, setup };
      }
    } else {
      if (c.high >= level - tolerance && c.close <= level) {
        logSignalEngineDebug("MTF_CONFIRMATION_MATCH", { dir, level, retestCandleIdx: i, tolerance });
        diag.conditions.retestTouch = "PASS";
        diag.conditions.retestClose = "PASS";
        return { dir, level, retestCandleIdx: i, setup };
      }
    }
  }
  logSignalEngineDebug("MTF_CONFIRMATION_BLOCKED", {
    reason: "no_retest_match",
    dir,
    level,
    tolerance,
    scanStart,
    len
  });
  recordMtfRejection("no_retest_match", {
    symbol,
    dir,
    level,
    tolerance,
    ltfEpoch,
    htfEpoch,
    aligned,
    conditions: Object.assign({}, diag.conditions, { retestTouch: "FAIL", retestClose: "FAIL" })
  });
  return null;
}

/**
 * Main MTF Top-Down signal detector.
 * Looks for a pin bar, engulfing candle, or micro break-of-structure at the
 * confirmed retest zone.
 *
 * @returns {Object|null}
 */
function detectMtfTopDown(confirmationOverride = null) {
  const symbol = getActiveSymbol();
  const baseConditions = {};
  if (!mtfTopDownEnabled) return null;
  if (!isSymbolEligibleForNewSignal(symbol, "mtf_top_down")) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "symbol_not_eligible" });
    recordMtfRejection("symbol_not_eligible", { symbol, conditions: { symbolEligibility: "FAIL" } });
    return null;
  }
  baseConditions.symbolEligibility = "PASS";
  if (!candles || candles.length < MTF_REQUIRED_BASE_CANDLES) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "insufficient_candles", candles: candles ? candles.length : 0, required: MTF_REQUIRED_BASE_CANDLES });
    recordMtfRejection("insufficient_candles", {
      symbol,
      candles: candles ? candles.length : 0,
      required: MTF_REQUIRED_BASE_CANDLES,
      conditions: Object.assign({}, baseConditions, { warmup: "FAIL" })
    });
    return null;
  }
  baseConditions.warmup = "PASS";

  const idx = candles.length - 1;
  const feasibility = checkMtfFilterFeasibility();
  if (!feasibility.pass) {
    recordMtfRejection("impossible_filter", {
      symbol,
      reasons: feasibility.reasons.slice(),
      conditions: Object.assign({}, baseConditions, { feasibility: "FAIL" })
    });
    return null;
  }
  baseConditions.feasibility = "PASS";

  if (idx - lastMtfTopDownIdx < MTF_TOP_DOWN_COOLDOWN) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "cooldown", idx, lastMtfTopDownIdx });
    recordMtfRejection("cooldown", {
      symbol,
      idx,
      lastMtfTopDownIdx,
      conditions: Object.assign({}, baseConditions, { cooldown: "FAIL" })
    });
    return null;
  }
  baseConditions.cooldown = "PASS";
  if (mtfTopDownHistory.some(s => s.result === "PENDING")) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "pending_signal_exists" });
    recordMtfRejection("pending_signal_exists", {
      symbol,
      conditions: Object.assign({}, baseConditions, { pendingGate: "FAIL" })
    });
    return null;
  }
  baseConditions.pendingGate = "PASS";

  const confirmation = confirmationOverride || detectMtfConfirmation();
  if (!confirmation) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "no_confirmation" });
    recordMtfRejection("no_confirmation", {
      symbol,
      conditions: Object.assign({}, baseConditions, { confirmation: "FAIL" })
    });
    return null;
  }
  baseConditions.confirmation = "PASS";

  const { dir, level, retestCandleIdx, setup } = confirmation;
  if (idx - retestCandleIdx > 3) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "confirmation_window_expired", idx, retestCandleIdx });
    recordMtfRejection("confirmation_window_expired", {
      symbol,
      idx,
      retestCandleIdx,
      conditions: Object.assign({}, baseConditions, { confirmationWindow: "FAIL" })
    });
    return null;
  }
  baseConditions.confirmationWindow = "PASS";

  const c = candles[idx];
  const prev = candles[idx - 1];
  if (!c || !prev) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "missing_current_or_prev_candle", idx });
    recordMtfRejection("missing_candle_context", {
      symbol,
      idx,
      conditions: Object.assign({}, baseConditions, { candleContext: "FAIL" })
    });
    return null;
  }
  baseConditions.candleContext = "PASS";
  const entryDriftAtr = atrValue > 0 ? Math.abs(c.close - level) / atrValue : Number.NaN;
  const maxEntryDriftAtr = getMaxEntryDriftAtr(symbol, getCurrentGranularitySec(), true);
  if (atrValue > 0 && entryDriftAtr > maxEntryDriftAtr) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", {
      reason: "entry_drift_too_large",
      entryDriftAtr,
      maxEntryDriftAtr
    });
    recordMtfRejection("entry_drift_too_large", {
      symbol,
      entryDriftAtr,
      maxEntryDriftAtr,
      conditions: Object.assign({}, baseConditions, { entryDrift: "FAIL" })
    });
    return null;
  }
  baseConditions.entryDrift = "PASS";
  const entryMode = getCurrentEntryMode();
  const timingQuality = evaluateEntryTimingQuality(dir, c, level, atrValue, {
    symbol,
    granSec: getCurrentGranularitySec(),
    entryMode
  });
  if (!timingQuality.pass) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "timing_quality_gate", detail: timingQuality.reason || null });
    recordMtfRejection("timing_quality_gate", {
      symbol,
      detail: timingQuality.reason || null,
      conditions: Object.assign({}, baseConditions, { timingQuality: "FAIL" })
    });
    return null;
  }
  baseConditions.timingQuality = "PASS";
  const recentLossPause = shouldPauseAfterRecentLosses(mtfTopDownHistory, {
    symbol,
    dir,
    strategyType: "mtf_top_down",
    timeframeSec: getCurrentGranularitySec()
  });
  if (recentLossPause.block) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "recent_loss_pause", detail: recentLossPause.reason || null });
    recordMtfRejection("recent_loss_pause", {
      symbol,
      detail: recentLossPause.reason || null,
      conditions: Object.assign({}, baseConditions, { recentLossPause: "FAIL" })
    });
    return null;
  }
  baseConditions.recentLossPause = "PASS";

  const hasPinBar = isPinBar(c, dir);
  const hasBullEngulf = dir === "BULL" && isBullishEngulfing(prev, c);
  const hasBearEngulf = dir === "BEAR" && isBearishEngulfing(prev, c);
  const microBosBull = dir === "BULL" && c.close > prev.high && c.close > c.open;
  const microBosBear = dir === "BEAR" && c.close < prev.low && c.close < c.open;
  if (!hasPinBar && !hasBullEngulf && !hasBearEngulf && !microBosBull && !microBosBear) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "pattern_not_confirmed" });
    recordMtfRejection("pattern_not_confirmed", {
      symbol,
      conditions: Object.assign({}, baseConditions, {
        pinBar: "FAIL",
        engulfing: "FAIL",
        microBos: "FAIL"
      })
    });
    return null;
  }
  baseConditions.pinBar = hasPinBar ? "PASS" : "FAIL";
  baseConditions.engulfing = (hasBullEngulf || hasBearEngulf) ? "PASS" : "FAIL";
  baseConditions.microBos = (microBosBull || microBosBear) ? "PASS" : "FAIL";

  const patternType = hasPinBar ? "pin_bar"
    : (hasBullEngulf || hasBearEngulf) ? "engulfing"
    : "micro_bos";

  const entry = c.close;
  const _profParams = getStrategyProfitParams();
  const _mtfRR = _profParams.rrMTFMin;
  const atrRef = Number.isFinite(atrValue) && atrValue > 0 ? atrValue : null;
  const slBufferAtr = MTF_SL_ATR_BUFFER + getVolatilityAdjustedStopBufferAtr(symbol, getCurrentGranularitySec(), { volumeSpike: true });
  const slBuffer = (atrRef || 0) * slBufferAtr * ((_profParams && _profParams.slBufferMult) || 1);
  markMtfPipelineStage("indicator_calculation", {
    symbol,
    atrValue: atrRef,
    entryDriftAtr,
    maxEntryDriftAtr,
    timingQuality,
    rrTarget: _mtfRR
  });
  const biasSlice = synthesizeTfCandles(MTF_BIAS_TF_MULT, { closedOnly: true }).slice(-MTF_BIAS_LOOKBACK);
  const execution = computeMtfExecutionLevels({
    dir,
    entry,
    level,
    idx,
    retestCandleIdx,
    currentCandle: c,
    atrRef,
    rrTarget: _mtfRR,
    stopBuffer: slBuffer,
    biasSlice
  });
  const sl = execution.stopLoss;
  const tp = execution.takeProfit;
  const risk = Number.isFinite(entry) && Number.isFinite(sl) ? Math.abs(entry - sl) : NaN;
  if (!execution.valid || !(risk > 0)) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "invalid_risk", entry, sl });
    recordMtfRejection("invalid_risk", {
      symbol,
      entry,
      sl,
      conditions: Object.assign({}, baseConditions, { risk: "FAIL" })
    });
    return null;
  }
  baseConditions.risk = "PASS";
  const rr = execution.riskReward;
  const mtfBias = computeMtfBias();

  const signal = {
    dir, entry, sl, tp, rr, level, retestCandleIdx,
    stopLoss: sl,
    takeProfit: tp,
    riskReward: rr,
    mtfBias,
    patternType,
    candleIdx: idx,
    epoch: c.epoch,
    time: Number.isFinite(c.epoch) ? new Date(c.epoch * 1000).toISOString() : new Date().toISOString(),
    symbol,
    timeframeSec: getCurrentGranularitySec(),
    result: "PENDING",
    type: "mtf_top_down",
    strategyType: "mtf_top_down",
    breakoutEpoch: setup && setup.breakoutEpoch != null ? setup.breakoutEpoch : null,
    volatilityRegime: getCurrentRegimeTag(),
    validUntilMs: Date.now() + getSignalValidityMs(),
    maxEntryDistanceAtr: getSignalDistanceLimitAtr(),
    entryDriftAtr,
    stopBufferAtr: slBufferAtr * (_profParams.slBufferMult || 1),
    entryMode,
    entryProgressAtr: timingQuality.progressAtr,
    entryBodyAtr: timingQuality.bodyAtr,
    entryCloseLocation: timingQuality.closeLocation,
    atr: execution.atr,
    atrAtSignal: execution.atr,
    tradeManagement: Object.assign({
      strategy: "mtf_top_down",
      validUntilMs: Date.now() + getSignalValidityMs()
    }, execution.tradeManagement || {})
  };
  const hasExecutionAtr = Number.isFinite(execution.atr) && execution.atr > 0;
  const atrDistanceWithinThreshold = hasExecutionAtr && Number.isFinite(entryDriftAtr) && entryDriftAtr <= maxEntryDriftAtr;
  signal.triggerFactors = [
    buildNamedTriggerFactor("HTF Trend Alignment", mtfBias === "BULL" ? "Bullish" : "Bearish", "MTF Confirmation", 15),
    buildNamedTriggerFactor("HTF Breakout Confirmed", null, "Breakout Quality", 15),
    buildNamedTriggerFactor("LTF Retest Completed", null, "Retest Quality", 14),
    buildNamedTriggerFactor("Entry Pattern Trigger", patternType === "pin_bar" ? "Pin Bar" : patternType === "engulfing" ? "Engulfing" : "Micro BOS", "Structure Strength", 14),
    buildNamedTriggerFactor("ATR Volatility Acceptable", null, "ATR Confirmation", 8, atrDistanceWithinThreshold),
    buildNamedTriggerFactor("Distance From Entry Within Threshold", Number.isFinite(entryDriftAtr) ? `${Math.round(entryDriftAtr * 100) / 100} ATR` : null, "ATR Confirmation", 8, atrDistanceWithinThreshold),
    buildNamedTriggerFactor("Confluence Score", `${Math.round(computeConfluenceScore(dir, entry, idx) / 16 * 100)}%`, "Confluence Score", 0, true, { persist: false })
  ];
  if (!Number.isFinite(signal.entry) || !Number.isFinite(signal.stopLoss) || !Number.isFinite(signal.takeProfit)) {
    logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "missing_execution_levels", entry: signal.entry, stopLoss: signal.stopLoss, takeProfit: signal.takeProfit });
    recordMtfRejection("missing_execution_levels", {
      symbol,
      entry: signal.entry,
      stopLoss: signal.stopLoss,
      takeProfit: signal.takeProfit,
      conditions: Object.assign({}, baseConditions, { executionLevels: "FAIL" })
    });
    return null;
  }
  stampSignalLifecycle(signal);
  const state = getMtfPipelineState(symbol);
  state.conditions = Object.assign({}, state.conditions || {}, baseConditions, { signalGenerated: "PASS" });
  state.lastRejection = null;
  state.lastSignal = signal;
  logSignalEngineDebug("MTF_CONDITION_BREAKDOWN", {
    symbol,
    signalId: signal.signalId,
    conditions: state.conditions
  });
  logSignalEngineDebug("MTF_SIGNAL_GENERATED", {
    signalId: signal.signalId,
    dir: signal.dir,
    entry: signal.entry,
    sl: signal.sl,
    tp: signal.tp,
    rr: signal.rr
  });
  return signal;
}

/**
 * Run the MTF Top-Down scanner and handle all alerting.
 */
function processMtfTopDown() {
  const symbol = getActiveSymbol();
  if (!mtfTopDownEnabled && !mtfDebugMode) return;
  markMtfPipelineStage("data_feed", {
    symbol,
    candles: candles ? candles.length : 0,
    granularitySec: getCurrentGranularitySec()
  });
  markMtfPipelineStage("candle_aggregation", {
    symbol,
    ltfCandles: candles ? candles.length : 0,
    requiredWarmup: MTF_REQUIRED_BASE_CANDLES
  });
  captureMtfHtfDiagnostics(symbol);
  if (!mtfTopDownEnabled) return;
  const setup = getMtfSetupState();
  if (setup && !_historicalProcessing) {
    const setupKey = [getActiveSymbol(), setup.dir, fmt(setup.level, 6), setup.breakoutEpoch || ""].join("|");
    if (setupKey !== lastMtfSetupAlertKey) {
      lastMtfSetupAlertKey = setupKey;
      sendSignalLifecycleTelegram("setup", {
        channel: "strategy",
        strategyLabel: "MTF Top-Down",
        symbol: getActiveSymbol(),
        timeframeSec: getCurrentGranularitySec(),
        dir: setup.dir,
        level: setup.level,
        entry: setup.level,
        maxDistanceAtr: getSignalDistanceLimitAtr(),
        validUntilMs: Date.now() + getSignalValidityMs(),
        reason: "Higher-timeframe breakout is confirmed; wait for the lower-timeframe retest."
      });
    }
  }
  const confirmation = detectMtfConfirmation(setup);
  if (confirmation && !_historicalProcessing) {
    const approachKey = [getActiveSymbol(), confirmation.dir, fmt(confirmation.level, 6), confirmation.retestCandleIdx].join("|");
    if (approachKey !== lastMtfApproachAlertKey) {
      lastMtfApproachAlertKey = approachKey;
      const currentPrice = candles.length > 0 ? candles[candles.length - 1].close : null;
      sendSignalLifecycleTelegram("approaching", {
        channel: "strategy",
        strategyLabel: "MTF Top-Down",
        symbol: getActiveSymbol(),
        timeframeSec: getCurrentGranularitySec(),
        dir: confirmation.dir,
        level: confirmation.level,
        entry: confirmation.level,
        distanceAtr: getSignalDistanceFromEntry({ entry: confirmation.level, atrAtSignal: getAtrReference() }, currentPrice),
        maxDistanceAtr: getSignalDistanceLimitAtr(),
        validUntilMs: Date.now() + getSignalValidityMs(),
        reason: "Retest held at the MTF level; wait for the trigger candle."
      });
    }
  }
  const signal = detectMtfTopDown(confirmation);
  if (!signal) {
    const state = getMtfPipelineState(symbol);
    const breakdown = getMtfRejectionBreakdown(state);
    const topReason = breakdown.length > 0 ? `${breakdown[0].reason} (${breakdown[0].percent}%)` : "none";
    if (mtfDebugMode) {
      const alignFail = Object.entries(state.alignment || {}).filter(([, v]) => v && v.aligned === false).map(([k]) => k);
      pushMtfDebugRow({
        symbol,
        strategy: "MTF Top-Down",
        mtfStatus: "REJECTED",
        ltfSignal: "FAIL",
        htfSummary: `${Object.keys(state.htf || {}).length} TF`,
        rejectionReason: state.lastRejection ? state.lastRejection.reason : "unknown",
        alignment: alignFail.length > 0 ? `MISS:${alignFail.join(",")}` : "PASS",
        time: new Date().toISOString().slice(11, 19)
      });
    }
    logSignalEngineDebug("MTF_REJECTION_STATS", { symbol, topReason, breakdown: breakdown.slice(0, 5) });
    return;
  }
  stampSignalLifecycle(signal);

  /* Min Confluence Gate */
  if (minConfluenceEnabled) {
    const confGate = checkConfluenceGate(signal.dir, signal.entry, signal.candleIdx);
    if (!confGate.pass) {
      addLog(`\u26a0 MTF Top-Down REJECTED \u2014 ${confGate.reason}`);
      logSignalEngineDebug("MTF_SIGNAL_FILTERED", { reason: "confluence_gate", detail: confGate.reason, signalId: signal.signalId });
      recordMtfRejection("confluence_gate", {
        symbol: signal.symbol || symbol,
        signalId: signal.signalId,
        detail: confGate.reason,
        conditions: Object.assign({}, getMtfPipelineState(signal.symbol || symbol).conditions || {}, { confluenceGate: "FAIL" })
      });
      /* Root-cause fix: previously gated on signal._sentViaTelegram, which is
         never true at this point (the signal has not been telegram-sent yet),
         so this cancellation alert could never fire. */
      sendSignalLifecycleTelegram("cancelled", {
        channel: "strategy",
        strategyLabel: "MTF Top-Down",
        signalId: signal.signalId,
        symbol: signal.symbol || getActiveSymbol(),
        timeframeSec: getCurrentGranularitySec(),
        dir: signal.dir,
        level: signal.level,
        reason: confGate.reason
      });
      return;
    }
  }

  lastMtfTopDownIdx = signal.candleIdx;
  markMtfPipelineStage("signal_validation", {
    symbol: signal.symbol || symbol,
    signalId: signal.signalId,
    status: "passed"
  });
  markMtfPipelineStage("signal_queue", {
    symbol: signal.symbol || symbol,
    signalId: signal.signalId,
    status: "queued"
  });

  /* Always compute and store confluence score on the signal for UI display */
  signal.confluenceScore = computeConfluenceScore(signal.dir, signal.entry, signal.candleIdx);
  signal._confFactors   = getActiveConfluenceFactors(signal.dir, signal.entry, signal.candleIdx);
  mergeSignalTriggerFactorDetails(signal, (signal._confFactors || []).map((factor) => {
    if (factor === "EMA Aligned") return buildNamedTriggerFactor("EMA Alignment", signal.dir === "BULL" ? "Bullish" : "Bearish", "Trend Alignment", 10);
    if (factor === "HTF Trend") return buildNamedTriggerFactor("HTF Trend Alignment", signal.dir === "BULL" ? "Bullish" : "Bearish", "MTF Confirmation", 15);
    if (factor === "Strong Breakout") return buildNamedTriggerFactor("HTF Breakout Confirmed", null, "Breakout Quality", 15);
    if (factor === "Confirm Pattern") return buildNamedTriggerFactor("Entry Pattern Trigger", signal.patternType === "pin_bar" ? "Pin Bar" : signal.patternType === "engulfing" ? "Engulfing" : "Micro BOS", "Structure Strength", 14);
    if (factor === "S/R Level") return buildNamedTriggerFactor("Market Structure Alignment", null, "Structure Strength", 10);
    if (factor === "Volume Spike") return buildNamedTriggerFactor("Volume Confirmation", null, "Volume Confirmation", 8);
    if (factor === "Momentum") return buildNamedTriggerFactor("Momentum Confirmation", null, "Momentum Score", 8);
    return buildNamedTriggerFactor(factor, null, resolveSignalFactorGroup(factor), SIGNAL_FACTOR_DEFAULT_WEIGHTS[resolveSignalFactorGroup(factor)] ?? 5);
  }));

  signal._stratOutcomeSent = false;
  signal._sentViaTelegram  = false;
  mtfTopDownHistory.unshift(signal);
  if (mtfSetupState && mtfSetupState.breakoutEpoch != null) mtfTerminalBreakoutEpoch = mtfSetupState.breakoutEpoch;
  mtfSetupState = null; /* consume setup once a trade signal is produced */
  if (mtfTopDownHistory.length > MTF_TOP_DOWN_MAX_HISTORY) mtfTopDownHistory.pop();

  playStrategyAlert(signal.dir);

  const sym = getActiveSymbol() || "--";
  const patLabel = signal.patternType === "pin_bar" ? "Pin Bar"
    : signal.patternType === "engulfing" ? "Engulfing"
    : "Micro BOS";
  const dirArrow = signal.dir === "BULL" ? "\u25b2 BUY" : "\u25bc SELL";
  addLog("\u23f1 MTF Top-Down " + dirArrow + " \u2014 " + sym + " @ " + fmtPrice(signal.entry, sym)
    + " | Bias: " + signal.mtfBias + " | Pattern: " + patLabel
    + " | Level: " + fmtPrice(signal.level, sym)
    + " | SL " + fmtPrice(signal.sl, sym)
    + " | TP " + fmtPrice(signal.tp, sym)
    + " | R:R 1:" + fmt(signal.rr, 1));
  logSignalEngineDebug("MTF_SIGNAL_QUEUED", {
    signalId: signal.signalId,
    symbol: signal.symbol || sym,
    dir: signal.dir,
    entry: signal.entry,
    sl: signal.sl,
    tp: signal.tp
  });
  /* Root-cause fix: the "Trade Activated" lifecycle notification must not
     depend on the initial "Trade Setup Detected" Telegram send succeeding.
     MTF trades enter at market (entry = close of the trigger candle), so the
     signal is activated the instant it is queued — send this independently
     so a failed/disabled/filtered setup alert can never suppress it (and,
     downstream, the TP/SL/Cancelled/Expired alerts that used to be gated on
     the setup alert's success flag). */
  logSignalEngineDebug("MTF_SIGNAL_ACTIVATED", { signalId: signal.signalId, symbol: signal.symbol || sym, dir: signal.dir, entry: signal.entry });
  void (async () => {
    let qualification = null;
    try {
      qualification = await qualifySignalForTelegram(signal, "MTF Top-Down", false, { strategy: "mtf_top_down", symbol: signal.symbol || sym, timeframeSec: signal.timeframeSec || getCurrentGranularitySec() });
    } catch (err) {
      console.warn("MTF adaptive qualification failed:", err.message);
      return;
    }
    if (!qualification || qualification.allowed !== true) return;
    sendSignalLifecycleTelegram("active", buildLifecyclePayloadFromSignal(signal, "MTF Top-Down", "strategy",
      signal.entryMode === "aggressive_intrabar"
        ? "Entry activated intrabar after the lower-timeframe trigger pushed away from the MTF level."
        : "Entry activated after the lower-timeframe trigger candle closed."));
  })();
  markMtfPipelineStage("notification_layer", {
    symbol: signal.symbol || sym,
    signalId: signal.signalId,
    notificationsEnabled,
    telegramAutoSend: telegramStrategyAutoSend
  });
  if (mtfDebugMode) {
    const state = getMtfPipelineState(signal.symbol || sym);
    const alignSummary = Object.entries(state.alignment || {}).map(([k, v]) => `${k}:${v && v.aligned ? "OK" : "MISS"}`).join(" ");
    const htfSummary = Object.entries(state.htf || {}).map(([k, v]) => `${k}:${v.closedCandles || 0}${v.complete ? "" : "*"}`).join(" ");
    pushMtfDebugRow({
      symbol: signal.symbol || sym,
      strategy: "MTF Top-Down",
      mtfStatus: "PASS",
      ltfSignal: `${signal.dir} ${signal.patternType}`,
      htfSummary,
      rejectionReason: "none",
      alignment: alignSummary || "--",
      time: new Date().toISOString().slice(11, 19)
    });
  }

  showToast(
    "MTF Top-Down " + dirArrow,
    sym + " @ " + fmtPrice(signal.entry, sym)
      + " | " + signal.mtfBias + " bias | " + patLabel
      + " at " + fmtPrice(signal.level, sym)
      + " | SL: " + fmtPrice(signal.sl, sym)
      + " | TP: " + fmtPrice(signal.tp, sym)
      + " | R:R 1:" + fmt(signal.rr, 1),
    "trade", 10000
  );

  if (notificationsEnabled && "Notification" in window && Notification.permission === "granted") {
    const body = "\u23f1 " + signal.dir + " MTF Top-Down \u2014 " + sym
      + " @ " + fmtPrice(signal.entry, sym)
      + "\nBias: " + signal.mtfBias + " | Pattern: " + patLabel
      + "\nLevel: " + fmtPrice(signal.level, sym)
      + "\nSL: " + fmtPrice(signal.sl, sym) + " | TP: " + fmtPrice(signal.tp, sym);
    throttledNotification("IT Guru: MTF Top-Down Signal!", body);
  }

  if (telegramStrategyAutoSend) {
    setTimeout(function() { sendTelegramStrategyAlert(signal); }, CHART_RENDER_DELAY_MS);
  }

  renderStrategyAlerts();

  if (autoTradeStrategyEnabled && autoTradeMtfTopDown && !_historicalProcessing) {
    logSignalEngineDebug("MTF_AUTOTRADE_TRIGGERED", { signalId: signal.signalId, symbol: signal.symbol || sym });
    executeAutoTrade({ dir: signal.dir, entry: signal.entry, sl: signal.sl, tp: signal.tp,
      symbol: signal.symbol || sym, source: "strategy", strategyName: "mtfTopDown" });
  }
}

/**
 * Monitor pending MTF Top-Down signals for SL/TP outcome.
 */
function monitorMtfTopDownOutcomes(candle) {
  if (!mtfTopDownEnabled) return;
  let changed = false;
  for (const s of mtfTopDownHistory) {
    if (s.result !== "PENDING") continue;
    const elapsed = (candles.length - 1) - s.candleIdx;

    if (elapsed < 0 || elapsed >= MTF_TOP_DOWN_MAX_CANDLES) {
      s.result = "EXPIRED";
      changed = true;
      addLog("\u23f1 MTF Top-Down EXPIRED (timeout " + MTF_TOP_DOWN_MAX_CANDLES + " candles) \u2014 " + (s.symbol || ""));
      logSignalEngineDebug("MTF_SIGNAL_EXPIRED", { signalId: s.signalId || null, reason: "timeout", symbol: s.symbol || "" });
      /* Root-cause fix: no longer gated on s._sentViaTelegram — the Expired
         lifecycle alert must fire even if the initial setup/strategy alert
         never succeeded or was filtered out. */
      sendSignalLifecycleTelegram("expired", {
        channel: "strategy",
        strategyLabel: "MTF Top-Down",
        signalId: s.signalId || null,
        symbol: s.symbol || getActiveSymbol(),
        timeframeSec: s.timeframeSec || getCurrentGranularitySec(),
        dir: s.dir,
        level: s.level,
        reason: `No trigger resolution within ${MTF_TOP_DOWN_MAX_CANDLES} candles.`
      });
      continue;
    }

    if (s.dir === "BULL") {
      if (candle.high >= s.tp) {
        s.result = "WIN"; changed = true;
        addLog("\u23f1 MTF Top-Down \u2705 WIN \u2014 " + (s.symbol || "") + " @ " + fmtPrice(s.tp, s.symbol));
        logSignalEngineDebug("MTF_SIGNAL_RESOLVED", { signalId: s.signalId || null, result: "WIN", via: "tp", symbol: s.symbol || "" });
        sendSignalLifecycleTelegram("tp", buildLifecyclePayloadFromSignal(s, "MTF Top-Down", "strategy"));
        if (telegramStrategyOutcomeSend && !s._stratOutcomeSent) sendStrategyOutcomeTelegram(s);
      } else if (candle.low <= s.sl) {
        s.result = "LOSS"; changed = true;
        addLog("\u23f1 MTF Top-Down \u274c LOSS \u2014 " + (s.symbol || "") + " @ " + fmtPrice(s.sl, s.symbol));
        logSignalEngineDebug("MTF_SIGNAL_RESOLVED", { signalId: s.signalId || null, result: "LOSS", via: "sl", symbol: s.symbol || "" });
        sendSignalLifecycleTelegram("sl", buildLifecyclePayloadFromSignal(s, "MTF Top-Down", "strategy"));
        if (telegramStrategyOutcomeSend && !s._stratOutcomeSent) sendStrategyOutcomeTelegram(s);
      }
    } else {
      if (candle.low <= s.tp) {
        s.result = "WIN"; changed = true;
        addLog("\u23f1 MTF Top-Down \u2705 WIN \u2014 " + (s.symbol || "") + " @ " + fmtPrice(s.tp, s.symbol));
        logSignalEngineDebug("MTF_SIGNAL_RESOLVED", { signalId: s.signalId || null, result: "WIN", via: "tp", symbol: s.symbol || "" });
        sendSignalLifecycleTelegram("tp", buildLifecyclePayloadFromSignal(s, "MTF Top-Down", "strategy"));
        if (telegramStrategyOutcomeSend && !s._stratOutcomeSent) sendStrategyOutcomeTelegram(s);
      } else if (candle.high >= s.sl) {
        s.result = "LOSS"; changed = true;
        addLog("\u23f1 MTF Top-Down \u274c LOSS \u2014 " + (s.symbol || "") + " @ " + fmtPrice(s.sl, s.symbol));
        logSignalEngineDebug("MTF_SIGNAL_RESOLVED", { signalId: s.signalId || null, result: "LOSS", via: "sl", symbol: s.symbol || "" });
        sendSignalLifecycleTelegram("sl", buildLifecyclePayloadFromSignal(s, "MTF Top-Down", "strategy"));
        if (telegramStrategyOutcomeSend && !s._stratOutcomeSent) sendStrategyOutcomeTelegram(s);
      }
    }
  }
  if (changed) {
    /* Send EXPIRED outcome summaries (WIN/LOSS outcome summaries are sent inline above). */
    for (const s of mtfTopDownHistory) {
      if (s.result === "EXPIRED" && !s._stratOutcomeSent && telegramStrategyOutcomeSend) {
        sendStrategyOutcomeTelegram(s);
      }
    }
    const symbol = getActiveSymbol();
    const hasPending = mtfTopDownHistory.some(s => s && s.result === "PENDING" && (s.symbol || symbol) === symbol);
    logSignalEngineDebug("MTF_SYMBOL_LOCK_STATUS", {
      symbol,
      locked: hasPending,
      reason: hasPending ? "pending_signal_exists" : "all_signals_resolved_or_expired"
    });
    if (!hasPending) {
      markMtfPipelineStage("signal_validation", { symbol, lockReleased: true, reason: "mtf_outcome_resolved" });
    }
    renderStrategyAlerts();
    /* Feature 13: record confluence factor outcomes for adaptive weighting */
    if (adaptiveConfluenceEnabled) {
      for (const s of mtfTopDownHistory) {
        if ((s.result === "WIN" || s.result === "LOSS") && !s._confRecorded) {
          if (recordConfluenceOutcome(s._confFactors || [], s.result, s.adaptiveScopeKey)) {
            s._confRecorded = true;
          }
        }
      }
    }
  }
}

/* ================= STRATEGY 14: CANDLESTICK INTERPRETATION (Market Narrative) ================= */

/**
 * Classify a single candle's order-flow story.
 * Returns an object describing who controlled the candle and how.
 *
 * @param {Object} c - Candle {open, high, low, close}
 * @returns {{ control, rejection, conviction, bodyRatio, upperWickRatio, lowerWickRatio, desc }}
 *   control: "BULL" | "BEAR" | "NEUTRAL"
 *   rejection: "UPPER" | "LOWER" | "BOTH" | "NONE"
 *   conviction: "STRONG" | "MODERATE" | "WEAK" | "INDECISION"
 *   desc: human-readable narrative
 */
function classifyCandle(c) {
  if (!c) return null;
  const range = c.high - c.low;
  if (range <= 0) return { control: "NEUTRAL", rejection: "NONE", conviction: "INDECISION", bodyRatio: 0, upperWickRatio: 0, lowerWickRatio: 0, desc: "Zero-range candle — no activity" };

  const body = Math.abs(c.close - c.open);
  const bodyRatio = body / range;
  const isBullish = c.close >= c.open;

  const upperWick = c.high - Math.max(c.open, c.close);
  const lowerWick = Math.min(c.open, c.close) - c.low;
  const upperWickRatio = upperWick / range;
  const lowerWickRatio = lowerWick / range;

  /* Body position: how far the body center is from candle midpoint */
  const bodyCenter = (c.open + c.close) / 2;
  const candleCenter = (c.high + c.low) / 2;

  let control = "NEUTRAL";
  let rejection = "NONE";
  let conviction = "MODERATE";
  let desc = "";

  /* Institutional Conviction (Marubozu-type): large body, minimal wicks */
  if (bodyRatio >= 0.85 && upperWickRatio < 0.08 && lowerWickRatio < 0.08) {
    control = isBullish ? "BULL" : "BEAR";
    conviction = "STRONG";
    desc = isBullish
      ? "Institutional bullish conviction — buyers dominated open to close with no pushback"
      : "Institutional bearish conviction — sellers dominated open to close with no pushback";
    return { control, rejection: "NONE", conviction, bodyRatio, upperWickRatio, lowerWickRatio, desc };
  }

  /* Bullish Control: close near high, strong body, minimal upper wick */
  if (isBullish && bodyRatio >= 0.6 && upperWickRatio < 0.15) {
    control = "BULL";
    conviction = bodyRatio >= 0.75 ? "STRONG" : "MODERATE";
    desc = "Bullish control — buyers pushed price higher with minimal seller resistance at the top";
  }
  /* Bearish Control: close near low, strong body, minimal lower wick */
  else if (!isBullish && bodyRatio >= 0.6 && lowerWickRatio < 0.15) {
    control = "BEAR";
    conviction = bodyRatio >= 0.75 ? "STRONG" : "MODERATE";
    desc = "Bearish control — sellers pushed price lower with minimal buyer defense at the bottom";
  }
  /* Upper Wick Rejection: long upper wick, sellers rejected higher prices */
  else if (upperWickRatio >= 0.5 && upperWickRatio > lowerWickRatio * 1.5) {
    control = "BEAR";
    rejection = "UPPER";
    conviction = bodyRatio < 0.2 ? "WEAK" : "MODERATE";
    desc = "Upper wick rejection — sellers aggressively rejected higher prices, potential supply zone";
  }
  /* Lower Wick Rejection: long lower wick, buyers defended lower prices */
  else if (lowerWickRatio >= 0.5 && lowerWickRatio > upperWickRatio * 1.5) {
    control = "BULL";
    rejection = "LOWER";
    conviction = bodyRatio < 0.2 ? "WEAK" : "MODERATE";
    desc = "Lower wick rejection — buyers defended lower prices, potential demand zone";
  }
  /* Indecision: small body, wicks on both sides */
  else if (bodyRatio < 0.3 && upperWickRatio > 0.25 && lowerWickRatio > 0.25) {
    control = "NEUTRAL";
    rejection = "BOTH";
    conviction = "INDECISION";
    desc = "Indecision — neither buyers nor sellers established control, equal rejection on both sides";
  }
  /* Default moderate classification */
  else {
    control = isBullish ? "BULL" : "BEAR";
    conviction = "WEAK";
    desc = isBullish
      ? "Weak bullish — buyers slightly favored but no decisive control"
      : "Weak bearish — sellers slightly favored but no decisive control";
  }

  return { control, rejection, conviction, bodyRatio, upperWickRatio, lowerWickRatio, desc };
}

/**
 * Detect key levels from the MTF (4× base) synthesised candles.
 * Returns an array of { price, type: "SUPPORT"|"RESISTANCE"|"BOTH", strength }
 */
function detectCandleInterpKeyLevels() {
  const mtfBars = synthesizeTfCandles(CANDLE_INTERP_MTF_MULT);
  if (mtfBars.length < CANDLE_INTERP_MTF_LOOKBACK) return [];

  const slice = mtfBars.slice(-CANDLE_INTERP_MTF_LOOKBACK);
  const levels = [];
  const tolerance = atrValue > 0 ? atrValue * 0.3 : 0;

  /* Scan for swing highs and swing lows as key levels */
  for (let i = 2; i < slice.length - 2; i++) {
    const prev2 = slice[i - 2], prev1 = slice[i - 1], curr = slice[i], next1 = slice[i + 1], next2 = slice[i + 2];

    /* Swing High (resistance) */
    if (curr.high > prev1.high && curr.high > prev2.high && curr.high > next1.high && curr.high > next2.high) {
      levels.push({ price: curr.high, type: "RESISTANCE", strength: 1 });
    }
    /* Swing Low (support) */
    if (curr.low < prev1.low && curr.low < prev2.low && curr.low < next1.low && curr.low < next2.low) {
      levels.push({ price: curr.low, type: "SUPPORT", strength: 1 });
    }
  }

  /* Also add session/previous candle highs and lows */
  const lastMTF = slice[slice.length - 1];
  if (lastMTF) {
    levels.push({ price: lastMTF.high, type: "RESISTANCE", strength: 0.5 });
    levels.push({ price: lastMTF.low, type: "SUPPORT", strength: 0.5 });
  }

  /* Merge nearby levels */
  const merged = [];
  for (const lev of levels.sort((a, b) => a.price - b.price)) {
    const nearby = merged.find(m => Math.abs(m.price - lev.price) < tolerance);
    if (nearby) {
      nearby.strength += lev.strength;
      if (nearby.type !== lev.type) nearby.type = "BOTH";
    } else {
      merged.push({ ...lev });
    }
  }

  return merged;
}

/**
 * Check if price is at a key level (support/resistance/supply/demand).
 * Returns the matching level or null.
 */
function isAtKeyLevel(price) {
  if (!price || atrValue <= 0) return null;
  const tolerance = atrValue * CANDLE_INTERP_LEVEL_TOL_ATR;
  const keyLevels = detectCandleInterpKeyLevels();

  for (const level of keyLevels) {
    if (Math.abs(price - level.price) <= tolerance) {
      return level;
    }
  }

  /* Also check supply/demand zones from the existing detector */
  const idx = candles.length - 1;
  if (idx > 0) {
    const sdZone = detectSupplyDemandZone(idx);
    if (sdZone) {
      return { price, type: sdZone.type === "demand" ? "SUPPORT" : "RESISTANCE", strength: 1.5, sdZone: sdZone.zone };
    }
  }

  return null;
}

/**
 * Compute the HTF directional bias using CANDLE_INTERP_HTF_MULT synthesis.
 * Reads the candle story on the HTF to determine trend direction.
 *
 * @returns {"BULL"|"BEAR"|"NEUTRAL"}
 */
function computeCandleInterpHTFBias() {
  const htfBars = synthesizeTfCandles(CANDLE_INTERP_HTF_MULT);
  if (htfBars.length < CANDLE_INTERP_HTF_LOOKBACK) return "NEUTRAL";

  const slice = htfBars.slice(-CANDLE_INTERP_HTF_LOOKBACK);
  let bullCount = 0, bearCount = 0, strongBull = 0, strongBear = 0;

  for (const bar of slice) {
    const cls = classifyCandle(bar);
    if (!cls) continue;
    if (cls.control === "BULL") { bullCount++; if (cls.conviction === "STRONG") strongBull++; }
    if (cls.control === "BEAR") { bearCount++; if (cls.conviction === "STRONG") strongBear++; }
  }

  /* Also check structural bias (higher-highs / higher-lows vs lower-highs / lower-lows) */
  let hhhl = 0, lhll = 0;
  for (let i = 1; i < slice.length; i++) {
    if (slice[i].high > slice[i - 1].high && slice[i].low > slice[i - 1].low) hhhl++;
    if (slice[i].high < slice[i - 1].high && slice[i].low < slice[i - 1].low) lhll++;
  }

  const bullScore = bullCount + strongBull * 0.5 + hhhl;
  const bearScore = bearCount + strongBear * 0.5 + lhll;

  if (bullScore > bearScore * 1.3) return "BULL";
  if (bearScore > bullScore * 1.3) return "BEAR";
  return "NEUTRAL";
}

/**
 * Detect multi-candle sequences that tell a reversal or continuation narrative.
 * Looks at the last CANDLE_INTERP_SEQ_LOOKBACK candles on the LTF.
 *
 * Returns { type, dir, sequence[], desc } or null.
 *   type: "BULLISH_REVERSAL" | "BEARISH_REVERSAL" | "BULLISH_CONTINUATION" | "BEARISH_CONTINUATION"
 */
function detectCandleSequence() {
  const len = candles.length;
  if (len < CANDLE_INTERP_SEQ_LOOKBACK) return null;

  const seqCandles = [];
  for (let i = len - CANDLE_INTERP_SEQ_LOOKBACK; i < len; i++) {
    seqCandles.push({ idx: i, candle: candles[i], cls: classifyCandle(candles[i]) });
  }

  /* Remove any null classifications */
  const valid = seqCandles.filter(s => s.cls != null);
  if (valid.length < 3) return null;

  const last3 = valid.slice(-3);
  const [first, second, third] = last3;

  /* Bullish Reversal Sequence:
     1. Indecision or weak bearish (seller exhaustion)
     2. Lower wick rejection at support (buyers defend)
     3. Strong bullish candle (buyers take control) */
  if ((first.cls.conviction === "INDECISION" || (first.cls.control === "BEAR" && first.cls.conviction === "WEAK"))
      && second.cls.rejection === "LOWER"
      && third.cls.control === "BULL" && (third.cls.conviction === "STRONG" || third.cls.conviction === "MODERATE")) {
    return {
      type: "BULLISH_REVERSAL",
      dir: "BULL",
      sequence: last3.map(s => s.cls),
      candleIdx: third.idx,
      desc: "Bullish reversal narrative: seller exhaustion → buyer defense (lower wick rejection) → bullish control candle"
    };
  }

  /* Bearish Reversal Sequence:
     1. Indecision or weak bullish (buyer exhaustion)
     2. Upper wick rejection at resistance (sellers reject)
     3. Strong bearish candle (sellers take control) */
  if ((first.cls.conviction === "INDECISION" || (first.cls.control === "BULL" && first.cls.conviction === "WEAK"))
      && second.cls.rejection === "UPPER"
      && third.cls.control === "BEAR" && (third.cls.conviction === "STRONG" || third.cls.conviction === "MODERATE")) {
    return {
      type: "BEARISH_REVERSAL",
      dir: "BEAR",
      sequence: last3.map(s => s.cls),
      candleIdx: third.idx,
      desc: "Bearish reversal narrative: buyer exhaustion → seller rejection (upper wick) → bearish control candle"
    };
  }

  /* Bullish Continuation:
     Consecutive strong bullish candles after a pullback (weak bear or indecision) */
  if (first.cls.control === "BEAR" && first.cls.conviction === "WEAK"
      && second.cls.control === "BULL" && (second.cls.conviction === "STRONG" || second.cls.conviction === "MODERATE")
      && third.cls.control === "BULL" && (third.cls.conviction === "STRONG" || third.cls.conviction === "MODERATE")) {
    return {
      type: "BULLISH_CONTINUATION",
      dir: "BULL",
      sequence: last3.map(s => s.cls),
      candleIdx: third.idx,
      desc: "Bullish continuation: shallow pullback → resumption of buyer control with conviction"
    };
  }

  /* Bearish Continuation:
     Consecutive strong bearish candles after a pullback (weak bull or indecision) */
  if (first.cls.control === "BULL" && first.cls.conviction === "WEAK"
      && second.cls.control === "BEAR" && (second.cls.conviction === "STRONG" || second.cls.conviction === "MODERATE")
      && third.cls.control === "BEAR" && (third.cls.conviction === "STRONG" || third.cls.conviction === "MODERATE")) {
    return {
      type: "BEARISH_CONTINUATION",
      dir: "BEAR",
      sequence: last3.map(s => s.cls),
      candleIdx: third.idx,
      desc: "Bearish continuation: shallow pullback → resumption of seller control with conviction"
    };
  }

  /* Extended Bullish Reversal: Absorption pattern
     Multiple weak/indecision candles at support followed by strong bullish */
  if (valid.length >= 4) {
    const last4 = valid.slice(-4);
    const weakOrIndecision = last4.slice(0, 3).every(s =>
      s.cls.conviction === "INDECISION" || s.cls.conviction === "WEAK" || s.cls.rejection === "LOWER"
    );
    const finalBull = last4[3].cls.control === "BULL" && last4[3].cls.conviction === "STRONG";
    if (weakOrIndecision && finalBull) {
      return {
        type: "BULLISH_REVERSAL",
        dir: "BULL",
        sequence: last4.map(s => s.cls),
        candleIdx: last4[3].idx,
        desc: "Absorption reversal: multiple candles of selling absorbed at support → explosive bullish breakout"
      };
    }
    /* Extended Bearish Reversal: Absorption pattern */
    const finalBear = last4[3].cls.control === "BEAR" && last4[3].cls.conviction === "STRONG";
    const weakOrUpperReject = last4.slice(0, 3).every(s =>
      s.cls.conviction === "INDECISION" || s.cls.conviction === "WEAK" || s.cls.rejection === "UPPER"
    );
    if (weakOrUpperReject && finalBear) {
      return {
        type: "BEARISH_REVERSAL",
        dir: "BEAR",
        sequence: last4.map(s => s.cls),
        candleIdx: last4[3].idx,
        desc: "Absorption reversal: multiple candles of buying absorbed at resistance → explosive bearish breakout"
      };
    }
  }

  return null;
}

/**
 * Compute volume confirmation score.
 * Returns 0 (no confirmation) to 2 (strong confirmation).
 */
function getCandleInterpVolumeScore(idx) {
  /* Use candle range as a proxy for volume (Deriv synths have no real volume) */
  if (idx < 10 || !candles[idx]) return 1;  /* neutral when insufficient data */

  const currentRange = candles[idx].high - candles[idx].low;
  let avgRange = 0;
  const lookback = Math.min(20, idx);
  for (let i = idx - lookback; i < idx; i++) {
    avgRange += (candles[i].high - candles[i].low);
  }
  avgRange /= lookback;

  if (avgRange <= 0) return 1;
  const ratio = currentRange / avgRange;

  if (ratio >= CANDLE_INTERP_VOL_SPIKE) return 2;  /* high volume = institutional */
  if (ratio >= 1.0) return 1;  /* normal volume */
  return 0;  /* weak volume = low conviction */
}

/**
 * Compute confidence score (0-100) based on alignment factors.
 * Factors:
 *   - HTF bias alignment: 25 pts
 *   - Key level interaction: 25 pts
 *   - Sequence quality: 25 pts
 *   - Volume confirmation: 15 pts
 *   - EMA alignment: 10 pts
 */
function computeCandleInterpConfidence(dir, htfBias, keyLevel, sequence, volScore, idx) {
  let score = 0;

  /* HTF Bias alignment (25 pts) */
  if (htfBias === dir) score += 25;
  else if (htfBias === "NEUTRAL") score += 10;
  /* If HTF conflicts, score stays 0 for this factor */

  /* Key level interaction (25 pts) */
  if (keyLevel) {
    score += 15;
    if (keyLevel.strength >= 1.5) score += 10;
    else if (keyLevel.strength >= 1.0) score += 5;
  }

  /* Sequence quality (25 pts) */
  if (sequence) {
    if (sequence.type.includes("REVERSAL")) score += 20;
    else score += 15;  /* continuation is slightly less weight */
    /* Bonus for strong conviction on the final candle */
    const lastCls = sequence.sequence[sequence.sequence.length - 1];
    if (lastCls && lastCls.conviction === "STRONG") score += 5;
  }

  /* Volume confirmation (15 pts) */
  if (volScore >= 2) score += 15;
  else if (volScore >= 1) score += 8;

  /* EMA alignment (10 pts) — check if price is on correct side of EMA200 */
  if (idx >= 0 && idx < emaMTF.length && emaMTF[idx] != null && candles[idx]) {
    const price = candles[idx].close;
    const ema200 = emaMTF[idx];
    if ((dir === "BULL" && price > ema200) || (dir === "BEAR" && price < ema200)) {
      score += 10;
    } else if ((dir === "BULL" && price > ema200 * 0.998) || (dir === "BEAR" && price < ema200 * 1.002)) {
      score += 5;  /* near EMA */
    }
  }

  return Math.min(100, score);
}

/**
 * Main Candlestick Interpretation signal detector.
 * Requires:
 *   1. Valid candle sequence (narrative)
 *   2. At a key level (context)
 *   3. HTF bias alignment (multi-timeframe)
 *   4. Minimum confidence threshold
 *
 * @returns {Object|null}
 */
function detectCandleInterpretation() {
  if (!candleInterpEnabled) return null;
  if (!candles || candles.length < 20) return null;

  const idx = candles.length - 1;

  /* Cooldown */
  if (idx - lastCandleInterpIdx < CANDLE_INTERP_COOLDOWN) return null;
  /* One pending at a time */
  if (candleInterpHistory.some(s => s.result === "PENDING")) return null;

  /* Step 1: Detect multi-candle sequence (narrative) */
  const sequence = detectCandleSequence();
  if (!sequence) return null;

  const dir = sequence.dir;
  const c = candles[idx];
  if (!c) return null;

  /* Step 2: HTF bias — reject if conflicts */
  const htfBias = computeCandleInterpHTFBias();
  if (htfBias !== "NEUTRAL" && htfBias !== dir) return null;  /* LTF conflicts with HTF — reject */

  /* Step 3: Context — must be at a key level */
  const keyLevel = isAtKeyLevel(c.close);
  if (!keyLevel) return null;  /* Signal in random area — ignore */

  /* Step 4: Volume score */
  const volScore = getCandleInterpVolumeScore(idx);

  /* Step 5: Confidence score — minimum threshold */
  const confidence = computeCandleInterpConfidence(dir, htfBias, keyLevel, sequence, volScore, idx);
  if (confidence < 50) return null;  /* Not enough alignment */

  /* Step 6: Compute entry / SL / TP */
  const entry = c.close;
  const slBuffer = atrValue > 0 ? atrValue * CANDLE_INTERP_SL_BUFFER_ATR : (c.high - c.low) * 0.3;
  const _profParams = getStrategyProfitParams();

  let sl, tp;
  if (dir === "BULL") {
    /* SL below the lowest low in the sequence + buffer */
    const seqLow = Math.min(...candles.slice(Math.max(0, idx - CANDLE_INTERP_SEQ_LOOKBACK), idx + 1).map(x => x.low));
    sl = seqLow - slBuffer * _profParams.slBufferMult;
    /* TP at nearest resistance or R:R minimum */
    const resistance = detectCandleInterpKeyLevels().filter(l => l.type === "RESISTANCE" && l.price > entry);
    if (resistance.length > 0) {
      tp = resistance[0].price;
    } else {
      tp = entry + Math.abs(entry - sl) * CANDLE_INTERP_MIN_RR;
    }
  } else {
    /* SL above the highest high in the sequence + buffer */
    const seqHigh = Math.max(...candles.slice(Math.max(0, idx - CANDLE_INTERP_SEQ_LOOKBACK), idx + 1).map(x => x.high));
    sl = seqHigh + slBuffer * _profParams.slBufferMult;
    /* TP at nearest support or R:R minimum */
    const support = detectCandleInterpKeyLevels().filter(l => l.type === "SUPPORT" && l.price < entry);
    if (support.length > 0) {
      tp = support[support.length - 1].price;
    } else {
      tp = entry - Math.abs(sl - entry) * CANDLE_INTERP_MIN_RR;
    }
  }

  const risk = Math.abs(entry - sl);
  if (risk <= 0) return null;

  /* Guarantee minimum R:R */
  if (Math.abs(tp - entry) / risk < CANDLE_INTERP_MIN_RR) {
    tp = dir === "BULL" ? entry + risk * CANDLE_INTERP_MIN_RR : entry - risk * CANDLE_INTERP_MIN_RR;
  }
  const rr = Math.abs(tp - entry) / risk;

  /* Classify final candle for output */
  const candleStory = classifyCandle(c);

  return {
    dir, entry, sl, tp, rr,
    htfBias,
    keyLevel,
    sequence: { type: sequence.type, desc: sequence.desc },
    candleStory,
    confidence,
    volScore,
    candleIdx: idx,
    epoch: c.epoch,
    symbol: getActiveSymbol(),
    result: "PENDING",
    type: "candle_interp"
  };
}

/**
 * Run the Candlestick Interpretation scanner and handle alerting.
 */
function processCandleInterpretation() {
  const signal = detectCandleInterpretation();
  if (!signal) return;

  /* Min Confluence Gate */
  if (minConfluenceEnabled) {
    const confGate = checkConfluenceGate(signal.dir, signal.entry, signal.candleIdx);
    if (!confGate.pass) {
      addLog(`⚠ Candle Interp REJECTED — ${confGate.reason}`);
      return;
    }
  }

  lastCandleInterpIdx = signal.candleIdx;

  /* Compute & store confluence score for UI */
  signal.confluenceScore = computeConfluenceScore(signal.dir, signal.entry, signal.candleIdx);
  signal._confFactors   = getActiveConfluenceFactors(signal.dir, signal.entry, signal.candleIdx);

  signal._stratOutcomeSent = false;
  signal._sentViaTelegram = false;
  candleInterpHistory.unshift(signal);
  if (candleInterpHistory.length > CANDLE_INTERP_MAX_HISTORY) candleInterpHistory.pop();

  playStrategyAlert(signal.dir);

  const symbol = getActiveSymbol() || "--";
  const confLabel = signal.confidence >= 75 ? "HIGH" : signal.confidence >= 60 ? "MED" : "LOW";
  addLog(`🕯 CANDLE INTERP ${signal.dir === "BULL" ? "▲ BUY" : "▼ SELL"} — ${symbol} @ ${fmtPrice(signal.entry, symbol)} | ${signal.sequence.type} | HTF:${signal.htfBias} | Conf:${signal.confidence}% (${confLabel}) | ${signal.candleStory ? signal.candleStory.desc : ""}`);

  showToast(
    `Candle Interp ${signal.dir === "BULL" ? "▲ BUY" : "▼ SELL"}`,
    `${symbol} @ ${fmtPrice(signal.entry, symbol)} | ${signal.sequence.type} | Confidence: ${signal.confidence}%`,
    "trade", 10000
  );

  if (notificationsEnabled && "Notification" in window && Notification.permission === "granted") {
    const body = `🕯 ${signal.dir} Candle Interpretation — ${symbol} @ ${fmtPrice(signal.entry, symbol)}\n${signal.sequence.desc}\nHTF: ${signal.htfBias} | Confidence: ${signal.confidence}%`;
    throttledNotification("IT Guru: Candle Interpretation!", body);
  }

  /* Telegram alert */
  if (telegramStrategyAutoSend) {
    setTimeout(() => sendTelegramStrategyAlert(signal), CHART_RENDER_DELAY_MS);
  }

  renderStrategyAlerts();

  /* Auto-trade */
  if (autoTradeStrategyEnabled && autoTradeCandleInterp && !_historicalProcessing) {
    executeAutoTrade({ dir: signal.dir, entry: signal.entry, sl: signal.sl, tp: signal.tp, symbol: signal.symbol || symbol, source: "strategy", strategyName: "candleInterp" });
  }
}

/**
 * Monitor pending candle interpretation signals for SL/TP outcome.
 */
function monitorCandleInterpOutcomes(candle) {
  if (!candleInterpEnabled) return;
  let changed = false;
  for (const s of candleInterpHistory) {
    if (s.result !== "PENDING") continue;
    const elapsed = (candles.length - 1) - s.candleIdx;
    if (elapsed < 0 || elapsed >= CANDLE_INTERP_MAX_CANDLES) {
      s.result = "EXPIRED";
      addLog(`🕯 Candle Interp EXPIRED (timeout) — ${s.symbol || ""} @ ${fmt(candle.close, 4)}`);
      changed = true; continue;
    }
    if (s.dir === "BULL") {
      if (_checkProfitExitAlert(s, candle, "Candle Interp")) changed = true;
      const slHit = candle.low <= s.sl, tpHit = candle.high >= s.tp;
      if (slHit && tpHit) { s.result = resolveBothHit(s); changed = true; }
      else if (slHit) { s.result = "LOSS"; addLog(`🕯 Candle Interp LOSS — hit SL @ ${fmt(s.sl, 4)}`); changed = true; }
      else if (tpHit) { s.result = "WIN"; addLog(`🕯 Candle Interp WIN — hit TP @ ${fmt(s.tp, 4)}`); changed = true; }
    } else {
      if (_checkProfitExitAlert(s, candle, "Candle Interp")) changed = true;
      const slHit = candle.high >= s.sl, tpHit = candle.low <= s.tp;
      if (slHit && tpHit) { s.result = resolveBothHit(s); changed = true; }
      else if (slHit) { s.result = "LOSS"; addLog(`🕯 Candle Interp LOSS — hit SL @ ${fmt(s.sl, 4)}`); changed = true; }
      else if (tpHit) { s.result = "WIN"; addLog(`🕯 Candle Interp WIN — hit TP @ ${fmt(s.tp, 4)}`); changed = true; }
    }
  }
  if (changed) {
    renderStrategyAlerts();
    for (const s of candleInterpHistory) {
      if ((s.result === "WIN" || s.result === "LOSS" || s.result === "EXPIRED") && !s._stratOutcomeSent && s._sentViaTelegram === true) {
        sendStrategyOutcomeTelegram(s);
      }
    }
    /* Feature 13: record confluence factor outcomes for adaptive weighting */
    if (adaptiveConfluenceEnabled) {
      for (const s of candleInterpHistory) {
        if ((s.result === "WIN" || s.result === "LOSS") && !s._confRecorded) {
          if (recordConfluenceOutcome(s._confFactors || [], s.result, s.adaptiveScopeKey)) {
            s._confRecorded = true;
          }
        }
      }
    }
  }
}
/* ================= LIVE SCALP SCANNER ================= */
let liveScalpEnabled = false;       /* master toggle */
let liveScalpMinConf = 3;           /* min confluence out of 7 to show alert */
let liveScalpHistory = [];          /* recent scalp alerts: { dir, price, sl, tp, conf, reasons[], epoch, candleIdx } */
const LIVE_SCALP_MAX_HISTORY = 30;
const LIVE_SCALP_COOLDOWN_CANDLES = 3;  /* min candles between consecutive scalp alerts */
let lastScalpCandleIdx = -999;

/**
 * Scans the latest candles for high-probability scalp setups using multi-
 * indicator confluence.  Runs on every candle update when liveScalpEnabled
 * is true.  A scalp is "legit" when >= liveScalpMinConf conditions agree.
 *
 * Confluence criteria (max 7):
 *   1. EMA Momentum   – EMA 8 > EMA 21 (BULL) or EMA 8 < EMA 21 (BEAR)
 *   2. RSI Zone        – RSI ≤ 40 bounce rising → BULL;
 *                        RSI ≥ 60 reject falling → BEAR
 *   3. MACD Momentum   – MACD histogram positive & growing (BULL) or negative & growing (BEAR),
 *                        OR histogram just flipped sign
 *   4. Stochastic Cross – %K crosses %D upward from < 25 (BULL) or downward from > 75 (BEAR)
 *   5. Bollinger Bounce – Price touches/pierces lower band then closes inside (BULL),
 *                        or upper band bounce (BEAR)
 *   6. Candle Pattern   – Bullish/bearish engulfing, pin bar, or doji reversal at EMAs
 *   7. ADX Trend        – ADX ≥ 20 confirms enough directional movement for a scalp
 *
 * Returns null or { dir, conf, reasons[], entry, sl, tp }
 */
function detectLiveScalp() {
  if (!liveScalpEnabled) return null;
  const len = candles.length;
  if (len < 3) return null;

  const idx = len - 1;
  const c   = candles[idx];
  const p   = candles[idx - 1];  /* previous candle */

  /* Enforce cooldown – don't spam alerts on consecutive candles */
  if (idx - lastScalpCandleIdx < LIVE_SCALP_COOLDOWN_CANDLES) return null;

  /* ---- Gather indicator values at current candle ---- */
  const emaF = emaFast.length > idx ? emaFast[idx] : null;
  const emaS = emaSlow.length > idx ? emaSlow[idx] : null;
  const rsiVal  = rsiValues.length > idx ? rsiValues[idx] : null;
  const rsiPrev = rsiValues.length > idx - 1 && idx > 0 ? rsiValues[idx - 1] : null;
  const macdH   = macdHistogram.length > idx ? macdHistogram[idx] : null;
  const macdHP  = macdHistogram.length > idx - 1 && idx > 0 ? macdHistogram[idx - 1] : null;
  const sK      = stochK.length > idx ? stochK[idx] : null;
  const sKP     = stochK.length > idx - 1 && idx > 0 ? stochK[idx - 1] : null;
  const sD      = stochD.length > idx ? stochD[idx] : null;
  const sDP     = stochD.length > idx - 1 && idx > 0 ? stochD[idx - 1] : null;
  const bbUp    = bbUpper.length > idx ? bbUpper[idx] : null;
  const bbLo    = bbLower.length > idx ? bbLower[idx] : null;
  const atrVal  = atrValue;

  /* ---- Score BULL and BEAR separately, pick the stronger ---- */
  const bullReasons = [];
  const bearReasons = [];

  /* 1. EMA Momentum */
  if (emaF != null && emaS != null) {
    if (emaF > emaS && c.close > emaF) bullReasons.push("EMA 8>21 ✓");
    if (emaF < emaS && c.close < emaF) bearReasons.push("EMA 8<21 ✓");
  }

  /* 2. RSI Zone (reversal-based for scalps) */
  if (rsiVal != null && rsiPrev != null) {
    if (rsiVal <= 40 && rsiVal > rsiPrev) bullReasons.push(`RSI ${rsiVal.toFixed(0)} bounce ✓`);
    if (rsiVal >= 60 && rsiVal < rsiPrev) bearReasons.push(`RSI ${rsiVal.toFixed(0)} reject ✓`);
  }

  /* 3. MACD Momentum (one point max — flip is strongest, then growing momentum) */
  if (macdH != null && macdHP != null) {
    if (macdH > 0 && macdHP <= 0) bullReasons.push("MACD flip +ve ✓");
    else if (macdH > 0 && macdH > macdHP) bullReasons.push("MACD momentum ↑ ✓");
    if (macdH < 0 && macdHP >= 0) bearReasons.push("MACD flip −ve ✓");
    else if (macdH < 0 && macdH < macdHP) bearReasons.push("MACD momentum ↓ ✓");
  }

  /* 4. Stochastic cross in extreme zone */
  if (sK != null && sD != null && sKP != null && sDP != null) {
    if (sKP <= sDP && sK > sD && sK < 30) bullReasons.push(`Stoch cross ↑ ${sK.toFixed(0)} ✓`);
    if (sKP >= sDP && sK < sD && sK > 70) bearReasons.push(`Stoch cross ↓ ${sK.toFixed(0)} ✓`);
  }

  /* 5. Bollinger Band bounce */
  if (bbLo != null && bbUp != null) {
    if (p.low <= bbLo && c.close > bbLo) bullReasons.push("BB lower bounce ✓");
    if (p.high >= bbUp && c.close < bbUp) bearReasons.push("BB upper bounce ✓");
  }

  /* 6. Candle pattern at/near EMA or recent S/R */
  const body = Math.abs(c.close - c.open);
  const range = c.high - c.low;
  const pBody = Math.abs(p.close - p.open);
  if (range > 0) {
    const isBullEngulf = c.close > c.open && p.close < p.open && body > pBody * 1.1 && c.close > p.open;
    const isBearEngulf = c.close < c.open && p.close > p.open && body > pBody * 1.1 && c.close < p.open;
    const isPinBarBull = c.close > c.open && (c.open - c.low) > body * 2 && (c.high - c.close) < body * 0.5;
    const isPinBarBear = c.close < c.open && (c.high - c.open) > body * 2 && (c.close - c.low) < body * 0.5;

    if (isBullEngulf) bullReasons.push("Bullish engulfing ✓");
    if (isBearEngulf) bearReasons.push("Bearish engulfing ✓");
    if (isPinBarBull) bullReasons.push("Bull pin bar ✓");
    if (isPinBarBear) bearReasons.push("Bear pin bar ✓");
  }

  /* 7. ADX trend strength (shared — benefits whichever side has momentum) */
  if (adxValue >= ADX_RANGING_THRESHOLD) {
    if (adxDiPlus > adxDiMinus) bullReasons.push(`ADX ${adxValue.toFixed(0)} DI+ ✓`);
    if (adxDiMinus > adxDiPlus) bearReasons.push(`ADX ${adxValue.toFixed(0)} DI− ✓`);
  }

  /* ---- Pick dominant direction ---- */
  const bullConf = bullReasons.length;
  const bearConf = bearReasons.length;
  const minConf  = liveScalpMinConf;

  let dir, conf, reasons;
  if (bullConf >= minConf && bullConf >= bearConf) {
    dir = "BULL"; conf = bullConf; reasons = bullReasons;
  } else if (bearConf >= minConf) {
    dir = "BEAR"; conf = bearConf; reasons = bearReasons;
  } else {
    return null;  /* not enough confluence */
  }

  /* ---- Compute entry / SL / TP using ATR ---- */
  const entry = c.close;
  const atr = atrVal > 0 ? atrVal : range;
  const slDist = atr * 0.75;  /* tight scalp SL: 0.75× ATR */
  const tpDist = atr * 1.0;   /* quick TP: 1× ATR → 1.33:1 R:R (1.0/0.75) */

  const sl = dir === "BULL" ? entry - slDist : entry + slDist;
  const tp = dir === "BULL" ? entry + tpDist : entry - tpDist;
  const rr = slDist > 0 ? tpDist / slDist : 0;

  return { dir, conf, reasons, entry, sl, tp, rr, epoch: c.epoch, candleIdx: idx, symbol: getActiveSymbol(), result: "PENDING" };
}

/**
 * Run the live scalp scanner and handle alerting.
 * Called from the main tick processing pipeline.
 */
function processLiveScalp() {
  const scalp = detectLiveScalp();
  if (!scalp) return;

  lastScalpCandleIdx = scalp.candleIdx;

  /* Store in history */
  liveScalpHistory.unshift(scalp);
  if (liveScalpHistory.length > LIVE_SCALP_MAX_HISTORY) liveScalpHistory.pop();

  /* Audio alert — distinct double-beep for scalps */
  playScalpAlert(scalp.dir);

  /* Browser notification */
  sendScalpNotification(scalp);

  /* Telegram alert (delayed to let canvas redraw first) */
  if (telegramScalpAutoSend) {
    setTimeout(() => sendTelegramScalpAlert(scalp), CHART_RENDER_DELAY_MS);
  }

  /* Update UI */
  renderScalpAlerts();
  updateScalpStatsUI();
  showScalpBanner(scalp);
  renderScalpTickerBanner();

  /* Log to signal log */
  const symbol = getActiveSymbol() || "--";
  addLog(`⚡ SCALP ${scalp.dir === "BULL" ? "▲ BUY" : "▼ SELL"} — ${symbol} @ ${fmt(scalp.entry, 4)} | Confluence ${scalp.conf}/7 | ${scalp.reasons.join(", ")}`);

  /* Auto-trade: place a Deriv multiplier contract for the scalp */
  if (autoTradeScalpEnabled && !_historicalProcessing) {
    executeAutoTrade({ dir: scalp.dir, entry: scalp.entry, sl: scalp.sl, tp: scalp.tp, symbol: scalp.symbol || symbol, source: "scalp" });
  }
}

/**
 * Monitor all PENDING scalps in liveScalpHistory for SL/TP outcome.
 * Called on every candle update (same pipeline as monitorTradeOutcome).
 * Uses a max-candle timeout (same as SCALP_MAX_CANDLES) for time-based exit.
 */

/**
 * Determine whether SL or TP was hit on a given candle for a scalp entry.
 * Returns { slHit, tpHit }.
 */
function checkScalpSLTP(s, candle) {
  if (s.dir === "BULL") {
    return { slHit: candle.low <= s.sl, tpHit: candle.high >= s.tp };
  }
  return { slHit: candle.high >= s.sl, tpHit: candle.low <= s.tp };
}

/**
 * When both SL and TP are breached in the same candle, resolve the outcome
 * by comparing distances from entry.  The closer level is assumed to have
 * been reached first.  On equal distance (1:1 R:R) the trade is marked WIN
 * since the TP was reachable at the same range as the SL.
 */
function resolveScalpBothHit(s) {
  const slDist = Math.abs(s.entry - s.sl);
  const tpDist = Math.abs(s.tp - s.entry);
  return tpDist <= slDist ? "WIN" : "LOSS";
}

/**
 * Generic "both SL and TP hit in same candle" resolver for all strategies.
 * When `partialTpHit` is set the 1:1 alert has already fired and partial profit
 * has been noted — the trade is always a WIN in that case since reaching the TP
 * is considered the primary outcome.  Otherwise falls back to distance comparison:
 * the level closer to entry is assumed to have been hit first.
 */
function resolveBothHit(s) {
  if (s.partialTpHit === true) return "WIN";
  return resolveScalpBothHit(s);
}

/**
 * [FIX] Resolve both SL and TP hit - improved version.
 * Takes candle data to make better distance comparisons.
 */
function resolveBothHitFixed(s, candle) {
  /* If partial TP was already hit, full TP should be treated as WIN */
  if (s.partialTpHit === true) return "WIN";
  
  /* Compare distances from entry to determine which was hit first */
  const slDist = Math.abs(s.entry - s.sl);
  const tpDist = Math.abs(s.tp - s.entry);
  
  /* For BULL: use candle.low for SL and candle.high for TP */
  if (s.dir === "BULL") {
    const distToSL = Math.abs(s.entry - candle.low);
    const distToTP = Math.abs(candle.high - s.entry);
    return distToSL <= distToTP ? "LOSS" : "WIN";
  } else {
    /* For BEAR: use candle.high for SL and candle.low for TP */
    const distToSL = Math.abs(candle.high - s.entry);
    const distToTP = Math.abs(s.entry - candle.low);
    return distToSL <= distToTP ? "LOSS" : "WIN";
  }
}

function monitorScalpOutcomes(candle) {
  if (!liveScalpEnabled) return;
  let changed = false;
  for (const s of liveScalpHistory) {
    if (s.result !== "PENDING") continue;

    /* Time-based exit: if enough candles have passed since the scalp entry */
    if (s.candleIdx !== null && s.candleIdx !== undefined) {
      const elapsed = (candles.length - 1) - s.candleIdx;
      if (elapsed >= SCALP_MAX_CANDLES) {
        /* Even on timeout, check if SL or TP was hit on this final candle */
        const { slHit, tpHit } = checkScalpSLTP(s, candle);
        if (tpHit && slHit) {
          s.result = resolveScalpBothHit(s);
        } else if (tpHit) {
          s.result = "WIN";
        } else if (slHit) {
          s.result = "LOSS";
        } else {
          /* Neither SL nor TP hit — fall back to close vs entry */
          const inProfit = (s.dir === "BULL" && candle.close > s.entry) ||
                           (s.dir === "BEAR" && candle.close < s.entry);
          s.result = inProfit ? "WIN" : "LOSS";
        }
        addLog(`⚡ Scalp ${s.result} (timeout ${SCALP_MAX_CANDLES} candles) — ${s.dir} ${s.symbol || ""} exit @ ${fmt(candle.close, 4)}`);
        changed = true;
        continue;
      }
    }

    /* Check SL / TP hit.
       When both SL and TP are hit within the same candle we compare the
       distance from the entry to each level — the closer level is assumed
       to have been reached first.  This avoids the old "SL always wins"
       bias that inflated the loss count. */
    const { slHit, tpHit } = checkScalpSLTP(s, candle);
    if (slHit && tpHit) {
      s.result = resolveScalpBothHit(s);
      addLog(`⚡ Scalp ${s.result} — ${s.symbol || ""} hit ${s.result === "WIN" ? "TP" : "SL"} @ ${fmt(s.result === "WIN" ? s.tp : s.sl, 4)} (both levels breached, ${s.result === "WIN" ? "TP" : "SL"} closer)`);
      changed = true;
    } else if (slHit) {
      s.result = "LOSS";
      addLog(`⚡ Scalp LOSS — ${s.symbol || ""} hit SL @ ${fmt(s.sl, 4)}`);
      changed = true;
    } else if (tpHit) {
      s.result = "WIN";
      addLog(`⚡ Scalp WIN — ${s.symbol || ""} hit TP @ ${fmt(s.tp, 4)}`);
      changed = true;
    }
  }
  if (changed) {
    updateScalpStatsUI();
    renderScalpTickerBanner();
    /* Send Telegram outcome for each newly resolved scalp */
    for (const s of liveScalpHistory) {
      if (s.result === "WIN" || s.result === "LOSS") {
        if (!s._outcomeSent) {
          s._outcomeSent = true;
          sendScalpOutcomeTelegram(s);
        }
      }
    }
  }
}

function playScalpAlert(dir) {
  if (!soundEnabled) return;
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const freq = dir === "BULL" ? 1000 : 800;
    /* Double beep for urgency */
    for (let i = 0; i < 2; i++) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.value = freq;
      osc.type = "sine";
      gain.gain.value = 0.15;
      osc.start(ctx.currentTime + i * 0.2);
      osc.stop(ctx.currentTime + i * 0.2 + 0.12);
    }
  } catch (e) { /* audio not available */ }
}

function sendScalpNotification(scalp) {
  if (!notificationsEnabled || !("Notification" in window)) return;
  if (Notification.permission !== "granted") return;
  const symbol = getActiveSymbol() || "--";
  const body = `⚡ ${scalp.dir} SCALP — ${symbol} @ ${fmt(scalp.entry, 4)}\nConfluence: ${scalp.conf}/7\n${scalp.reasons.slice(0, 3).join(" · ")}`;
  throttledNotification("IT Guru: Live Scalp Alert!", body);
}

/**
 * Build a formatted Telegram caption for a live scalp alert.
 * Uses Telegram HTML parse mode.
 */
function buildScalpTelegramCaption(scalp) {
  const symbol = scalp.symbol || getActiveSymbol() || "--";
  const symLabel = getSymbolLabel ? getSymbolLabel(symbol) : symbol;
  const gran = UI.granSelect ? UI.granSelect.value : "--";
  const tfLabel = TIMEFRAME_LABELS[gran] || gran + "s";
  const ts = new Date(scalp.epoch * 1000).toISOString().replace("T", " ").slice(0, 19) + " UTC";
  const dirEmoji = scalp.dir === "BULL" ? "🟢" : "🔴";
  const dirLabel = scalp.dir === "BULL" ? "BUY" : "SELL";

  const lines = [];
  lines.push(`<b>⚡ Live Scalp Alert</b>`);
  lines.push(``);
  lines.push(`<b>Symbol:</b> ${symLabel}`);
  lines.push(`<b>Timeframe:</b> ${tfLabel}`);
  lines.push(`<b>Direction:</b> ${dirEmoji} ${scalp.dir} (${dirLabel})`);

  /* Indicate if opposite mode will reverse this signal for auto-trading */
  if (autoTradeScalpOpposite) {
    const oppDir = scalp.dir === "BULL" ? "BEAR" : "BULL";
    const oppLabel = oppDir === "BULL" ? "BUY" : "SELL";
    const oppEmoji = oppDir === "BULL" ? "🟢" : "🔴";
    lines.push(`<b>🔄 Opposite Mode:</b> Signal ${scalp.dir} → Trading ${oppEmoji} ${oppDir} (${oppLabel})`);
  }

  lines.push(``);
  lines.push(`<b>📍 Entry:</b> <code>${fmtPrice(scalp.entry, symbol)}</code>`);
  lines.push(`<b>🛑 SL:</b> <code>${fmtPrice(scalp.sl, symbol)}</code>`);
  lines.push(`<b>🎯 TP:</b> <code>${fmtPrice(scalp.tp, symbol)}</code>`);
  if (scalp.rr != null) {
    lines.push(`<b>R:R:</b> 1:${fmt(scalp.rr, 1)}`);
  }
  lines.push(``);
  lines.push(`<b>Confluence:</b> ${scalp.conf}/7`);
  lines.push(`<b>Reasons:</b> ${scalp.reasons.join(", ")}`);

  /* Position sizing if available */
  if (accountSize > 0 && riskPercent > 0 && scalp.entry != null && scalp.sl != null) {
    const tradeObj = { entry: scalp.entry, sl: scalp.sl, tp: scalp.tp, rr: scalp.rr || 0, symbol };
    const m = calcPositionMetrics(tradeObj);
    if (m) {
      lines.push(``);
      lines.push(`<b>💰 $ Risk:</b> $${fmt(m.dollarRisk, 2)}`);
      if (scalp.tp != null) lines.push(`<b>💰 $ Reward:</b> $${fmt(m.dollarReward, 2)}`);
      lines.push(`<b>📦 Lot Size:</b> ${fmt(m.lotSize, 2)}`);
      if (!m.isSynthetic) {
        lines.push(`<b>📏 Pips at Risk:</b> ${fmt(m.pips, 1)}`);
      }
    }
  }

  lines.push(``);
  lines.push(`<i>${ts}</i>`);
  return lines.join("\n");
}

/**
 * Send a live scalp alert to Telegram with chart screenshot.
 */
async function sendTelegramScalpAlert(scalp, force = false) {
  if (!telegramScalpAutoSend && !force) return;

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Scalp Telegram skipped: ${err.message}`);
    return;
  }

  const qualification = await qualifySignalForTelegram(scalp, "Live Scalp", force, {
    strategy: "live_scalp",
    mtfStatus: getAdaptiveMtfStatus(scalp)
  });
  if (!qualification.allowed) return;

  if (UI.telegramStatus) UI.telegramStatus.textContent = "Sending scalp…";
  const caption = decorateAdaptiveTelegramCaption(buildScalpTelegramCaption(scalp), qualification.decision);
  try {
    const panel = (scalp.symbol && multiPanels.has(scalp.symbol)) ? multiPanels.get(scalp.symbol) : null;
    const blob = await captureTelegramScreenshot(panel);
    if (blob) {
      await sendTelegramPhoto(blob, caption);
    } else {
      await sendTelegramMessage(caption);
    }
    scalp._sentViaTelegram = true;
    addLog("📤 Scalp Telegram alert sent successfully");
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = "✅ Scalp sent!";
      UI.telegramStatus.className = "hint telegram-status telegram-ok";
    }
  } catch (err) {
    addLog(`📤 Scalp Telegram error: ${err.message}`);
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = `❌ Scalp: ${err.message}`;
      UI.telegramStatus.className = "hint telegram-status telegram-err";
    }
  }
  setTimeout(() => {
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = "";
      UI.telegramStatus.className = "hint telegram-status";
    }
  }, TELEGRAM_STATUS_CLEAR_MS);
}

/**
 * Send scalp outcome (WIN / LOSS) via Telegram when enabled.
 * Called from monitorScalpOutcomes after a scalp resolves.
 */
async function sendScalpOutcomeTelegram(scalp) {
  if (!telegramScalpOutcomeSend) return;

  /* Sync credentials from DOM */
  /* #14: credentials kept in sync by the DOM input listener — no need to re-read here */

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Scalp outcome Telegram skipped: ${err.message}`);
    return;
  }

  try {
    const sym = getSymbolLabel(scalp.symbol || getActiveSymbol() || "");
    const activeSym = scalp.symbol || getActiveSymbol() || "";
    const dir = scalp.dir === "BULL" ? "📈 BUY" : "📉 SELL";
    const result = scalp.result;
    const icon = result === "WIN" ? "✅" : "❌";
    const entryStr = scalp.entry != null ? fmtPrice(scalp.entry, activeSym) : "--";
    const slStr = scalp.sl != null ? fmtPrice(scalp.sl, activeSym) : "--";
    const tpStr = scalp.tp != null ? fmtPrice(scalp.tp, activeSym) : "--";
    const rrStr = scalp.rr != null ? "1:" + fmt(scalp.rr, 1) : "--";
    const confScore = scalp.conf != null ? scalp.conf + "/7" : "--";
    const reasons = scalp.reasons ? scalp.reasons.join(", ") : "--";

    const lines = [];
    lines.push(`${icon} <b>Scalp ${result}</b> — ${dir} ${sym}`);
    lines.push("");
    lines.push(`<b>📍 Entry:</b> ${entryStr}`);
    lines.push(`<b>🛑 SL:</b> ${slStr}`);
    lines.push(`<b>🎯 TP:</b> ${tpStr}`);
    lines.push(`<b>R:R:</b> ${rrStr}`);
    lines.push(`<b>Confluence:</b> ${confScore}`);
    lines.push(`<b>Reasons:</b> ${reasons}`);

    /* Scalp win/loss tally */
    const h = getAggregatedScalpHistory();
    const totalW = h.filter(s => s.result === "WIN").length;
    const totalL = h.filter(s => s.result === "LOSS").length;
    const wr = (totalW + totalL) > 0 ? (totalW / (totalW + totalL) * 100).toFixed(1) + "%" : "N/A";
    lines.push("");
    lines.push(`📊 <b>Scalp Record:</b> ${totalW}W / ${totalL}L (${wr} win rate)`);

    /* Opposite mode effectiveness from auto-trade history */
    const oppTrades = autoTradeHistory.filter(e => e.isOpposite && e.source === "scalp" && (e.result === "WIN" || e.result === "LOSS"));
    const normTrades = autoTradeHistory.filter(e => !e.isOpposite && e.source === "scalp" && (e.result === "WIN" || e.result === "LOSS"));
    if (oppTrades.length > 0 || normTrades.length > 0) {
      lines.push("");
      if (normTrades.length > 0) {
        const nw = normTrades.filter(e => e.result === "WIN").length;
        const nwr = (nw / normTrades.length * 100).toFixed(1);
        lines.push(`📈 <b>Normal:</b> ${nw}W / ${normTrades.length - nw}L (${nwr}%)`);
      }
      if (oppTrades.length > 0) {
        const ow = oppTrades.filter(e => e.result === "WIN").length;
        const owr = (ow / oppTrades.length * 100).toFixed(1);
        lines.push(`🔄 <b>Opposite:</b> ${ow}W / ${oppTrades.length - ow}L (${owr}%)`);
      }
    }

    lines.push(`<i>${new Date().toISOString().replace("T", " ").slice(0, 19)} UTC</i>`);

    await sendTelegramMessage(lines.join("\n"));
    addLog(`📤 Telegram: scalp outcome (${result}) sent`);
  } catch (err) {
    addLog(`📤 Scalp outcome Telegram error: ${err.message}`);
  }
}

/* ================= TELEGRAM: CUSTOM STRATEGY ALERTS (Liquidity Sweep, Stop Loss Hunt, Failed Pin Bar) ================= */

/**
 * Build a formatted Telegram message for a custom strategy signal.
 * Includes direction, entry, SL/TP, R:R, lot size (based on account amount), and symbol.
 * Uses Telegram HTML parse mode.
 */
function buildStrategyTelegramCaption(signal) {
  const symbol = signal.symbol || getActiveSymbol() || "--";
  const symLabel = getSymbolLabel ? getSymbolLabel(symbol) : symbol;
  const gran = UI.granSelect ? UI.granSelect.value : "--";
  const tfLabel = TIMEFRAME_LABELS[gran] || gran + "s";
  const ts = signal.epoch
    ? new Date(signal.epoch * 1000).toISOString().replace("T", " ").slice(0, 19) + " UTC"
    : new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC";
  const dirEmoji = signal.dir === "BULL" ? "🟢" : "🔴";
  const dirArrow = signal.dir === "BULL" ? "▲" : "▼";
  const dirLabel = signal.dir === "BULL" ? "BUY" : "SELL";

  /* Strategy-specific emoji and label */
  let stratEmoji = "📊";
  let stratLabel = "Strategy Signal";
  if (signal.type === "liquidity_sweep") {
    stratEmoji = "🌊";
    stratLabel = "Liquidity Sweep";
  } else if (signal.type === "stop_loss_hunt") {
    stratEmoji = "🎯";
    stratLabel = "Stop Loss Hunt";
  } else if (signal.type === "failed_pin_bar") {
    stratEmoji = "📌";
    stratLabel = "Failed Pin Bar";
  } else if (signal.type === "fib_scalp") {
    stratEmoji = "📐";
    stratLabel = "Fib Golden Zone Scalp";
  } else if (signal.type === "ny_open_range") {
    stratEmoji = "🕤";
    stratLabel = "NY Open Range (9:30 AM EST)";
  } else if (signal.type === "session_range") {
    stratEmoji = "🌍";
    stratLabel = "Session Range (London Sweep)";
  } else if (signal.type === "grid_scalper_ma") {
    stratEmoji = "🔲";
    const modeLabel = signal.mode === "bos" ? "BOS" : signal.mode === "triple_ma" ? "Triple MA" : "Price vs MA";
    stratLabel = `Grid Scalper MA [${modeLabel}]`;
  } else if (signal.type === "fvg_strat") {
    stratEmoji = "🎯";
    stratLabel = "Fair Value Gap";
  } else if (signal.type === "mtf_top_down") {
    stratEmoji = "⏱";
    stratLabel = "MTF Top-Down";
  } else if (signal.type === "power_of_3") {
    stratEmoji = "⚡";
    stratLabel = "Power of 3";
  } else if (signal.type === "tiktok") {
    stratEmoji = "📈";
    stratLabel = "TikTok Fibonacci";
  } else if (signal.type === "candle_interp") {
    stratEmoji = "🕯";
    stratLabel = "Candle Interpretation";
  } else if (signal.type === "orb") {
    stratEmoji = "📊";
    stratLabel = "Opening Range Breakout";
  } else if (signal.type === "breakout_retest") {
    stratEmoji = "💥";
    stratLabel = "Breakout Retest";
  }

  const triggerFactors = ensureSignalTriggerFactors(signal);
  const rrLabel = Number.isFinite(signal.riskReward) ? signal.riskReward : (Number.isFinite(signal.rr) ? signal.rr : null);
  const adaptiveConfidenceLabel = getAdaptiveConfidenceLabel(signal);
  const adaptiveConfidenceScore = signal._adaptiveDecision && Number.isFinite(signal._adaptiveDecision.final_confidence_score)
    ? signal._adaptiveDecision.final_confidence_score
    : null;
  const marketCategory = getAdaptiveMarketCategory(symbol, signal.timeframeSec != null ? signal.timeframeSec : getCurrentGranularitySec());
  const lines = [];
  lines.push(`<b>🚨 NEW TRADE SIGNAL</b>`);
  lines.push(``);
  lines.push(`<b>Strategy:</b> ${stratLabel}`);
  if (signal.signalId) lines.push(`<b>Signal ID:</b> <code>${signal.signalId}</code>`);
  lines.push(``);
  lines.push(`<b>Symbol:</b> ${symLabel}`);
  lines.push(`<b>Timeframe:</b> ${tfLabel}`);
  lines.push(`<b>Direction:</b> ${dirEmoji} ${dirLabel}`);

  /* Indicate if opposite mode will reverse this signal for auto-trading.
     For Grid Scalper MA the strategy's own Opposite Mode toggle
     (gridScalperMAOppositeEnabled) must also flip the alert, not only the
     auto-trade opposite toggle. */
  const gsOppositeOn = signal.type === "grid_scalper_ma" &&
    typeof gridScalperMAOppositeEnabled !== "undefined" && gridScalperMAOppositeEnabled;
  if (autoTradeStrategyOpposite || gsOppositeOn) {
    const oppDir = signal.dir === "BULL" ? "BEAR" : "BULL";
    const oppLabel = oppDir === "BULL" ? "BUY" : "SELL";
    const oppEmoji = oppDir === "BULL" ? "🟢" : "🔴";
    lines.push(`<b>🔄 Opposite Mode:</b> ✅ ENABLED`);
    lines.push(`<b>Signal:</b> ${signal.dir} → <b>Trading:</b> ${oppEmoji} ${oppDir} (${oppLabel})`);
  } else {
    lines.push(`<b>🔄 Opposite Mode:</b> ❌ Disabled`);
  }

  lines.push(`<b>📍 Entry:</b> <code>${fmtPrice(signal.entry, symbol)}</code>`);
  lines.push(`<b>🛑 Stop Loss:</b> <code>${fmtPrice(signal.stopLoss ?? signal.sl, symbol)}</code>`);
  lines.push(`<b>🎯 Take Profit:</b> <code>${fmtPrice(signal.takeProfit ?? signal.tp, symbol)}</code>`);
  if (rrLabel != null) {
    lines.push(`<b>Risk/Reward:</b> 1:${fmt(rrLabel, 1)}`);
  }
  if (Number.isFinite(signal.confluenceScore)) lines.push(`<b>Signal Quality:</b> ${Math.round((signal.confluenceScore / 16) * 100)}%`);
  if (adaptiveConfidenceLabel) {
    const scoreSuffix = Number.isFinite(adaptiveConfidenceScore) ? ` (${Math.round(adaptiveConfidenceScore)}%)` : "";
    lines.push(`<b>Adaptive Confidence:</b> ${adaptiveConfidenceLabel}${scoreSuffix}`);
  }
  if (marketCategory) lines.push(`<b>Market Category:</b> ${marketCategory}`);
  if (signal._adaptiveDecision && signal._adaptiveDecision.weight_version) lines.push(`<b>Learning Weight Version:</b> ${signal._adaptiveDecision.weight_version}`);
  if (Number.isFinite(signal.validUntilMs)) lines.push(`<b>Valid Until:</b> ${formatUtcTs(signal.validUntilMs)}`);
  if (signal.entryMode) lines.push(`<b>Entry Mode:</b> ${signal.entryMode === "aggressive_intrabar" ? "Aggressive Intrabar" : "Confirmed Close"}`);
  if (Number.isFinite(signal.entryDriftAtr)) lines.push(`<b>Entry Drift:</b> ${fmt(signal.entryDriftAtr, 2)} ATR`);
  if (Number.isFinite(signal.maxEntryDistanceAtr)) lines.push(`<b>Max Entry Distance:</b> ${fmt(signal.maxEntryDistanceAtr, 2)} ATR`);
  if (Number.isFinite(signal.stopBufferAtr)) lines.push(`<b>Stop Buffer:</b> ${fmt(signal.stopBufferAtr, 2)} ATR`);
  if (Number.isFinite(signal.atr ?? signal.atrAtSignal)) lines.push(`<b>ATR:</b> ${fmt(signal.atr ?? signal.atrAtSignal, 3)}`);

  /* Show opposite signal details when opposite mode is active */
  if ((autoTradeStrategyOpposite || gsOppositeOn) && signal.type === "grid_scalper_ma") {
    const oppDir = signal.dir === "BULL" ? "BEAR" : "BULL";
    const risk = Math.abs(signal.entry - signal.sl);
    const oppSl = oppDir === "BULL" ? signal.entry - risk : signal.entry + risk;
    const oppTp = oppDir === "BULL" ? signal.entry + risk * (signal.rr || 2) : signal.entry - risk * (signal.rr || 2);
    const oppDirLabel = oppDir === "BULL" ? "🟢 BUY" : "🔴 SELL";
    lines.push(``);
    lines.push(`<b>━━━ Opposite Signal ━━━</b>`);
    lines.push(`<b>Direction:</b> ${oppDirLabel}`);
    lines.push(`<b>📍 Entry:</b> <code>${fmtPrice(signal.entry, symbol)}</code>`);
    lines.push(`<b>🛑 SL:</b> <code>${fmtPrice(oppSl, symbol)}</code>`);
    lines.push(`<b>🎯 TP:</b> <code>${fmtPrice(oppTp, symbol)}</code>`);
    lines.push(`<b>R:R:</b> 1:${fmt(signal.rr || 2, 1)}`);
    lines.push(``);
    lines.push(`<b>━━━ Execution Used ━━━</b>`);
    lines.push(`<b>Final Direction:</b> ${oppDirLabel}`);
    lines.push(`<b>Final Entry:</b> <code>${fmtPrice(signal.entry, symbol)}</code>`);
    lines.push(`<b>Final SL:</b> <code>${fmtPrice(oppSl, symbol)}</code>`);
    lines.push(`<b>Final TP:</b> <code>${fmtPrice(oppTp, symbol)}</code>`);
    lines.push(`<b>Reason:</b> Opposite mode active — signal reversed with recalculated SL/TP`);
  }
  let strategyConfluence = Number.isFinite(signal.confluenceScore) ? signal.confluenceScore : null;
  if (strategyConfluence == null &&
      signal.dir &&
      signal.entry != null &&
      Number.isFinite(signal.candleIdx)) {
    strategyConfluence = computeConfluenceScore(signal.dir, signal.entry, signal.candleIdx);
    signal.confluenceScore = strategyConfluence;
  }
  if (Number.isFinite(strategyConfluence)) {
    lines.push(`<b>Confluence:</b> ${fmt(strategyConfluence, 0)}/16`);
  }
  if (signal.adaptiveQuality) {
    const q = signal.adaptiveQuality;
    if (Number.isFinite(q.compositeScore)) lines.push(`<b>Adaptive Strength:</b> ${Math.round(q.compositeScore * 100)}%`);
    if (Array.isArray(q.trace) && q.trace.length > 0) {
      lines.push(`<b>Adaptive Trace:</b> ${q.trace.join(" | ")}`);
    }
  }

  lines.push(``);
  lines.push(`<b>✅ Trigger Factors</b>`);
  const passedTriggerFactors = triggerFactors.filter((factor) => factor && factor.passed !== false);
  if (passedTriggerFactors.length > 0) {
    passedTriggerFactors.forEach((factor) => lines.push(`• ${formatSignalFactorLabel(factor)}`));
  } else {
    lines.push(`• Strategy-specific confirmation conditions were met.`);
  }

  /* Strategy-specific details */
  if (signal.type === "liquidity_sweep" && signal.range) {
    lines.push(``);
    lines.push(`<b>Range:</b> [${fmtPrice(signal.range.low, symbol)} – ${fmtPrice(signal.range.high, symbol)}]`);
  }
  if (signal.type === "stop_loss_hunt" && signal.level) {
    lines.push(``);
    lines.push(`<b>Key Level:</b> ${fmtPrice(signal.level.level, symbol)} (${signal.level.touches} touches)`);
  }
  if (signal.type === "failed_pin_bar" && signal.state) {
    lines.push(``);
    lines.push(`<b>State:</b> ${signal.state === "fear" ? "😱 FEAR" : "🤑 GREED"}`);
  }
  if (signal.type === "fib_scalp" && signal.goldenLow != null) {
    lines.push(``);
    lines.push(`<b>Golden Zone:</b> [${fmtPrice(signal.goldenLow, symbol)} – ${fmtPrice(signal.goldenHigh, symbol)}]`);
    lines.push(`<b>Fib Range:</b> [${fmtPrice(signal.fibLow, symbol)} – ${fmtPrice(signal.fibHigh, symbol)}]`);
  }
  if (signal.type === "grid_scalper_ma") {
    lines.push(``);
    const modeLabel = signal.mode === "bos" ? "BOS (Break of Structure)" : `Price vs MA (SMA ${gridScalperMAPeriod})`;
    lines.push(`<b>Mode:</b> ${modeLabel}`);
    if (signal.mode === "bos" && signal.breakLevel != null) {
      lines.push(`<b>Break Level:</b> ${fmt(signal.breakLevel, 4)}`);
    }
    /* TP Probability block */
    lines.push(``);
    lines.push(`<b>━━━ TP Probability ━━━</b>`);
    if (Number.isFinite(signal.origTPProb) && Number.isFinite(signal.oppTPProb)) {
      const origPct    = Math.round(signal.origTPProb * 100);
      const oppPct     = Math.round(signal.oppTPProb  * 100);
      const oppDirStr  = signal.dir === "BULL" ? "BEAR 🔴" : "BULL 🟢";
      const origDirStr = signal.dir === "BULL" ? "BULL 🟢" : "BEAR 🔴";
      const recLabel   = signal.probHighDir === "original"
        ? `✅ Trade ORIGINAL (${origDirStr})`
        : signal.probHighDir === "opposite"
        ? `✅ Trade OPPOSITE (${oppDirStr})`
        : "⚪ Equal — no clear edge";
      const sampleStr  = Number.isFinite(signal.probSampleSize) ? ` · ${signal.probSampleSize} trades` : "";
      lines.push(`<b>Original (${origDirStr}):</b> ${origPct}%`);
      lines.push(`<b>Opposite (${oppDirStr}):</b> ${oppPct}%`);
      lines.push(`<b>Recommendation:</b> ${recLabel}${sampleStr}`);
    } else {
      lines.push(`N/A — need ${typeof TP_PROB_MIN_SAMPLE !== "undefined" ? TP_PROB_MIN_SAMPLE : 5}+ resolved trades`);
    }
  }
  if (signal.type === "fvg_strat") {
    lines.push(``);
    if (signal.demandZoneHigh != null) {
      lines.push(`<b>📦 Demand/Supply Zone:</b> [${fmtPrice(signal.demandZoneLow, symbol)} – ${fmtPrice(signal.demandZoneHigh, symbol)}]`);
    }
    if (signal.fvgHigh != null) {
      lines.push(`<b>📊 FVG:</b> [${fmtPrice(signal.fvgLow, symbol)} – ${fmtPrice(signal.fvgHigh, symbol)}]`);
    }
    if (signal.fibLevel != null) {
      lines.push(`<b>📐 Fib Level:</b> ${fmt(signal.fibLevel * 100, 0)}% (discount zone ≤ ${fmt(FVG_FIB_DISCOUNT * 100, 0)}%)`);
    }
  }
  if (signal.type === "mtf_top_down") {
    lines.push(``);
    if (signal.mtfBias) {
      const biasEmoji = signal.mtfBias === "BULL" ? "📈" : signal.mtfBias === "BEAR" ? "📉" : "➡️";
      lines.push(`<b>${biasEmoji} HTF Bias:</b> ${signal.mtfBias}`);
    }
    if (signal.level != null) {
      lines.push(`<b>🎯 Key Level:</b> <code>${fmtPrice(signal.level, symbol)}</code>`);
    }
    if (signal.patternType) {
      const pLabel = signal.patternType === "pin_bar" ? "Pin Bar" : signal.patternType === "engulfing" ? "Engulfing" : "Micro BOS";
      lines.push(`<b>🕯 Entry Pattern:</b> ${pLabel}`);
    }
  }
  if (signal.type === "power_of_3") {
    lines.push(``);
    if (signal.oneHourOpen != null) {
      lines.push(`<b>🕐 1H Open:</b> <code>${fmtPrice(signal.oneHourOpen, symbol)}</code>`);
    }
    if (signal.sweepPrice != null) {
      lines.push(`<b>🧹 Sweep Price:</b> <code>${fmtPrice(signal.sweepPrice, symbol)}</code>`);
    }
    if (signal.fvgLow != null && signal.fvgHigh != null) {
      lines.push(`<b>📊 FVG:</b> [${fmtPrice(signal.fvgLow, symbol)} – ${fmtPrice(signal.fvgHigh, symbol)}]`);
    }
  }
  if (signal.type === "orderblock") {
    lines.push(``);
    if (signal.obLow != null && signal.obHigh != null) {
      lines.push(`<b>🏦 OB Zone:</b> [${fmtPrice(signal.obLow, symbol)} – ${fmtPrice(signal.obHigh, symbol)}]`);
    }
    if (signal.obIdx != null) {
      lines.push(`<b>OB Candle:</b> #${signal.obIdx}`);
    }
    if (signal.impulseLen != null) {
      lines.push(`<b>Impulse Candles:</b> ${signal.impulseLen}`);
    }
    if (signal.impulseAtr != null) {
      lines.push(`<b>Impulse Strength:</b> ${fmt(signal.impulseAtr, 2)}× ATR`);
    }
    if (signal.impulseDominance != null) {
      lines.push(`<b>Directional Dominance:</b> ${fmt(signal.impulseDominance * 100, 0)}%`);
    }
    if (signal.impulseStrongRatio != null) {
      lines.push(`<b>Strong Candle Ratio:</b> ${fmt(signal.impulseStrongRatio * 100, 0)}%`);
    }
  }
  if (signal.type === "tiktok") {
    lines.push(``);
    if (signal.swingLow != null && signal.swingHigh != null) {
      lines.push(`<b>📏 Impulse Range:</b> [${fmtPrice(signal.swingLow, symbol)} – ${fmtPrice(signal.swingHigh, symbol)}]`);
    }
    if (signal.lvl_88 != null) {
      lines.push(`<b>🎯 0.88 Level (Entry):</b> <code>${fmtPrice(signal.lvl_88, symbol)}</code>`);
    }
    if (signal.lvl_618 != null && signal.lvl_5 != null) {
      lines.push(`<b>📊 Step B Zone (0.5–0.618):</b> [${fmtPrice(signal.lvl_5, symbol)} – ${fmtPrice(signal.lvl_618, symbol)}]`);
    }
    if (signal.lvl_382 != null) {
      lines.push(`<b>📊 Step C Zone (0–0.382):</b> ≤ ${fmtPrice(signal.lvl_382, symbol)}`);
    }
  }
  if (signal.type === "candle_interp") {
    lines.push(``);
    if (signal.sequence) {
      lines.push(`<b>🕯 Pattern:</b> ${signal.sequence.type}`);
      if (signal.sequence.desc) lines.push(`<b>📖 Story:</b> ${signal.sequence.desc}`);
    }
    if (signal.htfBias) {
      const biasEmoji = signal.htfBias === "BULL" ? "📈" : signal.htfBias === "BEAR" ? "📉" : "➡️";
      lines.push(`<b>${biasEmoji} HTF Bias:</b> ${signal.htfBias}`);
    }
    if (signal.keyLevel) {
      const klLabel = typeof signal.keyLevel === "object" ? `${signal.keyLevel.type} @ ${fmtPrice(signal.keyLevel.price || signal.keyLevel.level, symbol)}` : signal.keyLevel;
      lines.push(`<b>🔑 Key Level:</b> ${klLabel}`);
    }
    if (signal.confidence != null) {
      const confLabel = signal.confidence >= 75 ? "HIGH" : signal.confidence >= 60 ? "MED" : "LOW";
      lines.push(`<b>📊 Confidence:</b> ${signal.confidence}% (${confLabel})`);
    }
    if (signal.volScore != null) {
      lines.push(`<b>📈 Volume Score:</b> ${fmt(signal.volScore, 1)}`);
    }
    if (signal.candleStory && signal.candleStory.desc) {
      lines.push(`<b>🕯 Final Candle:</b> ${signal.candleStory.desc}`);
    }
  }
  if (accountSize > 0 && riskPercent > 0 && signal.entry != null && signal.sl != null) {
    const tradeObj = { entry: signal.entry, sl: signal.sl, tp: signal.tp, rr: signal.rr || 0, symbol };
    const m = calcPositionMetrics(tradeObj);
    if (m) {
      lines.push(``);
      lines.push(`<b>💰 $ Risk:</b> $${fmt(m.dollarRisk, 2)}`);
      if (signal.tp != null) lines.push(`<b>💰 $ Reward:</b> $${fmt(m.dollarReward, 2)}`);
      lines.push(`<b>📦 Lot Size:</b> ${fmt(m.lotSize, 2)}`);
      if (!m.isSynthetic) {
        lines.push(`<b>📏 Pips at Risk:</b> ${fmt(m.pips, 1)}`);
      }
      lines.push(`<b>📐 Account:</b> $${fmt(accountSize, 2)} (${fmt(riskPercent, 1)}% risk)`);
    }
  }

  lines.push(``);
  lines.push(`<i>${ts}</i>`);
  return lines.join("\n");
}

function buildLifecycleTelegramCaption(kind, payload) {
  const symbol = payload.symbol || getActiveSymbol() || "";
  const symLabel = getSymbolLabel(symbol);
  const tfSec = payload.timeframeSec != null ? payload.timeframeSec : getCurrentGranularitySec();
  const tfLabel = TIMEFRAME_LABELS[String(tfSec)] || `${tfSec}s`;
  const dir = payload.dir || "--";
  const dirLabel = dir === "BULL" ? "🟢 BUY" : dir === "BEAR" ? "🔴 SELL" : dir;
  const titles = {
    setup: "🚨 NEW TRADE SIGNAL",
    approaching: "🟡 SIGNAL APPROACHING ENTRY",
    active: "🚨 NEW TRADE SIGNAL",
    tp: "🎯 TAKE PROFIT HIT",
    sl: "🛑 STOP LOSS HIT",
    cancelled: "⚪ TRADE CANCELLED",
    expired: "⌛ TRADE EXPIRED"
  };
  const title = titles[kind] || "Signal Update";
  const rrValue = Number.isFinite(payload.riskReward) ? payload.riskReward : (Number.isFinite(payload.rr) ? payload.rr : null);
  const triggerFactors = normalizeSignalTriggerFactors(
    payload.triggerFactors || payload.factorBreakdown || payload._confFactors || [],
    payload.mtf_status || payload.mtfStatus || null
  )
    .filter((factor) => factor && factor.passed !== false);
  const lines = [];
  lines.push(`<b>${title}</b>`);
  lines.push("");
  lines.push(`<b>Strategy:</b> ${payload.strategyLabel || "Breakout Retest"}`);
  if (payload.signalId) lines.push(`<b>Signal ID:</b> <code>${payload.signalId}</code>`);
  lines.push("");
  lines.push(`<b>Symbol:</b> ${symLabel}`);
  lines.push(`<b>Timeframe:</b> ${tfLabel}`);
  lines.push(`<b>Direction:</b> ${dirLabel}`);
  if (payload.level != null) lines.push(`<b>Key Level:</b> <code>${fmtPrice(payload.level, symbol)}</code>`);
  if (payload.entry != null) lines.push(`<b>Entry:</b> <code>${fmtPrice(payload.entry, symbol)}</code>`);
  if (payload.sl != null) lines.push(`<b>Stop Loss:</b> <code>${fmtPrice(payload.sl, symbol)}</code>`);
  if (payload.tp != null) lines.push(`<b>Take Profit:</b> <code>${fmtPrice(payload.tp, symbol)}</code>`);
  if (rrValue != null) lines.push(`<b>Risk/Reward:</b> 1:${fmt(rrValue, 1)}`);
  if (payload.confidenceScore != null) lines.push(`<b>Signal Quality:</b> ${Math.round((Number(payload.confidenceScore) / 16) * 100)}%`);
  if (payload.adaptiveConfidenceLabel) lines.push(`<b>Adaptive Confidence:</b> ${payload.adaptiveConfidenceLabel}`);
  if (payload.marketCategory) lines.push(`<b>Market Category:</b> ${payload.marketCategory}`);
  if (payload.weightVersion) lines.push(`<b>Learning Weight Version:</b> ${payload.weightVersion}`);
  if (payload.entryMode) lines.push(`<b>Entry Mode:</b> ${payload.entryMode === "aggressive_intrabar" ? "Aggressive Intrabar" : "Confirmed Close"}`);
  if (Number.isFinite(payload.entryDriftAtr)) lines.push(`<b>Entry Drift:</b> ${fmt(payload.entryDriftAtr, 2)} ATR`);
  if (Number.isFinite(payload.distanceAtr)) lines.push(`<b>Distance Now:</b> ${fmt(payload.distanceAtr, 2)} ATR`);
  if (Number.isFinite(payload.maxDistanceAtr)) lines.push(`<b>Max Valid Distance:</b> ${fmt(payload.maxDistanceAtr, 2)} ATR`);
  if (Number.isFinite(payload.stopBufferAtr)) lines.push(`<b>Stop Buffer:</b> ${fmt(payload.stopBufferAtr, 2)} ATR`);
  if (Number.isFinite(payload.atr)) lines.push(`<b>ATR:</b> ${fmt(payload.atr, 3)}`);
  if (Number.isFinite(payload.validUntilMs)) lines.push(`<b>Valid Until:</b> ${formatUtcTs(payload.validUntilMs)}`);
  if (triggerFactors.length > 0 && (kind === "active" || kind === "setup" || kind === "approaching")) {
    lines.push("");
    lines.push(`<b>✅ Trigger Factors</b>`);
    triggerFactors.forEach((factor) => lines.push(`• ${formatSignalFactorLabel(factor)}`));
  }
  if (payload.reason) lines.push(`<b>Reason:</b> ${payload.reason}`);
  lines.push("");
  lines.push(`<i>${formatUtcTs(Date.now())}</i>`);
  return lines.join("\n");
}

/**
 * Maps a lifecycle "kind" (setup/active/tp/sl/cancelled/expired/...) to the
 * notification_type enum accepted by the persistent, database-backed
 * idempotency registry (/api/trades/check_notification). This is what makes
 * duplicate-prevention survive page reloads / app restarts for EVERY
 * strategy that routes through sendSignalLifecycleTelegram() — not just
 * Grid Scalper MA, which previously was the only strategy backed by a
 * database dedup check (via TradeOutcomeService). Root cause of the
 * "duplicate SL notification every few minutes" bug: the old code only
 * guarded against duplicates with an in-memory Set
 * (sendSignalLifecycleTelegram._sentKeys) that is wiped on every reload/
 * restart, so a re-evaluated candle history or reconnect replay could
 * re-fire an already-delivered TP/SL/lifecycle alert.
 */
const LIFECYCLE_NOTIFICATION_TYPE_MAP = {
  setup: "LIFECYCLE_SETUP",
  approaching: "LIFECYCLE_APPROACHING",
  active: "LIFECYCLE_ACTIVE",
  tp: "LIFECYCLE_TP",
  sl: "LIFECYCLE_SL",
  cancelled: "LIFECYCLE_CANCELLED",
  expired: "LIFECYCLE_EXPIRED"
};

/** Small deterministic string hash — used as the `event_hash` idempotency
 *  fingerprint stored alongside every Telegram delivery-log row so the
 *  admin audit trail can detect duplicate events even across the
 *  trade_id/notification_type composite key (Requirement 1). */
function hashLifecycleEventKey(key) {
  let hash = 0;
  const s = String(key || "");
  for (let i = 0; i < s.length; i++) hash = ((hash << 5) - hash + s.charCodeAt(i)) | 0;
  return "evt_" + Math.abs(hash).toString(36);
}

/** Persistent (database-backed) duplicate check — survives reloads/restarts. */
async function isLifecycleNotificationAlreadySent(tradeId, kind) {
  const notifType = LIFECYCLE_NOTIFICATION_TYPE_MAP[kind];
  if (!tradeId || !notifType) return false;
  try {
    if (typeof ITGuruAuth === "undefined" || !ITGuruAuth.isLoggedIn()) return false;
    const resp = await profileApiFetch(
      "../api/trades/check_notification?trade_id=" + encodeURIComponent(tradeId) +
      "&notification_type=" + encodeURIComponent(notifType)
    );
    return !!(resp && resp.sent === true);
  } catch (e) {
    /* If the check itself fails (offline/500), do not block sending — the
       in-memory guard + delivery log still provide protection, and we never
       want a network hiccup to permanently swallow a real TP/SL alert. */
    return false;
  }
}

/** Registers a lifecycle notification as sent in the persistent idempotency
 *  registry so future reloads/restarts can never re-fire it. Best-effort:
 *  failures are logged but never block the caller. */
async function registerLifecycleNotificationSent(tradeId, signalId, kind, status) {
  const notifType = LIFECYCLE_NOTIFICATION_TYPE_MAP[kind];
  if (!tradeId || !notifType) return;
  try {
    if (typeof ITGuruAuth === "undefined" || !ITGuruAuth.isLoggedIn()) return;
    await profileApiFetch("../api/trades/check_notification", {
      method: "POST",
      body: JSON.stringify({
        trade_id: tradeId,
        signal_id: signalId || tradeId,
        notification_type: notifType,
        telegram_status: status === "sent" ? "sent" : (status === "failed" ? "failed" : "skipped")
      })
    });
  } catch (e) { /* best-effort only */ }
}

async function sendSignalLifecycleTelegram(kind, payload, force = false) {
  if (payload && !payload.signalId) {
    const basis = [
      payload.strategyLabel || payload.channel || "signal",
      payload.symbol || getActiveSymbol() || "",
      payload.timeframeSec != null ? payload.timeframeSec : getCurrentGranularitySec(),
      payload.dir || "",
      payload.entry != null ? fmt(payload.entry, 6) : (payload.level != null ? fmt(payload.level, 6) : ""),
      payload.validUntilMs != null ? payload.validUntilMs : ""
    ].join("|");
    let hash = 0;
    for (let i = 0; i < basis.length; i++) hash = ((hash << 5) - hash + basis.charCodeAt(i)) | 0;
    payload.signalId = `lfc-${Math.abs(hash)}`;
  }
  if (!telegramLifecycleAlertsEnabled && !force) return false;
  const now = Date.now();
  if (payload && Number.isFinite(payload.validUntilMs) && now > payload.validUntilMs && kind !== "cancelled" && kind !== "tp" && kind !== "sl") {
    kind = "expired";
    payload = Object.assign({}, payload, { reason: payload.reason || "Signal validity window expired before entry." });
  }
  if (payload && Number.isFinite(payload.distanceAtr) && Number.isFinite(payload.maxDistanceAtr)
      && payload.distanceAtr > payload.maxDistanceAtr && kind !== "cancelled" && kind !== "tp" && kind !== "sl") {
    kind = "cancelled";
    payload = Object.assign({}, payload, {
      reason: `Price stretched ${fmt(payload.distanceAtr, 2)} ATR from entry (limit ${fmt(payload.maxDistanceAtr, 2)} ATR).`
    });
  }
  /* Per-user notification-type toggle. Each lifecycle stage (setup,
     activation, TP, SL, cancelled, expired) is independently gated so, e.g.,
     disabling "Trade Cancelled" never blocks "Trade Setup" and vice versa. */
  if (!force && !isNotificationKindEnabled(kind)) {
    logSignalEngineDebug("TELEGRAM_SKIPPED", { reason: "preference_disabled", kind, signalId: payload && payload.signalId ? payload.signalId : null });
    recordTelegramDeliveryLog(kind, payload || {}, "skipped", { error: "Blocked by user notification preference" });
    return false;
  }
  if (!force && (kind === "setup" || kind === "active") && notificationPreferences.telegram_high_confidence_only
      && Number.isFinite(payload && payload.confidenceScore) && payload.confidenceScore < HIGH_CONFIDENCE_TELEGRAM_THRESHOLD) {
    logSignalEngineDebug("TELEGRAM_SKIPPED", { reason: "high_confidence_only", kind, confidenceScore: payload.confidenceScore });
    recordTelegramDeliveryLog(kind, payload || {}, "skipped", { error: "Blocked by high-confidence-only preference" });
    return false;
  }
  const channel = payload && payload.channel === "strategy" ? "strategy" : "trade";
  const enabled = channel === "strategy" ? telegramStrategyAutoSend : telegramAutoSend;
  if (!enabled && !force) return false;
  let dedupeKey = null;
  let eventHash = null;
  if (payload && payload.signalId) {
    dedupeKey = `${payload.signalId}|${kind}`;
    eventHash = hashLifecycleEventKey(dedupeKey);
    if (!force) {
      sendSignalLifecycleTelegram._sentKeys = sendSignalLifecycleTelegram._sentKeys || new Set();
      sendSignalLifecycleTelegram._inFlightKeys = sendSignalLifecycleTelegram._inFlightKeys || new Set();
      if (sendSignalLifecycleTelegram._sentKeys.has(dedupeKey) || sendSignalLifecycleTelegram._inFlightKeys.has(dedupeKey)) {
        logSignalEngineDebug("TELEGRAM_SKIPPED", { reason: "dedupe", kind, signalId: payload.signalId });
        return false;
      }
      /* Claim the dedup key atomically BEFORE checking persistent registry
         to prevent race condition where two concurrent calls both observe
         the registry as empty, both send the message, then both register.
         Must add to _inFlightKeys before any async operations. */
      sendSignalLifecycleTelegram._inFlightKeys.add(dedupeKey);
      /* Persistent, database-backed check: catches duplicates that the
         in-memory Set cannot, because it survives page reloads, app
         restarts, and reconnects. This is the fix for repeated SL/TP/
         lifecycle notifications recurring after the in-memory guard was
         wiped (e.g. "another SL notification every 5 minutes"). */
      const alreadySent = await isLifecycleNotificationAlreadySent(payload.signalId, kind);
      if (alreadySent) {
        sendSignalLifecycleTelegram._sentKeys.add(dedupeKey);
        sendSignalLifecycleTelegram._inFlightKeys.delete(dedupeKey);
        logSignalEngineDebug("TELEGRAM_SKIPPED", { reason: "dedupe_persisted", kind, signalId: payload.signalId });
        recordTelegramDeliveryLog(kind, payload || {}, "skipped", { error: "Duplicate suppressed by persistent idempotency registry" }, eventHash);
        return false;
      }
    }
  }
  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Lifecycle Telegram skipped: ${err.message}`);
    return false;
  }
  let sent = false;
  try {
    const resultData = await sendTelegramMessage(buildLifecycleTelegramCaption(kind, payload || {}));
    if (!force && dedupeKey) {
      sendSignalLifecycleTelegram._sentKeys = sendSignalLifecycleTelegram._sentKeys || new Set();
      sendSignalLifecycleTelegram._sentKeys.add(dedupeKey);
    }
    sent = true;
    addLog(`📤 Telegram lifecycle alert sent (${kind})`);
    logSignalEngineDebug("TELEGRAM_SENT", {
      kind,
      signalId: payload && payload.signalId ? payload.signalId : null,
      channel
    });
    recordTelegramDeliveryLog(kind, payload || {}, "sent", { response: resultData && resultData.ok ? "ok" : JSON.stringify(resultData || {}) }, eventHash);
    if (!force && payload && payload.signalId) {
      /* Register in the persistent idempotency registry AFTER a confirmed
         successful send only — mirrors the atomicity fix already applied to
         Grid Scalper MA (never mark "sent" before the Telegram call
         resolves, and never persist a dedup record for a failed send).
         Await this write to make it part of the delivery transaction and
         ensure the registration completes before the function resolves. */
      await registerLifecycleNotificationSent(payload.signalId, payload.signalId, kind, "sent");
    }
  } catch (err) {
    addLog(`📤 Lifecycle Telegram error: ${err.message}`);
    logSignalEngineDebug("TELEGRAM_FAILED", {
      kind,
      signalId: payload && payload.signalId ? payload.signalId : null,
      error: err.message
    });
    recordTelegramDeliveryLog(kind, payload || {}, "failed", { error: err.message }, eventHash);
  } finally {
    if (!force && dedupeKey && sendSignalLifecycleTelegram._inFlightKeys) {
      sendSignalLifecycleTelegram._inFlightKeys.delete(dedupeKey);
    }
  }
  return sent;
}

function maybeSendBreakoutLifecycleAlert(kind, extra = {}) {
  if (_historicalProcessing || !breakout) return;
  const currentPrice = candles.length > 0 ? candles[candles.length - 1].close : null;
  if (kind === "setup" && breakout._setupAlertSent) return;
  if (kind === "approaching" && breakout._approachAlertSent) return;
  if (kind === "active" && breakout._activeAlertSent) return;
  const payload = {
    signalId: trade && trade.signalId ? trade.signalId : (breakout && breakout.signalId ? breakout.signalId : null),
    channel: "trade",
    strategyLabel: "Breakout Retest",
    symbol: getActiveSymbol(),
    timeframeSec: getCurrentGranularitySec(),
    dir: breakout.dir,
    level: breakout.level,
    entry: trade && trade.entry != null ? trade.entry : breakout.level,
    sl: trade ? trade.sl : null,
    tp: trade ? trade.tp : null,
    stopBufferAtr: trade ? trade.stopBufferAtr : null,
    entryDriftAtr: trade ? trade.entryDriftAtr : null,
    distanceAtr: getSignalDistanceFromEntry(trade || { entry: breakout.level, atrAtSignal: getAtrReference() }, currentPrice),
    maxDistanceAtr: trade && Number.isFinite(trade.maxEntryDistanceAtr) ? trade.maxEntryDistanceAtr : getSignalDistanceLimitAtr(),
    validUntilMs: trade && Number.isFinite(trade.validUntilMs) ? trade.validUntilMs : Date.now() + getSignalValidityMs(),
    reason: extra.reason || null,
    entryMode: trade && trade.entryMode ? trade.entryMode : null
  };
  if (kind === "setup") breakout._setupAlertSent = true;
  if (kind === "approaching") breakout._approachAlertSent = true;
  if (kind === "active") breakout._activeAlertSent = true;
  sendSignalLifecycleTelegram(kind, payload);
}

function maybeSendBreakoutCancelled(reason) {
  if (_historicalProcessing || !breakout) return;
  if (!breakout._setupAlertSent && !breakout._approachAlertSent) return;
  recordAdaptiveCancellation(reason, { strategy: "breakout_retest", dir: breakout.dir });
  sendSignalLifecycleTelegram("cancelled", {
    signalId: breakout && breakout.signalId ? breakout.signalId : null,
    channel: "trade",
    strategyLabel: "Breakout Retest",
    symbol: getActiveSymbol(),
    timeframeSec: getCurrentGranularitySec(),
    dir: breakout.dir,
    level: breakout.level,
    reason
  });
}

/**
 * Universal guard applied to every strategy — including MTF Top-Down — before
 * a "new trade signal" notification is allowed to go out. A signal must never
 * be delivered without a stop loss and take profit, regardless of which
 * strategy produced it, so this is enforced centrally in the shared
 * notification pipeline rather than left to each strategy's own detector.
 */
function validateSignalExecutionLevels(signal, strategyLabel) {
  const stopLoss = signal ? (signal.stopLoss ?? signal.sl) : null;
  const takeProfit = signal ? (signal.takeProfit ?? signal.tp) : null;
  const hasStopLoss = Number.isFinite(stopLoss);
  const hasTakeProfit = Number.isFinite(takeProfit);
  if (!signal || !hasStopLoss || !hasTakeProfit) {
    console.error(`CRITICAL: ${strategyLabel || "Strategy"} signal rejected — missing stopLoss/takeProfit`, {
      signalId: signal && signal.signalId,
      symbol: signal && signal.symbol,
      stopLoss,
      takeProfit
    });
    addLog(`🚨 CRITICAL — ${strategyLabel || "Strategy"} signal REJECTED (no SL/TP): notification suppressed`);
    logSignalEngineDebug("SIGNAL_REJECTED_MISSING_SLTP", {
      strategyLabel,
      signalId: signal && signal.signalId,
      symbol: signal && signal.symbol,
      stopLoss,
      takeProfit
    });
    return false;
  }
  return true;
}

/**
 * Send a custom strategy alert to Telegram with chart screenshot.
 * Called from processLiquiditySweep, processStopLossHunt, processFailedPinBar.
 */
async function sendTelegramStrategyAlert(signal, force = false) {
  if (!telegramStrategyAutoSend && !force) return;
  if (signal) {
    if (signal._sentViaTelegram !== true) signal._sentViaTelegram = false;
    if (signal._telegramDelivered !== true) signal._telegramDelivered = false;
  }
  if (!validateSignalExecutionLevels(signal, resolveStrategyDisplayLabel(signal && (signal.type || signal.strategyType), signal && (signal.type || signal.strategyType) || "strategy"))) {
    return;
  }

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Strategy Telegram skipped: ${err.message}`);
    return;
  }

  const qualification = await qualifySignalForTelegram(signal, resolveStrategyDisplayLabel(signal.type || signal.strategyType, signal.type || signal.strategyType || "strategy"), force, {
    strategy: signal.strategyType || signal.type || "strategy"
  });
  if (!qualification.allowed) return;

  if (UI.telegramStatus) UI.telegramStatus.textContent = "Sending strategy alert…";
  stampSignalLifecycle(signal);
  const caption = decorateAdaptiveTelegramCaption(buildStrategyTelegramCaption(signal), qualification.decision);
  
  /* Log the caption length for debugging long message issues */
  const captionLength = caption ? caption.length : 0;
  const exceeds = captionLength > TELEGRAM_CAPTION_LIMIT;
  addLog(`📤 Caption Length: ${captionLength} / ${TELEGRAM_CAPTION_LIMIT} ${exceeds ? '⚠️ EXCEEDS LIMIT' : '✓ OK'}`);
  
  try {
    const panel = (signal.symbol && multiPanels.has(signal.symbol)) ? multiPanels.get(signal.symbol) : null;
    const blob = await captureTelegramScreenshot(panel);
    if (blob) {
      await sendTelegramPhoto(blob, caption);
    } else {
      await sendTelegramMessage(caption);
    }
    signal._sentViaTelegram = true;
    signal._telegramDelivered = true;
    addLog(`📤 Strategy Telegram alert sent (${signal.type})`);
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = "✅ Strategy alert sent!";
      UI.telegramStatus.className = "hint telegram-status telegram-ok";
    }
  } catch (err) {
    addLog(`📤 Strategy Telegram error: ${err.message}`);
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = `❌ Strategy: ${err.message}`;
      UI.telegramStatus.className = "hint telegram-status telegram-err";
    }
  }
  setTimeout(() => {
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = "";
      UI.telegramStatus.className = "hint telegram-status";
    }
  }, TELEGRAM_STATUS_CLEAR_MS);
}

/**
 * Centralized WIN/LOSS/EXPIRED resolution-notification deduplication.
 * Every trade-resolution notification sender (strategy outcome, session range
 * outcome, scalp outcome, breakout outcome, etc.) must consult this guard
 * before dispatching so the same trade_id + resolution_type combination can
 * never fire more than once, regardless of how many monitoring loops or
 * per-strategy channels attempt to send it. (Duplicate trade notification fix)
 */
const _tradeResolutionNotificationKeys = new Set();
function tradeResolutionNotificationKey(signal, resolutionType) {
  const tradeId = (signal && (signal.tradeId || signal.signalId)) ||
    `${(signal && signal.type) || "trade"}_${(signal && signal.symbol) || ""}_${signal && signal.candleIdx != null ? signal.candleIdx : (signal && signal.entryIdx)}_${(signal && signal.epoch) || ""}`;
  return `${tradeId}::${resolutionType}`;
}
function canSendTradeResolutionNotification(signal, resolutionType) {
  const key = tradeResolutionNotificationKey(signal, resolutionType);
  if (_tradeResolutionNotificationKeys.has(key)) {
    addLog(`[TRADE] Duplicate notification prevented (${key})`);
    return false;
  }
  _tradeResolutionNotificationKeys.add(key);
  addLog(`[TRADE] Resolution notification queued (${key})`);
  return true;
}

/**
 * Send strategy outcome (WIN / LOSS) via Telegram when enabled.
 * Called from monitorLiquiditySweepOutcomes, monitorStopLossHuntOutcomes,
 * monitorFailedPinBarOutcomes after a signal resolves.
 */
async function sendStrategyOutcomeTelegram(signal) {
  if (!telegramStrategyOutcomeSend) return;
  if (signal.result && !canSendTradeResolutionNotification(signal, signal.result)) return;

  /* Per-user notification-type toggle: EXPIRED outcome summaries respect
     telegram_trade_expired; WIN/LOSS respect telegram_take_profit /
     telegram_stop_loss so this optional stats message never bypasses the
     same independent toggles that gate the lifecycle alerts. */
  const outcomePrefKind = signal.result === "EXPIRED" ? "expired" : signal.result === "WIN" ? "tp" : "sl";
  if (!isNotificationKindEnabled(outcomePrefKind)) {
    logSignalEngineDebug("TELEGRAM_SKIPPED", { reason: "preference_disabled", kind: outcomePrefKind, signalId: signal.signalId || null });
    signal._stratOutcomeSent = true;
    return;
  }

  /* Sync credentials from DOM and validate BEFORE marking the signal as sent,
     so that a bad-credential failure leaves _stratOutcomeSent = false and allows
     a retry once credentials are corrected. (Bug #5 fix) */
  /* #14: credentials kept in sync by the DOM input listener — no need to re-read here */

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Strategy outcome Telegram skipped: ${err.message}`);
    return;
  }

  /* [FIX] Do NOT mark sent yet — wait for successful send to prevent lost notifications */
  /* OLD: signal._stratOutcomeSent = true; ← This was BEFORE the async send! */

  const result = signal.result;
  const activeSym = signal.symbol || getActiveSymbol() || "";
  const sym = getSymbolLabel(activeSym);
  const dir = signal.dir === "BULL" ? "📈 BUY" : "📉 SELL";

  /* Strategy-specific emoji and label */
  let stratEmoji = "📊";
  let stratLabel = "Strategy";
  if (signal.type === "liquidity_sweep") { stratEmoji = "🌊"; stratLabel = "Liquidity Sweep"; }
  else if (signal.type === "stop_loss_hunt") { stratEmoji = "🎯"; stratLabel = "Stop Loss Hunt"; }
  else if (signal.type === "failed_pin_bar") { stratEmoji = "📌"; stratLabel = "Failed Pin Bar"; }
  else if (signal.type === "fib_scalp") { stratEmoji = "📐"; stratLabel = "Fib Golden Zone"; }
  else if (signal.type === "grid_scalper_ma") {
    stratEmoji = "🔲";
    stratLabel = `Grid Scalper MA [${signal.mode === "bos" ? "BOS" : signal.mode === "triple_ma" ? "Triple MA" : "Price vs MA"}]`;
  }
  else if (signal.type === "fvg_strat") { stratEmoji = "🎯"; stratLabel = "Fair Value Gap"; }
  else if (signal.type === "mtf_top_down") { stratEmoji = "⏱"; stratLabel = "MTF Top-Down"; }
  else if (signal.type === "ny_open_range") { stratEmoji = "🕤"; stratLabel = "NY Open Range"; }
  else if (signal.type === "session_range") { stratEmoji = "🌍"; stratLabel = "Session Range"; }
  else if (signal.type === "power_of_3") { stratEmoji = "⚡"; stratLabel = "Power of 3"; }
  else if (signal.type === "orderblock") { stratEmoji = "🏦"; stratLabel = "Orderblock"; }
  else if (signal.type === "tiktok") { stratEmoji = "📈"; stratLabel = "TikTok Fibonacci"; }
  else if (signal.type === "candle_interp") { stratEmoji = "🕯"; stratLabel = "Candle Interpretation"; }

  /* ── EXPIRED: distinct short message, no statistics block ── */
  if (result === "EXPIRED") {
    try {
      const entryStr = signal.entry != null ? fmtPrice(signal.entry, activeSym) : "--";
      const slStr    = signal.sl    != null ? fmtPrice(signal.sl, activeSym)    : "--";
      const tpStr    = signal.tp    != null ? fmtPrice(signal.tp, activeSym)    : "--";
      const rrStr    = signal.rr    != null ? "1:" + fmt(signal.rr, 1)          : "--";
      const lines = [];
      lines.push(`⌛ <b>${stratLabel} — Trade Expired</b> — ${dir} ${sym}`);
      lines.push("");
      lines.push(`Setup timed out — no TP or SL was hit.`);
      lines.push(`<b>📍 Entry:</b> ${entryStr}`);
      lines.push(`<b>🛑 SL:</b> ${slStr}`);
      lines.push(`<b>🎯 TP:</b> ${tpStr}`);
      lines.push(`<b>R:R:</b> ${rrStr}`);
      lines.push(`<i>${new Date().toISOString().replace("T", " ").slice(0, 19)} UTC</i>`);
      await sendTelegramMessage(lines.join("\n"));
      addLog(`📤 Telegram: ${stratLabel} EXPIRED notification sent`);
    } catch (err) {
      addLog(`📤 Strategy expired Telegram error: ${err.message}`);
    }
    return;
  }

  /* ── WIN / LOSS ── */
  try {
    const isBreakevenOutcome = (s) => {
      if (!s || s.result !== "LOSS") return false;
      const raw = s.exitPrice != null ? s.exitPrice : s.sl;
      return raw != null &&
        s.entry != null &&
        Math.abs(raw - s.entry) < PRICE_EPSILON &&
        (s.partialTpHit === true || s._breakeven === true);
    };

    const entryStr = signal.entry != null ? fmtPrice(signal.entry, activeSym) : "--";
    /* Derive exit price: explicit value takes priority; fall back to TP (WIN) or SL (LOSS). */
    const rawExit = signal.exitPrice != null ? signal.exitPrice
      : result === "WIN" ? signal.tp
      : signal.sl;
    const isBreakeven = isBreakevenOutcome(signal);
    const icon = result === "WIN" ? "✅" : (isBreakeven ? "⚖️" : "❌");
    const resultLabel = result === "WIN" ? "WIN" : (isBreakeven ? "BREAKEVEN" : "LOSS");
    const outcomeTitle = result === "WIN" ? "TP Reached" : "SL Hit";
    const exitStr  = rawExit  != null ? fmtPrice(rawExit, activeSym)  : "--";
    const slStr    = signal.sl != null ? fmtPrice(signal.sl, activeSym) : "--";
    const tpStr    = signal.tp != null ? fmtPrice(signal.tp, activeSym) : "--";
    const rrStr    = signal.rr != null ? "1:" + fmt(signal.rr, 1) : "--";

    const lines = [];
    lines.push(`${icon} <b>${stratLabel} — ${outcomeTitle}</b> — ${dir} ${sym}`);
    lines.push("");
    if (signal.signalId) lines.push(`<b>Signal ID:</b> <code>${signal.signalId}</code>`);
    lines.push(`<b>📍 Entry:</b> ${entryStr}`);
    lines.push(`<b>🏁 Exit:</b> ${exitStr}`);
    lines.push(`<b>🛑 SL:</b> ${slStr}`);
    lines.push(`<b>🎯 TP:</b> ${tpStr}`);
    lines.push(`<b>R:R:</b> ${rrStr}`);

    if (signal.type === "failed_pin_bar" && signal.state) {
      lines.push(`<b>State:</b> ${signal.state === "fear" ? "😱 FEAR" : "🤑 GREED"}`);
    }
    if (signal.type === "fib_scalp" && signal.goldenLow != null) {
      lines.push(`<b>Golden Zone:</b> [${fmtPrice(signal.goldenLow, activeSym)} – ${fmtPrice(signal.goldenHigh, activeSym)}]`);
    }
    /* Partial TP info for PO3 and any strategy that sets partialTpHit (Bug #8) */
    if (signal.partialTpHit) {
      lines.push(`<b>🔔 Partial TP:</b> Hit at 1:1 (SL moved to breakeven)`);
    }

    /* Lot size / position sizing based on account amount */
    if (accountSize > 0 && riskPercent > 0 && signal.entry != null && signal.sl != null) {
      const tradeObj = { entry: signal.entry, sl: signal.sl, tp: signal.tp, rr: signal.rr || 0, symbol: signal.symbol || getActiveSymbol() };
      const m = calcPositionMetrics(tradeObj);
      if (m) {
        lines.push(``);
        lines.push(`<b>📦 Lot Size:</b> ${fmt(m.lotSize, 2)}`);
        lines.push(`<b>💰 $ Risk:</b> $${fmt(m.dollarRisk, 2)}`);
        if (signal.tp != null) lines.push(`<b>💰 $ Reward:</b> $${fmt(m.dollarReward, 2)}`);
        if (!m.isSynthetic) {
          lines.push(`<b>📏 Pips at Risk:</b> ${fmt(m.pips, 1)}`);
        }
      }
    }

    /* Win/loss tally across ALL strategy histories — exclude EXPIRED signals */
    let totalW = 0, totalL = 0, totalB = 0;
    const allStratHistories = [
      liquiditySweepHistory, stopLossHuntHistory, failedPinBarHistory,
      po3History, fibScalpHistory, gridScalperMAHistory,
      nyOpenRangeHistory, sessionRangeHistory, fvgStratHistory, tiktokHistory,
      po3_4hHistory, breakerBlockHistory, oteGoldenPocketHistory
    ];
    /* Per-strategy breakdown for this specific strategy.
       Note: this function is only called for secondary strategies — the main breakout
       strategy uses sendTradeOutcomeTelegram(), so signal.type for breakout signals is
       undefined and thisHistory will correctly be null (no per-strategy row shown). */
    let thisW = 0, thisL = 0, thisB = 0;
    const thisHistory = signal.type === "liquidity_sweep" ? liquiditySweepHistory
      : signal.type === "stop_loss_hunt" ? stopLossHuntHistory
      : signal.type === "failed_pin_bar" ? failedPinBarHistory
      : signal.type === "fib_scalp" ? fibScalpHistory
      : signal.type === "grid_scalper_ma" ? gridScalperMAHistory
      : signal.type === "ny_open_range" ? nyOpenRangeHistory
      : signal.type === "session_range" ? sessionRangeHistory
      : signal.type === "power_of_3" ? po3History
      : signal.type === "fvg_strat" ? fvgStratHistory
      : signal.type === "tiktok" ? tiktokHistory
      : signal.type === "po3_4h" ? po3_4hHistory
      : signal.type === "breaker_block" ? breakerBlockHistory
      : signal.type === "ote_golden_pocket" ? oteGoldenPocketHistory : null;
    for (const h of allStratHistories) {
      const isThis = h === thisHistory;
      for (const s of h) {
        if (s.result === "WIN") { totalW++; if (isThis) thisW++; }
        else if (s.result === "LOSS") {
          if (isBreakevenOutcome(s)) { totalB++; if (isThis) thisB++; }
          else { totalL++; if (isThis) thisL++; }
        }
        /* EXPIRED signals are intentionally excluded — SL was not hit */
      }
    }
    const wr = (totalW + totalL) > 0 ? (totalW / (totalW + totalL) * 100).toFixed(1) + "%" : "N/A";
    lines.push("");
    /* Show this strategy's own record first, then combined */
    if (thisHistory && (thisW + thisL + thisB) > 0) {
      const thisWr = (thisW + thisL) > 0 ? (thisW / (thisW + thisL) * 100).toFixed(1) + "%" : "N/A";
      lines.push(`${stratEmoji} <b>${stratLabel} Record:</b> ${thisW}W / ${thisL}L / ${thisB}BE (${thisWr})`);
    }
    if ((totalW + totalL + totalB) > (thisW + thisL + thisB)) {
      lines.push(`📊 <b>All Strategies Combined:</b> ${totalW}W / ${totalL}L / ${totalB}BE (${wr} win rate)`);
    } else {
      lines.push(`${stratEmoji} <b>Strategy Record:</b> ${totalW}W / ${totalL}L / ${totalB}BE (${wr} win rate)`);
    }

    /* Opposite mode effectiveness from auto-trade history */
    const oppTrades = autoTradeHistory.filter(e => e.isOpposite && (e.result === "WIN" || e.result === "LOSS"));
    const normTrades = autoTradeHistory.filter(e => !e.isOpposite && (e.result === "WIN" || e.result === "LOSS"));
    if (oppTrades.length > 0 || normTrades.length > 0) {
      lines.push("");
      if (normTrades.length > 0) {
        const nw = normTrades.filter(e => e.result === "WIN").length;
        const nwr = (nw / normTrades.length * 100).toFixed(1);
        lines.push(`📈 <b>Normal Trades:</b> ${nw}W / ${normTrades.length - nw}L (${nwr}%)`);
      }
      if (oppTrades.length > 0) {
        const ow = oppTrades.filter(e => e.result === "WIN").length;
        const owr = (ow / oppTrades.length * 100).toFixed(1);
        lines.push(`🔄 <b>Opposite Trades:</b> ${ow}W / ${oppTrades.length - ow}L (${owr}%)`);
      }
    }

    /* Shadow outcome — what the opposite direction would have done on this signal.
       For Grid Scalper MA with opposite mode active, signal.result reflects the
       original direction, so shadowResult = what the actual opposite trade did. */
    if (telegramShadowOutcomeSend) {
      const shadowResult = invertResult(result);
      const oppDirLabel  = getOppositeDirLabel(signal.dir);
      const shadowIcon   = getResultIcon(shadowResult);
      lines.push("");
      lines.push(`🔮 <b>Shadow (${oppDirLabel} would've):</b> ${shadowIcon} ${shadowResult}`);

      /* Cumulative shadow stats from auto-trade history */
      const shadowResolved = autoTradeHistory.filter(e => e.shadowResult === "WIN" || e.shadowResult === "LOSS");
      if (shadowResolved.length > 0) {
        const sw  = shadowResolved.filter(e => e.shadowResult === "WIN").length;
        const swr = (sw / shadowResolved.length * 100).toFixed(1);
        lines.push(`   (Shadow record: ${sw}W / ${shadowResolved.length - sw}L — ${swr}%)`);
      }
    }

    lines.push(`<i>${new Date().toISOString().replace("T", " ").slice(0, 19)} UTC</i>`);

    await sendTelegramMessage(lines.join("\n"));
    
    /* [FIX] Mark sent AFTER successful send (not before) */
    signal._stratOutcomeSent = true;
    
    addLog(`📤 Telegram: ${stratLabel} outcome (${result}) sent`);
    
    /* [FIX] Log to database after successful notification */
    if (typeof tradeOutcomeService !== 'undefined' && tradeOutcomeService) {
      const tradeId = signal.tradeId || signal.signalId;
      const notifType = result === "WIN" ? 'TRADE_WIN' : result === "LOSS" ? 'TRADE_LOSS' : 'TRADE_EXPIRED';
      await tradeOutcomeService._recordNotificationSent(tradeId, notifType, 'sent');
    }
  } catch (err) {
    /* [FIX] On error, DO NOT mark sent — allow retry on next cycle */
    addLog(`📤 Strategy outcome Telegram error: ${err.message}`);
  }
}

/**
 * Send a profit exit alert via Telegram when a trade that reached 1:1 profit
 * reverses back to the entry level, warning the trader to protect gains.
 * @param {Object} signal   — trade signal with { dir, entry, sl, tp, rr, symbol, type }
 * @param {string} stratLabel — human-readable strategy name (e.g. "Liquidity Sweep")
 */
async function sendProfitExitAlertTelegram(signal, stratLabel) {
  if (!telegramProfitExitAlertEnabled) return;

  /* Sync credentials from DOM */
  /* #14: credentials kept in sync by the DOM input listener — no need to re-read here */

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Profit exit alert Telegram skipped: ${err.message}`);
    return;
  }

  try {
    const sym = getSymbolLabel(signal.symbol || getActiveSymbol() || "");
    const activeSym = signal.symbol || getActiveSymbol() || "";
    const dir = signal.dir === "BULL" ? "📈 BUY" : "📉 SELL";
    const entryStr = signal.entry != null ? fmtPrice(signal.entry, activeSym) : "--";
    const slStr    = signal.sl    != null ? fmtPrice(signal.sl, activeSym)    : "--";
    const tpStr    = signal.tp    != null ? fmtPrice(signal.tp, activeSym)    : "--";
    const rrStr    = signal.rr    != null ? "1:" + fmt(signal.rr, 1) : "--";

    const origSl = signal._origSl != null ? signal._origSl : signal.sl;
    const risk   = origSl != null && signal.entry != null ? Math.abs(signal.entry - origSl) : null;

    const lines = [];
    lines.push(`⚠️ <b>Exit with Profit — ${stratLabel}</b>`);
    lines.push(``);
    lines.push(`Trade reached <b>1:1 profit</b> but price has reversed back to entry.`);
    lines.push(`Consider closing now to protect your gains before it turns into a loss.`);
    lines.push(``);
    lines.push(`${dir} ${sym}`);
    lines.push(`<b>📍 Entry:</b> <code>${entryStr}</code>`);
    lines.push(`<b>🛑 SL:</b> <code>${slStr}</code>`);
    lines.push(`<b>🎯 TP:</b> <code>${tpStr}</code>`);
    lines.push(`<b>R:R:</b> ${rrStr}`);
    if (risk != null && risk > 0) {
      const oneRStr = signal.dir === "BULL"
        ? fmtPrice(signal.entry + risk, activeSym)
        : fmtPrice(signal.entry - risk, activeSym);
      lines.push(`<b>1R level hit:</b> <code>${oneRStr}</code>`);
    }
    lines.push(``);
    lines.push(`<i>${new Date().toISOString().replace("T", " ").slice(0, 19)} UTC</i>`);

    await sendTelegramMessage(lines.join("\n"));
    addLog(`📤 Telegram: Profit exit alert sent for ${stratLabel}`);
  } catch (err) {
    addLog(`📤 Profit exit alert Telegram error: ${err.message}`);
  }
}

/**
 * Build a Telegram caption for session range signals (tight Asian range / London sweep).
 * @param {"TIGHT_ASIAN"|"LONDON_SWEEP"} signalType
 */
function buildSessionRangeTelegramCaption(signalType) {
  const activeSym = getActiveSymbol() || "";
  const symbol = UI.symbolSelect
    ? (UI.symbolSelect.options[UI.symbolSelect.selectedIndex]
       ? UI.symbolSelect.options[UI.symbolSelect.selectedIndex].text
       : UI.symbolSelect.value)
    : "--";
  const gran = UI.granSelect ? UI.granSelect.value : "--";
  const tfLabel = TIMEFRAME_LABELS[gran] || gran + "s";
  const ts = new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC";

  const lines = [];

  if (signalType === "LONDON_SWEEP") {
    const dir = londonSweepSignal ? londonSweepSignal.dir : "--";
    const sweepEmoji = dir === "HIGH" ? "▲" : "▼";
    const reversal = dir === "HIGH" ? "bearish" : "bullish";
    lines.push(`<b>🌍 London Sweep ${sweepEmoji} Asian ${dir}</b>`);
    lines.push(``);
    lines.push(`<b>Symbol:</b> ${symbol}`);
    lines.push(`<b>Timeframe:</b> ${tfLabel}`);
    lines.push(``);
    if (sessionRangeAsian) {
      lines.push(`<b>Asian Range:</b>`);
      lines.push(`  High: <code>${fmtPrice(sessionRangeAsian.high, activeSym)}</code>`);
      lines.push(`  Low: <code>${fmtPrice(sessionRangeAsian.low, activeSym)}</code>`);
      const rangeSize = sessionRangeAsian.high - sessionRangeAsian.low;
      lines.push(`  Size: <code>${fmtPrice(rangeSize, activeSym)}</code>${asianRangeTight ? " ⚡ TIGHT" : ""}`);
    }
    if (londonSweepSignal) {
      lines.push(``);
      lines.push(`<b>Sweep Price:</b> <code>${fmtPrice(londonSweepSignal.price, activeSym)}</code>`);
      lines.push(`<b>Signal:</b> Potential ${reversal} reversal`);
    }
    if (sessionRangeTrade) {
      const trDir = sessionRangeTrade.dir === "BULL" ? "📈 BUY" : "📉 SELL";
      lines.push(``);
      lines.push(`<b>🎯 Trade Setup:</b> ${trDir}`);
      lines.push(`<b>📍 Entry:</b> <code>${fmtPrice(sessionRangeTrade.entry, activeSym)}</code>`);
      lines.push(`<b>🛑 SL:</b> <code>${fmtPrice(sessionRangeTrade.sl, activeSym)}</code>`);
      lines.push(`<b>🎯 TP:</b> <code>${fmtPrice(sessionRangeTrade.tp, activeSym)}</code>`);
      lines.push(`<b>R:R:</b> 1:${fmt(sessionRangeTrade.rr, 1)}`);
      const trRisk = Math.abs(sessionRangeTrade.entry - sessionRangeTrade.sl);
      if (trRisk > 0) {
        lines.push(`<b>Risk (pips):</b> <code>${fmtPrice(trRisk, activeSym)}</code>`);
      }
    }
    if (sessionRangeLondon) {
      lines.push(``);
      lines.push(`<b>London Range:</b>`);
      lines.push(`  High: <code>${fmtPrice(sessionRangeLondon.high, activeSym)}</code>`);
      lines.push(`  Low: <code>${fmtPrice(sessionRangeLondon.low, activeSym)}</code>`);
    }
  } else {
    /* TIGHT_ASIAN */
    lines.push(`<b>⚡ Tight Asian Range Detected</b>`);
    lines.push(``);
    lines.push(`<b>Symbol:</b> ${symbol}`);
    lines.push(`<b>Timeframe:</b> ${tfLabel}`);
    lines.push(``);
    if (sessionRangeAsian) {
      lines.push(`<b>Asian Range:</b>`);
      lines.push(`  High: <code>${fmtPrice(sessionRangeAsian.high, activeSym)}</code>`);
      lines.push(`  Low: <code>${fmtPrice(sessionRangeAsian.low, activeSym)}</code>`);
      const rangeSize = sessionRangeAsian.high - sessionRangeAsian.low;
      lines.push(`  Size: <code>${fmtPrice(rangeSize, activeSym)}</code>`);
      if (atrValue > 0) {
        lines.push(`  ATR: <code>${fmtPrice(atrValue, activeSym)}</code>`);
        lines.push(`  Ratio: ${fmt(rangeSize / atrValue, 2)}× ATR (< ${ASIAN_TIGHT_ATR_MULT}×)`);
      }
    }
    lines.push(``);
    lines.push(`<b>Signal:</b> Compression likely to expand during London session`);
  }

  if (sessionRangeNY) {
    lines.push(``);
    lines.push(`<b>NY Range:</b>`);
    lines.push(`  High: <code>${fmtPrice(sessionRangeNY.high, activeSym)}</code>`);
    lines.push(`  Low: <code>${fmtPrice(sessionRangeNY.low, activeSym)}</code>`);
  }

  lines.push(``);
  lines.push(`<i>${ts}</i>`);
  return lines.join("\n");
}

async function sendSessionRangeOutcomeTelegram(resolvedTrade, panelSymbol) {
  if (!telegramSessionRangeOutcomeSend) return;
  if (resolvedTrade._stratOutcomeSent) return;  /* Already sent */
  if (resolvedTrade.result && !canSendTradeResolutionNotification(resolvedTrade, resolvedTrade.result)) return;

  /* Sync credentials from DOM */
  if (UI.telegramBotToken) telegramBotToken = UI.telegramBotToken.value;
  if (UI.telegramChatId) telegramChatId = UI.telegramChatId.value;

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Session Range outcome Telegram skipped: ${err.message}`);
    return;
  }

  try {
    const sym = getSymbolLabel(resolvedTrade.symbol || panelSymbol || getActiveSymbol() || "");
    const activeSym = resolvedTrade.symbol || panelSymbol || getActiveSymbol() || "";
    const dir = resolvedTrade.dir === "BULL" ? "📈 BUY" : "📉 SELL";
    const result = resolvedTrade.result;
    const icon = result === "WIN" ? "✅" : "❌";
    const entryStr = resolvedTrade.entry != null ? fmtPrice(resolvedTrade.entry, activeSym) : "--";
    const slStr = resolvedTrade.sl != null ? fmtPrice(resolvedTrade.sl, activeSym) : "--";
    const tpStr = resolvedTrade.tp != null ? fmtPrice(resolvedTrade.tp, activeSym) : "--";
    const rrStr = resolvedTrade.rr != null ? "1:" + fmt(resolvedTrade.rr, 1) : "--";
    const risk = Math.abs(resolvedTrade.entry - resolvedTrade.sl);

    const lines = [];
    lines.push(`${icon} <b>Session Range ${result}</b> — ${dir} ${sym}`);
    lines.push("");
    lines.push(`<b>🌍 London Sweep Trade</b>`);
    lines.push(`<b>📍 Entry:</b> <code>${entryStr}</code>`);
    lines.push(`<b>🛑 SL:</b> <code>${slStr}</code>`);
    lines.push(`<b>🎯 TP:</b> <code>${tpStr}</code>`);
    lines.push(`<b>R:R:</b> ${rrStr}`);
    if (risk > 0) {
      lines.push(`<b>Risk (pips):</b> <code>${fmt(risk, 5)}</code>`);
    }

    /* Lot size / position sizing based on account amount */
    if (accountSize > 0 && riskPercent > 0 && resolvedTrade.entry != null && resolvedTrade.sl != null) {
      const tradeObj = { entry: resolvedTrade.entry, sl: resolvedTrade.sl, tp: resolvedTrade.tp, rr: resolvedTrade.rr || 0, symbol: resolvedTrade.symbol || getActiveSymbol() };
      const m = calcPositionMetrics(tradeObj);
      if (m) {
        lines.push(``);
        lines.push(`<b>📦 Lot Size:</b> ${fmt(m.lotSize, 2)}`);
        lines.push(`<b>💰 $ Risk:</b> $${fmt(m.dollarRisk, 2)}`);
        if (resolvedTrade.tp != null) lines.push(`<b>💰 $ Reward:</b> $${fmt(m.dollarReward, 2)}`);
        if (!m.isSynthetic) {
          lines.push(`<b>📏 Pips at Risk:</b> ${fmt(m.pips, 1)}`);
        }
      }
    }

    /* Win/loss tally */
    const totalW = sessionRangeTradeWins;
    const totalL = sessionRangeTradeLosses;
    const wr = (totalW + totalL) > 0 ? (totalW / (totalW + totalL) * 100).toFixed(1) + "%" : "N/A";
    lines.push("");
    lines.push(`🌍 <b>Session Range Record:</b> ${totalW}W / ${totalL}L (${wr} win rate)`);
    lines.push(`<i>${new Date().toISOString().replace("T", " ").slice(0, 19)} UTC</i>`);

    await sendTelegramMessage(lines.join("\n"));
    resolvedTrade._stratOutcomeSent = true;
    addLog(`📤 Telegram: Session Range outcome (${result}) sent`);
  } catch (err) {
    addLog(`📤 Session Range outcome Telegram error: ${err.message}`);
  }
}

/**
 * Send a session range signal to Telegram with chart screenshot.
 * @param {"TIGHT_ASIAN"|"LONDON_SWEEP"} signalType
 * @param {string|null} panelSymbol  — if non-null, capture this panel's chart instead of the main chart
 */
async function sendTelegramSessionRangeAlert(signalType, panelSymbol) {
  if (!telegramSessionRangeAutoSend) return;
  const panel = panelSymbol ? multiPanels.get(panelSymbol) : null;
  if (panelSymbol && !panel) return;
  const scopedSymbol = panelSymbol || getActiveSymbol();
  const scopedTimeframeSec = panel && Number.isFinite(panel.gran) ? panel.gran : getCurrentGranularitySec();
  const scopedTrade = panel ? (panel.sessionRangeTrade || null) : sessionRangeTrade;
  if (scopedTrade) {
    if (scopedTrade._sentViaTelegram !== true) scopedTrade._sentViaTelegram = false;
    if (scopedTrade._telegramDelivered !== true) scopedTrade._telegramDelivered = false;
  }
  const scopedConfluenceFactors = (() => {
    if (typeof getActiveConfluenceFactors !== "function") return [];
    if (!panel) return getActiveConfluenceFactors();
    const snap = _snapshotChartGlobals();
    const prevPanelSymbol = _multiPanelProcessing;
    const prevPanelGran = _multiPanelGran;
    try {
      activatePanel(panel);
      _multiPanelProcessing = panel.symbol;
      _multiPanelGran = panel.gran || null;
      return getActiveConfluenceFactors();
    } finally {
      _multiPanelProcessing = prevPanelSymbol;
      _multiPanelGran = prevPanelGran;
      _restoreChartGlobals(snap);
    }
  })();

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 Session Range Telegram skipped: ${err.message}`);
    return;
  }

  const pseudoSignal = Object.assign({
    type: "session_range",
    strategyType: "session_range",
    symbol: scopedSymbol,
    dir: (scopedTrade && scopedTrade.dir) || null,
    entry: scopedTrade && scopedTrade.entry,
    sl: scopedTrade && scopedTrade.sl,
    tp: scopedTrade && scopedTrade.tp,
    time: new Date().toISOString(),
    _confFactors: scopedConfluenceFactors
  }, scopedTrade || {});
  const isScopedTradeStillCurrent = () => {
    if (panelSymbol && multiPanels.get(panelSymbol) !== panel) return false;
    if (!scopedTrade) return true;
    return panel ? panel.sessionRangeTrade === scopedTrade : sessionRangeTrade === scopedTrade;
  };
  const qualification = await qualifySignalForTelegram(pseudoSignal, "Session Range", false, { strategy: "session_range", symbol: pseudoSignal.symbol, timeframeSec: scopedTimeframeSec });
  if (!isScopedTradeStillCurrent()) return;
  if (scopedTrade && qualification.decision) scopedTrade._adaptiveDecision = qualification.decision;
  if (!qualification.allowed) return;

  const symLabel = panelSymbol ? getSymbolLabel(panelSymbol) : "";
  const pendingStatusText = `Sending session range${symLabel ? " " + symLabel : ""}…`;
  let trackedTelegramStatus = null;
  const trackedTelegramStatusOwner = {};
  const trackedTelegramStatusInvocationGeneration = (() => {
    if (!UI.telegramStatus) return 0;
    const nextGeneration = Number(UI.telegramStatus._sessionRangeInvocationGeneration || 0) + 1;
    UI.telegramStatus._sessionRangeInvocationGeneration = nextGeneration;
    return nextGeneration;
  })();
  const trackedTelegramStatusGeneration = ((UI.telegramStatus && Number(UI.telegramStatus._sessionRangeStatusGeneration)) || 0) + 1;
  const setTrackedTelegramStatus = (text, className = "hint telegram-status") => {
    if (!UI.telegramStatus) return;
    if (Number(UI.telegramStatus._sessionRangeInvocationGeneration || 0) !== trackedTelegramStatusInvocationGeneration) return;
    UI.telegramStatus.textContent = text;
    UI.telegramStatus.className = className;
    UI.telegramStatus._sessionRangeStatusOwner = trackedTelegramStatusOwner;
    UI.telegramStatus._sessionRangeStatusGeneration = trackedTelegramStatusGeneration;
    trackedTelegramStatus = { owner: trackedTelegramStatusOwner, generation: trackedTelegramStatusGeneration };
  };
  const clearTrackedTelegramStatus = () => {
    if (!trackedTelegramStatus) return;
    const trackedStatus = trackedTelegramStatus;
    trackedTelegramStatus = null;
    if (!UI.telegramStatus) return;
    if (UI.telegramStatus._sessionRangeStatusOwner !== trackedStatus.owner) return;
    if (Number(UI.telegramStatus._sessionRangeStatusGeneration || 0) !== trackedStatus.generation) return;
    UI.telegramStatus.textContent = "";
    UI.telegramStatus.className = "hint telegram-status";
    delete UI.telegramStatus._sessionRangeStatusOwner;
    if (Number(UI.telegramStatus._sessionRangeStatusGeneration || 0) === trackedStatus.generation) {
      delete UI.telegramStatus._sessionRangeStatusGeneration;
    }
  };
  setTrackedTelegramStatus(pendingStatusText);
  try {
    try {
      let caption;
      let blob;
      if (panel) {
        const snap = _snapshotChartGlobals();
        const prevPanelSymbol = _multiPanelProcessing;
        const prevPanelGran = _multiPanelGran;
        const prevUiSymbol = UI.symbolSelect ? UI.symbolSelect.value : null;
        const prevUiGran = UI.granSelect ? UI.granSelect.value : null;
        let capturePromise;
        try {
          activatePanel(panel);
          _multiPanelProcessing = panel.symbol;
          _multiPanelGran = panel.gran || null;
          if (UI.symbolSelect) UI.symbolSelect.value = panel.symbol;
          if (UI.granSelect && Number.isFinite(panel.gran)) UI.granSelect.value = String(panel.gran);
          caption = buildSessionRangeTelegramCaption(signalType);
          capturePromise = captureTelegramScreenshot(null);
        } finally {
          _multiPanelProcessing = prevPanelSymbol;
          _multiPanelGran = prevPanelGran;
          _restoreChartGlobals(snap);
          if (UI.symbolSelect && prevUiSymbol !== null) UI.symbolSelect.value = prevUiSymbol;
          if (UI.granSelect && prevUiGran !== null) UI.granSelect.value = prevUiGran;
        }
        blob = await capturePromise;
        if (!isScopedTradeStillCurrent()) {
          clearTrackedTelegramStatus();
          return;
        }
      } else {
        blob = await captureTelegramScreenshot(null);
        if (!isScopedTradeStillCurrent()) {
          clearTrackedTelegramStatus();
          return;
        }
        caption = buildSessionRangeTelegramCaption(signalType);
      }
      caption = decorateAdaptiveTelegramCaption(caption, qualification.decision);
      if (!isScopedTradeStillCurrent()) {
        clearTrackedTelegramStatus();
        return;
      }
      if (blob) {
        await sendTelegramPhoto(blob, caption);
      } else {
        await sendTelegramMessage(caption);
      }
      pseudoSignal._sentViaTelegram = true;
      pseudoSignal._telegramDelivered = true;
      if (scopedTrade && isScopedTradeStillCurrent()) {
        scopedTrade._sentViaTelegram = true;
        scopedTrade._telegramDelivered = true;
      }
      addLog(`📤 Session Range Telegram alert sent — ${signalType}${symLabel ? " [" + symLabel + "]" : ""}`);
      setTrackedTelegramStatus(`✅ Session range sent!${symLabel ? " (" + symLabel + ")" : ""}`, "hint telegram-status telegram-ok");
    } catch (err) {
      addLog(`📤 Session Range Telegram error: ${err.message}`);
      setTrackedTelegramStatus(`❌ Session: ${err.message}`, "hint telegram-status telegram-err");
    }
  } finally {
    setTimeout(() => {
      clearTrackedTelegramStatus();
    }, TELEGRAM_STATUS_CLEAR_MS);
  }
}

/* ================= TELEGRAM: NY OPEN RANGE PHASE ALERTS ================= */

/**
 * Build a Telegram caption for NY Open Range phase notifications.
 * @param {"RANGE_SET"|"BREAKOUT"} phaseType
 */
function buildNyOpenRangeTelegramCaption(phaseType) {
  const activeSym = getActiveSymbol() || "";
  const symLabel  = getSymbolLabel ? getSymbolLabel(activeSym) : activeSym;
  const gran      = UI.granSelect ? UI.granSelect.value : "--";
  const tfLabel   = TIMEFRAME_LABELS[gran] || gran + "s";
  const ts        = new Date().toISOString().replace("T", " ").slice(0, 19) + " UTC";

  const lines = [];

  if (phaseType === "RANGE_SET") {
    lines.push(`<b>🕤 NY Open Range — Range Established</b>`);
    lines.push(``);
    lines.push(`<b>Symbol:</b> ${symLabel}`);
    lines.push(`<b>Timeframe:</b> ${tfLabel}`);
    lines.push(``);
    lines.push(`<b>🧠 Why triggered:</b>`);
    lines.push(`• The 9:30–9:35 AM EST opening window has closed. Range high and low are now locked in.`);
    if (nyOpenRange) {
      lines.push(``);
      lines.push(`<b>📊 Opening Range:</b>`);
      lines.push(`  <b>High:</b> <code>${fmtPrice(nyOpenRange.high, activeSym)}</code>`);
      lines.push(`  <b>Low:</b> <code>${fmtPrice(nyOpenRange.low, activeSym)}</code>`);
      const rangeSize = nyOpenRange.high - nyOpenRange.low;
      lines.push(`  <b>Size:</b> <code>${fmtPrice(rangeSize, activeSym)}</code>`);
      if (atrValue > 0) {
        lines.push(`  <b>Range / ATR:</b> ${fmt(rangeSize / atrValue, 2)}×`);
      }
    }
    lines.push(``);
    lines.push(`<b>Next step:</b> Watching for a full candle body close outside the range — breakout trigger.`);
  } else if (phaseType === "BREAKOUT") {
    const dir       = nyOpenRangeBreakout ? nyOpenRangeBreakout.dir : "--";
    const dirEmoji  = dir === "BULL" ? "▲" : "▼";
    const dirWord   = dir === "BULL" ? "BULLISH" : "BEARISH";
    const sideWord  = dir === "BULL" ? "above the range high" : "below the range low";
    const nextWord  = dir === "BULL" ? "low wicks into the range but close stays above the high"
                                     : "high wicks into the range but close stays below the low";
    lines.push(`<b>🕤 NY Open Range — ${dirWord} Breakout ${dirEmoji}</b>`);
    lines.push(``);
    lines.push(`<b>Symbol:</b> ${symLabel}`);
    lines.push(`<b>Timeframe:</b> ${tfLabel}`);
    lines.push(``);
    lines.push(`<b>🧠 Why triggered:</b>`);
    lines.push(`• A full candle body (both open and close) closed ${sideWord}, confirming a directional breakout beyond the opening range.`);
    if (nyOpenRange) {
      lines.push(``);
      lines.push(`<b>📊 Opening Range:</b>`);
      lines.push(`  <b>High:</b> <code>${fmtPrice(nyOpenRange.high, activeSym)}</code>`);
      lines.push(`  <b>Low:</b> <code>${fmtPrice(nyOpenRange.low, activeSym)}</code>`);
    }
    if (nyOpenRangeBreakout) {
      lines.push(``);
      lines.push(`<b>🔓 Breakout Level:</b> <code>${fmtPrice(nyOpenRangeBreakout.level, activeSym)}</code>`);
      lines.push(`<b>Direction:</b> ${dir === "BULL" ? "🟢 BULL (BUY)" : "🔴 BEAR (SELL)"}`);
    }
    lines.push(``);
    lines.push(`<b>Next step:</b> Waiting for retest — a candle whose ${nextWord} — to trigger the entry signal.`);
  }

  lines.push(``);
  lines.push(`<i>${ts}</i>`);
  return lines.join("\n");
}

/**
 * Send a NY Open Range phase notification to Telegram with chart screenshot.
 * Gated on telegramStrategyAutoSend.
 * @param {"RANGE_SET"|"BREAKOUT"} phaseType
 */
async function sendTelegramNyOpenRangeAlert(phaseType, panelSymbol = null) {
  if (!telegramStrategyAutoSend) return;
  const panel = panelSymbol ? multiPanels.get(panelSymbol) : null;
  if (panelSymbol && !panel) return;
  const scopedTrade = panel ? (panel.nyOpenRangeTrade || null) : nyOpenRangeTrade;
  const scopedBreakout = panel ? (panel.nyOpenRangeBreakout || null) : nyOpenRangeBreakout;
  if (scopedTrade) {
    if (scopedTrade._sentViaTelegram !== true) scopedTrade._sentViaTelegram = false;
    if (scopedTrade._telegramDelivered !== true) scopedTrade._telegramDelivered = false;
  }
  const scopedConfluenceFactors = (() => {
    if (typeof getActiveConfluenceFactors !== "function") return [];
    if (!panel) return getActiveConfluenceFactors();
    const snap = _snapshotChartGlobals();
    try {
      activatePanel(panel);
      return getActiveConfluenceFactors();
    } finally {
      _restoreChartGlobals(snap);
    }
  })();

  try {
    const { token, chatId } = getTelegramCredentials();
    validateTelegramCredentials(token, chatId);
  } catch (err) {
    addLog(`📤 NY Open Range Telegram skipped: ${err.message}`);
    return;
  }

  const pseudoSignal = Object.assign({
    type: "ny_open_range",
    strategyType: "ny_open_range",
    symbol: panelSymbol || getActiveSymbol(),
    dir: (scopedTrade && scopedTrade.dir) || (scopedBreakout && scopedBreakout.dir) || null,
    entry: scopedTrade && scopedTrade.entry,
    sl: scopedTrade && scopedTrade.sl,
    tp: scopedTrade && scopedTrade.tp,
    time: new Date().toISOString(),
    _confFactors: scopedConfluenceFactors
  }, scopedTrade || {});
  const qualification = await qualifySignalForTelegram(pseudoSignal, "NY Open Range", false, { strategy: "ny_open_range", symbol: pseudoSignal.symbol });
  if (scopedTrade && qualification.decision) scopedTrade._adaptiveDecision = qualification.decision;
  if (!qualification.allowed) return;

  const symLabel = panelSymbol ? getSymbolLabel(panelSymbol) : "";
  if (UI.telegramStatus) UI.telegramStatus.textContent = `Sending NY range alert${symLabel ? " " + symLabel : ""}…`;
  try {
    const blob = await captureTelegramScreenshot(panel || null);
    let caption;
    if (panel) {
      const snap = _snapshotChartGlobals();
      activatePanel(panel);
      caption = buildNyOpenRangeTelegramCaption(phaseType);
      _restoreChartGlobals(snap);
    } else {
      caption = buildNyOpenRangeTelegramCaption(phaseType);
    }
    caption = decorateAdaptiveTelegramCaption(caption, qualification.decision);
    if (blob) {
      await sendTelegramPhoto(blob, caption);
    } else {
      await sendTelegramMessage(caption);
    }
    pseudoSignal._sentViaTelegram = true;
    pseudoSignal._telegramDelivered = true;
    if (scopedTrade) {
      scopedTrade._sentViaTelegram = true;
      scopedTrade._telegramDelivered = true;
    }
    addLog(`📤 NY Open Range Telegram alert sent — ${phaseType}${symLabel ? " [" + symLabel + "]" : ""}`);
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = `✅ NY range alert sent!${symLabel ? " (" + symLabel + ")" : ""}`;
      UI.telegramStatus.className = "hint telegram-status telegram-ok";
    }
  } catch (err) {
    addLog(`📤 NY Open Range Telegram error: ${err.message}`);
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = `❌ NY range: ${err.message}`;
      UI.telegramStatus.className = "hint telegram-status telegram-err";
    }
  }
  setTimeout(() => {
    if (UI.telegramStatus) {
      UI.telegramStatus.textContent = "";
      UI.telegramStatus.className = "hint telegram-status";
    }
  }, TELEGRAM_STATUS_CLEAR_MS);
}

function renderScalpAlerts() {
  if (!UI.scalpAlertList) return;
  UI.scalpAlertList.innerHTML = "";
  const allScalps = getAggregatedScalpHistory();
  for (const s of allScalps) {
    const li = document.createElement("li");
    li.className = "scalp-alert-item " + (s.dir === "BULL" ? "scalp-bull" : "scalp-bear");
    const t = new Date(s.epoch * 1000);
    const ts = t.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    li.innerHTML =
      `<span class="scalp-dir">${s.dir === "BULL" ? "▲ BUY" : "▼ SELL"}</span>` +
      (s.symbol ? `<span class="scalp-symbol">${s.symbol}</span>` : "") +
      `<span class="scalp-price">@ ${fmtPrice(s.entry, s.symbol)}</span>` +
      `<span class="scalp-conf">${s.conf}/7</span>` +
      `<span class="scalp-time">${ts}</span>` +
      `<div class="scalp-reasons">${s.reasons.join(" · ")}</div>` +
      `<div class="scalp-levels">SL: ${fmtPrice(s.sl, s.symbol)} &nbsp;|&nbsp; TP: ${fmtPrice(s.tp, s.symbol)}</div>`;
    UI.scalpAlertList.appendChild(li);
  }
  if (UI.scalpAlertCount) UI.scalpAlertCount.textContent = allScalps.length;
}

function showScalpBanner(scalp) {
  if (!UI.scalpAlertBanner) return;
  const symRaw = getActiveSymbol() || "--";
  const symbol = UI.symbolSelect ? (UI.symbolSelect.options[UI.symbolSelect.selectedIndex]?.text || symRaw) : symRaw;
  const dirLabel = scalp.dir === "BULL" ? "▲ BUY" : "▼ SELL";
  UI.scalpAlertBannerText.textContent = `⚡ SCALP ${dirLabel}  ${symbol}  @ ${fmt(scalp.entry, 4)}  —  Conf ${scalp.conf}/7  —  ${scalp.reasons.slice(0, 3).join(" · ")}`;
  UI.scalpAlertBanner.className = "scalp-banner scalp-banner-show " + (scalp.dir === "BULL" ? "scalp-banner-bull" : "scalp-banner-bear");
  /* Auto-hide after 12 seconds */
  clearTimeout(UI.scalpAlertBanner._hideTimer);
  UI.scalpAlertBanner._hideTimer = setTimeout(() => {
    if (UI.scalpAlertBanner) UI.scalpAlertBanner.classList.remove("scalp-banner-show");
  }, 12000);
}

/* ================= EMA TREND FILTER ================= */
/**
 * Returns true if the EMA 8/21 crossover aligns with the given breakout direction.
 * If emaFilterEnabled is off, always returns true.
 */
function isEmaAligned(dir) {
  if (!emaFilterEnabled) return true;
  const lastFast = emaFast.length > 0 ? emaFast[emaFast.length - 1] : null;
  const lastSlow = emaSlow.length > 0 ? emaSlow[emaSlow.length - 1] : null;
  if (lastFast == null || lastSlow == null) return true; /* not enough data */
  if (dir === "BULL") return lastFast > lastSlow;
  if (dir === "BEAR") return lastFast < lastSlow;
  return true;
}

/* ================= HTF TREND (EMA 100 PROXY) ================= */
/**
 * Returns the higher-timeframe trend direction based on EMA 100.
 * Price above EMA 100 = BULL, below = BEAR, within 0.1% = FLAT.
 */
function getHTFTrend() {
  const lastHTF = emaHTF.length > 0 ? emaHTF[emaHTF.length - 1] : null;
  const lastPrice = candles.length > 0 ? candles[candles.length - 1].close : null;
  if (lastHTF == null || lastPrice == null) return "FLAT";
  if (lastPrice > lastHTF * 1.001) return "BULL";
  if (lastPrice < lastHTF * 0.999) return "BEAR";
  return "FLAT";
}

/**
 * Returns true if the HTF trend agrees with the breakout direction.
 * If htfFilterEnabled is off, always returns true.
 * "FLAT" trend allows both directions.
 */
function isHTFAligned(dir) {
  if (!htfFilterEnabled) return true;
  const trend = getHTFTrend();
  if (trend === "FLAT") return true;
  return trend === dir;
}

/* ================= RSI AT RETEST ================= */
/**
 * Returns true if the RSI confirms the pullback has room to reverse.
 * For BULL retest: RSI should be ≤ RSI_RETEST_BULL_MAX (pulled back enough).
 * For BEAR retest: RSI should be ≥ RSI_RETEST_BEAR_MIN (bounced enough).
 * If rsiFilterEnabled is off, always returns true.
 *
 * #12: Dynamic thresholds based on ADX regime.
 * In a TRENDING market (ADX ≥ ADX_TRENDING_THRESHOLD) the thresholds are relaxed
 * by 10 RSI points so momentum continuation trades in strong trends are not blocked.
 * In a RANGING market (ADX < ADX_RANGING_THRESHOLD) thresholds are tightened by 5
 * to avoid chasing weak mean-reversion moves.
 */
function isRSIFavorable(dir) {
  if (!rsiFilterEnabled) return true;
  if (rsiValues.length === 0) return true;
  const currentRSI = rsiValues[rsiValues.length - 1];
  if (currentRSI == null) return true;
  /* #12: Adjust thresholds based on market regime */
  let bullMax = RSI_RETEST_BULL_MAX;
  let bearMin = RSI_RETEST_BEAR_MIN;
  if (adxValue > 0) {
    if (adxValue >= ADX_TRENDING_THRESHOLD) {
      /* Trending — relax thresholds (allow higher RSI on bull retests, lower on bear) */
      bullMax += 10;
      bearMin -= 10;
    } else if (adxValue < ADX_RANGING_THRESHOLD) {
      /* Ranging — tighten thresholds */
      bullMax -= 5;
      bearMin += 5;
    }
  }
  if (dir === "BULL") return currentRSI <= bullMax;
  if (dir === "BEAR") return currentRSI >= bearMin;
  return true;
}

/* ================= VOLUME SPIKE ON BREAKOUT ================= */
/**
 * Checks if the breakout candle has a significantly larger range than
 * the average of recent candles, serving as a volume/momentum proxy.
 * Synthetic indices have no tick volume, so range is the best proxy.
 * If volumeSpikeEnabled is off, always returns true.
 * @param {number} candleIdx - index of the breakout candle in the candles array
 */
function hasVolumeSpikeOnBreakout(candleIdx) {
  if (!volumeSpikeEnabled) return true;
  if (candleIdx < 0 || candleIdx >= candles.length) return true;
  const startIdx = Math.max(0, candleIdx - VOLUME_SPIKE_LOOKBACK);
  if (startIdx >= candleIdx) return true;
  let sumRange = 0;
  let count = 0;
  for (let i = startIdx; i < candleIdx; i++) {
    sumRange += candles[i].high - candles[i].low;
    count++;
  }
  if (count === 0) return true;
  const avgRange = sumRange / count;
  if (avgRange <= 0) return true;
  const tuning = getMarketTuning();
  const effectiveMult = VOLUME_SPIKE_MULT * tuning.volumeSpikeMult;
  const breakoutRange = candles[candleIdx].high - candles[candleIdx].low;
  return breakoutRange >= avgRange * effectiveMult;
}

/* ================= SESSION FILTER ================= */
/**
 * Returns true if the current UTC hour falls within the active trading session.
 * Sessions help avoid low-liquidity periods that produce noisy signals.
 * If sessionFilterEnabled is off, always returns true.
 */
function isWithinActiveSession() {
  if (!sessionFilterEnabled) return true;
  const hour = new Date().getUTCHours();
  switch (sessionFilterMode) {
    case "london":
      return hour >= SESSION_LONDON.start && hour < SESSION_LONDON.end;
    case "new_york":
      return hour >= SESSION_NEW_YORK.start && hour < SESSION_NEW_YORK.end;
    case "overlap":
      /* Overlap = intersection of London and New York sessions */
      return hour >= Math.max(SESSION_LONDON.start, SESSION_NEW_YORK.start) &&
             hour < Math.min(SESSION_LONDON.end, SESSION_NEW_YORK.end);
    case "asian":
      return hour >= SESSION_ASIAN.start && hour < SESSION_ASIAN.end;
    case "london_ny":
    default:
      return (hour >= SESSION_LONDON.start && hour < SESSION_LONDON.end) ||
             (hour >= SESSION_NEW_YORK.start && hour < SESSION_NEW_YORK.end);
  }
}

function getActiveSessionName() {
  const hour = new Date().getUTCHours();
  const sessions = [];
  if (hour >= SESSION_LONDON.start && hour < SESSION_LONDON.end) sessions.push("London");
  if (hour >= SESSION_NEW_YORK.start && hour < SESSION_NEW_YORK.end) sessions.push("NY");
  if (hour >= SESSION_ASIAN.start && hour < SESSION_ASIAN.end) sessions.push("Asian");
  return sessions.length > 0 ? sessions.join("/") : "Off-Hours";
}

/* ================= FIBONACCI AT RETEST ================= */
/**
 * Finds the nearest Fibonacci retracement level to a price level.
 * Uses the swing from the lookback period before/including the opening range.
 * Returns { level, ratio, from } if within tolerance, or null.
 */
function getFibRetestLevel(level) {
  if (!fibRetestEnabled || !openingRange) return null;
  const lookbackEnd = Math.min(openingRange.endIdx, candles.length - 1);
  const lookbackStart = Math.max(0, lookbackEnd - SWING_LOOKBACK_PERIOD);
  if (lookbackEnd < lookbackStart) return null;

  let swingHigh = -Infinity, swingLow = Infinity;
  for (let i = lookbackStart; i <= lookbackEnd; i++) {
    if (candles[i].high > swingHigh) swingHigh = candles[i].high;
    if (candles[i].low < swingLow) swingLow = candles[i].low;
  }

  const swingRange = swingHigh - swingLow;
  if (swingRange <= 0) return null;
  const tolerance = atrValue > 0
    ? atrValue * FIB_TOLERANCE_ATR_MULT
    : swingRange * 0.02;

  for (const fib of FIB_LEVELS) {
    const fibFromHigh = swingHigh - swingRange * fib;
    if (Math.abs(level - fibFromHigh) <= tolerance) {
      return { level: fibFromHigh, ratio: fib, from: "high" };
    }
    const fibFromLow = swingLow + swingRange * fib;
    if (Math.abs(level - fibFromLow) <= tolerance) {
      return { level: fibFromLow, ratio: fib, from: "low" };
    }
  }
  return null;
}

function hasFibConfluence(level) {
  return getFibRetestLevel(level) !== null;
}

/* ================= BREAKOUT STRENGTH (VOLUME PROXY) ================= */
/**
 * Checks breakout conviction by comparing candle range AND body size to ATR.
 * A strong breakout candle should have:
 *   - range >= 80% of ATR
 *   - body (|close-open|) >= 60% of candle range (strong directional move)
 * When ATR data is unavailable, returns true (no filter).
 */
function hasBreakoutConviction(candle) {
  if (atrValue <= 0) return true;
  const tuning = getMarketTuning();
  const candleRange = candle.high - candle.low;
  const bodySize = Math.abs(candle.close - candle.open);
  const rangeOk = candleRange >= atrValue * 0.8 * tuning.breakoutConvictionMult;
  const bodyOk = candleRange > 0 ? bodySize >= candleRange * 0.6 : false;
  return rangeOk && bodyOk;
}

/* ================= PIN BAR / HAMMER / SHOOTING STAR ================= */
/**
 * Detects pin bar patterns (hammer for bullish, shooting star for bearish).
 * A pin bar has a small body and a long tail (shadow) in the rejection direction.
 * The tail must be >= PIN_BAR_TAIL_RATIO × the body length.
 * @param {object} c - candle object
 * @param {string|null} dir - if provided, only detect pin bars in that direction
 * @returns {boolean}
 */
function isPinBar(c, dir) {
  const body = Math.abs(c.close - c.open);
  const range = c.high - c.low;
  if (range === 0) return false;
  const upperWick = c.high - Math.max(c.open, c.close);
  const lowerWick = Math.min(c.open, c.close) - c.low;

  /* Hammer / bullish pin bar: long lower wick, small body at top */
  if (!dir || dir === "BULL") {
    if (lowerWick >= body * PIN_BAR_TAIL_RATIO && lowerWick > upperWick * PIN_BAR_WICK_DOMINANCE) {
      return true;
    }
  }
  /* Shooting star / bearish pin bar: long upper wick, small body at bottom */
  if (!dir || dir === "BEAR") {
    if (upperWick >= body * PIN_BAR_TAIL_RATIO && upperWick > lowerWick * PIN_BAR_WICK_DOMINANCE) {
      return true;
    }
  }
  return false;
}

/* ================= INSIDE BAR DETECTION ================= */
/**
 * Returns true if 'curr' candle is completely contained within 'prev' candle range.
 * The inside bar indicates consolidation/indecision before a breakout.
 */
function isInsideBar(prev, curr) {
  if (!prev || !curr) return false;
  return curr.high <= prev.high && curr.low >= prev.low;
}

/**
 * Returns true if 'curr' breaks out of the inside bar 'mother' in the given direction.
 */
function isInsideBarBreakout(mother, curr, dir) {
  if (!mother || !curr) return false;
  if (dir === "BULL") return curr.close > mother.high;
  if (dir === "BEAR") return curr.close < mother.low;
  return false;
}

/* ================= MORNING STAR / EVENING STAR ================= */
/**
 * Morning Star: 3-candle bullish reversal.
 *   c1 = large bearish, c2 = small-bodied (star), c3 = large bullish closing into c1.
 */
function isMorningStar(c1, c2, c3) {
  if (!c1 || !c2 || !c3) return false;
  const c1Body = c1.close - c1.open;
  const c2Body = Math.abs(c2.close - c2.open);
  const c3Body = c3.close - c3.open;
  const c1Range = c1.high - c1.low;

  if (c1Body >= 0) return false;              /* c1 must be bearish */
  if (c3Body <= 0) return false;              /* c3 must be bullish */
  if (c1Range === 0) return false;
  if (c2Body / c1Range > STAR_BODY_RATIO) return false;  /* c2 must be small relative to c1 */
  /* c3 should close well into c1's body (at least 50%) */
  const c1MidBody = (c1.open + c1.close) / 2;
  return c3.close >= c1MidBody;
}

/**
 * Evening Star: 3-candle bearish reversal.
 *   c1 = large bullish, c2 = small-bodied (star), c3 = large bearish closing into c1.
 */
function isEveningStar(c1, c2, c3) {
  if (!c1 || !c2 || !c3) return false;
  const c1Body = c1.close - c1.open;
  const c2Body = Math.abs(c2.close - c2.open);
  const c3Body = c3.close - c3.open;
  const c1Range = c1.high - c1.low;

  if (c1Body <= 0) return false;              /* c1 must be bullish */
  if (c3Body >= 0) return false;              /* c3 must be bearish */
  if (c1Range === 0) return false;
  if (c2Body / c1Range > STAR_BODY_RATIO) return false;  /* c2 must be small relative to c1 */
  /* c3 should close well into c1's body (at least 50%) */
  const c1MidBody = (c1.open + c1.close) / 2;
  return c3.close <= c1MidBody;
}

/* ================= PIERCING LINE / DARK CLOUD COVER ================= */
/**
 * Piercing Line (bullish): 2-candle reversal at bottom.
 *   c1 = bearish, c2 = bullish opening below c1 low, closing above midpoint of c1 body.
 * From FOREX_MILLIONAIRE_365_DAYS: Listed among the 7 powerful reversal patterns.
 */
function isPiercingLine(prev, curr) {
  if (!prev || !curr) return false;
  const prevBody = prev.close - prev.open;
  const currBody = curr.close - curr.open;
  if (prevBody >= 0 || currBody <= 0) return false;  /* prev bearish, curr bullish */
  const prevMid = (prev.open + prev.close) / 2;      /* midpoint of prev body */
  /* curr opens below prev low, closes above midpoint but not above prev open (not engulfing) */
  return curr.open <= prev.low && curr.close >= prevMid && curr.close < prev.open;
}

/**
 * Dark Cloud Cover (bearish): 2-candle reversal at top.
 *   c1 = bullish, c2 = bearish opening above c1 high, closing below midpoint of c1 body.
 * From FOREX_MILLIONAIRE_365_DAYS: Listed among the 7 powerful reversal patterns.
 */
function isDarkCloudCover(prev, curr) {
  if (!prev || !curr) return false;
  const prevBody = prev.close - prev.open;
  const currBody = curr.close - curr.open;
  if (prevBody <= 0 || currBody >= 0) return false;  /* prev bullish, curr bearish */
  const prevMid = (prev.open + prev.close) / 2;      /* midpoint of prev body */
  /* curr opens above prev high, closes below midpoint but not below prev open (not engulfing) */
  return curr.open >= prev.high && curr.close <= prevMid && curr.close > prev.open;
}

/* ================= DRAGONFLY / GRAVESTONE DOJI ================= */
/**
 * Dragonfly Doji: long lower shadow, no upper shadow, open ≈ close ≈ high.
 * Bullish reversal at bottom of downtrend.
 * From FOREX_MILLIONAIRE_365_DAYS: "Sellers pushed down, buyers pushed back up."
 */
function isDragonflyDoji(c) {
  if (!c) return false;
  const range = c.high - c.low;
  if (range === 0) return false;
  const body = Math.abs(c.close - c.open);
  const upperWick = c.high - Math.max(c.open, c.close);
  const lowerWick = Math.min(c.open, c.close) - c.low;
  return (body / range < DOJI_BODY_RATIO) && (lowerWick / range > 0.6) && (upperWick / range < 0.1);
}

/**
 * Gravestone Doji: long upper shadow, no lower shadow, open ≈ close ≈ low.
 * Bearish reversal at top of uptrend.
 * From FOREX_MILLIONAIRE_365_DAYS: "Buyers pushed up, sellers pushed back down."
 */
function isGravestoneDoji(c) {
  if (!c) return false;
  const range = c.high - c.low;
  if (range === 0) return false;
  const body = Math.abs(c.close - c.open);
  const upperWick = c.high - Math.max(c.open, c.close);
  const lowerWick = Math.min(c.open, c.close) - c.low;
  return (body / range < DOJI_BODY_RATIO) && (upperWick / range > 0.6) && (lowerWick / range < 0.1);
}

/* ================= TWEEZERS TOPS & BOTTOMS ================= */
/**
 * Tweezers: Two candles with matching highs (tops) or matching lows (bottoms).
 * From FOREX_MILLIONAIRE_365_DAYS: "Market tested level twice and was rejected."
 *
 * Returns "top" | "bottom" | null.
 */
function isTweezers(prev, curr) {
  if (!prev || !curr) return null;
  const tolerance = Math.max(prev.high, curr.high) * TWEEZERS_TOLERANCE_PCT;

  /* Tweezers Top: matching highs, prev bullish + curr bearish */
  if (Math.abs(prev.high - curr.high) <= tolerance) {
    if (prev.close > prev.open && curr.close < curr.open) return "top";
  }
  /* Tweezers Bottom: matching lows, prev bearish + curr bullish */
  if (Math.abs(prev.low - curr.low) <= tolerance) {
    if (prev.close < prev.open && curr.close > curr.open) return "bottom";
  }
  return null;
}

/* ================= RAILWAY TRACK (2-Candle Reversal) ================= */
/**
 * Railway Track: Two consecutive candles of nearly equal body length but
 * opposite direction — a sharp reversal signal.
 * From TRENDLINE_TRADING_STRATEGY.md: Listed as the 7th powerful reversal
 * candlestick pattern alongside doji, engulfing, piercing/dark cloud,
 * harami, hammer/shooting star, and spinning top.
 *
 * Bullish Railway Track: bearish candle followed by bullish candle of similar size.
 * Bearish Railway Track: bullish candle followed by bearish candle of similar size.
 * Bodies must be ≥ 60% of each candle's range (strong conviction candles)
 * and body sizes within 30% of each other.
 *
 * Returns "bull" | "bear" | null.
 */
const RAILWAY_BODY_RANGE_MIN = 0.6;   /* min body/range ratio for each candle */
const RAILWAY_BODY_SIZE_TOL  = 0.30;  /* max difference ratio between body sizes */

function isRailwayTrack(prev, curr) {
  if (!prev || !curr) return null;
  const prevRange = prev.high - prev.low;
  const currRange = curr.high - curr.low;
  if (prevRange === 0 || currRange === 0) return null;
  const prevBody = prev.close - prev.open;          /* signed */
  const currBody = curr.close - curr.open;          /* signed */
  const absPrevBody = Math.abs(prevBody);
  const absCurrBody = Math.abs(currBody);
  /* Both candles must have strong bodies */
  if (absPrevBody / prevRange < RAILWAY_BODY_RANGE_MIN) return null;
  if (absCurrBody / currRange < RAILWAY_BODY_RANGE_MIN) return null;
  /* Opposite direction */
  if (prevBody * currBody >= 0) return null;         /* same sign = not opposite */
  /* Similar body size (within tolerance) */
  const maxBody = Math.max(absPrevBody, absCurrBody);
  if (maxBody === 0) return null;
  if (Math.abs(absPrevBody - absCurrBody) / maxBody > RAILWAY_BODY_SIZE_TOL) return null;
  /* Bullish: prev bearish, curr bullish; Bearish: prev bullish, curr bearish */
  return currBody > 0 ? "bull" : "bear";
}

/* ================= SPIKE REJECTION STRATEGY (Boom/Crash/DEX) ================= */
/**
 * MD-file strategy: Pin Bar Rejection after Spike.
 * From FOREX_MILLIONAIRE_365_DAYS: "Longer tail = more powerful signal" and
 * pin bars at key levels (S/R) are the highest-probability reversal signals.
 *
 * For Boom indices: after an upward spike, look for bearish pin bars
 * (shooting stars) at the spike high → signals spike exhaustion / pullback.
 * For Crash indices: after a downward spike, look for bullish pin bars
 * (hammers) at the spike low → signals spike exhaustion / bounce.
 * For DEX indices: same spike-aware logic — UP variants spike up, DN spike down.
 *
 * Returns { detected, type, dir } or null.
 */
function detectSpikeRejection(idx) {
  const mtype = getMarketType();
  if (mtype !== "boom" && mtype !== "crash" && mtype !== "dex") return null;
  if (idx < 2 || idx >= candles.length) return null;

  const prev = candles[idx - 1];
  const curr = candles[idx];

  /* Determine spike direction based on market type */
  let checkBullSpike = false;
  let checkBearSpike = false;
  if (mtype === "boom") {
    checkBullSpike = true;
  } else if (mtype === "crash") {
    checkBearSpike = true;
  } else if (mtype === "dex") {
    /* DEX UP variants spike up, DEX DN variants spike down */
    const sym = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
    if (/UP$/i.test(sym)) checkBullSpike = true;
    else if (/DN$/i.test(sym)) checkBearSpike = true;
    else { checkBullSpike = true; checkBearSpike = true; }  /* unknown DEX variant: check both directions */
  }

  /* Check if previous candle was a spike */
  if (checkBullSpike && isSpikeCandle(prev, "BULL")) {
    const label = mtype === "dex" ? "DEX UP" : "Boom";
    /* After bullish spike, look for bearish pin bar (shooting star) = rejection */
    if (isPinBar(curr, "BEAR")) {
      return { detected: true, type: "spike_rejection_pinbar", dir: "BEAR",
               desc: `Bearish pin bar after ${label} spike — exhaustion signal` };
    }
    /* Or a bearish engulfing of the spike = power shift */
    if (isBearishEngulfing(prev, curr)) {
      return { detected: true, type: "spike_rejection_engulfing", dir: "BEAR",
               desc: `Bearish engulfing after ${label} spike — sellers taking control` };
    }
  }

  if (checkBearSpike && isSpikeCandle(prev, "BEAR")) {
    const label = mtype === "dex" ? "DEX DN" : "Crash";
    /* After bearish spike, look for bullish pin bar (hammer) = rejection */
    if (isPinBar(curr, "BULL")) {
      return { detected: true, type: "spike_rejection_pinbar", dir: "BULL",
               desc: `Bullish pin bar after ${label} spike — exhaustion signal` };
    }
    /* Or a bullish engulfing of the spike = power shift */
    if (isBullishEngulfing(prev, curr)) {
      return { detected: true, type: "spike_rejection_engulfing", dir: "BULL",
               desc: `Bullish engulfing after ${label} spike — buyers taking control` };
    }
  }

  return null;
}

/* ================= INSIDE BAR FALSE BREAKOUT (Boom/Crash) ================= */
/**
 * MD-file strategy: Inside Bar False Breakout.
 * From FOREX_MILLIONAIRE_365_DAYS: "One of the most powerful price action strategies"
 * and "Banks and institutions use stop-hunting strategies to create liquidity."
 *
 * Detects when price breaks out of an inside bar pattern then quickly reverses
 * back inside the mother bar range — a trap/stop-hunt signal.
 * Especially powerful on Boom/Crash where spikes create false breakouts.
 *
 * Returns { detected, dir, motherIdx } or null.
 */
function detectInsideBarFalseBreakout(idx) {
  if (idx < 3 || idx >= candles.length) return null;

  /* Look back up to 3 candles for an inside bar + false breakout sequence */
  for (let i = idx - 2; i >= Math.max(0, idx - 4); i--) {
    const mother = candles[i];
    const child = candles[i + 1];
    if (!isInsideBar(mother, child)) continue;

    /* Check candles after the inside bar for false breakout + reversal */
    for (let j = i + 2; j <= idx; j++) {
      const breakoutCandle = candles[j];
      const motherMid = (mother.high + mother.low) / 2;
      /* Bullish false breakout: broke below mother.low then closed back inside upper half */
      if (breakoutCandle.low < mother.low && breakoutCandle.close > motherMid && breakoutCandle.close <= mother.high) {
        return { detected: true, dir: "BULL", motherIdx: i,
                 desc: "Inside bar false breakout (bear trap) — bullish reversal" };
      }
      /* Bearish false breakout: broke above mother.high then closed back inside lower half */
      if (breakoutCandle.high > mother.high && breakoutCandle.close < motherMid && breakoutCandle.close >= mother.low) {
        return { detected: true, dir: "BEAR", motherIdx: i,
                 desc: "Inside bar false breakout (bull trap) — bearish reversal" };
      }
    }
  }
  return null;
}

/* ================= DRIFT SWITCH REGIME DETECTION ================= */
/**
 * Drift Switch indices alternate between bullish, bearish, and sideways regimes.
 * Detect the current regime via EMA 8/21 crossover:
 *   - EMA 8 > EMA 21 → bullish regime
 *   - EMA 8 < EMA 21 → bearish regime
 * Also detect recent regime switches (crossover in last N candles).
 *
 * Returns { regime, recentSwitch, desc } or null if insufficient data.
 */
const DRIFT_SWITCH_LOOKBACK = 10; /* candles to check for recent EMA crossover */

function detectDriftSwitchRegime() {
  if (emaFast.length < 2 || emaSlow.length < 2) return null;
  const lastFast = emaFast[emaFast.length - 1];
  const lastSlow = emaSlow[emaSlow.length - 1];
  if (lastFast == null || lastSlow == null) return null;

  const regime = lastFast > lastSlow ? "BULL" : lastFast < lastSlow ? "BEAR" : "FLAT";

  /* Check for recent EMA crossover (regime switch) */
  let recentSwitch = false;
  const checkLen = Math.min(DRIFT_SWITCH_LOOKBACK, emaFast.length - 1, emaSlow.length - 1);
  for (let i = 1; i <= checkLen; i++) {
    const fi = emaFast[emaFast.length - 1 - i];
    const si = emaSlow[emaSlow.length - 1 - i];
    if (fi == null || si == null) continue;
    /* Previous was opposite? → crossover happened */
    if ((regime === "BULL" && fi < si) || (regime === "BEAR" && fi > si)) {
      recentSwitch = true;
      break;
    }
  }

  const desc = recentSwitch
    ? `Drift Switch regime switch to ${regime} detected (EMA 8/${regime === "BULL" ? ">" : "<"} EMA 21 crossover)`
    : `Drift Switch in ${regime} regime (EMA 8 ${regime === "BULL" ? ">" : "<"} EMA 21)`;
  return { regime, recentSwitch, desc };
}

/* ================= DAILY RESET PREFERRED DIRECTION ================= */
/**
 * Daily Reset indices have a natural trend direction:
 *   - RDBULL → trending BULL (up)
 *   - RDBEAR → trending BEAR (down)
 * Returns "BULL" | "BEAR" | null.
 */
function getDailyResetPreferredDir() {
  const sym = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
  if (/^RDBULL/i.test(sym)) return "BULL";
  if (/^RDBEAR/i.test(sym)) return "BEAR";
  return null;
}

/* ================= SUPPLY/DEMAND ZONE DETECTION (Jump Indices) ================= */
/**
 * MD-file strategy: Supply & Demand Zones.
 * From FOREX_MILLIONAIRE_365_DAYS: Quality S&D zones have
 * "Quick, strong departure from zone" — exactly what Jump candles produce.
 *
 * Scans recent candles for zones where price departed rapidly (jump candle),
 * then checks if current price has returned to that zone.
 * Returns { zone, type } or null.
 */
const SD_ZONE_LOOKBACK = 30;
const SD_ZONE_TOUCH_TOLERANCE = 0.5; /* ATR multiplier for zone proximity */

function detectSupplyDemandZone(idx) {
  if (idx < 2 || idx >= candles.length || atrValue <= 0) return null;
  const currentPrice = candles[idx].close;
  const tolerance = atrValue * SD_ZONE_TOUCH_TOLERANCE;
  const lookbackStart = Math.max(0, idx - SD_ZONE_LOOKBACK);

  for (let i = lookbackStart; i < idx - 1; i++) {
    if (!isJumpCandle(i)) continue;
    const jumpC = candles[i];
    const body = jumpC.close - jumpC.open;

    if (body > 0) {
      /* Bullish jump → created a demand zone at the jump's low area */
      const demandZoneTop = Math.min(jumpC.open, jumpC.close);
      const demandZoneBot = jumpC.low;
      if (currentPrice >= demandZoneBot - tolerance && currentPrice <= demandZoneTop + tolerance) {
        return { zone: { top: demandZoneTop, bottom: demandZoneBot }, type: "demand",
                 desc: "Price returning to demand zone from bullish jump — buy opportunity" };
      }
    } else if (body < 0) {
      /* Bearish jump → created a supply zone at the jump's high area */
      const supplyZoneBot = Math.max(jumpC.open, jumpC.close);
      const supplyZoneTop = jumpC.high;
      if (currentPrice >= supplyZoneBot - tolerance && currentPrice <= supplyZoneTop + tolerance) {
        return { zone: { top: supplyZoneTop, bottom: supplyZoneBot }, type: "supply",
                 desc: "Price returning to supply zone from bearish jump — sell opportunity" };
      }
    }
  }
  return null;
}

/* ================= MOMENTUM IMPULSE DETECTION (Jump Indices) ================= */
/**
 * MD-file strategy: Momentum / Impulsive Move.
 * From FOREX_MILLIONAIRE_365_DAYS: "Best place to buy is at beginning of impulsive move."
 *
 * Detects the start of an impulsive move by looking for:
 * 1. A jump/gap candle (the impulse trigger)
 * 2. Followed by continuation in the same direction (momentum confirmation)
 * Returns { dir, strength } or null.
 */
function detectMomentumImpulse(idx) {
  if (idx < 3 || idx >= candles.length) return null;

  /* Check if the previous 2-3 candles show impulse pattern */
  for (let start = idx - 2; start >= Math.max(0, idx - 3); start--) {
    if (!isJumpCandle(start)) continue;
    const jumpDir = candles[start].close > candles[start].open ? "BULL" : "BEAR";

    /* Check subsequent candles continue in the same direction */
    let continuation = 0;
    for (let j = start + 1; j <= idx; j++) {
      const dir = candles[j].close > candles[j].open ? "BULL" : "BEAR";
      if (dir === jumpDir) continuation++;
    }

    if (continuation >= 1) {
      return { dir: jumpDir, strength: continuation,
               desc: `Momentum impulse ${jumpDir} — ${continuation + 1} candles in same direction after jump` };
    }
  }
  return null;
}

/* ================= TRENDLINE TOUCH (Step Index) ================= */
/**
 * MD-file strategy: Trendline Third-Touch Entry.
 * From TRENDLINE_TRADING_STRATEGY: "You enter on point 3, 4, 5 after the pullback"
 * and "Only wait for the third touch before considering trendline valid."
 *
 * For Step Index's orderly movement, we detect swing lows (uptrend) or
 * swing highs (downtrend) that align on a trendline, and count touches.
 * Returns { dir, touches, slope } or null when ≥ 3 touches found.
 */
const TRENDLINE_MIN_TOUCHES = 3;
const TRENDLINE_TOLERANCE_ATR = 0.3;

function detectTrendlineTouch(idx) {
  if (idx < 10 || idx >= candles.length || atrValue <= 0) return null;
  const tolerance = atrValue * TRENDLINE_TOLERANCE_ATR;
  const lookback = Math.max(0, idx - 40);

  /* Collect recent swing lows for uptrend trendline */
  const swingLows = [];
  for (let i = lookback + SWING_NEIGHBOR_BARS; i <= idx - SWING_NEIGHBOR_BARS; i++) {
    if (isTrueSwingLow(i)) swingLows.push({ idx: i, price: candles[i].low });
  }

  /* Collect recent swing highs for downtrend trendline */
  const swingHighs = [];
  for (let i = lookback + SWING_NEIGHBOR_BARS; i <= idx - SWING_NEIGHBOR_BARS; i++) {
    if (isTrueSwingHigh(i)) swingHighs.push({ idx: i, price: candles[i].high });
  }

  /* Check ascending trendline (connect swing lows) — bullish */
  if (swingLows.length >= 2) {
    const first = swingLows[0];
    const last = swingLows[swingLows.length - 1];
    if (last.idx !== first.idx) {
      const slope = (last.price - first.price) / (last.idx - first.idx);
      if (slope > 0) {
        let touches = 0;
        for (const sw of swingLows) {
          const expected = first.price + slope * (sw.idx - first.idx);
          if (Math.abs(sw.price - expected) <= tolerance) touches++;
        }
        /* Check if current candle is near the trendline */
        const expectedNow = first.price + slope * (idx - first.idx);
        const currentLow = candles[idx].low;
        if (touches >= TRENDLINE_MIN_TOUCHES && Math.abs(currentLow - expectedNow) <= tolerance) {
          return { dir: "BULL", touches, slope,
                   desc: `Ascending trendline touch #${touches} — buy on pullback to support` };
        }
      }
    }
  }

  /* Check descending trendline (connect swing highs) — bearish */
  if (swingHighs.length >= 2) {
    const first = swingHighs[0];
    const last = swingHighs[swingHighs.length - 1];
    if (last.idx !== first.idx) {
      const slope = (last.price - first.price) / (last.idx - first.idx);
      if (slope < 0) {
        let touches = 0;
        for (const sw of swingHighs) {
          const expected = first.price + slope * (sw.idx - first.idx);
          if (Math.abs(sw.price - expected) <= tolerance) touches++;
        }
        const expectedNow = first.price + slope * (idx - first.idx);
        const currentHigh = candles[idx].high;
        if (touches >= TRENDLINE_MIN_TOUCHES && Math.abs(currentHigh - expectedNow) <= tolerance) {
          return { dir: "BEAR", touches, slope,
                   desc: `Descending trendline touch #${touches} — sell on pullback to resistance` };
        }
      }
    }
  }

  return null;
}

/* ================= DYNAMIC MA SUPPORT/RESISTANCE (Step Index) ================= */
/**
 * MD-file strategy: Moving Average (8 & 21 SMA) as Dynamic S/R.
 * From FOREX_MILLIONAIRE_365_DAYS: MA acts as "dynamic support" (uptrend) or
 * "dynamic resistance" (downtrend). "Very important factor of confluence."
 *
 * Checks if price is bouncing off EMA 8 or EMA 21.
 * Returns { level, ema, dir } or null.
 */
function detectMABounce(idx) {
  if (idx < 1 || idx >= candles.length) return null;
  if (emaFast.length <= idx || emaSlow.length <= idx) return null;
  const fast = emaFast[idx];
  const slow = emaSlow[idx];
  if (fast == null || slow == null) return null;

  const c = candles[idx];
  const tolerance = atrValue > 0 ? atrValue * 0.3 : (c.high - c.low) * 0.5;

  /* In uptrend (fast > slow): look for price bouncing off EMA as support */
  if (fast > slow) {
    if (c.low <= fast + tolerance && c.close > fast) {
      return { level: fast, ema: "EMA8", dir: "BULL",
               desc: "Price bouncing off EMA 8 support — bullish continuation" };
    }
    if (c.low <= slow + tolerance && c.close > slow) {
      return { level: slow, ema: "EMA21", dir: "BULL",
               desc: "Price bouncing off EMA 21 support — bullish continuation" };
    }
  }

  /* In downtrend (fast < slow): look for price rejected by EMA as resistance */
  if (fast < slow) {
    if (c.high >= fast - tolerance && c.close < fast) {
      return { level: fast, ema: "EMA8", dir: "BEAR",
               desc: "Price rejected at EMA 8 resistance — bearish continuation" };
    }
    if (c.high >= slow - tolerance && c.close < slow) {
      return { level: slow, ema: "EMA21", dir: "BEAR",
               desc: "Price rejected at EMA 21 resistance — bearish continuation" };
    }
  }

  return null;
}

/* ================= S/R CONFLUENCE CHECK ================= */
/**
 * Checks if the breakout level coincides with a recent swing high or swing low,
 * providing double support/resistance confirmation.
 * Returns true if the level is within ATR tolerance of a recent swing point.
 */
function hasSRConfluence(level) {
  if (level == null || candles.length < SWING_LOOKBACK_PERIOD) return false;
  const tolerance = atrValue > 0 ? atrValue * SR_CONFLUENCE_ATR_MULT : Math.abs(level * SR_CONFLUENCE_PRICE_PCT);
  const lookbackStart = Math.max(0, candles.length - SWING_LOOKBACK_PERIOD);

  /* Check for true swing highs/lows near the level */
  for (let i = lookbackStart + SWING_NEIGHBOR_BARS; i < candles.length - SWING_NEIGHBOR_BARS; i++) {
    if (isTrueSwingHigh(i) && Math.abs(candles[i].high - level) <= tolerance) return true;
    if (isTrueSwingLow(i) && Math.abs(candles[i].low - level) <= tolerance) return true;
  }

  return false;
}

/* ================= FALSE BREAKOUT DETECTION ================= */
/**
 * After a breakout is detected, check if the next FALSE_BREAKOUT_CANDLES candles
 * have all closed back inside the opening range, invalidating the breakout.
 * Returns true if the breakout appears false.
 */
function isFalseBreakout(currentIdx) {
  if (!falseBreakoutEnabled || !breakout || !openingRange) return false;
  /* Need at least FALSE_BREAKOUT_CANDLES after breakout to judge */
  const checkStart = breakout.candleIdx + 1;
  const checkEnd = Math.min(checkStart + FALSE_BREAKOUT_CANDLES, candles.length);
  if (currentIdx < checkStart + FALSE_BREAKOUT_CANDLES - 1) return false;

  let allInside = true;
  for (let i = checkStart; i < checkEnd; i++) {
    const c = candles[i];
    if (c.close > openingRange.high || c.close < openingRange.low) {
      allInside = false;
      break;
    }
  }
  return allInside;
}

/* ================= CONFLUENCE SCORE ================= */
/**
 * Computes a quality score for the current setup based on multiple factors.
 * Base factors (0-9): EMA, HTF, breakout strength, pin/inside bar at retest,
 * S/R confluence, RSI, volume spike, active session, Fibonacci.
 * Market-type bonus (+1-3): spike rejection / S&D zone / trendline / MA bounce,
 * preferred direction alignment (Boom/Crash), step run / jump impulse.
 * Maximum possible varies by market type (9-12).
 */
function computeConfluenceScore(overrideDir, overrideLevel, overrideCandleIdx) {
  /* When called without args: use main breakout context (full state available).
     When called with args (secondary strategies): use the provided direction,
     level, and candle index instead of breakout/retestInfo state. */
  const dir   = overrideDir   !== undefined ? overrideDir   : (breakout ? breakout.dir   : null);
  const level = overrideLevel !== undefined ? overrideLevel : (breakout ? breakout.level : null);
  if (!dir) return 0;
  /* hasBoCtx: true only when called with no args (main strategy — full breakout state available) */
  const hasBoCtx = overrideDir === undefined && overrideLevel === undefined && overrideCandleIdx === undefined && !!breakout;
  /* Breakout-state factors also count for secondary strategies when the main breakout
     state exists and matches the signal direction (keeps score consistent with the
     Required Confluences gate and the stats panel). */
  const boMatch = hasBoCtx || (!!breakout && breakout.dir === dir);

  let score = 0;

  /* Factor 1: EMA alignment */
  const lastFast = emaFast.length > 0 ? emaFast[emaFast.length - 1] : null;
  const lastSlow = emaSlow.length > 0 ? emaSlow[emaSlow.length - 1] : null;
  if (lastFast != null && lastSlow != null) {
    if ((dir === "BULL" && lastFast > lastSlow) ||
        (dir === "BEAR" && lastFast < lastSlow)) {
      score++;
    }
  }

  /* Factor 2: HTF trend alignment (only counts if actually aligned, not just FLAT) */
  const htf = getHTFTrend();
  if (htf === dir) score++;

  /* Factor 3: Strong breakout candle (breakout state matching signal direction) */
  if (boMatch && breakout.strong) score++;

  /* Factor 4: Pin bar, inside bar, dragonfly/gravestone doji, tweezers, or railway track at retest
     (breakout state matching signal direction — requires retestInfo from the breakout state machine) */
  if (boMatch && retestInfo && retestInfo.candleIdx < candles.length) {
    const rc = candles[retestInfo.candleIdx];
    const prevRC = retestInfo.candleIdx > 0 ? candles[retestInfo.candleIdx - 1] : null;
    if (isPinBar(rc, dir) || (prevRC && isInsideBar(prevRC, rc)) ||
        (dir === "BULL" && isDragonflyDoji(rc)) ||
        (dir === "BEAR" && isGravestoneDoji(rc)) ||
        (prevRC && isTweezers(prevRC, rc)) ||
        (prevRC && isRailwayTrack(prevRC, rc))) {
      score++;
    }
  }

  /* Factor 5: S/R confluence */
  if (level != null && hasSRConfluence(level)) score++;

  /* Factor 5b: Extra confirmation pattern quality (breakout state matching signal direction) */
  if (boMatch && confirmInfo && confirmInfo.pattern) {
    const p = confirmInfo.pattern;
    if (p === "piercing line" || p === "dark cloud cover" ||
        p === "tweezers bottom" || p === "tweezers top" ||
        p === "dragonfly doji" || p === "gravestone doji" ||
        p === "railway track (bullish)" || p === "railway track (bearish)") {
      score++;
    }
  }

  /* Factor 6: RSI favorable */
  if (rsiValues.length > 0) {
    const rsi = rsiValues[rsiValues.length - 1];
    if (rsi != null) {
      if ((dir === "BULL" && rsi <= RSI_RETEST_BULL_MAX) ||
          (dir === "BEAR" && rsi >= RSI_RETEST_BEAR_MIN)) {
        score++;
      }
    }
  }

  /* Factor 7: Volume spike — use breakout candle for main strategy, signal candle for secondary */
  {
    const vIdx = hasBoCtx ? breakout.candleIdx : (overrideCandleIdx !== undefined ? overrideCandleIdx : candles.length - 1);
    if (vIdx >= 0 && vIdx < candles.length && hasVolumeSpikeOnBreakout(vIdx)) score++;
  }

  /* Factor 8: Within active trading session */
  if (isWithinActiveSession()) score++;

  /* Factor 9: Fibonacci confluence at key level */
  if (level != null && hasFibConfluence(level)) score++;

  /* Factor 10: Market-type-specific signal confluence */
  const mtype = getMarketType();
  const lastIdx = candles.length - 1;

  if (mtype === "boom" || mtype === "crash" || mtype === "dex") {
    /* Spike rejection or inside bar false breakout at current position */
    const spikeRej = detectSpikeRejection(lastIdx);
    const ibFalse = detectInsideBarFalseBreakout(lastIdx);
    if ((spikeRej && spikeRej.dir === dir) || (ibFalse && ibFalse.dir === dir)) {
      score++;
    }
  } else if (mtype === "jump") {
    const sdZone = detectSupplyDemandZone(lastIdx);
    const impulse = detectMomentumImpulse(lastIdx);
    if ((sdZone && ((sdZone.type === "demand" && dir === "BULL") ||
                    (sdZone.type === "supply" && dir === "BEAR"))) ||
        (impulse && impulse.dir === dir)) {
      score++;
    }
  } else if (mtype === "step") {
    const tlTouch = detectTrendlineTouch(lastIdx);
    const maBounce = detectMABounce(lastIdx);
    if ((tlTouch && tlTouch.dir === dir) || (maBounce && maBounce.dir === dir)) {
      score++;
    }
  } else if (mtype === "dailyreset") {
    /* Daily Reset: breakout aligned with natural trend direction (RDBULL→BULL, RDBEAR→BEAR) */
    const drPref = getDailyResetPreferredDir();
    if (drPref && drPref === dir) {
      score++;
    }
  } else if (mtype === "driftswitch") {
    /* Drift Switch: breakout aligned with current EMA crossover regime */
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime && dsRegime.regime === dir) {
      score++;
    }
  }

  /* Factor 11: Preferred direction alignment for Boom/Crash/DEX/DriftSwitch */
  const tuning = getMarketTuning();
  if (tuning.preferredDir && tuning.preferredDir === dir) {
    score++;
  }
  /* DEX direction preference from UP/DN variant (not in tuning.preferredDir which is null) */
  if (mtype === "dex") {
    const sym = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
    if ((/UP$/i.test(sym) && dir === "BULL") ||
        (/DN$/i.test(sym) && dir === "BEAR")) {
      score++;
    }
  }
  /* Drift Switch: recent regime switch bonus (fresh crossover = strong signal) */
  if (mtype === "driftswitch") {
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime && dsRegime.recentSwitch && dsRegime.regime === dir) {
      score++;
    }
  }

  /* Factor 12: Step run momentum or Jump impulse confirmation */
  if (mtype === "step") {
    const run = getStepRunLength();
    if ((dir === "BULL" && run >= STEP_RUN_THRESHOLD) ||
        (dir === "BEAR" && run <= -STEP_RUN_THRESHOLD)) {
      score++;
    }
  } else if (mtype === "jump") {
    const impulse = detectMomentumImpulse(lastIdx);
    if (impulse && impulse.dir === dir && impulse.strength >= 2) {
      score++;
    }
  }

  /* Factor 13 (GainzAlgo V2): MACD histogram alignment */
  {
    const hist = getCurrentMACD();
    if (hist != null) {
      if ((dir === "BULL" && hist > 0) || (dir === "BEAR" && hist < 0)) score++;
    }
  }

  /* Factor 14 (GainzAlgo V2): Bollinger Band squeeze preceding breakout */
  if (isBBSqueeze()) score++;

  /* Factor 15 (GainzAlgo V2): ADX trending confirmation */
  if (adxValue >= ADX_TRENDING_THRESHOLD) score++;

  /* Factor 16 (GainzAlgo V2): Stochastic momentum alignment */
  {
    const k = getCurrentStoch();
    if (k != null) {
      if ((dir === "BULL" && k <= 50) || (dir === "BEAR" && k >= 50)) score++;
    }
  }

  return score;
}

/* Returns an array of human-readable factor names that are currently active
   for the given signal.  Mirrors computeConfluenceScore() exactly but collects
   factor names instead of incrementing a counter.  Used by Feature 13 (adaptive
   confluence weighting) to record per-factor outcomes. */
function getActiveConfluenceFactors(overrideDir, overrideLevel, overrideCandleIdx) {
  const dir   = overrideDir   !== undefined ? overrideDir   : (breakout ? breakout.dir   : null);
  const level = overrideLevel !== undefined ? overrideLevel : (breakout ? breakout.level : null);
  if (!dir) return [];
  const hasBoCtx = overrideDir === undefined && overrideLevel === undefined && overrideCandleIdx === undefined && !!breakout;
  /* Breakout-state factors (Strong Breakout / Confirm Pattern / Confirm Quality) also count for
     secondary strategies when the main breakout state exists and matches the signal direction —
     this keeps the Required Confluences gate consistent with the stats panel, which reads the
     same global breakout state. */
  const boMatch = hasBoCtx || (!!breakout && breakout.dir === dir);

  const factors = [];

  /* Factor 1: EMA alignment */
  const lastFast = emaFast.length > 0 ? emaFast[emaFast.length - 1] : null;
  const lastSlow = emaSlow.length > 0 ? emaSlow[emaSlow.length - 1] : null;
  if (lastFast != null && lastSlow != null) {
    if ((dir === "BULL" && lastFast > lastSlow) || (dir === "BEAR" && lastFast < lastSlow)) factors.push("EMA Aligned");
  }

  /* Factor 2: HTF trend alignment */
  const htf = getHTFTrend();
  if (htf === dir) factors.push("HTF Trend");

  /* Factor 3: Strong breakout candle (breakout state matching signal direction) */
  if (boMatch && breakout.strong) factors.push("Strong Breakout");

  /* Factor 4: Confirm pattern at retest (breakout state matching signal direction) */
  if (boMatch && retestInfo && retestInfo.candleIdx < candles.length) {
    const rc = candles[retestInfo.candleIdx];
    const prevRC = retestInfo.candleIdx > 0 ? candles[retestInfo.candleIdx - 1] : null;
    if (isPinBar(rc, dir) || (prevRC && isInsideBar(prevRC, rc)) ||
        (dir === "BULL" && isDragonflyDoji(rc)) ||
        (dir === "BEAR" && isGravestoneDoji(rc)) ||
        (prevRC && isTweezers(prevRC, rc)) ||
        (prevRC && isRailwayTrack(prevRC, rc))) {
      factors.push("Confirm Pattern");
    }
  }

  /* Factor 5: S/R confluence */
  if (level != null && hasSRConfluence(level)) factors.push("S/R Level");

  /* Factor 5b: Extra confirmation pattern quality (breakout state matching signal direction) */
  if (boMatch && confirmInfo && confirmInfo.pattern) {
    const p = confirmInfo.pattern;
    if (p === "piercing line" || p === "dark cloud cover" ||
        p === "tweezers bottom" || p === "tweezers top" ||
        p === "dragonfly doji" || p === "gravestone doji" ||
        p === "railway track (bullish)" || p === "railway track (bearish)") {
      factors.push("Confirm Quality");
    }
  }

  /* Factor 6: RSI favorable */
  if (rsiValues.length > 0) {
    const rsi = rsiValues[rsiValues.length - 1];
    if (rsi != null) {
      if ((dir === "BULL" && rsi <= RSI_RETEST_BULL_MAX) || (dir === "BEAR" && rsi >= RSI_RETEST_BEAR_MIN)) factors.push("RSI Favors");
    }
  }

  /* Factor 7: Volume spike */
  {
    const vIdx = hasBoCtx ? breakout.candleIdx : (overrideCandleIdx !== undefined ? overrideCandleIdx : candles.length - 1);
    if (vIdx >= 0 && vIdx < candles.length && hasVolumeSpikeOnBreakout(vIdx)) factors.push("Volume Spike");
  }

  /* Factor 8: Within active trading session */
  if (isWithinActiveSession()) factors.push("Active Session");

  /* Factor 9: Fibonacci confluence at key level */
  if (level != null && hasFibConfluence(level)) factors.push("Fib Level");

  /* Factor 10: Market-type-specific signal confluence */
  const mtype = getMarketType();
  const lastIdx = candles.length - 1;
  if (mtype === "boom" || mtype === "crash" || mtype === "dex") {
    const spikeRej = detectSpikeRejection(lastIdx);
    const ibFalse = detectInsideBarFalseBreakout(lastIdx);
    if ((spikeRej && spikeRej.dir === dir) || (ibFalse && ibFalse.dir === dir)) factors.push("Market Signal");
  } else if (mtype === "jump") {
    const sdZone = detectSupplyDemandZone(lastIdx);
    const impulse = detectMomentumImpulse(lastIdx);
    if ((sdZone && ((sdZone.type === "demand" && dir === "BULL") || (sdZone.type === "supply" && dir === "BEAR"))) ||
        (impulse && impulse.dir === dir)) {
      factors.push("Market Signal");
    }
  } else if (mtype === "step") {
    const tlTouch = detectTrendlineTouch(lastIdx);
    const maBounce = detectMABounce(lastIdx);
    if ((tlTouch && tlTouch.dir === dir) || (maBounce && maBounce.dir === dir)) factors.push("Market Signal");
  } else if (mtype === "dailyreset") {
    const drPref = getDailyResetPreferredDir();
    if (drPref && drPref === dir) factors.push("Market Signal");
  } else if (mtype === "driftswitch") {
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime && dsRegime.regime === dir) factors.push("Market Signal");
  }

  /* Factor 11: Preferred direction alignment */
  const tuning = getMarketTuning();
  if (tuning.preferredDir && tuning.preferredDir === dir) factors.push("Preferred Dir");
  if (mtype === "dex") {
    const sym = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
    if ((/UP$/i.test(sym) && dir === "BULL") || (/DN$/i.test(sym) && dir === "BEAR")) factors.push("DEX Direction");
  }
  if (mtype === "driftswitch") {
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime && dsRegime.recentSwitch && dsRegime.regime === dir) factors.push("DS Recent Switch");
  }

  /* Factor 12: Step run momentum or Jump impulse confirmation */
  if (mtype === "step") {
    const run = getStepRunLength();
    if ((dir === "BULL" && run >= STEP_RUN_THRESHOLD) || (dir === "BEAR" && run <= -STEP_RUN_THRESHOLD)) factors.push("Momentum");
  } else if (mtype === "jump") {
    const impulse = detectMomentumImpulse(lastIdx);
    if (impulse && impulse.dir === dir && impulse.strength >= 2) factors.push("Momentum");
  }

  /* Factor 13: MACD histogram alignment */
  {
    const hist = getCurrentMACD();
    if (hist != null) {
      if ((dir === "BULL" && hist > 0) || (dir === "BEAR" && hist < 0)) factors.push("MACD Aligned");
    }
  }

  /* Factor 14: Bollinger Band squeeze */
  if (isBBSqueeze()) factors.push("BB Squeeze");

  /* Factor 15: ADX trending confirmation */
  if (adxValue >= ADX_TRENDING_THRESHOLD) factors.push("ADX Trending");

  /* Factor 16: Stochastic momentum alignment */
  {
    const k = getCurrentStoch();
    if (k != null) {
      if ((dir === "BULL" && k <= 50) || (dir === "BEAR" && k >= 50)) factors.push("Stoch Aligned");
    }
  }

  return factors;
}

/* ================= STRATEGY LOGIC ================= */

function processAllCandles() {
  _historicalProcessing = true;
  openingRange = null;
  breakout = null;
  retestInfo = null;
  indecisionInfo = null;
  confirmInfo = null;
  trade = null;
  trailingSL   = null;
  partialTpHit = false;
  teslaT1Hit = false;
  teslaT2Hit = false;
  teslaT3Hit = false;
  teslaBEHit = false;
  retestCount  = 0;
  setPhase("WAITING");

  /* Reset NY Open Range for full reprocessing */
  resetNyOpenRange();

  /* Reset Session Ranges for full reprocessing */
  resetSessionRanges();

  if (candles.length === 0) {
    _historicalProcessing = false;
    return;
  }
  rangeStartEpoch = candles[0].epoch;
  computeATR();
  computeRSI();
  computeMACD();
  computeBollingerBands();
  computeADX();
  computeStochastic();
  computeEMA200();
  computeVWAP();

  buildOpeningRange();

  if (openingRange) {
    for (let i = openingRange.endIdx + 1; i < candles.length; i++) {
      processCandle(i);
      if (trade) {
        if (autoResetEnabled) {
          /* Simulate the live auto-reset so subsequent setups can be discovered
             in the same historical batch.  Without this, processAllCandles()
             stops at the first historical trade and leaves the panel in TRADE
             phase; the first streaming OHLC then triggers a late auto-reset
             that starts a brand-new range from the very latest candle, causing
             all multi-symbol panels to show "BREAKOUT" even when the single-
             chart has already advanced to RETEST or CONFIRM. */
          openingRange   = null;
          breakout       = null;
          retestInfo     = null;
          indecisionInfo = null;
          confirmInfo    = null;
          trade          = null;
          trailingSL     = null;
          partialTpHit   = false;
          retestCount    = 0;
          monitoringTrade = false;  /* trade cleared — nothing left to monitor */
          rangeStartEpoch = candles[i].epoch;
          buildOpeningRange();
          if (openingRange) {
            i = openingRange.endIdx; /* loop will increment to endIdx + 1 */
          }
          /* Continue loop — process remaining candles against the new setup */
        } else {
          break;
        }
      }
    }
  }

  /* NY Open Range: build range and process all candles through it */
  if (nyOpenRangeEnabled) {
    buildNyOpenRange();
    if (nyOpenRange) {
      for (let i = nyOpenRange.endIdx + 1; i < candles.length; i++) {
        processNyOpenRangeCandle(i);
        if (nyOpenRangeTrade) break;
      }
    }
  }

  /* Session Ranges: build ranges and detect London sweep */
  if (sessionRangesEnabled) {
    buildSessionRanges();
    detectLondonAsianSweep();
  }

  cleanupPendingSignalsForSymbol(getActiveSymbol(), "breakout_retest");
  updateStateUI();
  _historicalProcessing = false;
}

function processLatestCandle() {
  /* When monitoring a resolved trade with auto-reset, skip the short-circuit */
  if (phase === "TRADE" && !monitoringTrade && autoResetEnabled) {
    resetForNextSetup();
    addLog("Auto-reset: scanning for new setup...");
  }

  /* Session Ranges: rebuild ranges and check for London sweep on each candle.
     Always runs before any phase-based early return so sweeps are never missed
     while the main indicator is in TRADE, WAITING, or RANGE phases. */
  if (sessionRangesEnabled) {
    buildSessionRanges();
    detectLondonAsianSweep();
  }

  if (phase === "TRADE") { updateStateUI(); return; }

  if (phase === "WAITING" || phase === "RANGE") {
    buildOpeningRange();
    /* If still in WAITING/RANGE, nothing more to do */
    if (phase === "WAITING" || phase === "RANGE") {
      /* NY Open Range: try to build / advance on each candle */
      if (nyOpenRangeEnabled) {
        buildNyOpenRange();
        if (nyOpenRange && nyOpenRangePhase !== "TRADE") {
          processNyOpenRangeCandle(candles.length - 1);
        }
      }
      updateStateUI();
      return;
    }
    /* Range just completed → process all post-range candles so we catch
       breakouts (and subsequent phases) that formed while we were in RANGE. */
    if (openingRange) {
      for (let i = openingRange.endIdx + 1; i < candles.length; i++) {
        processCandle(i);
        if (trade) break;
      }
    }
    updateStateUI();
    return;
  }

  const idx = candles.length - 1;

  /* Allow multiple phase transitions on the same candle (e.g. retest candle
     that is also indecision).  Cap the loop to avoid infinite spins.
     TRADE is the terminal phase — once a trade is built, stop advancing. */
  let prevPhase = phase;
  const MAX_ADVANCES = 5;
  for (let attempt = 0; attempt < MAX_ADVANCES; attempt++) {
    processCandle(idx);
    if (phase === prevPhase || phase === "TRADE") break;
    prevPhase = phase;
  }

  /* NY Open Range: advance on latest candle (runs alongside main strategy) */
  if (nyOpenRangeEnabled) {
    buildNyOpenRange();
    if (nyOpenRange && nyOpenRangePhase !== "TRADE") {
      processNyOpenRangeCandle(idx);
    }
  }

  updateStateUI();
}

function runIntrabarTimingOptimizations(currentCandle) {
  if (!aggressiveEntryEnabled || !candleCloseOnlyEnabled || _historicalProcessing) return;
  if (!currentCandle || candles.length < 2) return;

  const idx = candles.length - 1;

  /* Detect the breakout itself intrabar instead of waiting for the level-breaking
     candle to close. Waiting for candle close was the single biggest source of
     delayed entries — by the time the candle finished forming, most of the
     initial breakout move (and its best entry price) was already gone. All
     existing breakout filters (EMA/HTF/MTF alignment, HH/HL, session, volume
     spike) and the downstream false-breakout / follow-through invalidation
     checks still apply, so signal quality is preserved while latency drops. */
  if (!monitoringTrade && !trade && !breakout && phase === "BREAKOUT") {
    const prevMode = _entryModeContext;
    _entryModeContext = "aggressive_intrabar";
    try {
      processLatestCandle();
    } finally {
      _entryModeContext = prevMode;
    }
  }

  if (!monitoringTrade && !trade && breakout && retestInfo && indecisionInfo && !confirmInfo && phase === "CONFIRM" && idx > indecisionInfo.candleIdx) {
    const prevMode = _entryModeContext;
    _entryModeContext = "aggressive_intrabar";
    try {
      processLatestCandle();
    } finally {
      _entryModeContext = prevMode;
    }
  }

  if (!mtfTopDownEnabled || mtfTopDownHistory.some(s => s.result === "PENDING")) return;
  const prevMode = _entryModeContext;
  _entryModeContext = "aggressive_intrabar";
  try {
    processMtfTopDown();
  } finally {
    _entryModeContext = prevMode;
  }
}

/**
 * Reset indicator state for next setup while keeping candle data and signal history.
 * Starts a new opening range from the latest candle epoch.
 */
function resetForNextSetup() {
  const resetSymbol = (trade && trade.symbol) || getActiveSymbol();
  openingRange   = null;
  breakout       = null;
  retestInfo     = null;
  indecisionInfo = null;
  confirmInfo    = null;
  trade          = null;
  trailingSL     = null;
  partialTpHit   = false;
  retestCount    = 0;
  /* Reset NY Open Range alongside main strategy */
  resetNyOpenRange();
  /* Reset Session Ranges alongside main strategy */
  resetSessionRanges();
  /* Start new range from the latest candle */
  rangeStartEpoch = candles.length > 0 ? candles[candles.length - 1].epoch : null;
  setPhase("RANGE");
  updateStateUI();
  logSignalLifecycleEvent(resetSymbol, "State Reset Complete");
}

function buildOpeningRange() {
  if (!rangeStartEpoch || candles.length === 0) return;

  /* Scalping mode uses a shorter opening range (from MD: 5min) */
  const effectiveRangeMin = scalpingModeEnabled ? SCALP_RANGE_MINUTES : RANGE_MINUTES;
  const rangeEndEpoch = rangeStartEpoch + effectiveRangeMin * 60;
  let high = -Infinity, low = Infinity;
  let startIdx = 0, endIdx = 0;

  for (let i = 0; i < candles.length; i++) {
    if (candles[i].epoch > rangeEndEpoch) break;
    if (candles[i].high > high) high = candles[i].high;
    if (candles[i].low < low)   low = candles[i].low;
    endIdx = i;
  }

  if (high === -Infinity) return;

  openingRange = { high, low, startIdx, endIdx };

  const lastEpoch = candles[candles.length - 1].epoch;
  if (lastEpoch <= rangeEndEpoch) {
    setPhase("RANGE");
  } else if (!breakout) {
    setPhase("BREAKOUT");
  }
}

/* ================= MARKET-TYPE LOGGING HELPERS ================= */
/**
 * Logs market-type-specific context when a breakout is detected.
 * Provides traders with actionable insights based on the instrument type.
 */
function logMarketTypeContext(idx, dir) {
  const mtype = getMarketType();
  const tuning = getMarketTuning();

  if (mtype === "boom") {
    if (dir === "BULL") {
      addLog(`📈 BOOM INDEX: Breakout aligned with spike direction — high probability`);
    }
    if (isSpikeCandle(candles[idx], dir)) {
      addLog(`⚡ Spike candle detected — characteristic Boom upward spike`);
    }
  } else if (mtype === "crash") {
    if (dir === "BEAR") {
      addLog(`📉 CRASH INDEX: Breakout aligned with spike direction — high probability`);
    }
    if (isSpikeCandle(candles[idx], dir)) {
      addLog(`⚡ Spike candle detected — characteristic Crash downward spike`);
    }
  } else if (mtype === "jump") {
    if (isJumpCandle(idx)) {
      addLog(`🦘 JUMP INDEX: Jump/gap candle detected — watch for momentum continuation`);
    }
    const sdZone = detectSupplyDemandZone(idx);
    if (sdZone) {
      addLog(`📍 ${sdZone.desc}`);
    }
  } else if (mtype === "step") {
    const run = getStepRunLength();
    if (Math.abs(run) >= STEP_RUN_THRESHOLD) {
      addLog(`🪜 STEP INDEX: ${Math.abs(run)}-step momentum run ${run > 0 ? "UP" : "DOWN"}`);
    }
    const tlTouch = detectTrendlineTouch(idx);
    if (tlTouch) {
      addLog(`📐 ${tlTouch.desc}`);
    }
  } else if (mtype === "dex") {
    const sym = _multiPanelProcessing || (UI.symbolSelect ? UI.symbolSelect.value : "");
    const isDexUp = /UP$/i.test(sym);
    const isDexDn = /DN$/i.test(sym);
    if (isDexUp && dir === "BULL") {
      addLog(`📰 DEX UP: Breakout aligned with spike-up direction — high probability`);
    } else if (isDexDn && dir === "BEAR") {
      addLog(`📰 DEX DN: Breakout aligned with spike-down direction — high probability`);
    }
    if (isSpikeCandle(candles[idx], dir)) {
      addLog(`⚡ DEX spike candle detected — news-event-like impulse`);
    }
  } else if (mtype === "driftswitch") {
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime) {
      addLog(`🔄 ${dsRegime.desc}`);
      if (dsRegime.regime === dir) {
        addLog(`✅ DRIFT SWITCH: Breakout ${dir} aligned with ${dsRegime.regime} regime`);
      } else {
        addLog(`⚠ DRIFT SWITCH: Breakout ${dir} against ${dsRegime.regime} regime — caution`);
      }
    } else {
      addLog(`🔄 DRIFT SWITCH: Breakout ${dir} — confirm regime alignment before entry`);
    }
  } else if (mtype === "dailyreset") {
    const drPref = getDailyResetPreferredDir();
    if (drPref) {
      if (drPref === dir) {
        addLog(`📅 DAILY RESET: Breakout ${dir} aligned with natural trend — high probability`);
      } else {
        addLog(`⚠ DAILY RESET: Breakout ${dir} against natural ${drPref} trend — counter-trend, caution`);
      }
    }
  }
}

/**
 * Logs market-type-specific signals at retest for extra context.
 */
function logMarketTypeSignals(idx) {
  const mtype = getMarketType();

  if (mtype === "boom" || mtype === "crash" || mtype === "dex") {
    const spikeRej = detectSpikeRejection(idx);
    if (spikeRej) addLog(`✅ ${spikeRej.desc}`);
    const ibFalse = detectInsideBarFalseBreakout(idx);
    if (ibFalse) addLog(`✅ ${ibFalse.desc}`);
  } else if (mtype === "jump") {
    const sdZone = detectSupplyDemandZone(idx);
    if (sdZone) addLog(`✅ ${sdZone.desc}`);
    const impulse = detectMomentumImpulse(idx);
    if (impulse) addLog(`✅ ${impulse.desc}`);
  } else if (mtype === "step") {
    const maBounce = detectMABounce(idx);
    if (maBounce) addLog(`✅ ${maBounce.desc}`);
    const tlTouch = detectTrendlineTouch(idx);
    if (tlTouch) addLog(`✅ ${tlTouch.desc}`);
  } else if (mtype === "dailyreset") {
    const drPref = getDailyResetPreferredDir();
    if (drPref) {
      addLog(`📅 Daily Reset natural trend: ${drPref} — ${drPref === (breakout ? breakout.dir : "") ? "aligned ✅" : "counter-trend ⚠"}`);
    }
  } else if (mtype === "driftswitch") {
    const dsRegime = detectDriftSwitchRegime();
    if (dsRegime) {
      addLog(`🔄 ${dsRegime.desc}`);
      if (breakout && dsRegime.regime === breakout.dir) {
        addLog(`✅ Breakout aligned with Drift Switch ${dsRegime.regime} regime`);
      } else if (breakout) {
        addLog(`⚠ Breakout AGAINST Drift Switch ${dsRegime.regime} regime — caution`);
      }
    }
  }
}

function processCandle(idx) {
  if (!openingRange) return;
  const c = candles[idx];
  const tuning = getMarketTuning();

  /* PHASE: looking for breakout */
  if (!breakout) {
    /* Opening range size filter — too narrow = noise, too wide = risky */
    if (!isRangeSizeOK()) {
      return;  /* silently skip — range size is checked once */
    }
    /* ADX Hard Gate — block in ranging or exhausted markets */
    if (!isADXInRange()) {
      return;  /* silently skip — ADX checked each candle */
    }
    /* Market-type direction filter: Boom prefers BULL, Crash prefers BEAR.
       Counter-trend breakouts on spike markets are much less reliable. */
    if (c.close > openingRange.high) {
      if (tuning.preferredDir === "BEAR") {
        addLog(`Bullish breakout at #${idx} BLOCKED — Crash index prefers BEAR direction`);
        return;
      }
      /* Apply EMA filter */
      if (!isEmaAligned("BULL")) {
        addLog(`Bullish breakout at #${idx} BLOCKED by EMA filter (EMA8 < EMA21)`);
        return;
      }
      /* Apply HTF trend filter */
      if (!isHTFAligned("BULL")) {
        addLog(`Bullish breakout at #${idx} BLOCKED by HTF trend filter`);
        return;
      }
      /* Apply MTF structure (EMA 200) */
      if (!isMTFStructureAligned("BULL")) {
        addLog(`Bullish breakout at #${idx} BLOCKED by MTF structure (price below EMA 200)`);
        return;
      }
      /* Apply HH/HL structure check */
      if (!hasHHHLStructure("BULL")) {
        addLog(`Bullish breakout at #${idx} BLOCKED by HH/HL structure (no higher-highs/higher-lows)`);
        return;
      }
      /* Apply session filter */
      if (!isWithinActiveSession()) {
        addLog(`Bullish breakout at #${idx} BLOCKED by session filter (${getActiveSessionName()})`);
        return;
      }
      /* Log breakout strength (volume proxy) */
      const conviction = hasBreakoutConviction(c);
      /* Apply volume spike filter */
      const volumeSpike = hasVolumeSpikeOnBreakout(idx);
      if (!volumeSpike) {
        addLog(`Bullish breakout at #${idx} BLOCKED by volume spike filter (candle range too small)`);
        return;
      }
      breakout = { dir: "BULL", candleIdx: idx, level: openingRange.high, strong: conviction, volumeSpike, signalId: generateSignalId("breakout"), detectedAtMs: Date.now() };
      retestCount = 0;  /* reset retest counter for double-retest filter */
      setPhase("RETEST");
      addLog(`BULLISH breakout at candle #${idx}, level ${fmt(openingRange.high, 4)}${conviction ? " (STRONG)" : " (WEAK)"}${volumeSpike ? " 📈 Vol Spike" : ""}`);
      /* Log market-type-specific context */
      logMarketTypeContext(idx, "BULL");
      addLog(`Next action: ${getRecommendedOrderType() || "BUY"} — ride the breakout momentum`);
    } else if (c.close < openingRange.low) {
      if (tuning.preferredDir === "BULL") {
        addLog(`Bearish breakout at #${idx} BLOCKED — Boom index prefers BULL direction`);
        return;
      }
      /* Apply EMA filter */
      if (!isEmaAligned("BEAR")) {
        addLog(`Bearish breakout at #${idx} BLOCKED by EMA filter (EMA8 > EMA21)`);
        return;
      }
      /* Apply HTF trend filter */
      if (!isHTFAligned("BEAR")) {
        addLog(`Bearish breakout at #${idx} BLOCKED by HTF trend filter`);
        return;
      }
      /* Apply MTF structure (EMA 200) */
      if (!isMTFStructureAligned("BEAR")) {
        addLog(`Bearish breakout at #${idx} BLOCKED by MTF structure (price above EMA 200)`);
        return;
      }
      /* Apply HH/HL structure check */
      if (!hasHHHLStructure("BEAR")) {
        addLog(`Bearish breakout at #${idx} BLOCKED by HH/HL structure (no lower-highs/lower-lows)`);
        return;
      }
      /* Apply session filter */
      if (!isWithinActiveSession()) {
        addLog(`Bearish breakout at #${idx} BLOCKED by session filter (${getActiveSessionName()})`);
        return;
      }
      const conviction = hasBreakoutConviction(c);
      /* Apply volume spike filter */
      const volumeSpike = hasVolumeSpikeOnBreakout(idx);
      if (!volumeSpike) {
        addLog(`Bearish breakout at #${idx} BLOCKED by volume spike filter (candle range too small)`);
        return;
      }
      breakout = { dir: "BEAR", candleIdx: idx, level: openingRange.low, strong: conviction, volumeSpike, signalId: generateSignalId("breakout"), detectedAtMs: Date.now() };
      retestCount = 0;  /* reset retest counter for double-retest filter */
      setPhase("RETEST");
      addLog(`BEARISH breakout at candle #${idx}, level ${fmt(openingRange.low, 4)}${conviction ? " (STRONG)" : " (WEAK)"}${volumeSpike ? " 📈 Vol Spike" : ""}`);
      logMarketTypeContext(idx, "BEAR");
      addLog(`Next action: ${getRecommendedOrderType() || "SELL"} — ride the breakout momentum`);
    }
    return;
  }

  /* FALSE BREAKOUT DETECTION: invalidate if price returns inside range */
  if (!retestInfo && isFalseBreakout(idx)) {
    addLog(`⚠ FALSE BREAKOUT detected — ${FALSE_BREAKOUT_CANDLES} candles closed back inside range. Resetting.`);
    maybeSendBreakoutCancelled("False breakout invalidated before the retest confirmation completed.");
    breakout = null;
    setPhase("BREAKOUT");
    return;
  }

  /* PHASE: looking for retest */
  if (!retestInfo) {
    if (idx <= breakout.candleIdx) return;
    /* Post-breakout follow-through check */
    if (!hasFollowThrough()) {
      addLog(`Breakout at #${breakout.candleIdx} INVALIDATED — no follow-through (next candle reversed)`);
      maybeSendBreakoutCancelled("Breakout failed the follow-through check.");
      breakout = null;
      setPhase("BREAKOUT");
      return;
    }
    /* Time decay — setup too stale */
    if (!isTimeDecayOK(idx)) {
      addLog(`⏳ Time decay: ${idx - breakout.candleIdx} candles since breakout (max ${timeDecayCandles}) — resetting`);
      maybeSendBreakoutCancelled(`Setup expired after ${idx - breakout.candleIdx} candles without a valid confirmation.`);
      breakout = null;
      setPhase("BREAKOUT");
      return;
    }
    /* Breakout distance check */
    if (!isBreakoutDistanceOK(idx)) {
      addLog(`📏 Breakout distance: price too far from level (>${breakoutDistATR}× ATR) — skipping retest`);
      return;
    }
    const touches = touchesLevel(c, breakout.level);
    if (touches) {
      /* Track retest count for double-retest filter */
      retestCount++;
      if (!isDoubleRetestSatisfied()) {
        addLog(`Retest #${retestCount} at #${idx} — waiting for double retest (need ${2 - retestCount} more)`);
        return;  /* don't set retestInfo yet; wait for 2nd touch */
      }
      /* Apply RSI filter at retest */
      if (!isRSIFavorable(breakout.dir)) {
        const rsi = getCurrentRSI();
        addLog(`Retest at #${idx} — RSI ${fmt(rsi, 1)} not favorable for ${breakout.dir} (skipping)`);
        return;
      }
      /* Apply momentum divergence filter */
      if (!hasMomentumDivergence(breakout.dir)) {
        addLog(`Retest at #${idx} BLOCKED by divergence filter — no favorable RSI divergence`);
        return;
      }
      retestInfo = { candleIdx: idx };
      setPhase("INDECISION");
      /* Feature 7: build divergence visual markers on retest */
      if (divergenceVisualEnabled) buildDivergenceMarkers();
      addLog(`Retest detected at candle #${idx}${retestCount > 1 ? ` (retest #${retestCount})` : ""}`);
      /* Log RSI at retest */
      const rsi = getCurrentRSI();
      if (rsi != null) {
        addLog(`RSI at retest: ${fmt(rsi, 1)}${rsi <= 30 ? " (oversold)" : rsi >= 70 ? " (overbought)" : ""}`);
      }
      /* Log S/R confluence if present */
      if (hasSRConfluence(breakout.level)) {
        addLog("✅ S/R confluence: breakout level aligns with recent swing point");
      }
      /* Log Fibonacci confluence if present */
      const fibResult = getFibRetestLevel(breakout.level);
      if (fibResult) {
        addLog(`✅ Fibonacci confluence: retest near ${(fibResult.ratio * 100).toFixed(1)}% level`);
      }
      /* Log market-type-specific signals at retest */
      logMarketTypeSignals(idx);
      addLog(`Pullback trade: ${getRecommendedOrderType() || (breakout.dir === "BULL" ? "BUY LIMIT" : "SELL LIMIT")} at retest level`);
    }
    return;
  }

  /* PHASE: looking for indecision */
  if (!indecisionInfo) {
    /* Allow the retest candle itself to also be indecision */
    if (idx < retestInfo.candleIdx) return;

    /* Lower-TF fast-track: on 1M/5M (gran ≤ LOWER_TF_5M_SEC) a strong engulfing candle at the
     * retest zone acts as a combined indecision+confirmation, cutting the pipeline by
     * one candle and preventing stale entries on fast-moving lower time frames. */
    if (getCurrentGranularitySec() <= LOWER_TF_5M_SEC && idx > 0) {
      const prev = candles[idx - 1];
      let fastPattern = "";
      if (breakout.dir === "BULL" && isBullishEngulfing(prev, c)) {
        fastPattern = "fast-track bullish engulfing";
      } else if (breakout.dir === "BEAR" && isBearishEngulfing(prev, c)) {
        fastPattern = "fast-track bearish engulfing";
      }
      if (fastPattern) {
        indecisionInfo = { candleIdx: idx };
        let confirmed = true;
        if (!hasConsecutiveDirection(idx, breakout.dir)) {
          addLog(`${fastPattern} at #${idx} BLOCKED — consecutive direction filter`);
          confirmed = false;
        }
        if (confirmed && !isVWAPAligned(breakout.dir)) {
          addLog(`${fastPattern} at #${idx} BLOCKED — VWAP filter`);
          confirmed = false;
        }
        if (confirmed && !hasStochCrossover(breakout.dir)) {
          addLog(`${fastPattern} at #${idx} BLOCKED — stochastic crossover filter`);
          confirmed = false;
        }
        if (confirmed && !isConfirmBarValid(idx)) {
          addLog(`${fastPattern} at #${idx} BLOCKED — confirm bar filter`);
          confirmed = false;
        }
        if (confirmed) {
          confirmInfo = { candleIdx: idx, pattern: fastPattern };
          recordConfirmedSignal(fastPattern);
          addLog(`${fastPattern} at #${idx} (lower-TF fast-track)`);
          buildTrade(c, idx);
          if (trade) {
            confluenceScore = computeConfluenceScore();
            if (!isConfluenceSufficient()) {
              addLog(`⚠ Trade REJECTED — confluence ${confluenceScore}/${minConfluenceValue} below minimum`);
              maybeSendBreakoutCancelled(`Trade rejected because confluence ${confluenceScore}/${minConfluenceValue} was below the minimum threshold.`);
              trade = null;
              confirmInfo = null;
              indecisionInfo = null;
              return;
            }
            setPhase("TRADE");
            multiRHitLevels = [];
            addLog(`${fastPattern} at #${idx} — TRADE ENTRY (lower-TF)`);
            addLog(`Confluence score: ${confluenceScore}`);
            recordSignal(fastPattern);
          } else {
            /* buildTrade() rejected the setup (news pause, timing-quality/ATR-drift,
               min R:R, recent-loss pause, strength requirement, etc.) — clear both
               confirmInfo and indecisionInfo so the pipeline keeps hunting for a
               fresh setup instead of permanently freezing in the CONFIRM phase. */
            confirmInfo = null;
            indecisionInfo = null;
          }
        } else {
          /* Fast-track blocked by a filter — clear indecision so normal path resumes */
          indecisionInfo = null;
        }
        return;
      }
    }

    if (isIndecision(c, idx)) {
      indecisionInfo = { candleIdx: idx };
      setPhase("CONFIRM");
      /* Describe what type of indecision was detected */
      let indecisionType = "doji/spinning-top";
      if (breakout && isPinBar(c, breakout.dir)) indecisionType = "pin bar";
      else if (idx > 0 && isInsideBar(candles[idx - 1], c)) indecisionType = "inside bar";
      if (idx === retestInfo.candleIdx) {
        addLog(`Retest candle #${idx} is also indecision (${indecisionType})`);
      } else {
        addLog(`Indecision candle at #${idx} (${indecisionType})`);
      }
    }
    return;
  }

  /* PHASE: looking for confirmation (engulfing / morning-evening star / inside bar breakout / market-type patterns) */
  if (!confirmInfo) {
    if (idx <= indecisionInfo.candleIdx) return;
    const prev = candles[idx - 1];
    let confirmed = false;
    let confirmPattern = "";

    /* Classic engulfing pattern */
    if (breakout.dir === "BULL" && isBullishEngulfing(prev, c)) {
      confirmed = true;
      confirmPattern = "bullish engulfing";
    } else if (breakout.dir === "BEAR" && isBearishEngulfing(prev, c)) {
      confirmed = true;
      confirmPattern = "bearish engulfing";
    }

    /* Morning Star / Evening Star (3-candle pattern) */
    if (!confirmed && idx >= 2) {
      const c1 = candles[idx - 2];
      const c2 = candles[idx - 1];
      if (breakout.dir === "BULL" && isMorningStar(c1, c2, c)) {
        confirmed = true;
        confirmPattern = "morning star";
      } else if (breakout.dir === "BEAR" && isEveningStar(c1, c2, c)) {
        confirmed = true;
        confirmPattern = "evening star";
      }
    }

    /* Inside bar breakout: if indecision was an inside bar, breakout of mother confirms */
    if (!confirmed && indecisionInfo.candleIdx > 0) {
      const mother = candles[indecisionInfo.candleIdx - 1];
      const indecisionCandle = candles[indecisionInfo.candleIdx];
      if (isInsideBar(mother, indecisionCandle) && isInsideBarBreakout(mother, c, breakout.dir)) {
        confirmed = true;
        confirmPattern = "inside bar breakout";
      }
    }

    /* Piercing Line / Dark Cloud Cover (2-candle reversal from MD files) */
    if (!confirmed) {
      if (breakout.dir === "BULL" && isPiercingLine(prev, c)) {
        confirmed = true;
        confirmPattern = "piercing line";
      } else if (breakout.dir === "BEAR" && isDarkCloudCover(prev, c)) {
        confirmed = true;
        confirmPattern = "dark cloud cover";
      }
    }

    /* Dragonfly / Gravestone Doji confirmation (directional doji from MD files) */
    if (!confirmed) {
      if (breakout.dir === "BULL" && isDragonflyDoji(c)) {
        confirmed = true;
        confirmPattern = "dragonfly doji";
      } else if (breakout.dir === "BEAR" && isGravestoneDoji(c)) {
        confirmed = true;
        confirmPattern = "gravestone doji";
      }
    }

    /* Tweezers Tops & Bottoms (double-test rejection from MD files) */
    if (!confirmed) {
      const tweezersType = isTweezers(prev, c);
      if (tweezersType === "bottom" && breakout.dir === "BULL") {
        confirmed = true;
        confirmPattern = "tweezers bottom";
      } else if (tweezersType === "top" && breakout.dir === "BEAR") {
        confirmed = true;
        confirmPattern = "tweezers top";
      }
    }

    /* Railway Track (sharp 2-candle reversal from TRENDLINE_TRADING_STRATEGY.md) */
    if (!confirmed) {
      const rtType = isRailwayTrack(prev, c);
      if (rtType === "bull" && breakout.dir === "BULL") {
        confirmed = true;
        confirmPattern = "railway track (bullish)";
      } else if (rtType === "bear" && breakout.dir === "BEAR") {
        confirmed = true;
        confirmPattern = "railway track (bearish)";
      }
    }

    /* ---- Market-type-specific confirmation patterns (from MD files) ---- */
    const mtype = getMarketType();

    /* Boom/Crash/DEX: Spike rejection (pin bar or engulfing after spike) confirms reversal.
       From FOREX_MILLIONAIRE_365_DAYS: Pin bar + key level = high probability. */
    if (!confirmed && (mtype === "boom" || mtype === "crash" || mtype === "dex")) {
      const spikeRej = detectSpikeRejection(idx);
      if (spikeRej && spikeRej.dir === breakout.dir) {
        confirmed = true;
        confirmPattern = spikeRej.type === "spike_rejection_pinbar"
          ? "spike rejection pin bar" : "spike rejection engulfing";
      }
      /* Inside bar false breakout (stop-hunt trap) as confirmation */
      if (!confirmed) {
        const ibFalse = detectInsideBarFalseBreakout(idx);
        if (ibFalse && ibFalse.dir === breakout.dir) {
          confirmed = true;
          confirmPattern = "inside bar false breakout (trap)";
        }
      }
    }

    /* Jump: Momentum impulse or S&D zone return as confirmation.
       From FOREX_MILLIONAIRE_365_DAYS: "Best place to buy is at beginning of impulsive move." */
    if (!confirmed && mtype === "jump") {
      const impulse = detectMomentumImpulse(idx);
      if (impulse && impulse.dir === breakout.dir) {
        confirmed = true;
        confirmPattern = "momentum impulse";
      }
      if (!confirmed) {
        const sdZone = detectSupplyDemandZone(idx);
        if (sdZone) {
          if ((sdZone.type === "demand" && breakout.dir === "BULL") ||
              (sdZone.type === "supply" && breakout.dir === "BEAR")) {
            confirmed = true;
            confirmPattern = sdZone.type + " zone return";
          }
        }
      }
    }

    /* Step: Trendline touch or MA bounce as confirmation.
       From TRENDLINE_TRADING_STRATEGY: "Enter on point 3, 4, 5 after pullback." */
    if (!confirmed && mtype === "step") {
      const tlTouch = detectTrendlineTouch(idx);
      if (tlTouch && tlTouch.dir === breakout.dir) {
        confirmed = true;
        confirmPattern = `trendline touch #${tlTouch.touches}`;
      }
      if (!confirmed) {
        const maBounce = detectMABounce(idx);
        if (maBounce && maBounce.dir === breakout.dir) {
          confirmed = true;
          confirmPattern = `${maBounce.ema} bounce`;
        }
      }
      /* Step run momentum confirmation */
      if (!confirmed) {
        const run = getStepRunLength();
        if ((breakout.dir === "BULL" && run >= STEP_RUN_THRESHOLD) ||
            (breakout.dir === "BEAR" && run <= -STEP_RUN_THRESHOLD)) {
          confirmed = true;
          confirmPattern = `step momentum run (${Math.abs(run)} steps)`;
        }
      }
    }

    /* Drift Switch: EMA crossover regime alignment as confirmation */
    if (!confirmed && mtype === "driftswitch") {
      const dsRegime = detectDriftSwitchRegime();
      if (dsRegime && dsRegime.regime === breakout.dir) {
        confirmed = true;
        confirmPattern = dsRegime.recentSwitch
          ? `drift switch regime switch (${dsRegime.regime})`
          : `drift switch regime aligned (${dsRegime.regime})`;
      }
    }

    /* Daily Reset: natural trend alignment as confirmation */
    if (!confirmed && mtype === "dailyreset") {
      const drPref = getDailyResetPreferredDir();
      if (drPref && drPref === breakout.dir) {
        confirmed = true;
        confirmPattern = `daily reset trend aligned (${drPref})`;
      }
    }

    if (confirmed) {
      /* Apply consecutive direction filter */
      if (!hasConsecutiveDirection(idx, breakout.dir)) {
        addLog(`${confirmPattern} at #${idx} BLOCKED — consecutive direction filter (momentum not aligned)`);
        confirmed = false;
      }
      /* Apply VWAP alignment filter */
      if (confirmed && !isVWAPAligned(breakout.dir)) {
        addLog(`${confirmPattern} at #${idx} BLOCKED — VWAP filter (price wrong side of VWAP)`);
        confirmed = false;
      }
      /* Apply stochastic crossover filter */
      if (confirmed && !hasStochCrossover(breakout.dir)) {
        addLog(`${confirmPattern} at #${idx} BLOCKED — stochastic crossover filter (no K/D cross)`);
        confirmed = false;
      }
      /* Apply confirmation bar filter (next candle must close in direction) */
      if (confirmed && !isConfirmBarValid(idx)) {
        addLog(`${confirmPattern} at #${idx} BLOCKED — confirm bar filter (candle didn't close in ${breakout.dir} direction)`);
        confirmed = false;
      }
    }

    if (confirmed) {
      confirmInfo = { candleIdx: idx, pattern: confirmPattern };
      /* Record a CONFIRMED signal immediately so it appears in the Live Signals banner */
      recordConfirmedSignal(confirmPattern);
      addLog(`${confirmPattern} confirmed at #${idx}`);
      buildTrade(c, idx);
      if (trade) {
        /* Apply min confluence gate — check after trade is built so score is accurate */
        confluenceScore = computeConfluenceScore();
        if (!isConfluenceSufficient()) {
          addLog(`⚠ Trade REJECTED — confluence ${confluenceScore}/${minConfluenceValue} below minimum`);
          maybeSendBreakoutCancelled(`Trade rejected because confluence ${confluenceScore}/${minConfluenceValue} was below the minimum threshold.`);
          trade = null;
          confirmInfo = null;
          return;
        }
        setPhase("TRADE");
        /* Feature 15: reset multi-R hit levels for new trade */
        multiRHitLevels = [];
        addLog(`${confirmPattern} at #${idx} — TRADE ENTRY`);
        /* Confluence score was already computed for the min gate check above */
        addLog(`Confluence score: ${confluenceScore}`);
        recordSignal(confirmPattern);
      } else {
        /* buildTrade() rejected the setup (news pause, timing-quality/ATR-drift,
           min R:R, recent-loss pause, strength requirement, symbol eligibility, etc.)
           — clear confirmInfo so the pipeline keeps watching subsequent candles for
           a fresh valid confirmation instead of permanently freezing in CONFIRM. */
        confirmInfo = null;
      }
    }
    return;
  }
}

/* ---- Level touch detection (with optional ATR-based tolerance) ---- */
function touchesLevel(candle, level) {
  const tuning = getMarketTuning();
  let tolerance;
  if (atrToleranceEnabled && atrValue > 0) {
    /* retestToleranceMult replaces the default 0.5 factor, not multiplied on top */
    tolerance = atrValue * 0.5 * tuning.retestToleranceMult;
  } else {
    tolerance = (candle.high - candle.low) * LEVEL_TOUCH_TOLERANCE * tuning.retestToleranceMult;
  }
  return candle.low - tolerance <= level && candle.high + tolerance >= level;
}

/* ---- Indecision candle detection ---- */
function isIndecision(c, idx) {
  const body = Math.abs(c.close - c.open);
  const range = c.high - c.low;
  if (range === 0) return true;
  const bodyRatio = body / range;

  /* Classic doji */
  if (bodyRatio < DOJI_BODY_RATIO) return true;

  /* Spinning top */
  if (bodyRatio < SPINNING_TOP_BODY_RATIO) {
    const upperWick = c.high - Math.max(c.open, c.close);
    const lowerWick = Math.min(c.open, c.close) - c.low;
    if (upperWick > 0 && lowerWick > 0) return true;
  }

  /* Pin bar / hammer / shooting star at retest zone */
  if (breakout && isPinBar(c, breakout.dir)) return true;

  /* Dragonfly / Gravestone doji (directional indecision from MD files) */
  if (isDragonflyDoji(c) || isGravestoneDoji(c)) return true;

  /* Inside bar: current candle contained within previous candle */
  if (idx != null && idx > 0 && idx < candles.length) {
    const prev = candles[idx - 1];
    if (isInsideBar(prev, c)) return true;
  }

  return false;
}

/* ---- Engulfing pattern detection ---- */
function isBullishEngulfing(prev, curr) {
  if (!prev || !curr) return false;
  const currBody = curr.close - curr.open;
  return currBody > 0 &&
    curr.close > Math.max(prev.open, prev.close) &&
    curr.open <= Math.min(prev.open, prev.close);
}

function isBearishEngulfing(prev, curr) {
  if (!prev || !curr) return false;
  const currBody = curr.close - curr.open;
  return currBody < 0 &&
    curr.close < Math.min(prev.open, prev.close) &&
    curr.open >= Math.max(prev.open, prev.close);
}

/* ---- Trade setup builder ---- */
function buildTrade(confirmCandle, confirmIdx) {
  /* Feature 11: News pause gate — block new trades during high-impact events */
  const pauseEvent = getNewsPauseEvent();
  if (pauseEvent) {
    addLog(`⛔ Trade BLOCKED by News Pause: ${pauseEvent.currency} ${pauseEvent.title} within ±${newsPauseMinutes}min window`);
    showToast("News Pause Active", `Trading paused for: ${pauseEvent.currency} ${pauseEvent.title}`, "warning", 8000);
    return;
  }

  const regime = getCurrentRegimeTag();
  const symbol = getActiveSymbol();
  if (!isSymbolEligibleForNewSignal(symbol, "breakout_retest")) {
    addLog("⚠ Trade REJECTED — symbol still has an active pending trade");
    return;
  }
  const granSec = getCurrentGranularitySec();
  const dynamicConfluenceMin = getDynamicMinConfluence(symbol, granSec, regime);
  if (minConfluenceEnabled) {
    if (requiredConfluences.length > 0) {
      const confGate = checkConfluenceGate();
      if (!confGate.pass) {
        addLog(`⚠ Trade REJECTED — ${confGate.reason}`);
        return;
      }
    } else {
      const confScore = computeConfluenceScore();
      if (confScore < dynamicConfluenceMin) {
        addLog(`⚠ Trade REJECTED — dynamic confluence ${confScore}/${dynamicConfluenceMin} (${regime})`);
        return;
      }
    }
  }
  if (requiresStrongBreakoutNow(symbol, granSec, regime) && !(breakout && breakout.strong)) {
    addLog(`⚠ Trade REJECTED — breakout strength too weak for ${regime} regime`);
    return;
  }

  const riskVal   = parseFloat(UI.riskInput.value);
  const rewardVal = parseFloat(UI.rewardInput.value);
  const riskUnits  = (!isNaN(riskVal) && riskVal > 0) ? riskVal : 1;
  const rewardUnits = (!isNaN(rewardVal) && rewardVal > 0) ? rewardVal : 1;
  /* Scalping mode: cap R:R at SCALP_RR_TARGET for quick profits (from MD: 5-10 pip profits) */
  const profile = getOptimizationProfile(symbol, granSec, regime);
  const tunedRRFloor = profile && Number.isFinite(profile.minRR) ? profile.minRR : minRRValue;
  const rrRaw = scalpingModeEnabled ? Math.min(rewardUnits / riskUnits, SCALP_RR_TARGET) : rewardUnits / riskUnits;
  const rr = (!minRREnabled || scalpingModeEnabled) ? rrRaw : Math.max(rrRaw, tunedRRFloor);
  const effectiveMinRR = minRREnabled ? tunedRRFloor : 0;

  /* ---- SL ATR buffer scaled by granularity ----
   * Lower time-frames have smaller ATR values but higher relative noise, so SL gets
   * more room (wider buffer) to avoid being hit by random wicks before the trade
   * has a chance to develop.  Constants defined near the top of the file. */
  const _gran = getCurrentGranularitySec();
  const slAtrBuf = _gran <= LOWER_TF_1M_SEC ? SL_ATR_BUF_1M
                 : _gran <= LOWER_TF_5M_SEC  ? SL_ATR_BUF_5M
                 : SL_ATR_BUF_DEFAULT;
  const atrRef = getAtrReference();
  const extraStopAtr = getVolatilityAdjustedStopBufferAtr(symbol, _gran, breakout);
  const maxEntryDriftAtr = getMaxEntryDriftAtr(symbol, _gran, false);
  const entryMode = getCurrentEntryMode();
  const timingQuality = evaluateEntryTimingQuality(breakout.dir, confirmCandle, breakout.level, atrRef, {
    symbol,
    granSec: _gran,
    entryMode
  });
  if (!timingQuality.pass) {
    const rejectKey = `timing|${confirmIdx}|${timingQuality.reason}`;
    if (!(entryMode === "aggressive_intrabar" && breakout && breakout._lastEntryRejectKey === rejectKey)) {
      addLog(`⚠ Trade REJECTED — ${timingQuality.reason}`);
    }
    if (entryMode === "aggressive_intrabar" && breakout) breakout._lastEntryRejectKey = rejectKey;
    return;
  }
  const recentLossPause = shouldPauseAfterRecentLosses(signalHistory, {
    symbol,
    dir: breakout.dir,
    strategyType: "breakout_retest",
    timeframeSec: _gran
  });
  if (recentLossPause.block) {
    const rejectKey = `loss-pause|${confirmIdx}|${recentLossPause.reason}`;
    if (!(entryMode === "aggressive_intrabar" && breakout && breakout._lastEntryRejectKey === rejectKey)) {
      addLog(`⚠ Trade REJECTED — ${recentLossPause.reason}`);
    }
    if (entryMode === "aggressive_intrabar" && breakout) breakout._lastEntryRejectKey = rejectKey;
    return;
  }
  if (breakout) breakout._lastEntryRejectKey = "";

  /* ---- Resolve the retest/indecision zone candles for precise SL placement ----
   * Using the lowest point of the retest + indecision zone (BULL) or the highest
   * point (BEAR) with a small ATR buffer gives a structurally meaningful stop that
   * invalidates the setup exactly when price breaks through the zone.  This is
   * significantly tighter than a 35-candle swing look-back and reduces initial
   * risk without sacrificing structural validity.  Fall back to the swing-based SL
   * when retestInfo / indecisionInfo is unavailable (e.g. historical re-processing
   * edge cases). */
  const rtCandle = retestInfo    && retestInfo.candleIdx    < candles.length ? candles[retestInfo.candleIdx]    : null;
  const inCandle = indecisionInfo && indecisionInfo.candleIdx < candles.length ? candles[indecisionInfo.candleIdx] : null;

  if (breakout.dir === "BULL") {
    const entry = confirmCandle.close;
    const entryDriftAtr = atrRef > 0 ? Math.abs(entry - breakout.level) / atrRef : 0;
    if (atrRef > 0 && entryDriftAtr > maxEntryDriftAtr) {
      addLog(`⚠ Trade REJECTED — entry closed ${fmt(entryDriftAtr, 2)} ATR above the retest level (max ${fmt(maxEntryDriftAtr, 2)} ATR)`);
      return;
    }

    /* SL anchor: lowest low of the retest/indecision zone; fall back to swing */
    const zoneLows = [rtCandle, inCandle].filter(Boolean).map(c => c.low);
    const swingAnchor = findSwingLow(confirmIdx);
    let slAnchor = zoneLows.length > 0 ? Math.min(...zoneLows) : swingAnchor;
    if (zoneLows.length > 0) {
      const zoneRisk = entry - (slAnchor - atrRef * (slAtrBuf + extraStopAtr));
      if (zoneRisk > 0 && zoneRisk < atrRef * STRUCTURAL_SL_MIN_RISK_ATR) {
        slAnchor = swingAnchor;
        addLog(`ℹ️ SL fallback: zone risk ${fmt(zoneRisk, 4)} too tight (< ${fmt(STRUCTURAL_SL_MIN_RISK_ATR, 1)} ATR), using swing low.`);
      }
    }
    const sl = slAnchor - atrRef * (slAtrBuf + extraStopAtr);

    const risk = entry - sl;
    if (risk <= 0) return;
    const tp = pureTrailingEnabled ? null : entry + risk * rr;
    const actualRR = pureTrailingEnabled ? rr : (tp - entry) / risk;

    /* Min R:R gate: reject trade if R:R is below minimum */
    if (minRREnabled && actualRR < effectiveMinRR) {
      addLog(`⚠ Trade REJECTED — R:R ${fmt(actualRR, 1)} below minimum ${fmt(effectiveMinRR, 1)}`);
      return;
    }
    trade = {
      entry, sl, tp, dir: "BULL", rr: actualRR, scalpingMode: scalpingModeEnabled,
      entryIdx: confirmIdx, outcomeStartIdx: confirmIdx + 1, symbol: getActiveSymbol(),
      atrAtEntry: atrRef, stopBufferAtr: slAtrBuf + extraStopAtr, entryDriftAtr,
      validUntilMs: Date.now() + getSignalValidityMs(), maxEntryDistanceAtr: getSignalDistanceLimitAtr(),
      entryMode, entryProgressAtr: timingQuality.progressAtr, entryBodyAtr: timingQuality.bodyAtr,
      entryCloseLocation: timingQuality.closeLocation
    };
    /* #17: Apply backtest slippage — entry worsens by 0.5 ATR in backtest mode.
     * Recalculate TP from the slipped entry so R:R is preserved correctly. */
    if (backtestMode && atrValue > 0) {
      const slip = atrValue * (BACKTEST_SLIPPAGE_ATR + BACKTEST_SPREAD_ATR);
      trade.entry += slip;  /* fill is worse for BULL */
      const slippedRisk = trade.entry - sl;
      trade.tp = pureTrailingEnabled ? null : trade.entry + slippedRisk * rr;
      trade.backtestSlippage = slip;
      trade.outcomeStartIdx += BACKTEST_LATENCY_CANDLES;
    }
  } else {
    const entry = confirmCandle.close;
    const entryDriftAtr = atrRef > 0 ? Math.abs(entry - breakout.level) / atrRef : 0;
    if (atrRef > 0 && entryDriftAtr > maxEntryDriftAtr) {
      addLog(`⚠ Trade REJECTED — entry closed ${fmt(entryDriftAtr, 2)} ATR below the retest level (max ${fmt(maxEntryDriftAtr, 2)} ATR)`);
      return;
    }

    /* SL anchor: highest high of the retest/indecision zone; fall back to swing */
    const zoneHighs = [rtCandle, inCandle].filter(Boolean).map(c => c.high);
    const swingAnchor = findSwingHigh(confirmIdx);
    let slAnchor = zoneHighs.length > 0 ? Math.max(...zoneHighs) : swingAnchor;
    if (zoneHighs.length > 0) {
      const zoneRisk = (slAnchor + atrRef * (slAtrBuf + extraStopAtr)) - entry;
      if (zoneRisk > 0 && zoneRisk < atrRef * STRUCTURAL_SL_MIN_RISK_ATR) {
        slAnchor = swingAnchor;
        addLog(`ℹ️ SL fallback: zone risk ${fmt(zoneRisk, 4)} too tight (< ${fmt(STRUCTURAL_SL_MIN_RISK_ATR, 1)} ATR), using swing high.`);
      }
    }
    const sl = slAnchor + atrRef * (slAtrBuf + extraStopAtr);

    const risk = sl - entry;
    if (risk <= 0) return;
    const tp = pureTrailingEnabled ? null : entry - risk * rr;
    const actualRR = pureTrailingEnabled ? rr : (entry - tp) / risk;

    /* Min R:R gate: reject trade if R:R is below minimum */
    if (minRREnabled && actualRR < effectiveMinRR) {
      addLog(`⚠ Trade REJECTED — R:R ${fmt(actualRR, 1)} below minimum ${fmt(effectiveMinRR, 1)}`);
      return;
    }
    trade = {
      entry, sl, tp, dir: "BEAR", rr: actualRR, scalpingMode: scalpingModeEnabled,
      entryIdx: confirmIdx, outcomeStartIdx: confirmIdx + 1, symbol: getActiveSymbol(),
      atrAtEntry: atrRef, stopBufferAtr: slAtrBuf + extraStopAtr, entryDriftAtr,
      validUntilMs: Date.now() + getSignalValidityMs(), maxEntryDistanceAtr: getSignalDistanceLimitAtr(),
      entryMode, entryProgressAtr: timingQuality.progressAtr, entryBodyAtr: timingQuality.bodyAtr,
      entryCloseLocation: timingQuality.closeLocation
    };
    /* #17: Apply backtest slippage — entry worsens by 0.5 ATR in backtest mode.
     * Recalculate TP from the slipped entry so R:R is preserved correctly. */
    if (backtestMode && atrValue > 0) {
      const slip = atrValue * (BACKTEST_SLIPPAGE_ATR + BACKTEST_SPREAD_ATR);
      trade.entry -= slip;  /* fill is worse for BEAR */
      const slippedRisk = sl - trade.entry;
      trade.tp = pureTrailingEnabled ? null : trade.entry - slippedRisk * rr;
      trade.backtestSlippage = slip;
      trade.outcomeStartIdx += BACKTEST_LATENCY_CANDLES;
    }
  }

  if (scalpingModeEnabled) {
    addLog(`⚡ SCALPING MODE — quick TP at R:R ${fmt(rr, 1)}, max ${SCALP_MAX_CANDLES} candles`);
  }

  if (trade) {
    trade.strategyType = "breakout_retest";
    stampSignalLifecycle(trade);
    logSignalEngineDebug("TRADE_OPEN", {
      signalId: trade.signalId || null,
      symbol: trade.symbol || getActiveSymbol(),
      dir: trade.dir,
      entry: trade.entry,
      sl: trade.sl,
      tp: trade.tp
    });
  }

  /* Reset trailing/partial state for new trade */
  trailingSL   = null;
  partialTpHit = false;
  teslaT1Hit = false;
  teslaT2Hit = false;
  teslaT3Hit = false;
  teslaBEHit = false;
}

/* ---- True swing point detection ---- */
/**
 * A true swing low is a candle whose low is lower than the lows of
 * SWING_NEIGHBOR_BARS candles on each side.
 */
function isTrueSwingLow(idx) {
  const n = SWING_NEIGHBOR_BARS;
  if (idx - n < 0 || idx + n >= candles.length) return false;
  const low = candles[idx].low;
  for (let i = idx - n; i <= idx + n; i++) {
    if (i === idx) continue;
    if (candles[i].low <= low) return false;
  }
  return true;
}

function isTrueSwingHigh(idx) {
  const n = SWING_NEIGHBOR_BARS;
  if (idx - n < 0 || idx + n >= candles.length) return false;
  const high = candles[idx].high;
  for (let i = idx - n; i <= idx + n; i++) {
    if (i === idx) continue;
    if (candles[i].high >= high) return false;
  }
  return true;
}

function findSwingLow(upToIdx) {
  /* Scalping mode uses tighter lookback for closer SL (from MD: minimize risk) */
  const effectiveLookback = scalpingModeEnabled ? SCALP_LOOKBACK : SWING_LOOKBACK_PERIOD;
  const lookback = Math.max(0, upToIdx - effectiveLookback);

  /* Try true swing point first (scan from most recent backwards) */
  for (let i = upToIdx - SWING_NEIGHBOR_BARS; i >= lookback + SWING_NEIGHBOR_BARS; i--) {
    if (isTrueSwingLow(i)) return candles[i].low;
  }

  /* Fallback to simple min in lookback window */
  let low = Infinity;
  for (let i = lookback; i <= upToIdx; i++) {
    if (candles[i].low < low) low = candles[i].low;
  }
  return low;
}

function findSwingHigh(upToIdx) {
  /* Scalping mode uses tighter lookback for closer SL (from MD: minimize risk) */
  const effectiveLookback = scalpingModeEnabled ? SCALP_LOOKBACK : SWING_LOOKBACK_PERIOD;
  const lookback = Math.max(0, upToIdx - effectiveLookback);

  /* Try true swing point first (scan from most recent backwards) */
  for (let i = upToIdx - SWING_NEIGHBOR_BARS; i >= lookback + SWING_NEIGHBOR_BARS; i--) {
    if (isTrueSwingHigh(i)) return candles[i].high;
  }

  /* Fallback to simple max in lookback window */
  let high = -Infinity;
  for (let i = lookback; i <= upToIdx; i++) {
    if (candles[i].high > high) high = candles[i].high;
  }
  return high;
}

/* ================= WIN/LOSS TRACKING ================= */

/* Record a lightweight "CONFIRMED" signal as soon as the confirmation pattern fires,
   before the trade is built. This makes the signal visible in the Live Signals banner
   at the confirmed stage. If a trade is subsequently built and passes all gates,
   recordSignal() upgrades this entry to "PENDING" with full trade details. */
function recordConfirmedSignal(confirmPattern) {
  const pattern = confirmPattern || "engulfing";
  const sym = _multiPanelProcessing || UI.symbolSelect.value;
  const signal = {
    time: new Date().toISOString(),
    symbol: sym,
    dir: breakout ? breakout.dir : null,
    type: "breakout_retest",
    strategyType: "breakout_retest",
    candleIdx: confirmInfo && Number.isFinite(confirmInfo.candleIdx) ? confirmInfo.candleIdx : (candles.length - 1),
    entry: null,
    sl: null,
    tp: null,
    rr: null,
    result: "CONFIRMED",
    emaAligned: emaFilterEnabled && breakout ? isEmaAligned(breakout.dir) : null,
    htfTrend: getHTFTrend(),
    breakoutStrength: (breakout && breakout.strong) ? "STRONG" : "WEAK",
    partialTpHit: false,
    trailingSL: null,
    confluenceScore: null,
    srConfluence: breakout ? hasSRConfluence(breakout.level) : false,
    confirmPattern: pattern,
    rsiAtRetest: getCurrentRSI(),
    volumeSpike: breakout ? (breakout.volumeSpike != null ? breakout.volumeSpike : hasVolumeSpikeOnBreakout(breakout.candleIdx)) : null,
    session: getActiveSessionName(),
    fibLevel: null,
    macdHist: getCurrentMACD(),
    bbSqueeze: isBBSqueeze(),
    adx: adxValue > 0 ? +fmt(adxValue, 1) : null,
    stochK: getCurrentStoch() != null ? +fmt(getCurrentStoch(), 1) : null,
    volatilityRegime: adxValue > 0 ? getVolatilityRegime() : null,
    timeframeSec: getCurrentGranularitySec(),
    scalpingMode: scalpingModeEnabled,
    entryMode: getCurrentEntryMode(),
    lotSize: null,
    pipsAtRisk: null,
    stake: null,
    breakoutDetectedAtMs: breakout ? breakout.detectedAtMs : null
  };
  stampSignalLifecycle(signal);
  signalHistory.push(signal);
  if (signalHistory.length > SIGNAL_HISTORY_MAX) signalHistory.shift();
  persistSignalHistory();
  updateStatsUI();
  updateSignalBanners();
  /* Pipeline audit: breakout detected → signal created (this CONFIRMED entry) */
  if (breakout && Number.isFinite(breakout.detectedAtMs)) {
    logPipelineDelay("Breakout detected → Signal created", breakout.detectedAtMs, {
      signalId: signal.signalId || null, symbol: sym
    });
  }
}

function recordSignal(confirmPattern) {
  if (!trade) return;
  const pattern = confirmPattern || "engulfing";
  const fibResult = breakout ? getFibRetestLevel(breakout.level) : null;

  /* Try to upgrade the last CONFIRMED signal instead of creating a duplicate.
     Verify symbol matches to avoid upgrading a signal from a different panel. */
  const currentSymbol = _multiPanelProcessing || UI.symbolSelect.value;
  const lastIdx = signalHistory.length - 1;
  const lastConfirmed = lastIdx >= 0
    && signalHistory[lastIdx].result === "CONFIRMED"
    && signalHistory[lastIdx].symbol === currentSymbol
    ? signalHistory[lastIdx] : null;

  const signal = lastConfirmed || {};
  if (!lastConfirmed) signal.time = new Date().toISOString();
  signal.symbol = currentSymbol;
  signal.dir = trade.dir;
  signal.type = "breakout_retest";
  signal.strategyType = "breakout_retest";
  signal.candleIdx = trade.entryIdx;
  signal.entry = trade.entry;
  signal.sl = trade.sl;
  signal.tp = trade.tp;
  signal.rr = trade.rr;
  signal.result = "PENDING";
  signal.emaAligned = emaFilterEnabled ? isEmaAligned(trade.dir) : null;
  signal.htfTrend = getHTFTrend();
  signal.breakoutStrength = (breakout && breakout.strong) ? "STRONG" : "WEAK";
  signal.partialTpHit = false;
  signal.trailingSL = null;
  signal.confluenceScore = computeConfluenceScore();
  signal._confFactors    = getActiveConfluenceFactors();
  signal.srConfluence = breakout ? hasSRConfluence(breakout.level) : false;
  signal.confirmPattern = pattern;
  signal.rsiAtRetest = getCurrentRSI();
  signal.volumeSpike = breakout ? (breakout.volumeSpike != null ? breakout.volumeSpike : hasVolumeSpikeOnBreakout(breakout.candleIdx)) : null;
  signal.session = getActiveSessionName();
  signal.fibLevel = fibResult ? (fibResult.ratio * 100).toFixed(1) + "%" : null;
  signal.macdHist = getCurrentMACD();
  signal.bbSqueeze = isBBSqueeze();
  signal.adx = adxValue > 0 ? +fmt(adxValue, 1) : null;
  signal.stochK = getCurrentStoch() != null ? +fmt(getCurrentStoch(), 1) : null;
  signal.volatilityRegime = adxValue > 0 ? getVolatilityRegime() : null;
  signal.timeframeSec = getCurrentGranularitySec();
  signal.scalpingMode = scalpingModeEnabled;
  signal.entryMode = trade.entryMode || getCurrentEntryMode();
  signal.lotSize = null;
  signal.pipsAtRisk = null;
  signal.stake = null;
  signal.entryDriftAtr = trade.entryDriftAtr;
  signal.stopBufferAtr = trade.stopBufferAtr;
  signal.entryProgressAtr = trade.entryProgressAtr;
  signal.entryBodyAtr = trade.entryBodyAtr;
  signal.entryCloseLocation = trade.entryCloseLocation;
  if (signal.breakoutDetectedAtMs == null && breakout) signal.breakoutDetectedAtMs = breakout.detectedAtMs;
  stampSignalLifecycle(signal, { atrAtSignal: trade.atrAtEntry });
  trade.signalId = signal.signalId;
  trade.breakoutDetectedAtMs = signal.breakoutDetectedAtMs;

  /* Populate lot-size fields from account sizing */
  if (accountSize > 0 && riskPercent > 0) {
    const pm = calcPositionMetrics(trade);
    if (pm) {
      signal.lotSize    = pm.lotSize;
      signal.pipsAtRisk = pm.isSynthetic ? null : pm.pips;
      signal.stake      = null;  /* deprecated — using lot size for MT5 */
    }
  }
  if (!lastConfirmed) {
    signalHistory.push(signal);
    if (signalHistory.length > SIGNAL_HISTORY_MAX) signalHistory.shift();
  }
  /* Pipeline audit: breakout detected → signal stored as PENDING trade */
  if (Number.isFinite(signal.breakoutDetectedAtMs)) {
    logPipelineDelay("Breakout detected → Signal stored", signal.breakoutDetectedAtMs, {
      signalId: signal.signalId || null, symbol: signal.symbol
    });
  }
  /* Capture chart screenshot as data URL for PDF export */
  try {
    if (UI.canvas) signal.chartImage = UI.canvas.toDataURL("image/png");
  } catch (e) { /* canvas tainted or unavailable */ }
  monitoringTrade = true;
  cleanupPendingSignalsForSymbol(signal.symbol, "breakout_retest", { keepSignalId: signal.signalId });
  logSignalLifecycleEvent(signal.symbol, "Signal Generated", {
    signalId: signal.signalId || null,
    strategy: signal.strategyType || signal.type || "breakout_retest"
  });
  logSignalEngineDebug("TRADE_ACTIVATED", {
    signalId: signal.signalId || null,
    symbol: signal.symbol,
    dir: signal.dir,
    entry: signal.entry
  });
  persistSignalHistory();
  updateStatsUI();

  /* ── Send Telegram notification for Breakout trade ── */
  addLog(`[BREAKOUT GENERATED] Signal ID: ${signal.signalId} | ${signal.dir} @ ${fmt(signal.entry, 4)} | SL: ${fmt(signal.sl, 4)} | TP: ${fmt(signal.tp, 4)}`);
  
  if (telegramStrategyAutoSend) {
    addLog(`[BREAKOUT QUEUED] Telegram alert queued for delivery`);
    setTimeout(() => {
      sendTelegramStrategyAlert(signal).then(() => {
        addLog(`[BREAKOUT SENT] Telegram notification delivered successfully`);
        if (Number.isFinite(signal.breakoutDetectedAtMs)) {
          logPipelineDelay("Breakout detected → Telegram sent (auto)", signal.breakoutDetectedAtMs, {
            signalId: signal.signalId || null, symbol: signal.symbol
          });
        }
      }).catch((err) => {
        addLog(`[BREAKOUT FAILED] Telegram notification delivery failed: ${err.message}`);
      });
    }, CHART_RENDER_DELAY_MS);
  }

  if (notificationsEnabled && "Notification" in window && Notification.permission === "granted") {
    addLog(`[BREAKOUT SENT] Desktop notification delivered`);
    const body = `🔲 ${signal.dir} Breakout Retest — ${signal.symbol} @ ${fmt(signal.entry, 4)}\nSL: ${fmt(signal.sl, 4)} | TP: ${fmt(signal.tp, 4)}`;
    throttledNotification("IT Guru: Breakout Retest!", body);
  }

  /* Auto-trade: place a Deriv contract when the toggle is enabled */
  if (autoTradeEnabled && !_historicalProcessing) {
    executeAutoTrade({ dir: trade.dir, entry: trade.entry, sl: trade.sl, tp: trade.tp, symbol: trade.symbol || getActiveSymbol(), source: "breakout" });
  }
}

/* ================= AUTO-TRADE SHARED MESSAGE HANDLER ================= */
/**
 * Handle auto-trade related WS messages (proposal, buy, POC, errors).
 * Called from BOTH the main WS onmessage and each multi-panel WS onmessage.
 *
 * @param {Object}    msg     — parsed WS message
 * @param {WebSocket} msgWs   — the WebSocket this message arrived on
 * @returns {boolean} true if the message was consumed (caller should return)
 */
function handleAutoTradeMessage(msg, msgWs) {

  /* ---- Error handling for auto-trade messages ---- */
  if (msg.error) {
    const pt = msg.passthrough || {};
    const tradeSymbol = pt.tradeSymbol || null;
    const isAutoTradeByPassthrough = pt.auto_trade;
    /* Match POC errors by contract ID */
    const isAutoTradeByContractId = msg.msg_type === "proposal_open_contract" &&
      findSlotByContractId(msg.echo_req && msg.echo_req.contract_id);
    /* Fallback: any proposal/buy error while there's a slot in-flight for the
       symbol embedded in passthrough */
    const slotForSymbol = tradeSymbol ? autoTradeSlots.get(tradeSymbol) : null;
    const isAutoTradeByInProgress = slotForSymbol && slotForSymbol.inProgress &&
      (msg.msg_type === "proposal" || msg.msg_type === "buy");

    if (isAutoTradeByPassthrough || isAutoTradeByContractId || isAutoTradeByInProgress) {
      const sym = tradeSymbol ||
        (isAutoTradeByContractId && isAutoTradeByContractId.symbol) || "?";
      const slot = tradeSymbol ? getAutoTradeSlot(tradeSymbol) :
        (isAutoTradeByContractId ? isAutoTradeByContractId.slot : null);
      const tradeId = msg.passthrough && msg.passthrough.tradeId;
      const errCode = msg.error.code ? ` [${msg.error.code}]` : "";
      addLog(`⚠ [${sym}] Auto-trade error (${msg.msg_type})${errCode}: ${msg.error.message}`);
      if (slot) {
        /* Remove the specific trade from activeTrades if tradeId is available */
        if (tradeId) {
          removeActiveTrade(sym, tradeId);
        } else {
          slot.inProgress = false;
        }
        slot.consecutiveErrors++;
        if (slot.consecutiveErrors >= AUTO_TRADE_MAX_CONSECUTIVE_ERRORS) {
          addLog(`🛑 Auto-trade paused — ${slot.consecutiveErrors} consecutive errors on ${sym}. Disable and re-enable to resume.`);
          autoTradeEnabled = false;
          autoTradeScalpEnabled = false;
          autoTradeStrategyEnabled = false;
          if (UI.autoTradeToggle)         UI.autoTradeToggle.checked = false;
          if (UI.autoTradeScalpToggle)    UI.autoTradeScalpToggle.checked = false;
          if (UI.autoTradeStrategyToggle) UI.autoTradeStrategyToggle.checked = false;
          slot.consecutiveErrors = 0;
        }
        if (!tradeId) {
          slot.contractId = null;
          slot.pendingContractId = null;
          clearAutoTradePendingTimeout(sym);
        }
      }
      resolveAutoTradeHistoryEntry(0, "ERROR", tradeSymbol, tradeId);
      return true;
    }
    return false; /* not an auto-trade error — let caller handle */
  }

  /* ---- Proposal response → buy ---- */
  if (msg.msg_type === "proposal" && msg.passthrough && msg.passthrough.auto_trade) {
    const tradeSymbol = msg.passthrough.tradeSymbol;
    const tradeId = msg.passthrough.tradeId;
    const slot = tradeSymbol ? getAutoTradeSlot(tradeSymbol) : null;
    if (!slot || !slot.inProgress) {
      addLog(`⚠ Auto-trade proposal received but trade was cancelled — ignoring (${tradeSymbol || "?"})`);
      return true;
    }
    const proposal = msg.proposal || {};
    if (!proposal.id) {
      addLog(`⚠ [${tradeSymbol}] Auto-trade proposal missing ID — cannot buy`);
      if (tradeId) {
        removeActiveTrade(tradeSymbol, tradeId);
      } else {
        slot.inProgress = false;
        clearAutoTradePendingTimeout(tradeSymbol);
      }
      resolveAutoTradeHistoryEntry(0, "ERROR", tradeSymbol, tradeId);
      return true;
    }
    const src = msg.passthrough.source || "breakout";
    const label = autoTradeSourceLabel(src, msg.passthrough.strategyName);
    addLog(`🤖 ${label} auto-trade: buying contract — ask $${proposal.ask_price} (${tradeSymbol})`);
    slot.consecutiveErrors = 0;  /* successful proposal — reset error counter */
    msgWs.send(JSON.stringify({
      buy: proposal.id,
      price: proposal.ask_price,
      passthrough: { auto_trade: true, source: src, strategyName: msg.passthrough.strategyName || null, tradeSymbol, tradeId }
    }));
    return true;
  }

  /* ---- Buy response ---- */
  if (msg.msg_type === "buy" && msg.passthrough && msg.passthrough.auto_trade) {
    const b = msg.buy;
    const tradeSymbol = msg.passthrough.tradeSymbol;
    const tradeId = msg.passthrough.tradeId;
    const slot = tradeSymbol ? getAutoTradeSlot(tradeSymbol) : null;
    const src = msg.passthrough.source || "breakout";
    const label = autoTradeSourceLabel(src, msg.passthrough.strategyName);
    const cid = String(b.contract_id);
    if (slot) {
      slot.contractId = cid;
      /* Update the specific trade entry with the contract ID */
      const tradeEntry = tradeId ? findTradeByTradeId(tradeSymbol, tradeId) : null;
      if (tradeEntry) {
        tradeEntry.contractId = cid;
        /* Clear the short proposal timeout and start the longer pending timeout */
        if (tradeEntry.pendingTimer) {
          clearTimeout(tradeEntry.pendingTimer);
          tradeEntry.pendingTimer = null;
        }
      }
    }
    addLog(`✅ ${label} auto-trade: contract purchased — ID ${b.contract_id}, paid $${b.buy_price} (${tradeSymbol})`);
    msgWs.send(JSON.stringify({
      proposal_open_contract: 1,
      contract_id: b.contract_id,
      subscribe: 1,
      passthrough: { auto_trade: true, source: src, strategyName: msg.passthrough.strategyName || null, tradeSymbol, tradeId }
    }));
    /* Start timeout to detect hung contracts (multiplier contracts can stay open for a long time) */
    if (tradeSymbol) startAutoTradePendingTimeout(tradeSymbol, msgWs, tradeId);
    return true;
  }

  /* ---- Proposal Open Contract (POC) updates ---- */
  if (msg.msg_type === "proposal_open_contract") {
    const poc = msg.proposal_open_contract;
    const pt = msg.passthrough || {};
    const tradeSymbol = pt.tradeSymbol || null;
    const tradeId = pt.tradeId || null;

    /* Match by passthrough OR by contract ID lookup */
    const hasPassthrough = pt.auto_trade;
    const byContractId = poc && findSlotByContractId(poc.contract_id);
    if (hasPassthrough || byContractId) {
      const sym = tradeSymbol || (byContractId && byContractId.symbol) || "?";
      const slot = tradeSymbol ? getAutoTradeSlot(tradeSymbol) :
        (byContractId ? byContractId.slot : null);
      if (!slot) return true; /* matched but no slot — nothing to update */

      const isSold = (poc && poc.is_sold) || (poc && poc.status === "sold");
      if (!isSold && poc && poc.contract_id) {
        /* #5: Stats-calibrated time stop — cut trades open longer than the
           median winner resolution time × 2 (stale trades skew to losers). */
        const timeStopMs = getAdaptiveTimeStopMs();
        const openEntry = (tradeId && tradeSymbol) ? findTradeByTradeId(tradeSymbol, tradeId)
          : (byContractId && byContractId.tradeEntry) || null;
        if (timeStopMs != null && openEntry && !openEntry.timeStopSent &&
            Number.isFinite(openEntry.startTime) && (Date.now() - openEntry.startTime) > timeStopMs &&
            poc.is_valid_to_sell && msgWs && msgWs.readyState === WebSocket.OPEN) {
          openEntry.timeStopSent = true;
          addLog(`⏱ [${sym}] Adaptive time stop — trade open ${Math.round((Date.now() - openEntry.startTime) / 60000)} min > calibrated ${Math.round(timeStopMs / 60000)} min limit. Selling at market.`);
          msgWs.send(JSON.stringify({ sell: poc.contract_id, price: 0 }));
        }
      }
      if (isSold && slot) {
        const profit = parseFloat(poc.profit) || 0;
        const won = profit > 0;
        const src = pt.source || "breakout";
        const label = autoTradeSourceLabel(src, pt.strategyName);
        addLog(`🤖 ${label} auto-trade result: ${won ? "WIN ✅" : "LOSS ❌"} — profit $${fmt(profit, 2)} (${sym})`);
        /* Remove the specific trade from activeTrades */
        const resolveTradeId = tradeId || (byContractId && byContractId.tradeEntry && byContractId.tradeEntry.tradeId);
        if (resolveTradeId) {
          removeActiveTrade(sym, resolveTradeId);
        } else {
          /* Fallback: remove by contractId match */
          const cid = poc && String(poc.contract_id);
          const matchEntry = slot.activeTrades.find(t => String(t.contractId) === cid);
          if (matchEntry) {
            removeActiveTrade(sym, matchEntry.tradeId);
          } else {
            slot.inProgress = false;
            slot.contractId = null;
            slot.pendingContractId = null;
          }
        }
        clearAutoTradePendingTimeout(sym, tradeId);
        const effectiveTradeId = resolveTradeId || tradeId;
        resolveAutoTradeHistoryEntry(profit, won ? "WIN" : "LOSS", sym, effectiveTradeId);
        /* Request a fresh balance in case the balance subscription missed
           the update (e.g. brief disconnect during contract settlement). */
        if (msgWs && msgWs.readyState === WebSocket.OPEN) {
          msgWs.send(JSON.stringify({ balance: 1, subscribe: 1 }));
        }
      }
      return true;
    }
  }

  /* ---- Balance stream ---- */
  if (msg.msg_type === "balance") {
    const bal = msg.balance;
    if (bal && bal.balance != null) {
      autoTradeBalance = parseFloat(bal.balance);
      if (sessionStartBalance === null || sessionStartBalance === undefined) sessionStartBalance = autoTradeBalance;
      ensureAutoTradeDailyBaseline();
      updateAutoTradeBalanceUI();
      updateAutoTradePLUI();
    }
    return true;
  }

  return false; /* message not consumed */
}

/* ================= AUTO-TRADE EXECUTION ================= */
/**
 * Place a multiplier trade on Deriv with SL/TP.
 *
 * @param {Object} signal - { dir, entry, sl, tp, symbol, source }
 *   dir    – "BULL" or "BEAR"
 *   entry  – entry price (used for SL/TP distance calc)
 *   sl     – stop-loss price
 *   tp     – take-profit price (may be null for pure trailing)
 *   symbol – Deriv symbol string
 *   source – "breakout" | "scalp" | "strategy" (for logging)
 *
 * Uses MULTUP/MULTDOWN contracts with limit_order.stop_loss and
 * limit_order.take_profit expressed as absolute distance from entry.
 */
function autoTradeSourceLabel(source, strategyName) {
  if (source === "scalp") return "⚡ Scalp";
  if (source === "strategy") {
    const STRAT_LABELS = {
      liquiditySweep: "🌊 Liquidity Sweep",
      stopLossHunt:   "🎯 Stop Loss Hunt",
      failedPinBar:   "📌 Failed Pin Bar",
      fibScalp:       "📐 Fib Golden Zone",
      po3:            "⚡ Power of 3",
      tiktok:         "📈 TikTok Fib",
      nyOpenRange:    "🕤 NY Open Range",
      sessionRange:   "🌍 Session Range",
      gridScalperMA:  "🔲 Grid Scalper MA",
      mtfTopDown:     "⏱ MTF Top-Down"
    };
    return STRAT_LABELS[strategyName] || (strategyName ? `📊 ${resolveStrategyDisplayLabel(strategyName, strategyName)}` : "📊 Strategy");
  }
  return "📈 Breakout";
}

function _pruneTimestamps(arr, now, windowMs) {
  const keepFrom = now - windowMs;
  return arr.filter(ts => ts >= keepFrom);
}

function canPlaceByFrequency(symbol, strategyName) {
  const now = Date.now();
  const symArr = _pruneTimestamps(symbolTradeTimestamps.get(symbol) || [], now, AUTO_TRADE_SYMBOL_FREQ_WINDOW_MS);
  symbolTradeTimestamps.set(symbol, symArr);
  if (symArr.length >= AUTO_TRADE_MAX_TRADES_PER_SYMBOL_WINDOW) {
    return { ok: false, reason: `trade frequency cap reached for ${symbol}` };
  }

  if (strategyName) {
    const stratArr = _pruneTimestamps(strategyTradeTimestamps.get(strategyName) || [], now, AUTO_TRADE_SYMBOL_FREQ_WINDOW_MS);
    strategyTradeTimestamps.set(strategyName, stratArr);
    if (stratArr.length >= AUTO_TRADE_MAX_TRADES_PER_STRATEGY_WINDOW) {
      return { ok: false, reason: `${strategyName} frequency cap reached` };
    }
  }
  return { ok: true };
}

function recordTradeFrequency(symbol, strategyName) {
  const now = Date.now();
  const symArr = _pruneTimestamps(symbolTradeTimestamps.get(symbol) || [], now, AUTO_TRADE_SYMBOL_FREQ_WINDOW_MS);
  symArr.push(now);
  symbolTradeTimestamps.set(symbol, symArr);
  if (strategyName) {
    const stratArr = _pruneTimestamps(strategyTradeTimestamps.get(strategyName) || [], now, AUTO_TRADE_SYMBOL_FREQ_WINDOW_MS);
    stratArr.push(now);
    strategyTradeTimestamps.set(strategyName, stratArr);
  }
}

function getStrategyAllowedRegimes(strategyName) {
  const map = {
    liquiditySweep: ["RANGING", "TRANSITIONING"],
    sessionRange:   ["RANGING", "TRANSITIONING"],
    nyOpenRange:    ["TRANSITIONING", "RANGING"],
    fvgStrat:       ["TRENDING", "TRANSITIONING"],
    mtfTopDown:     ["TRENDING", "TRANSITIONING"],
    orderblock:     ["TRENDING", "TRANSITIONING"],
    po3:            ["TRENDING", "TRANSITIONING"],
    fibScalp:       ["TRANSITIONING", "TRENDING"],
    stopLossHunt:   ["TRANSITIONING", "RANGING"],
    failedPinBar:   ["TRANSITIONING", "RANGING"],
    gridScalperMA:  ["TRENDING", "TRANSITIONING"],
    tiktok:         ["TRENDING", "TRANSITIONING"]
  };
  return map[strategyName] || ["TRENDING", "TRANSITIONING", "RANGING"];
}

function isStrategyTemporarilyPaused(strategyName, regime) {
  const key = `${strategyName}|${regime}`;
  const until = strategyRegimePausedUntil[key] || 0;
  return until > Date.now();
}

function evaluateTradeRealism(signal, multiplier, stake) {
  if (!signal || !signal.entry || signal.entry <= 0) return { passed: true, cost: 0 };
  const entry = signal.entry;
  const slDist = signal.sl != null ? Math.abs(entry - signal.sl) : 0;
  const tpDist = signal.tp != null ? Math.abs(signal.tp - entry) : 0;
  const riskDollar = slDist > 0 ? slDist * multiplier * stake / entry : 0;
  const rewardDollar = tpDist > 0 ? tpDist * multiplier * stake / entry : 0;
  const spreadDollar = atrValue > 0 ? (atrValue * BACKTEST_SPREAD_ATR * multiplier * stake / entry) : 0;
  const slippageDollar = atrValue > 0 ? (atrValue * BACKTEST_SLIPPAGE_ATR * multiplier * stake / entry) : 0;
  const latencyDollar = atrValue > 0 ? (atrValue * 0.25 * BACKTEST_LATENCY_CANDLES * multiplier * stake / entry) : 0;
  const totalCost = spreadDollar + slippageDollar + latencyDollar;

  if (signal.tp == null) return { passed: true, cost: totalCost, rewardDollar, riskDollar };
  const robustReward = rewardDollar - totalCost;
  const minRequired = Math.max(riskDollar * 0.6, totalCost * 1.2);
  return { passed: robustReward > minRequired, cost: totalCost, rewardDollar, riskDollar };
}

function calculateRiskAdjustedStake(signal, multiplier) {
  const baseStake = Math.max(MIN_AUTO_TRADE_STAKE, parseFloat(autoTradeStake) || 1);
  const maxStake = (autoTradeMaxStake > 0 && autoTradeMaxStake >= baseStake) ? autoTradeMaxStake : baseStake * 4;
  let stake = Math.max(MIN_AUTO_TRADE_STAKE, autoTradeCurrentStake || baseStake);

  if (autoTradeBalance != null && autoTradeBalance > 0 && signal && signal.entry > 0 && signal.sl != null) {
    const regime = getCurrentRegimeTag();
    const volMult = regime === "TRENDING" ? 1.15 : (regime === "RANGING" ? 0.7 : 0.9);
    const streakMult = autoTradeLossCount >= 2 ? 0.6 : (autoTradeLossCount === 1 ? 0.8 : 1.0);
    const riskBudget = autoTradeBalance * AUTO_TRADE_RISK_PER_TRADE_PCT * volMult * streakMult;
    const slDist = Math.abs(signal.entry - signal.sl);
    if (slDist > 0 && multiplier > 0) {
      const budgetStake = riskBudget * signal.entry / (slDist * multiplier);
      if (Number.isFinite(budgetStake) && budgetStake > 0) {
        stake = Math.min(stake, budgetStake);
      }
    }
  }

  stake = Math.max(MIN_AUTO_TRADE_STAKE, Math.min(maxStake, stake));
  return +fmt(stake, 2);
}

/* ================= PROFIT-DRIVEN IMPROVEMENTS ================= */

/** Stake multiplier for one stats bucket based on its rolling profit factor.
 *  PF ≥ 1.5 → full risk, PF 1.0–1.5 → reduced risk, PF < 1.0 → poor risk.
 *  Buckets without enough samples stay at full risk (never punish on noise). */
function getExpectancyBucketMultiplier(entries) {
  const stats = getTradeAnalytics(entries);
  if (stats.samples < EXPECTANCY_WEIGHT_MIN_SAMPLES) return 1.0;
  if (stats.pf >= EXPECTANCY_WEIGHT_FULL_PF && stats.expectancy > 0) return 1.0;
  if (stats.pf >= 1.0 && stats.expectancy >= 0) return EXPECTANCY_WEIGHT_REDUCED;
  return EXPECTANCY_WEIGHT_POOR;
}

/** #1: Expectancy-weighted stake allocation.
 *  Scales stake by rolling expectancy per strategy, per symbol and per session
 *  so losing buckets stop receiving equal capital.  Returns { mult, reasons }. */
function getExpectancyStakeMultiplier(strategyName, symbol, session) {
  const resolved = autoTradeHistory.filter(e => e.result === "WIN" || e.result === "LOSS");
  let mult = 1.0;
  const reasons = [];
  if (strategyName) {
    const m = getExpectancyBucketMultiplier(resolved.filter(e => e.strategyName === strategyName));
    if (m < 1) reasons.push(`strategy ${strategyName} ×${m}`);
    mult *= m;
  }
  if (symbol) {
    const m = getExpectancyBucketMultiplier(resolved.filter(e => e.symbol === symbol));
    if (m < 1) reasons.push(`symbol ${symbol} ×${m}`);
    mult *= m;
  }
  if (session) {
    const m = getExpectancyBucketMultiplier(resolved.filter(e => e.session === session));
    if (m < 1) reasons.push(`session ${session} ×${m}`);
    mult *= m;
  }
  return { mult: Math.max(EXPECTANCY_WEIGHT_FLOOR, mult), reasons };
}

/** #2: Weighted confluence scoring — each factor contributes its learned
 *  win-rate edge (Feature 13 stats) instead of a flat +1, then setups are
 *  tiered for sizing: A → 1.0×, B → 0.5×, C → skip.  Signals without enough
 *  rated factors default to tier A so early trading is never blocked. */
function getWeightedConfluenceTier(factors) {
  const rated = [];
  for (const f of (factors || [])) {
    const stats = confluenceFactorStats[f];
    if (!stats) continue;
    const total = stats.wins + stats.losses;
    if (total < CONF_WEIGHT_MIN_SAMPLES) continue;
    rated.push(stats.wins / total);
  }
  if (rated.length < CONF_ADAPTIVE_MIN_RATED) {
    return { tier: "A", sizeMult: 1.0, score: null, ratedCount: rated.length };
  }
  const score = rated.reduce((s, w) => s + w, 0) / rated.length;
  if (score >= CONF_TIER_A_MIN) return { tier: "A", sizeMult: 1.0, score, ratedCount: rated.length };
  if (score >= CONF_TIER_B_MIN) return { tier: "B", sizeMult: CONF_TIER_B_SIZE, score, ratedCount: rated.length };
  return { tier: "C", sizeMult: 0, score, ratedCount: rated.length };
}

/** Extract fiat currency codes from a Deriv/MT5 forex symbol (e.g. frxEURUSD →
 *  ["EUR","USD"]).  Returns [] for synthetics so they are never grouped. */
function getFiatCurrencies(symbol) {
  const m = /^frx([A-Z]{3})([A-Z]{3})$/.exec(symbol || "");
  return m ? [m[1], m[2]] : [];
}

function _activeTradeDir(contractType) {
  if (contractType === "MULTUP") return "BULL";
  if (contractType === "MULTDOWN") return "BEAR";
  if (typeof contractType === "string" && contractType.startsWith("BUY")) return "BULL";
  if (typeof contractType === "string" && contractType.startsWith("SELL")) return "BEAR";
  return null;
}

/** #6: Correlation / basket exposure control.  Computes signed per-currency
 *  exposure across all open trades (long base = +1, short quote = −1 per
 *  trade) and blocks a new fiat trade that would push any single currency's
 *  net exposure past MAX_CORRELATED_CURRENCY_EXPOSURE — preventing several
 *  trades that are effectively the same macro bet. */
function checkCorrelatedExposure(symbol, dir) {
  const [base, quote] = getFiatCurrencies(symbol);
  if (!base) return { ok: true };  /* synthetics: no correlation grouping */
  const exposure = {};
  const bump = (ccy, delta) => { exposure[ccy] = (exposure[ccy] || 0) + delta; };
  for (const [sym, slot] of autoTradeSlots.entries()) {
    const [b, q] = getFiatCurrencies(sym);
    if (!b) continue;
    for (const t of slot.activeTrades) {
      const d = _activeTradeDir(t.contractType);
      if (!d) continue;
      bump(b, d === "BULL" ? 1 : -1);
      bump(q, d === "BULL" ? -1 : 1);
    }
  }
  bump(base, dir === "BULL" ? 1 : -1);
  bump(quote, dir === "BULL" ? -1 : 1);
  for (const [ccy, net] of Object.entries(exposure)) {
    if (Math.abs(net) > MAX_CORRELATED_CURRENCY_EXPOSURE) {
      return { ok: false, reason: `correlated ${ccy} exposure would reach ${net > 0 ? "+" : ""}${net} (cap ±${MAX_CORRELATED_CURRENCY_EXPOSURE})` };
    }
  }
  return { ok: true };
}

/** #5: Stats-calibrated time stop.  Winners resolve fast — measure the median
 *  time-to-resolution of winning trades and cut open contracts exceeding
 *  median × ADAPTIVE_TIME_STOP_MULT (stale trades skew to losers).
 *  Returns null until enough winners exist to calibrate. */
function getAdaptiveTimeStopMs() {
  const durations = autoTradeHistory
    .filter(e => e.result === "WIN" && Number.isFinite(e.resolvedAt) && Number.isFinite(e.time) && e.resolvedAt > e.time)
    .map(e => e.resolvedAt - e.time)
    .sort((a, b) => a - b);
  if (durations.length < ADAPTIVE_TIME_STOP_MIN_WINNERS) return null;
  const median = durations[Math.floor(durations.length / 2)];
  return Math.min(ADAPTIVE_TIME_STOP_MAX_MS, Math.max(ADAPTIVE_TIME_STOP_MIN_MS, median * ADAPTIVE_TIME_STOP_MULT));
}

/** #5: Adaptive multi-R exit ladder.  Weak learned expectancy (in R) → exit
 *  fully by 1.5R; strong expectancy → let the default 3R ladder run. */
function getAdaptiveMultiRLadder() {
  const stats = getTradeAnalytics(autoTradeHistory);
  if (stats.rSamples >= EXPECTANCY_WEIGHT_MIN_SAMPLES && stats.expectancyR != null && stats.expectancyR <= 0) {
    return [ { r: 1.0, pct: 50 }, { r: 1.5, pct: 50 } ];
  }
  return multiRLadder;
}

/** #7: Shadow-result exploitation.  Flags strategy|session buckets where the
 *  shadow (opposite direction) consistently outperforms the actual results —
 *  candidates for inverting or disabling that bucket. */
function getShadowOutperformingBuckets() {
  const buckets = {};
  for (const e of autoTradeHistory) {
    if (e.result !== "WIN" && e.result !== "LOSS") continue;
    const key = `${e.strategyName || e.source || "breakout"}|${e.session || "?"}`;
    if (!buckets[key]) buckets[key] = { n: 0, wins: 0, shadowWins: 0 };
    const b = buckets[key];
    b.n++;
    if (e.result === "WIN") b.wins++;
    if (e.shadowResult === "WIN") b.shadowWins++;
  }
  const flagged = [];
  for (const [key, b] of Object.entries(buckets)) {
    if (b.n < SHADOW_BUCKET_MIN_SAMPLES) continue;
    const wr = b.wins / b.n;
    const shadowWr = b.shadowWins / b.n;
    if (shadowWr - wr >= SHADOW_BUCKET_EDGE) {
      flagged.push({ key, samples: b.n, winRate: wr, shadowWinRate: shadowWr });
    }
  }
  return flagged;
}

const _shadowFlaggedBuckets = new Set();
function maybeFlagShadowBuckets() {
  for (const b of getShadowOutperformingBuckets()) {
    if (_shadowFlaggedBuckets.has(b.key)) continue;
    _shadowFlaggedBuckets.add(b.key);
    addLog(`🔮 Shadow edge detected — ${b.key.replace(/\|/g, " / ")}: shadow WR ${(b.shadowWinRate * 100).toFixed(0)}% vs actual ${(b.winRate * 100).toFixed(0)}% over ${b.samples} trades. Consider inverting or disabling this bucket.`);
  }
}


function mt5BridgeHeaders(extra = {}) {
  const h = Object.assign({ "Content-Type": "application/json" }, extra);
  if (typeof ITGuruAuth !== "undefined" && ITGuruAuth.getToken()) {
    h["Authorization"] = "Bearer " + ITGuruAuth.getToken();
  }
  return h;
}

/** Fetch the admin-configured daily loss limit % from the server, overriding
 *  AUTO_TRADE_DAILY_LOSS_CAP_PCT_DEFAULT. Silently keeps the default on any
 *  failure (not logged in, offline, server error) so this never blocks or
 *  breaks auto-trading — it only ever narrows/widens the existing safety cap. */
async function fetchRiskConfig() {
  try {
    if (typeof ITGuruAuth === "undefined" || !ITGuruAuth.isLoggedIn()) return;
    /* Reset the gate before starting this authenticated request — a prior
       logged-out call (or an earlier settled fetch) may have already set
       riskConfigInitialRequestSettled, which would otherwise let trades
       through against the stale/default cap while this refresh (e.g. after
       an in-page login) is still in flight. */
    riskConfigInitialRequestSettled = false;
    const resp = await fetch("/api/mt5/risk_config.php", { headers: mt5BridgeHeaders() });
    const data = await safeJson(resp);
    const pct = Number(data?.dailyLossLimitPct);
    if (resp.ok && data?.ok && Number.isFinite(pct) && pct > 0) {
      AUTO_TRADE_DAILY_LOSS_CAP_PCT = pct;
      addLog(`⚙ Daily loss cap set from admin config: ${fmt(pct, 1)}%`);
    }
  } catch { /* keep default — non-critical background fetch */ }
  finally { riskConfigInitialRequestSettled = true; }
}

function buildMt5BridgePayload(signal, effectiveDir, tradeSl, tradeTp, symbol, stake) {
  const currentPrice = candles.length > 0 ? Number(candles[candles.length - 1]?.close || candles[candles.length - 1]?.c || 0) : null;
  const side = effectiveDir === "BULL" ? "BUY" : "SELL";
  const orderType = (() => {
    if (currentPrice == null || !Number.isFinite(currentPrice) || currentPrice <= 0) {
      return side === "BUY" ? "BUY_MARKET" : "SELL_MARKET";
    }
    if (side === "BUY") {
      if (signal.entry > currentPrice) return "BUY_STOP";
      if (signal.entry < currentPrice) return "BUY_LIMIT";
      return "BUY_MARKET";
    }
    if (signal.entry < currentPrice) return "SELL_STOP";
    if (signal.entry > currentPrice) return "SELL_LIMIT";
    return "SELL_MARKET";
  })();

  const idempotencyKey = [
    symbol,
    side,
    signal.entry != null ? fmtPrice(signal.entry, symbol) : "--",
    tradeSl != null ? fmtPrice(tradeSl, symbol) : "--",
    tradeTp != null ? fmtPrice(tradeTp, symbol) : "--",
    signal.source || "breakout",
    signal.strategyName || "none",
    Math.floor(Date.now() / 1000)
  ].join("|");

  return {
    symbol,
    dir: side,
    entry: signal.entry,
    sl: tradeSl,
    tp: tradeTp,
    currentPrice: (currentPrice != null && Number.isFinite(currentPrice) && currentPrice > 0) ? currentPrice : null,
    lot: stake,
    orderType,
    source: signal.source || "breakout",
    strategyName: signal.strategyName || null,
    idempotencyKey,
    constraints: {
      minStopPoints: mt5MinStopPoints,
      freezePoints: mt5FreezePoints,
      lotStep: mt5LotStep,
      minLot: mt5MinLot,
      maxLot: mt5MaxLot
    }
  };
}

function resolveMt5HistoryResult(status) {
  /* IMPORTANT: a bridge/EA status is NOT a trade outcome.
   * - FILLED only means a position was opened at the broker — real profit/loss
   *   is unknown until the position actually closes (TP/SL/manual), which this
   *   bridge has no callback for. Scoring it "WIN" was fabricating profit.
   * - REJECTED/CANCELLED/EXPIRED mean the order NEVER reached (or was never
   *   accepted by) the broker — zero account impact. Scoring these "LOSS" was
   *   counting EA-side validation/risk rejections (duplicate guard, max
   *   trades/exposure, spread, stale signal, hedging block, daily-loss halt,
   *   broker reject, etc.) as real trading losses, which incorrectly drove
   *   autoTradeLossCount past AUTO_TRADE_MAX_LOSSES and halted all future
   *   auto-trading (and locked the symbol cooldown) even though no MT5 trade
   *   was ever executed. See ITGuruMt5Bridge.mq5 SIGNAL_REJECTED/
   *   VALIDATION_FAIL/RISK_REJECT/ORDER_REJECTED log events for the real
   *   per-signal rejection reason. */
  if (status === "FILLED") return "OPEN";
  if (status === "REJECTED" || status === "CANCELLED" || status === "EXPIRED") return "CANCELLED";
  return "PENDING";
}

function submitMt5BridgeTrade({
  signal, effectiveDir, tradeSl, tradeTp, symbol, slot, regime, stake, contractType, label
}) {
  if (!mt5SignalApiUrl) {
    addLog("⚠ MT5 bridge skipped — Signal API URL is empty");
    return;
  }
  if (typeof ITGuruAuth === "undefined" || !ITGuruAuth.isLoggedIn()) {
    addLog("⚠ MT5 bridge skipped — please log in first");
    return;
  }

  /* Guard against dispatching a broker order with missing/invalid SL or TP,
     or stops on the wrong side of entry for the trade direction actually
     being sent (effectiveDir, after opposite-mode swaps). Catching this here
     — before a request is ever built/sent — avoids relying on the server's
     422 rejection (which still means "signal fired but no order was placed
     with SL/TP", the exact failure mode this bridge must prevent). */
  const entryNum = Number(signal.entry);
  const slNum = Number(tradeSl);
  const tpNum = Number(tradeTp);
  if (!Number.isFinite(entryNum) || entryNum <= 0 ||
      !Number.isFinite(slNum) || slNum <= 0 ||
      !Number.isFinite(tpNum) || tpNum <= 0) {
    addLog(`⚠ MT5 bridge skipped — ${label} signal is missing a valid entry/SL/TP (entry=${signal.entry}, sl=${tradeSl}, tp=${tradeTp})`);
    return;
  }
  const slOk = effectiveDir === "BULL" ? slNum < entryNum : slNum > entryNum;
  const tpOk = effectiveDir === "BULL" ? tpNum > entryNum : tpNum < entryNum;
  if (!slOk || !tpOk) {
    addLog(`⚠ MT5 bridge skipped — ${label} SL/TP on wrong side of entry for ${effectiveDir} (entry=${entryNum}, sl=${slNum}, tp=${tpNum})`);
    return;
  }

  const payload = buildMt5BridgePayload(signal, effectiveDir, tradeSl, tradeTp, symbol, stake);
  const headers = mt5BridgeHeaders({ "X-Idempotency-Key": payload.idempotencyKey });
  const oppositeTag = (effectiveDir !== signal.dir) ? " [OPPOSITE]" : "";
  addLog(`🤖 ${label} MT5 bridge: ${payload.orderType} ${symbol} lot ${fmt(payload.lot, 2)}${oppositeTag}` + (maxConcurrentTrades > 1 ? ` [${slot.activeTrades.length + 1}/${maxConcurrentTrades}]` : ""));

  fetch(mt5SignalApiUrl, {
    method: "POST",
    headers,
    body: JSON.stringify(payload)
  }).then(async (resp) => {
    const data = await safeJson(resp);
    if (!resp.ok || !data?.ok || !data?.order?.orderId) {
      throw new Error(data?.error || `HTTP ${resp.status}`);
    }
    const order = data.order;
    const tradeId = String(order.orderId);
    if (!slot.activeTrades.some(t => t.tradeId === tradeId)) {
      slot.activeTrades.push({ tradeId, contractId: null, startTime: Date.now(), pendingTimer: null, contractType });
      slot.inProgress = true;
      addAutoTradeHistoryEntry({
        source: signal.source,
        strategyName: signal.strategyName,
        type: payload.orderType,
        symbol,
        tradeId,
        profit: null,
        result: "PENDING",
        originalDir: signal.dir,
        tradedDir: effectiveDir,
        isOpposite: effectiveDir !== signal.dir,
        regime,
        session: getActiveSessionName(),
        timeframeSec: getCurrentGranularitySec(),
        realismCost: 0
      });
    }
    recordTradeFrequency(symbol, signal.strategyName || null);
    addLog(`✅ MT5 bridge queued ${tradeId} (${order.status || "QUEUED"})`);
    mt5LastStatusSyncTs = 0;
  }).catch((err) => {
    addLog(`⚠ MT5 bridge submit failed: ${err.message || err}`);
  });
}

async function pollMt5BridgeStatus() {
  if (autoTradeExecutionMode !== "mt5" || !mt5StatusPollingEnabled || !mt5StatusApiUrl) return;
  if (typeof ITGuruAuth === "undefined" || !ITGuruAuth.isLoggedIn()) return;

  const url = `${mt5StatusApiUrl}${mt5StatusApiUrl.includes("?") ? "&" : "?"}since=${encodeURIComponent(mt5LastStatusSyncTs)}&limit=100`;
  try {
    const resp = await fetch(url, { headers: mt5BridgeHeaders() });
    const data = await safeJson(resp);
    if (!resp.ok || !data?.ok || !Array.isArray(data.orders)) return;
    const serverTime = Number(data.serverTime || 0);
    if (Number.isFinite(serverTime) && serverTime > mt5LastStatusSyncTs) {
      mt5LastStatusSyncTs = serverTime;
    }

    for (const o of data.orders) {
      const tradeId = String(o.orderId || "");
      const status = String(o.status || "").toUpperCase();
      const symbol = String(o.symbol || getActiveSymbol());
      if (!tradeId || !status) continue;

      if (MT5_FINAL_STATUSES.has(status)) {
        removeActiveTrade(symbol, tradeId);
        const result = resolveMt5HistoryResult(status);
        resolveAutoTradeHistoryEntry(0, result, symbol, tradeId);
        logSignalEngineDebug("MT5_STATUS_RESOLVED", {
          signalId: tradeId, symbol, brokerStatus: status, scoredResult: result,
          brokerTicket: o.brokerTicket || null, message: o.message || null
        });
      }
      if (status === "REJECTED" || status === "CANCELLED") {
        const msg = o.message ? ` — ${o.message}` : "";
        /* status/order_status.php surfaces the exact EA-side rejection reason
         * (validation failure, risk-check reject, broker retcode, etc. — see
         * ITGuruMt5Bridge.mq5 VALIDATION_FAIL/RISK_REJECT/ORDER_REJECTED log
         * events). No order reached/was accepted by the broker, so this is
         * NOT scored as a trading loss (see resolveMt5HistoryResult). */
        addLog(`⚠ MT5 ${status} ${tradeId}${msg} (no broker execution — not counted as a loss)`);
      } else if (status === "FILLED") {
        addLog(`✅ MT5 filled ${tradeId}${o.brokerTicket ? ` (ticket ${o.brokerTicket})` : ""} — position open, outcome pending until close`);
      } else if (status === "EXPIRED") {
        addLog(`⏱ MT5 ${status} ${tradeId}${o.message ? ` — ${o.message}` : ""} (no broker execution — not counted as a loss)`);
      }
    }
  } catch { /* silent background poll */ }
}

function getTradeAnalytics(entries) {
  const resolved = (entries || []).filter(e => e && (e.result === "WIN" || e.result === "LOSS") && typeof e.profit === "number");
  if (resolved.length === 0) return { samples: 0, pf: 0, expectancy: 0, maxDrawdown: 0, rSamples: 0, avgR: null, expectancyR: null };
  let wins = 0, losses = 0, totalWin = 0, totalLoss = 0;
  let eq = 0, peak = 0, maxDrawdown = 0;
  let rSamples = 0, rSum = 0;
  for (const e of resolved) {
    eq += e.profit;
    if (eq > peak) peak = eq;
    maxDrawdown = Math.max(maxDrawdown, peak - eq);
    if (e.profit > 0) { wins++; totalWin += e.profit; }
    else { losses++; totalLoss += Math.abs(e.profit); }
    if (Number.isFinite(e.rMultiple)) { rSamples++; rSum += e.rMultiple; }
  }
  const pf = totalLoss > 0 ? totalWin / totalLoss : (totalWin > 0 ? Infinity : 0);
  const avgWin = wins > 0 ? totalWin / wins : 0;
  const avgLoss = losses > 0 ? totalLoss / losses : 0;
  const winRate = resolved.length > 0 ? wins / resolved.length : 0;
  const expectancy = winRate * avgWin - (1 - winRate) * avgLoss;
  /* R-multiple based expectancy — the true optimization target: a 45% WR at
     +2.1R average beats a 60% WR at +0.8R.  avgR is the mean realized
     R-multiple across trades that recorded their initial risk. */
  const avgR = rSamples > 0 ? rSum / rSamples : null;
  return { samples: resolved.length, pf, expectancy, maxDrawdown, rSamples, avgR, expectancyR: avgR };
}

function updateStrategyRegimeStats(entry) {
  if (!entry || !entry.strategyName || (entry.result !== "WIN" && entry.result !== "LOSS")) return;
  const regime = entry.regime || "TRANSITIONING";
  const key = `${entry.strategyName}|${regime}`;
  if (!strategyRegimeStats[key]) strategyRegimeStats[key] = { wins: 0, losses: 0, totalWin: 0, totalLoss: 0, samples: 0 };
  const s = strategyRegimeStats[key];
  s.samples++;
  if (entry.result === "WIN") { s.wins++; s.totalWin += Math.max(0, entry.profit || 0); }
  else { s.losses++; s.totalLoss += Math.abs(entry.profit || 0); }
  const pf = s.totalLoss > 0 ? s.totalWin / s.totalLoss : (s.totalWin > 0 ? Infinity : 0);
  const avgWin = s.wins > 0 ? s.totalWin / s.wins : 0;
  const avgLoss = s.losses > 0 ? s.totalLoss / s.losses : 0;
  const winRate = s.samples > 0 ? s.wins / s.samples : 0;
  const expectancy = winRate * avgWin - (1 - winRate) * avgLoss;
  if (s.samples >= AUTO_TRADE_STRATEGY_DEMOTE_MIN_SAMPLES && (pf < 0.9 || expectancy < 0)) {
    strategyRegimePausedUntil[key] = Date.now() + AUTO_TRADE_STRATEGY_DEMOTE_PAUSE_MS;
    addLog(`🧯 Strategy auto-pause: ${entry.strategyName} in ${regime} (PF ${fmt(pf,2)}, E ${fmt(expectancy,2)})`);
  }
}

function rebuildWalkForwardProfilesFromHistory() {
  const pools = [
    getAggregatedSignalHistory(),
    getAggregatedScalpHistory(),
    getAggregatedStrategyHistory().map(s => {
      if (!s || typeof s !== "object") return s;
      const next = Object.assign({}, s);
      delete next._stratLabel;
      return next;
    })
  ];
  const all = [];
  for (const p of pools) {
    for (const s of (p || [])) {
      if (!s || (s.result !== "WIN" && s.result !== "LOSS")) continue;
      all.push(s);
    }
  }
  const grouped = {};
  for (const s of all) {
    const symbol = s.symbol || getActiveSymbol();
    const gran = s.timeframeSec || getCurrentGranularitySec();
    const regime = s.volatilityRegime || "TRANSITIONING";
    const key = `${symbol}|${gran}|${regime}`;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(s);
  }
  const nextProfiles = {};
  for (const [key, arr] of Object.entries(grouped)) {
    const recent = arr.slice(-WALK_FORWARD_WINDOW_TRADES);
    if (recent.length < WALK_FORWARD_MIN_SAMPLES) continue;
    let bestThreshold = minConfluenceValue;
    let bestExpectancy = -Infinity;
    for (let th = 6; th <= 16; th++) {
      const filtered = recent.filter(s => !Number.isFinite(s.confluenceScore) || s.confluenceScore >= th);
      if (filtered.length < Math.max(6, Math.floor(recent.length * 0.35))) continue;
      const wins = filtered.filter(s => s.result === "WIN").length;
      const losses = filtered.filter(s => s.result === "LOSS").length;
      const total = wins + losses;
      if (total === 0) continue;
      const avgR = filtered.reduce((sum, s) => sum + ((Number.isFinite(s.rr) && s.rr > 0) ? s.rr : 1), 0) / total;
      const wr = wins / total;
      const expectancyR = wr * avgR - (1 - wr);
      if (expectancyR > bestExpectancy) {
        bestExpectancy = expectancyR;
        bestThreshold = th;
      }
    }
    const strong = recent.filter(s => s.breakoutStrength === "STRONG");
    const weak = recent.filter(s => s.breakoutStrength === "WEAK");
    const strongWr = strong.length > 0 ? strong.filter(s => s.result === "WIN").length / strong.length : 0;
    const weakWr = weak.length > 0 ? weak.filter(s => s.result === "WIN").length / weak.length : 0;
    const avgRR = recent.reduce((sum, s) => sum + ((Number.isFinite(s.rr) && s.rr > 0) ? s.rr : 1), 0) / recent.length;
    nextProfiles[key] = {
      requiredConfluence: bestThreshold,
      requireStrongBreakout: (weak.length >= 4 && strongWr > weakWr + 0.08),
      minRR: Math.max(1.5, Math.min(3.5, avgRR)),
      samples: recent.length,
      updatedAt: Date.now()
    };
  }
  walkForwardProfiles = nextProfiles;
}

function executeAutoTrade(signal, _capturedWs) {
  /* Block if session TP/SL has been hit */
  if (autoTradeHalted) {
    addLog("⛔ Auto-trade blocked — session limit hit (reset session to resume)");
    return;
  }

  /* Gate execution until the initial fetchRiskConfig() request settles, so a
   * signal can never fire against the hardcoded AUTO_TRADE_DAILY_LOSS_CAP_PCT_DEFAULT
   * while a stricter admin-configured cap is still in flight. Once the initial
   * request settles (success, failure, or skipped while logged out) this never
   * blocks again — later fetches (e.g. after login) only refine the cap value. */
  if (!riskConfigInitialRequestSettled) {
    addLog("⏳ Auto-trade skipped — waiting for risk config to load");
    return;
  }

  if (!signal || !signal.dir || (signal.dir !== "BULL" && signal.dir !== "BEAR")) {
    addLog("⚠ Auto-trade skipped — invalid signal direction");
    return;
  }

  /* Capture the WS that should carry this trade — in multi-panel mode
     _capturedWs is the panel's own authenticated WS.  In single-panel mode
     route through the dedicated auth channel; the public feed carries market
     data only and must never be used for trade execution. */
  const tradeWs = _capturedWs || authWs;
  if (autoTradeExecutionMode !== "mt5") {
    if (!tradeWs || tradeWs.readyState !== WebSocket.OPEN) {
      addLog("⚠ Auto-trade skipped — auth WebSocket not connected (set Deriv token in Settings)");
      return;
    }
    if (!authorized) {
      addLog("⚠ Auto-trade skipped — not authorized (set Deriv token in Settings)");
      return;
    }
  }

  const symbol = signal.symbol || getActiveSymbol();
  const slot = getAutoTradeSlot(symbol);
  const regime = getCurrentRegimeTag();
  ensureAutoTradeDailyBaseline();
  if (autoTradeDailyStartBalance != null && autoTradeBalance != null && autoTradeDailyStartBalance > 0) {
    const dailyDropPct = (autoTradeDailyStartBalance - autoTradeBalance) / autoTradeDailyStartBalance * 100;
    if (dailyDropPct >= AUTO_TRADE_DAILY_LOSS_CAP_PCT) {
      autoTradeHalted = true;
      addLog(`🛑 Auto-trade blocked — daily loss cap reached (${fmt(dailyDropPct,1)}%).`);
      return;
    }
  }

  const cooldownUntil = symbolCooldownUntil.get(symbol) || 0;
  if (cooldownUntil > Date.now()) {
    const leftSec = Math.ceil((cooldownUntil - Date.now()) / 1000);
    addLog(`⚠ Auto-trade skipped — cooldown active on ${symbol} (${leftSec}s left)`);
    logSignalEngineDebug("SYMBOL_LOCKED", { symbol, reason: "cooldown_after_loss", cooldownUntil, leftSec });
    return;
  } else if (symbolCooldownUntil.has(symbol)) {
    logSignalEngineDebug("SYMBOL_UNLOCKED", { symbol, reason: "cooldown_expired", cooldownUntil });
    symbolCooldownUntil.delete(symbol);
  }

  const freq = canPlaceByFrequency(symbol, signal.strategyName || null);
  if (!freq.ok) {
    addLog(`⚠ Auto-trade skipped — ${freq.reason}`);
    return;
  }

  if (signal.source === "strategy" && signal.strategyName) {
    const allowed = getStrategyAllowedRegimes(signal.strategyName);
    if (!allowed.includes(regime)) {
      addLog(`⚠ Auto-trade skipped — ${signal.strategyName} gated in ${regime} regime`);
      return;
    }
    if (isStrategyTemporarilyPaused(signal.strategyName, regime)) {
      addLog(`⚠ Auto-trade skipped — ${signal.strategyName} temporarily paused in ${regime}`);
      return;
    }
  }

  /* Regime-aware routing for the main breakout pipeline — breakout/momentum
     entries only run in TRENDING/TRANSITIONING regimes (mean-reversion
     strategies keep RANGING via getStrategyAllowedRegimes). */
  if (signal.source === "breakout" && regime === "RANGING") {
    addLog("⚠ Auto-trade skipped — breakout signals are routed out of RANGING regime");
    return;
  }

  /* Allow multiple concurrent trades up to maxConcurrentTrades per symbol */
  const activeCount = slot.activeTrades.length;
  if (activeCount >= maxConcurrentTrades) {
    addLog(`⚠ Auto-trade skipped — max concurrent trades (${maxConcurrentTrades}) reached for ${symbol} (${activeCount} active)`);
    return;
  }

  /* Block if a multiplier fetch is in progress for this symbol */
  if (autoTradeExecutionMode !== "mt5" && slot.fetchingMultiplier) {
    addLog(`⚠ Auto-trade skipped — fetching multiplier data for ${symbol}`);
    return;
  }

  /* Apply opposite mode: reverse direction for scalp / strategy if enabled */
  let effectiveDir = signal.dir;
  if (signal._oppositePreApplied) {
    /* SL/TP and direction already computed for the effective direction by the caller */
  } else if (signal.source === "scalp" && autoTradeScalpOpposite) {
    effectiveDir = signal.dir === "BULL" ? "BEAR" : "BULL";
    addLog(`🔄 Opposite mode (Scalp): reversed ${signal.dir} → ${effectiveDir}`);
  } else if (signal.source === "strategy" && autoTradeStrategyOpposite) {
    effectiveDir = signal.dir === "BULL" ? "BEAR" : "BULL";
    addLog(`🔄 Opposite mode (Strategy): reversed ${signal.dir} → ${effectiveDir}`);
  }

  /* #16: Same-symbol opposing-direction check.
   * Use effectiveDir (after opposite mode) so hedging protection matches
   * the actual direction that would be traded. */
  if (activeCount > 0 && slot.activeTrades.length > 0) {
    const opposingContractType = effectiveDir === "BULL" ? "MULTDOWN" : "MULTUP";
    const hasOpposing = slot.activeTrades.some(t => t.contractType === opposingContractType);
    if (hasOpposing) {
      addLog(`⚠ Auto-trade skipped — opposing ${effectiveDir === "BULL" ? "BEAR" : "BULL"} trade already active on ${symbol}. Close it first to avoid hedging.`);
      return;
    }
  }

  /* When opposite mode flips direction, swap SL and TP so they are on the
     correct side of the entry for the reversed trade direction.
     Skip if caller already computed correct SL/TP (_oppositePreApplied). */
  let tradeSl = signal.sl;
  let tradeTp = signal.tp;
  if (!signal._oppositePreApplied && effectiveDir !== signal.dir && tradeSl != null && tradeTp != null) {
    tradeSl = signal.tp;
    tradeTp = signal.sl;
  }

  /* Dynamic quality gate by market regime + profile */
  if (minConfluenceEnabled && signal.entry != null) {
    const gateIdx = signal.candleIdx != null ? signal.candleIdx : candles.length - 1;
    if (requiredConfluences.length > 0) {
      const confGate = checkConfluenceGate(effectiveDir, signal.entry, gateIdx);
      if (!confGate.pass) {
        addLog(`⚠ Auto-trade skipped — ${confGate.reason}`);
        return;
      }
    } else {
      const dynamicConfMin = getDynamicMinConfluence(symbol, getCurrentGranularitySec(), regime);
      const confScore = computeConfluenceScore(effectiveDir, signal.entry, gateIdx);
      if (confScore < dynamicConfMin) {
        addLog(`⚠ Auto-trade skipped — dynamic confluence ${confScore}/${dynamicConfMin} (${regime})`);
        return;
      }
    }
  }
  if (signal.source === "breakout" && requiresStrongBreakoutNow(symbol, getCurrentGranularitySec(), regime) && !(breakout && breakout.strong)) {
    addLog(`⚠ Auto-trade skipped — weak breakout blocked in ${regime} regime`);
    return;
  }

  const contractType = effectiveDir === "BULL" ? "MULTUP" : "MULTDOWN";
  let stake = Math.max(MIN_AUTO_TRADE_STAKE, autoTradeCurrentStake);
  const label = autoTradeSourceLabel(signal.source, signal.strategyName);

  /* #6: Correlation / basket exposure control across correlated symbols */
  const corr = checkCorrelatedExposure(symbol, effectiveDir);
  if (!corr.ok) {
    addLog(`⚠ Auto-trade skipped — ${corr.reason}`);
    return;
  }

  /* #2: Weighted confluence tier — size stakes on learned factor quality
     (A-setups 1.0×, B-setups 0.5×, C-setups skipped). */
  let sizeMult = 1.0;
  if (adaptiveConfluenceEnabled && signal.entry != null) {
    const tierFactors = signal._confFactors ||
      getActiveConfluenceFactors(effectiveDir, signal.entry, signal.candleIdx != null ? signal.candleIdx : candles.length - 1);
    const tier = getWeightedConfluenceTier(tierFactors);
    if (tier.tier === "C") {
      addLog(`⚠ Auto-trade skipped — C-setup (weighted confluence ${(tier.score * 100).toFixed(0)}% over ${tier.ratedCount} rated factors)`);
      return;
    }
    if (tier.sizeMult < 1) {
      addLog(`📐 ${tier.tier}-setup — stake ×${tier.sizeMult} (weighted confluence ${(tier.score * 100).toFixed(0)}%)`);
    }
    sizeMult *= tier.sizeMult;
  }

  /* #1: Expectancy-weighted allocation per strategy / symbol / session */
  const expWeight = getExpectancyStakeMultiplier(signal.strategyName, symbol, getActiveSessionName());
  if (expWeight.mult < 1) {
    addLog(`📉 Expectancy weighting — stake ×${fmt(expWeight.mult, 2)} (${expWeight.reasons.join(", ")})`);
  }
  sizeMult *= expWeight.mult;
  stake = Math.max(MIN_AUTO_TRADE_STAKE, +(stake * sizeMult).toFixed(2));

  if (autoTradeExecutionMode === "mt5") {
    stake = Math.max(mt5MinLot, Math.min(mt5MaxLot, stake));
    submitMt5BridgeTrade({
      signal,
      effectiveDir,
      tradeSl,
      tradeTp,
      symbol,
      slot,
      regime,
      stake,
      contractType,
      label
    });
    return;
  }

  /* Validate multiplier against known valid values for this symbol.
     Check order: API cache → hardcoded fallback map → if neither exists,
     attempt an async fetch and retry.  This guarantees the multiplier
     is always valid before the proposal is sent. */
  let multiplier = parseInt(autoTradeMultiplier, 10) || DEFAULT_AUTO_TRADE_MULTIPLIER;
  const knownValid = getValidMultipliersForSymbol(symbol);

  if (knownValid && knownValid.length > 0) {
    /* We have valid values — correct the multiplier if needed */
    if (!knownValid.includes(multiplier)) {
      const corrected = pickBestMultiplier(knownValid, multiplier);
      addLog(`⚠ Multiplier ×${multiplier} invalid for ${symbol} — corrected to ×${corrected} (valid: ${knownValid.join(", ")})`);
      multiplier = corrected;
      autoTradeMultiplier = corrected;
      if (UI.autoTradeMultiplier) UI.autoTradeMultiplier.value = corrected;
      saveSettings();
    }
  } else {
    /* No cached or fallback data yet — try fetching from API before trading */
    addLog(`⏳ Fetching valid multipliers for ${symbol} before placing trade…`);
    slot.fetchingMultiplier = true;
    /* Capture the current panel WS now; `ws` may be swapped by activatePanel()
       before the async .then() callback fires (multi-panel race condition). */
    const capturedWs = tradeWs;
    fetchValidMultipliers(symbol).then(apiValid => {
      slot.fetchingMultiplier = false;
      if (!apiValid || apiValid.length === 0) {
        addLog(`⚠ Could not fetch valid multipliers for ${symbol} — skipping trade`);
        return;
      }
      if (!apiValid.includes(multiplier)) {
        const corrected = pickBestMultiplier(apiValid, multiplier);
        autoTradeMultiplier = corrected;
        if (UI.autoTradeMultiplier) UI.autoTradeMultiplier.value = corrected;
        saveSettings();
      }
      /* Re-invoke with the (now-cached) data, forwarding the captured WS so the
         trade still goes through the correct panel connection. */
      executeAutoTrade(signal, capturedWs);
    }).catch(err => {
      slot.fetchingMultiplier = false;
      addLog(`⚠ Failed to fetch multipliers for ${symbol}: ${err.message || err}`);
    });
    return;
  }

  stake = calculateRiskAdjustedStake({ entry: signal.entry, sl: tradeSl, tp: tradeTp }, multiplier);
  /* Re-apply quality/expectancy size multiplier (risk-adjusted stake is
     recomputed from the base risk budget above). */
  stake = Math.max(MIN_AUTO_TRADE_STAKE, +(stake * sizeMult).toFixed(2));
  const realism = evaluateTradeRealism({ entry: signal.entry, sl: tradeSl, tp: tradeTp }, multiplier, stake);
  if (!realism.passed) {
    addLog(`⚠ Auto-trade skipped — realism stress failed (cost $${fmt(realism.cost,2)} too high vs expected reward)`);
    return;
  }

  /* Build limit_order with SL and optional TP (distance from entry in USD).
     Dollar value formula: priceDist × multiplier × stake / entry
     When the raw SL value falls below Deriv's minimum, scale BOTH SL and TP
     proportionally so the strategy's R:R ratio (e.g. 1:2) is preserved. */
  const limitOrder = {};
  if (signal.entry != null && signal.entry > 0) {
    let slVal = null;
    let tpVal = null;
    if (tradeSl != null) {
      const slDist = Math.abs(signal.entry - tradeSl);
      if (slDist > 0) slVal = slDist * multiplier * stake / signal.entry;
    }
    if (tradeTp != null) {
      const tpDist = Math.abs(tradeTp - signal.entry);
      if (tpDist > 0) tpVal = tpDist * multiplier * stake / signal.entry;
    }
    /* If the raw SL dollar value is below Deriv's minimum, scale both SL and TP
       by the same factor to keep the intended R:R ratio intact. */
    if (slVal !== null && slVal < MIN_LIMIT_ORDER_AMOUNT) {
      const scale = MIN_LIMIT_ORDER_AMOUNT / slVal;
      slVal *= scale;
      if (tpVal !== null) tpVal *= scale;
      addLog(`ℹ️ ${tpVal !== null ? "SL/TP" : "SL"} scaled ×${fmt(scale, 2)} to meet $${MIN_LIMIT_ORDER_AMOUNT} minimum (preserving R:R ratio)`);
    }
    if (slVal !== null && isFinite(slVal) && slVal > 0) limitOrder.stop_loss = +fmt(slVal, 2);
    if (tpVal !== null && isFinite(tpVal) && tpVal > 0) limitOrder.take_profit = +fmt(Math.max(tpVal, MIN_LIMIT_ORDER_AMOUNT), 2);
  }

  slot.inProgress = true;
  /* Generate unique trade ID for concurrent trade tracking (counter + timestamp = guaranteed unique) */
  const tradeId = `${symbol}_${Date.now()}_${++_autoTradeIdCounter}`;
  /* #16: store contractType so opposing-direction check can inspect active trades */
  const tradeEntry = { tradeId, contractId: null, startTime: Date.now(), pendingTimer: null, contractType };
  slot.activeTrades.push(tradeEntry);

  const slLog = limitOrder.stop_loss != null ? ` SL $${limitOrder.stop_loss}` : "";
  const tpLog = limitOrder.take_profit != null ? ` TP $${limitOrder.take_profit}` : "";
  const oppositeTag = (effectiveDir !== signal.dir) ? " [OPPOSITE]" : "";
  addLog(`🤖 ${label} auto-trade: ${contractType} on ${symbol} — $${fmt(stake, 2)} ×${multiplier}${slLog}${tpLog}${oppositeTag}` + (maxConcurrentTrades > 1 ? ` [${slot.activeTrades.length}/${maxConcurrentTrades}]` : ""));

  /* Record pending trade in history */
  const isOpposite = (effectiveDir !== signal.dir);
  addAutoTradeHistoryEntry({
    source: signal.source,
    strategyName: signal.strategyName,
    type: contractType,
    symbol,
    tradeId,
    profit: null,
    result: "PENDING",
    originalDir: signal.dir,
    tradedDir: effectiveDir,
    isOpposite,
    regime,
    session: getActiveSessionName(),
    timeframeSec: getCurrentGranularitySec(),
    realismCost: realism.cost || 0,
    /* Initial dollar risk (SL limit-order value) for realized R-multiple tracking */
    riskAmount: limitOrder.stop_loss != null ? limitOrder.stop_loss : (realism.riskDollar || null)
  });

  const payload = {
    proposal: 1,
    amount: stake,
    basis: "stake",
    contract_type: contractType,
    currency: "USD",
    symbol,
    multiplier,
    passthrough: { auto_trade: true, source: signal.source || "breakout", strategyName: signal.strategyName || null, tradeSymbol: symbol, tradeId }
  };
  if (Object.keys(limitOrder).length > 0) payload.limit_order = limitOrder;

  tradeWs.send(JSON.stringify(payload));
  recordTradeFrequency(symbol, signal.strategyName || null);

  /* Start a short safety timeout for the proposal → buy window.
     If the buy doesn't happen within AUTO_TRADE_PROPOSAL_TIMEOUT_MS
     (e.g. the proposal errors out without triggering our error handler,
     or the WS drops silently), this ensures the trade is cleaned up
     instead of staying PENDING forever and blocking all future trades.
     Once the buy succeeds, the buy handler replaces this with the
     longer AUTO_TRADE_PENDING_TIMEOUT_MS via startAutoTradePendingTimeout(). */
  tradeEntry.pendingTimer = setTimeout(() => {
    tradeEntry.pendingTimer = null;
    if (tradeEntry.contractId) return;   /* buy succeeded — longer timeout running */
    addLog(`⚠ [${symbol}] Auto-trade proposal/buy timed out — cleaning up`);
    removeActiveTrade(symbol, tradeId);
    resolveAutoTradeHistoryEntry(0, "CANCELLED", symbol, tradeId);
  }, AUTO_TRADE_PROPOSAL_TIMEOUT_MS);
}

/* ================= AUTO-TRADE HISTORY & BALANCE HELPERS ================= */

/** Clear the pending-trade timeout timer for a specific symbol slot or trade.
 *  @param {string} symbol — the symbol
 *  @param {string} [tradeId] — if provided, only clear the timer for this specific trade */
function clearAutoTradePendingTimeout(symbol, tradeId) {
  if (symbol) {
    const slot = autoTradeSlots.get(symbol);
    if (slot) {
      if (tradeId) {
        /* Clear timer for a specific trade entry */
        const entry = slot.activeTrades.find(t => t.tradeId === tradeId);
        if (entry && entry.pendingTimer) {
          clearTimeout(entry.pendingTimer);
          entry.pendingTimer = null;
        }
      } else if (slot.pendingTimer) {
        clearTimeout(slot.pendingTimer);
        slot.pendingTimer = null;
      }
    }
  }
  /* Legacy global fallback for callers that don't pass symbol */
  if (autoTradePendingTimer) {
    clearTimeout(autoTradePendingTimer);
    autoTradePendingTimer = null;
  }
}

/** Start a timeout that resolves a stuck PENDING trade after AUTO_TRADE_PENDING_TIMEOUT_MS.
 *  If the contract hasn't resolved by then, we attempt a one-shot status query;
 *  if the WS is not available, mark it as CANCELLED.
 *  @param {string} symbol — the symbol whose slot to use
 *  @param {WebSocket} [tradeWs] — the WS connection to use for the status query
 *  @param {string} [tradeId] — if provided, timeout is for a specific concurrent trade */
function startAutoTradePendingTimeout(symbol, tradeWs, tradeId) {
  const slot = getAutoTradeSlot(symbol);
  const wsRef = tradeWs || authWs;
  const tradeEntry = tradeId ? findTradeByTradeId(symbol, tradeId) : null;

  if (tradeEntry) {
    /* Per-trade timeout for concurrent mode */
    if (tradeEntry.pendingTimer) {
      clearTimeout(tradeEntry.pendingTimer);
      tradeEntry.pendingTimer = null;
    }
    tradeEntry.pendingTimer = setTimeout(() => {
      tradeEntry.pendingTimer = null;
      /* Check if this trade is still active */
      if (!slot.activeTrades.includes(tradeEntry)) return;

      /* Try one-shot query before giving up */
      if (wsRef && wsRef.readyState === WebSocket.OPEN && tradeEntry.contractId) {
        addLog(`⏰ [${symbol}] Pending trade timeout — querying contract ${tradeEntry.contractId} status…`);
        wsRef.send(JSON.stringify({
          proposal_open_contract: 1,
          contract_id: tradeEntry.contractId,
          passthrough: { auto_trade: true, source: "timeout_query", tradeSymbol: symbol, tradeId }
        }));
        /* Give the one-shot query 15 seconds to resolve, then force-cancel */
        tradeEntry.pendingTimer = setTimeout(() => {
          tradeEntry.pendingTimer = null;
          if (!slot.activeTrades.includes(tradeEntry)) return;
          addLog(`⚠ [${symbol}] Contract ${tradeEntry.contractId} did not resolve after timeout — marking as cancelled`);
          removeActiveTrade(symbol, tradeId);
          resolveAutoTradeHistoryEntry(0, "CANCELLED", symbol, tradeId);
        }, AUTO_TRADE_QUERY_TIMEOUT_MS);
      } else {
        addLog(`⚠ [${symbol}] Pending trade timeout — no active connection to query contract status, marking as cancelled`);
        removeActiveTrade(symbol, tradeId);
        resolveAutoTradeHistoryEntry(0, "CANCELLED", symbol, tradeId);
      }
    }, AUTO_TRADE_PENDING_TIMEOUT_MS);
  } else {
    /* Legacy single-trade timeout */
    clearAutoTradePendingTimeout(symbol);
    slot.pendingTimer = setTimeout(() => {
      slot.pendingTimer = null;
      if (!slot.inProgress) return; /* already resolved */

      /* Try one-shot query before giving up */
      if (wsRef && wsRef.readyState === WebSocket.OPEN && slot.contractId) {
        addLog(`⏰ [${symbol}] Pending trade timeout — querying contract ${slot.contractId} status…`);
        wsRef.send(JSON.stringify({
          proposal_open_contract: 1,
          contract_id: slot.contractId,
          passthrough: { auto_trade: true, source: "timeout_query", tradeSymbol: symbol }
        }));
        /* Give the one-shot query 15 seconds to resolve, then force-cancel */
        slot.pendingTimer = setTimeout(() => {
          slot.pendingTimer = null;
          if (!slot.inProgress) return;
          addLog(`⚠ [${symbol}] Contract ${slot.contractId} did not resolve after timeout — marking as cancelled`);
          slot.inProgress = false;
          slot.contractId = null;
          slot.pendingContractId = null;
          resolveAutoTradeHistoryEntry(0, "CANCELLED", symbol);
        }, AUTO_TRADE_QUERY_TIMEOUT_MS);
      } else {
        addLog(`⚠ [${symbol}] Pending trade timeout — no active connection to query contract status, marking as cancelled`);
        slot.inProgress = false;
        slot.contractId = null;
        slot.pendingContractId = null;
        resolveAutoTradeHistoryEntry(0, "CANCELLED", symbol);
      }
    }, AUTO_TRADE_PENDING_TIMEOUT_MS);
  }
}

/** Recompute cumulative P/L from actual trade history entries.
 *  This is the source-of-truth — we never rely on an incrementally
 *  accumulated value that can drift due to bugs or interruptions. */
function recalcAutoTradePL() {
  autoTradePL = autoTradeHistory.reduce((sum, e) => {
    if ((e.result === "WIN" || e.result === "LOSS") && typeof e.profit === "number") {
      return sum + e.profit;
    }
    return sum;
  }, 0);
}

/** Add a new entry to the auto-trade history array and re-render. */
function addAutoTradeHistoryEntry({ source, strategyName, type, symbol, tradeId, profit, result, originalDir, tradedDir, isOpposite, regime, session, timeframeSec, realismCost, riskAmount }) {
  const entry = {
    time: Date.now(),
    source: source || "breakout",
    strategyName: strategyName || null,
    type,
    symbol: symbol || "--",
    tradeId: tradeId || null,
    profit: profit != null ? profit : null,
    result: result || "PENDING",
    originalDir: originalDir || null,
    tradedDir: tradedDir || null,
    isOpposite: !!isOpposite,
    regime: regime || getCurrentRegimeTag(),
    session: session || getActiveSessionName(),
    timeframeSec: timeframeSec || getCurrentGranularitySec(),
    realismCost: Number.isFinite(realismCost) ? realismCost : 0,
    /* Initial dollar risk (loss at SL) — enables realized R-multiple tracking */
    riskAmount: (Number.isFinite(riskAmount) && riskAmount > 0) ? riskAmount : null
  };
  autoTradeHistory.unshift(entry);
  /* Cap history to MAX_AUTO_TRADE_HISTORY entries */
  if (autoTradeHistory.length > MAX_AUTO_TRADE_HISTORY) autoTradeHistory.length = MAX_AUTO_TRADE_HISTORY;
  renderAutoTradeHistory();
  persistAutoTradeHistory();
}

/** Resolve the most recent PENDING entry with profit and result.
 *  @param {number} profit
 *  @param {string} result — "WIN" | "LOSS" | "ERROR" | "CANCELLED"
 *  @param {string} [symbol] — if provided, only resolve a PENDING entry for this symbol
 *  @param {string} [tradeId] — if provided, resolve the specific entry with this tradeId */
function resolveAutoTradeHistoryEntry(profit, result, symbol, tradeId) {
  let pending;
  if (tradeId) {
    /* Prefer exact match by tradeId when available — prevents wrong-entry
       resolution in concurrent-trade scenarios where multiple strategies fire
       simultaneously on the same symbol. */
    pending = autoTradeHistory.find(e => e.result === "PENDING" && e.tradeId === tradeId);
  }
  if (!pending) {
    /* Fall back to symbol-based lookup (handles persisted history entries that
       pre-date the tradeId field, and callers that don't supply a tradeId). */
    pending = symbol
      ? autoTradeHistory.find(e => e.result === "PENDING" && e.symbol === symbol)
      : autoTradeHistory.find(e => e.result === "PENDING");
  }
  if (!pending) return;  /* nothing to resolve */
  pending.profit = profit;
  pending.result = result;
  pending.shadowResult = invertResult(result); /* what the opposite direction would have done */
  pending.resolvedAt = Date.now();
  /* Realized R-multiple (profit / initial risk) — profit comes from asymmetry,
     so gates are optimized by expectancy in R rather than by win rate. */
  pending.rMultiple = (Number.isFinite(pending.riskAmount) && pending.riskAmount > 0 &&
                       typeof profit === "number" && (result === "WIN" || result === "LOSS"))
    ? +(profit / pending.riskAmount).toFixed(2)
    : null;
  /* Recompute P/L from all entries (prevents incremental drift) */
  recalcAutoTradePL();

  /* ── Stake management (mirrors bot.js handleResult logic) ── */
  const baseStake = Math.max(MIN_AUTO_TRADE_STAKE, parseFloat(autoTradeStake) || 1);
  if (result === "WIN") {
    autoTradeLossCount = 0;
    autoTradeWinStreak++;
    /* Pyramid up only after consecutive wins (controlled compounding) */
    if (autoTradeWinStreak >= AUTO_TRADE_WIN_STREAK_MIN) {
      const maxStake = (autoTradeMaxStake > 0 && autoTradeMaxStake >= baseStake)
        ? autoTradeMaxStake
        : baseStake * 4;  /* soft cap at 4× base when no explicit max set */
      autoTradeCurrentStake = Math.min(
        +(autoTradeCurrentStake * AUTO_TRADE_STAKE_SCALE).toFixed(2),
        maxStake
      );
      addLog(`📈 Auto-trade stake compounded → $${fmt(autoTradeCurrentStake, 2)} (${autoTradeWinStreak} consecutive wins)`);
    }
  } else if (result === "LOSS") {
    autoTradeWinStreak = 0;
    autoTradeLossCount++;
    autoTradeCurrentStake = baseStake;  /* reset to base stake on every loss */
    addLog(`🔁 Auto-trade stake reset to $${fmt(baseStake, 2)} after loss`);
    if (pending.symbol) {
      const until = Date.now() + AUTO_TRADE_COOLDOWN_AFTER_LOSS_MS;
      symbolCooldownUntil.set(pending.symbol, until);
      addLog(`🔒 ${pending.symbol} cooldown locked after SL (${Math.ceil(AUTO_TRADE_COOLDOWN_AFTER_LOSS_MS / 1000)}s)`);
      logSignalEngineDebug("SYMBOL_LOCKED", { symbol: pending.symbol, reason: "loss", cooldownUntil: until, outcome: result });
    }
    /* Loss cluster protection — pause after N consecutive losses */
    if (autoTradeLossCount >= AUTO_TRADE_MAX_LOSSES) {
      autoTradeHalted = true;
      addLog(`🛑 Auto-trade paused — ${AUTO_TRADE_MAX_LOSSES} consecutive losses reached. Reset session to resume.`);
    }
  }
  if (pending.symbol && (result === "WIN" || result === "CANCELLED" || result === "OPEN")) {
    logSignalEngineDebug("SYMBOL_UNLOCKED", { symbol: pending.symbol, reason: result.toLowerCase(), outcome: result });
  }
  updateAutoTradeCurrentStakeUI();
  updateStrategyRegimeStats(pending);
  const scoped = autoTradeHistory.filter(e =>
    e.strategyName &&
    e.strategyName === pending.strategyName &&
    e.regime === pending.regime &&
    (e.result === "WIN" || e.result === "LOSS")
  );
  const scopedStats = getTradeAnalytics(scoped);
  if (pending.strategyName && scopedStats.samples >= AUTO_TRADE_STRATEGY_DEMOTE_MIN_SAMPLES) {
    const rInfo = scopedStats.expectancyR != null ? ` | E(R) ${fmt(scopedStats.expectancyR,2)}R` : "";
    addLog(`📊 ${pending.strategyName}/${pending.regime}: PF ${scopedStats.pf === Infinity ? "∞" : fmt(scopedStats.pf,2)} | E $${fmt(scopedStats.expectancy,2)}${rInfo} | DD $${fmt(scopedStats.maxDrawdown,2)}`);
  }
  if (pending.rMultiple != null && (result === "WIN" || result === "LOSS")) {
    addLog(`📏 Realized R-multiple: ${pending.rMultiple >= 0 ? "+" : ""}${fmt(pending.rMultiple,2)}R (${pending.symbol})`);
  }

  /* #7: flag strategy/session buckets where the shadow direction outperforms */
  maybeFlagShadowBuckets();

  /* ── Session TP / SL check ── */
  checkAutoTradeSessionLimits();

  renderAutoTradeHistory();
  updateAutoTradePLUI();
  persistAutoTradeHistory();
}

/** Check session-level TP/SL — stop all auto-trading when cumulative P/L hits either limit. */
function checkAutoTradeSessionLimits() {
  if (autoTradeHalted) return;
  ensureAutoTradeDailyBaseline();
  const tp = parseFloat(autoTradeSessionTP) || 0;
  const sl = parseFloat(autoTradeSessionSL) || 0;
  if (tp > 0 && autoTradePL >= tp) {
    autoTradeHalted = true;
    addLog(`✅ Auto-trade Session TP $${fmt(tp, 2)} reached — auto-trading halted. Reset session to resume.`);
  } else if (sl > 0 && autoTradePL <= -sl) {
    autoTradeHalted = true;
    addLog(`🛑 Auto-trade Session SL $${fmt(sl, 2)} reached — auto-trading halted. Reset session to resume.`);
  }
  /* #15: Max-drawdown circuit breaker — halt stake compounding when balance has
   * dropped by AUTO_TRADE_MAX_DRAWDOWN_PCT% from the session-start balance.
   * This is separate from the session SL (which is based on P/L) and acts as a
   * safety net against deep equity drawdowns from a bad run.             */
  if (!autoTradeHalted && sessionStartBalance != null && autoTradeBalance != null) {
    if (sessionStartBalance > 0) {
      const drawdownPct = (sessionStartBalance - autoTradeBalance) / sessionStartBalance * 100;
      if (drawdownPct >= AUTO_TRADE_MAX_DRAWDOWN_PCT) {
        autoTradeHalted = true;
        addLog(`🛑 Auto-trade halted — max drawdown of ${AUTO_TRADE_MAX_DRAWDOWN_PCT}% from session start (${fmt(drawdownPct, 1)}% drop). Reset session to resume.`);
        showToast("⚠️ Drawdown Circuit Breaker",
          `Balance has fallen ${fmt(drawdownPct, 1)}% below session start. Auto-trading paused.`,
          "warning", 8000);
      }
    }
  }

  if (!autoTradeHalted && autoTradeDailyStartBalance != null && autoTradeBalance != null && autoTradeDailyStartBalance > 0) {
    const dailyDropPct = (autoTradeDailyStartBalance - autoTradeBalance) / autoTradeDailyStartBalance * 100;
    if (dailyDropPct >= AUTO_TRADE_DAILY_LOSS_CAP_PCT) {
      autoTradeHalted = true;
      addLog(`🛑 Auto-trade halted — daily loss cap ${AUTO_TRADE_DAILY_LOSS_CAP_PCT}% reached (${fmt(dailyDropPct,1)}% drop today).`);
      showToast("Daily Loss Cap Hit", `Daily drawdown reached ${fmt(dailyDropPct,1)}%. Auto-trading paused.`, "warning", 7000);
    }
  }

  /* Daily profit lock (give-back protection) — once the day reaches
     +AUTO_TRADE_PROFIT_LOCK_TRIGGER_PCT%, stop trading if half of the peak
     gain is given back, so a good day is never turned into a flat/losing one. */
  if (!autoTradeHalted && autoTradeDailyStartBalance != null && autoTradeDailyPeakBalance != null &&
      autoTradeBalance != null && autoTradeDailyStartBalance > 0) {
    const peakGainPct = (autoTradeDailyPeakBalance - autoTradeDailyStartBalance) / autoTradeDailyStartBalance * 100;
    const currentGain = autoTradeBalance - autoTradeDailyStartBalance;
    const peakGain    = autoTradeDailyPeakBalance - autoTradeDailyStartBalance;
    if (peakGainPct >= AUTO_TRADE_PROFIT_LOCK_TRIGGER_PCT && peakGain > 0 &&
        currentGain <= peakGain * (1 - AUTO_TRADE_PROFIT_LOCK_GIVEBACK)) {
      autoTradeHalted = true;
      addLog(`🔒 Auto-trade halted — daily profit lock: peak gain ${fmt(peakGainPct,1)}% and ${Math.round(AUTO_TRADE_PROFIT_LOCK_GIVEBACK*100)}% of it given back. Locking in +$${fmt(Math.max(0,currentGain),2)}. Reset session to resume.`);
      showToast("🔒 Daily Profit Lock", `Half of today's peak gain was given back — auto-trading paused to protect +$${fmt(Math.max(0,currentGain),2)}.`, "warning", 8000);
    }
  }
}

/** Update the live "current stake" display in the auto-trade panel. */
function updateAutoTradeCurrentStakeUI() {
  if (UI.autoTradeCurrentStakeDisplay) {
    UI.autoTradeCurrentStakeDisplay.textContent = `$${fmt(autoTradeCurrentStake, 2)}`;
    UI.autoTradeCurrentStakeDisplay.style.color =
      autoTradeCurrentStake > (parseFloat(autoTradeStake) || 1)
        ? "var(--success)" : "";
  }
}

/** Render the auto-trade history list in the DOM. */
function renderAutoTradeHistory() {
  if (!UI.autoTradeHistoryList || !UI.autoTradeHistoryEmpty) return;
  UI.autoTradeHistoryList.innerHTML = "";
  if (autoTradeHistory.length === 0) {
    UI.autoTradeHistoryEmpty.style.display = "";
    return;
  }
  UI.autoTradeHistoryEmpty.style.display = "none";
  for (const e of autoTradeHistory) {
    const li = document.createElement("li");
    const srcLabel = autoTradeSourceLabel(e.source, e.strategyName);
    const isBull = e.type === "MULTUP";
    const timeStr = new Date(e.time).toLocaleTimeString();

    let profitClass = "pending";
    let profitText = "⏳ Pending";
    if (e.result === "WIN") { profitClass = "win"; profitText = `+$${fmt(e.profit, 2)}`; }
    else if (e.result === "LOSS") { profitClass = "loss"; profitText = `−$${fmt(Math.abs(e.profit), 2)}`; }
    else if (e.result === "ERROR") { profitClass = "error"; profitText = "⚠ Error"; }
    else if (e.result === "CANCELLED") { profitClass = "cancelled"; profitText = "✖ Cancelled"; }

    /* Show opposite mode info: original signal → actual trade */
    let oppositeInfo = "";
    if (e.isOpposite && e.originalDir && e.tradedDir) {
      oppositeInfo = `<span class="at-opposite" title="Original signal: ${e.originalDir}, Traded: ${e.tradedDir}">🔄 ${e.originalDir}→${e.tradedDir}</span>`;
    }

    li.innerHTML =
      `<span class="at-source">${srcLabel}</span>` +
      `<span class="at-type ${isBull ? "bull" : "bear"}">${e.type}</span>` +
      oppositeInfo +
      `<span class="at-profit ${profitClass}">${profitText}</span>` +
      `<span class="at-time">${timeStr}</span>`;
    UI.autoTradeHistoryList.appendChild(li);
  }

  /* Render opposite mode effectiveness summary */
  renderOppositeModeSummary();
}

/**
 * Render opposite mode effectiveness summary.
 * Shows win rate for trades taken with opposite mode vs normal mode.
 */
function renderOppositeModeSummary() {
  const container = document.getElementById("oppositeModeSummary");
  if (!container) return;

  const oppTrades = autoTradeHistory.filter(e => e.isOpposite && (e.result === "WIN" || e.result === "LOSS"));
  const normalTrades = autoTradeHistory.filter(e => !e.isOpposite && (e.result === "WIN" || e.result === "LOSS"));

  if (oppTrades.length === 0 && normalTrades.length === 0) {
    container.innerHTML = "";
    container.style.display = "none";
    return;
  }

  container.style.display = "";

  const oppWins = oppTrades.filter(e => e.result === "WIN").length;
  const oppLosses = oppTrades.filter(e => e.result === "LOSS").length;
  const oppWR = oppTrades.length > 0 ? (oppWins / oppTrades.length * 100).toFixed(1) : "0.0";
  const oppPL = oppTrades.reduce((sum, e) => sum + (e.profit || 0), 0);

  const normWins = normalTrades.filter(e => e.result === "WIN").length;
  const normLosses = normalTrades.filter(e => e.result === "LOSS").length;
  const normWR = normalTrades.length > 0 ? (normWins / normalTrades.length * 100).toFixed(1) : "0.0";
  const normPL = normalTrades.reduce((sum, e) => sum + (e.profit || 0), 0);

  let html = `<div class="opposite-summary">`;
  html += `<div class="opposite-summary-title">📊 Signal Accuracy</div>`;
  if (normalTrades.length > 0) {
    html += `<div class="opposite-row"><span class="opp-label">Normal:</span> <span>${normWins}W / ${normLosses}L</span> <span class="opp-wr">${normWR}%</span> <span class="${normPL >= 0 ? 'opp-profit' : 'opp-loss'}">${normPL >= 0 ? '+' : ''}$${fmt(normPL, 2)}</span></div>`;
  }
  if (oppTrades.length > 0) {
    html += `<div class="opposite-row"><span class="opp-label">🔄 Opposite:</span> <span>${oppWins}W / ${oppLosses}L</span> <span class="opp-wr">${oppWR}%</span> <span class="${oppPL >= 0 ? 'opp-profit' : 'opp-loss'}">${oppPL >= 0 ? '+' : ''}$${fmt(oppPL, 2)}</span></div>`;
  }

  /* Shadow row — what the other direction would have done, per resolved trades that have shadowResult set */
  const shadowTrades = autoTradeHistory.filter(e => e.shadowResult === "WIN" || e.shadowResult === "LOSS");
  if (shadowTrades.length > 0) {
    const shadowWins   = shadowTrades.filter(e => e.shadowResult === "WIN").length;
    const shadowLosses = shadowTrades.filter(e => e.shadowResult === "LOSS").length;
    const shadowWR     = (shadowWins / shadowTrades.length * 100).toFixed(1);
    /* Shadow P/L is the inverse of actual P/L for the same trades */
    const shadowPL     = shadowTrades.reduce((sum, e) => sum - (e.profit || 0), 0);
    html += `<div class="opposite-row"><span class="opp-label">🔮 Shadow:</span> <span>${shadowWins}W / ${shadowLosses}L</span> <span class="opp-wr">${shadowWR}%</span> <span class="${shadowPL >= 0 ? 'opp-profit' : 'opp-loss'}" title="What the other direction would've returned">${shadowPL >= 0 ? '+' : ''}$${fmt(shadowPL, 2)}</span></div>`;
  }

  /* Expectancy in R across resolved trades that recorded initial risk */
  const rStats = getTradeAnalytics(autoTradeHistory);
  if (rStats.expectancyR != null) {
    html += `<div class="opposite-row"><span class="opp-label">📏 E(R):</span> <span>${rStats.rSamples} trades</span> <span class="${rStats.expectancyR >= 0 ? 'opp-profit' : 'opp-loss'}" title="Average realized R-multiple (profit / initial risk)">${rStats.expectancyR >= 0 ? '+' : ''}${fmt(rStats.expectancyR, 2)}R</span></div>`;
  }

  /* Buckets where the shadow direction consistently outperforms */
  for (const b of getShadowOutperformingBuckets().slice(0, 3)) {
    html += `<div class="opposite-row"><span class="opp-label">⚠️ ${b.key.replace(/\|/g, " / ")}:</span> <span title="Shadow outperforms — consider inverting or disabling">shadow ${(b.shadowWinRate * 100).toFixed(0)}% vs ${(b.winRate * 100).toFixed(0)}% (${b.samples})</span></div>`;
  }

  html += `</div>`;
  container.innerHTML = html;
}

/** Update the balance display value. */
function updateAutoTradeBalanceUI() {
  if (UI.autoTradeBalanceValue) {
    UI.autoTradeBalanceValue.textContent =
      autoTradeBalance != null ? `$${fmt(autoTradeBalance, 2)}` : "---";
  }
}

/** Update the P/L display value. */
function updateAutoTradePLUI() {
  if (UI.autoTradePLValue) {
    /* Use auto-trade history P/L if any trades have completed; otherwise show
       a live session P/L computed from balance changes so the display updates
       in real-time even before the first auto-trade resolves. */
    const hasCompletedTrades = autoTradeHistory.some(e => e.result === "WIN" || e.result === "LOSS");
    let displayPL = autoTradePL;
    if (!hasCompletedTrades && sessionStartBalance != null && autoTradeBalance != null) {
      displayPL = autoTradeBalance - sessionStartBalance;
    }
    const prefix = displayPL >= 0 ? "+$" : "−$";
    UI.autoTradePLValue.textContent = `${prefix}${fmt(Math.abs(displayPL), 2)}`;
    UI.autoTradePLValue.style.color =
      displayPL > 0 ? "var(--success)" :
      displayPL < 0 ? "var(--danger)" : "";
  }
}

/** Show/hide the balance section.
 *  Visible whenever the user is authorized (so they always see their balance
 *  and live session P/L) OR when any auto-trade toggle is on. */
function updateAutoTradeBalanceVisibility() {
  if (!UI.autoTradeBalanceSection) return;
  const anyEnabled = autoTradeEnabled || autoTradeScalpEnabled || autoTradeStrategyEnabled;
  /* Show balance section whenever authorized OR any auto-trade toggle is on */
  UI.autoTradeBalanceSection.style.display = (authorized || anyEnabled) ? "" : "none";
}

/** Persist auto-trade history to localStorage. */
function persistAutoTradeHistory() {
  try {
    localStorage.setItem(LS_PREFIX + "autoTradeHistory", JSON.stringify(autoTradeHistory));
    localStorage.setItem(LS_PREFIX + "autoTradePL", JSON.stringify(autoTradePL));
  } catch (e) { /* storage not available */ }
}

/** Restore auto-trade history from localStorage. */
function restoreAutoTradeHistory() {
  try {
    const raw = localStorage.getItem(LS_PREFIX + "autoTradeHistory");
    if (raw) {
      const parsed = JSON.parse(raw);
      autoTradeHistory = Array.isArray(parsed) ? parsed : [];
    }

    /* Clean up stale PENDING entries from previous sessions.
       If the page was closed/crashed without a proper WS close, PENDING
       entries may still be lingering. Mark them CANCELLED since the
       contract subscription is lost and we can't track them anymore. */
    let hadStale = false;
    for (const e of autoTradeHistory) {
      if (e.result === "PENDING") {
        e.result = "CANCELLED";
        e.profit = 0;
        hadStale = true;
      }
    }

    /* Always recompute P/L from actual history entries (self-healing).
       The stored autoTradePL value may have drifted due to bugs or
       interrupted sessions — the history entries are the source of truth. */
    recalcAutoTradePL();

    renderAutoTradeHistory();
    updateAutoTradePLUI();

    /* Persist cleaned-up state if we fixed stale entries */
    if (hadStale) persistAutoTradeHistory();
  } catch (e) { /* storage not available */ }
}

function monitorTradeOutcome(candle) {
  if (!monitoringTrade || !trade) return;
  const releasedTrade = trade;
  const tradeSymbol = releasedTrade.symbol || getActiveSymbol();
  const pending = (releasedTrade.signalId
    ? signalHistory.findLast((s) => s && s.result === "PENDING" && s.signalId === releasedTrade.signalId)
    : null) || findPendingTradeSignal(tradeSymbol);
  if (!pending) {
    logSignalEngineDebug("TRADE_RELEASE", {
      signalId: releasedTrade.signalId || null,
      reason: "missing_pending_signal_record",
      symbol: tradeSymbol
    });
    cleanupPendingSignalsForSymbol(tradeSymbol, "breakout_retest", { keepSignalId: releasedTrade.signalId || null });
    monitoringTrade = false;
    trade = null;
    trailingSL = null;
    partialTpHit = false;
    logSignalLifecycleEvent(tradeSymbol, "State Reset Complete", {
      signalId: releasedTrade.signalId || null,
      reason: "missing_pending_signal_record"
    });
    if (phase === "TRADE") setPhase("BREAKOUT");
    return;
  }

  const effectiveSL = trailingSL != null ? trailingSL : trade.sl;
  const currentIdx = candles.length - 1;
  if (trade.outcomeStartIdx != null && currentIdx < trade.outcomeStartIdx) return;
  if (!pending._openedLogged) {
    pending._openedLogged = true;
    logSignalLifecycleEvent(pending.symbol || tradeSymbol, "Trade Opened", {
      signalId: pending.signalId || trade.signalId || null,
      entry: pending.entry != null ? pending.entry : trade.entry,
      strategy: pending.strategyType || pending.type || "breakout_retest"
    });
  }

  /* ---- Partial TP at 1:1 ---- */
  if (partialTpEnabled && !partialTpHit) {
    const risk = Math.abs(trade.entry - trade.sl);
    if (trade.dir === "BULL") {
      const partialLevel = trade.entry + risk; /* 1:1 reward */
      if (candle.high >= partialLevel) {
        partialTpHit = true;
        addLog(`Partial TP hit at 1:1 (${fmt(partialLevel, 4)}) — alert only, trade continues to full TP`);
        pending.partialTpHit = true;
        showToast("🔔 Partial TP Hit", `1:1 reached (${fmt(partialLevel, 4)}) — profits noted, trade continues to full TP`, "trade", 8000);
        sendPartialTpTelegram(pending, partialLevel);
        /* Defer SL/TP check to next candle to avoid dual-resolution on the
           same candle that triggered the partial TP alert. */
        return;
      }
    } else {
      const partialLevel = trade.entry - risk; /* 1:1 reward */
      if (candle.low <= partialLevel) {
        partialTpHit = true;
        addLog(`Partial TP hit at 1:1 (${fmt(partialLevel, 4)}) — alert only, trade continues to full TP`);
        pending.partialTpHit = true;
        showToast("🔔 Partial TP Hit", `1:1 reached (${fmt(partialLevel, 4)}) — profits noted, trade continues to full TP`, "trade", 8000);
        sendPartialTpTelegram(pending, partialLevel);
        /* Defer SL/TP check to next candle — same reasoning as BULL case above. */
        return;
      }
    }
  }

  /* ---- Tesla 3–6–9 Scaling Model ---- */
  if (teslaScalingEnabled) {
    const risk = Math.abs(trade.entry - trade.sl);
    const isBull = trade.dir === "BULL";

    /* Slide SL to breakeven at the plan's configured trigger:
       Conservative = +1R, Aggressive = +2R. */
    if (!teslaBEHit) {
      const beTrigger = teslaScalingPlan === "aggressive"
        ? TESLA_AGGRESSIVE_BE_TRIGGER
        : TESLA_CONSERVATIVE_BE_TRIGGER;
      const beLevel = isBull ? trade.entry + risk * beTrigger : trade.entry - risk * beTrigger;
      const beHit   = isBull ? candle.high >= beLevel : candle.low <= beLevel;
      if (beHit) {
        teslaBEHit = true;
        trade.sl = trade.entry;  /* slide SL to breakeven */
        /* Advance trailing SL to breakeven if it would regress below it */
        if (trailingSL != null) {
          trailingSL = isBull
            ? Math.max(trailingSL, trade.entry)
            : Math.min(trailingSL, trade.entry);
        }
        const beLabel = `+${beTrigger}R (${teslaScalingPlan} BE)`;
        addLog(`⚡ Tesla 3–6–9: SL moved to breakeven @ ${fmtPrice(trade.entry, pending.symbol)} at ${beLabel}`);
        showToast("⚡ Tesla BE", `SL locked at breakeven (${beLabel}) — running to T1 (3R)`, "info", 6000);
        /* Defer SL/TP check to next candle.  The current forming candle's high (BEAR)
           or low (BULL) may still be at entry because the candle opened there before the
           trade moved in our favour.  Checking the SL now would fire an immediate false
           LOSS — wait for the next tick where price data reflects the SL movement. */
        return;
      }
    }

    /* T1 = 3R — first partial exit.
       Returns early to defer SL/TP resolution to the next candle; this prevents
       a simultaneous TP/SL hit on the same candle from overriding the scaling alert. */
    if (!teslaT1Hit) {
      const t1Level = isBull ? trade.entry + risk * TESLA_T1_R : trade.entry - risk * TESLA_T1_R;
      const t1Hit   = isBull ? candle.high >= t1Level : candle.low <= t1Level;
      if (t1Hit) {
        teslaT1Hit = true;
        pending.teslaT1Hit = true;
        const action = teslaScalingPlan === "conservative" ? "Close 50% of position" : "Close 25% of position";
        addLog(`⚡ Tesla 3–6–9: T1 (3R) reached @ ${fmtPrice(t1Level, pending.symbol)} — ${action}`);
        showToast("⚡ Tesla T1 (3R) ✓", `${action} | Next: T2 at ${TESLA_T2_R}R`, "trade", 8000);
        sendTeslaLevelTelegram(pending, "T1 (3R)", t1Level, teslaScalingPlan);
        return;
      }
    }

    /* T2 = 6R — second partial exit */
    if (teslaT1Hit && !teslaT2Hit) {
      const t2Level = isBull ? trade.entry + risk * TESLA_T2_R : trade.entry - risk * TESLA_T2_R;
      const t2Hit   = isBull ? candle.high >= t2Level : candle.low <= t2Level;
      if (t2Hit) {
        teslaT2Hit = true;
        pending.teslaT2Hit = true;
        const action = teslaScalingPlan === "conservative" ? "Close 30% of position" : "Close 35% of position";
        addLog(`⚡ Tesla 3–6–9: T2 (6R) reached @ ${fmtPrice(t2Level, pending.symbol)} — ${action}`);
        showToast("⚡ Tesla T2 (6R) ✓", `${action} | Next: T3 at ${TESLA_T3_R}R`, "trade", 8000);
        sendTeslaLevelTelegram(pending, "T2 (6R)", t2Level, teslaScalingPlan);
        return;
      }
    }

    /* T3 = 9R — final exit */
    if (teslaT1Hit && teslaT2Hit && !teslaT3Hit) {
      const t3Level = isBull ? trade.entry + risk * TESLA_T3_R : trade.entry - risk * TESLA_T3_R;
      const t3Hit   = isBull ? candle.high >= t3Level : candle.low <= t3Level;
      if (t3Hit) {
        teslaT3Hit = true;
        pending.teslaT3Hit = true;
        const action = teslaScalingPlan === "conservative" ? "Close remaining 20% — full exit" : "Close 20% — trail the rest";
        addLog(`⚡ Tesla 3–6–9: T3 (9R) reached @ ${fmtPrice(t3Level, pending.symbol)} — ${action}`);
        showToast("⚡ Tesla T3 (9R) ✓", `${action}`, "trade", 10000);
        sendTeslaLevelTelegram(pending, "T3 (9R)", t3Level, teslaScalingPlan);
        return;
      }
    }
  }

  /* ---- Trailing stop (ATR-based) ---- */
  if (trailingStopEnabled && atrValue > 0) {
    /* Scalping mode uses a tighter trailing stop (from MD: take profit quickly / move SL tighter) */
    const regimeTrailAdj = getCurrentRegimeTag() === "TRENDING" ? 1.15 : (getCurrentRegimeTag() === "RANGING" ? 0.8 : 1.0);
    const trailMult = (trade.scalpingMode) ? SCALP_TRAILING_ATR_MULT : (TRAILING_STOP_ATR_MULT * regimeTrailAdj);
    if (trade.dir === "BULL") {
      const newTrail = candle.high - atrValue * trailMult;
      /* Only activate/advance trail when it strictly improves (is higher than) the effective SL
         AND the new trail is above entry — i.e. only lock in genuine profit.
         This prevents the trailing stop from initialising below entry on wide-SL trades,
         which would cause a premature LOSS exit before price has moved in the trade's favour.
         Until those conditions are met, checkSL falls back to trade.sl. */
      if (newTrail > effectiveSL && newTrail > trade.entry) {
        trailingSL = newTrail;
      }
    } else {
      const newTrail = candle.low + atrValue * trailMult;
      /* Only activate/advance trail when it strictly improves (is lower than) the effective SL
         AND the new trail is below entry — i.e. only lock in genuine profit.
         Without the entry guard, a wide original SL (e.g. 27 pts) combined with a small ATR
         causes the formula candle.low + ATR*mult to satisfy the < effectiveSL gate while still
         sitting above entry, triggering a LOSS on the very next adverse tick even though the
         real SL was never reached (as observed: entry 524.39, trailSL 527.06, SL 551.56). */
      if (newTrail < effectiveSL && newTrail < trade.entry) {
        trailingSL = newTrail;
      }
    }
    pending.trailingSL = trailingSL;
  }

  /* ---- Non-scalp time-stop for stalled trades ---- */
  if (!trade.scalpingMode && trade.entryIdx != null) {
    const candlesSinceEntry = candles.length - 1 - trade.entryIdx;
    if (candlesSinceEntry >= GENERAL_TRADE_STALL_TIMEOUT_CANDLES) {
      const exitPrice = candle.close;
      const inProfit = (trade.dir === "BULL" && exitPrice >= trade.entry) ||
                       (trade.dir === "BEAR" && exitPrice <= trade.entry);
      pending.result = inProfit ? "WIN" : "LOSS";
      pending.exitPrice = exitPrice;
      pending.outcomeCandleIdx = currentIdx;
      if (inProfit) {
        signalWins++;
      } else if (Math.abs(exitPrice - trade.entry) < PRICE_EPSILON) {
        pending._breakeven = true;
        signalBreakevens++;
      } else {
        signalLosses++;
      }
      addLog(`⏱ Time-stop (${GENERAL_TRADE_STALL_TIMEOUT_CANDLES} candles) — exit at ${fmt(exitPrice, 4)} → ${pending.result}`);
      monitoringTrade = false;
      persistSignalHistory();
      updateStatsUI();
      playPhaseAlert(inProfit ? "TRADE" : "RANGE");
      sendTradeOutcomeTelegram(pending);
      return;
    }
  }

  /* ---- Scalping max-candle timeout ---- */
  if (trade.scalpingMode && trade.entryIdx != null) {
    const candlesSinceEntry = candles.length - 1 - trade.entryIdx;
    if (candlesSinceEntry >= SCALP_MAX_CANDLES) {
      /* Time-based exit: close at current price (market close) */
      const exitPrice = candle.close;
      const inProfit = (trade.dir === "BULL" && exitPrice >= trade.entry) ||
                       (trade.dir === "BEAR" && exitPrice <= trade.entry);
      pending.result = inProfit ? "WIN" : "LOSS";
      pending.exitPrice = exitPrice;
      pending.outcomeCandleIdx = currentIdx;
      if (inProfit) {
        signalWins++;
      } else if (Math.abs(exitPrice - trade.entry) < PRICE_EPSILON) {
        pending._breakeven = true;
        signalBreakevens++;
      } else {
        signalLosses++;
      }
      addLog(`⏱ Scalp TIMEOUT (${SCALP_MAX_CANDLES} candles) — exit at ${fmt(exitPrice, 4)} → ${pending.result}`);
      monitoringTrade = false;
      persistSignalHistory();
      updateStatsUI();
      playPhaseAlert(inProfit ? "TRADE" : "RANGE");
      sendTradeOutcomeTelegram(pending);
      return;
    }
  }

  /* ---- Check SL / TP outcome ---- */
  /* Use effectiveSL (initialised at the top of this function, before any trailing-stop
     update) rather than re-reading trailingSL here.  This prevents a trailing-stop
     advance driven by the current candle's high from immediately triggering an SL hit
     on the same candle's low.  The advance takes effect from the next candle onwards,
     eliminating false WIN resolutions that occurred when price barely ticked above
     entry (advancing the trail above entry) and then reversed back through entry on
     the same bar. */
  let resolved = false;

  /* When the SL is at exactly entry (breakeven — set by Tesla BE or a trailing stop
     advanced to entry), use candle.close (current price) rather than candle.high/low
     to determine whether the SL was hit.  A live forming candle's high (BEAR) or low
     (BULL) can be equal to entry for the entire candle period simply because the candle
     opened at entry; treating that as an SL hit would fire a false LOSS while the trade
     is still in profit.  candle.close reflects the actual current price. */
  const atBreakeven = Math.abs(effectiveSL - trade.entry) < PRICE_EPSILON;

  if (trade.dir === "BULL") {
    const slHit = atBreakeven ? candle.close <= effectiveSL : candle.low <= effectiveSL;
    const tpHit = !pureTrailingEnabled && trade.tp != null && candle.high >= trade.tp;
    if (slHit && tpHit) {
      /* Both levels hit in same candle — closer level was hit first */
      pending.result = effectiveSL > trade.entry ? "WIN" : resolveBothHit({ entry: trade.entry, sl: effectiveSL, tp: trade.tp, partialTpHit: partialTpHit === true });
      pending.exitPrice = pending.result === "WIN" ? trade.tp : effectiveSL;
      if (pending.result === "WIN") {
        signalWins++;
      } else if (Math.abs(pending.exitPrice - trade.entry) < PRICE_EPSILON) {
        pending._breakeven = true;
        signalBreakevens++;
      } else {
        signalLosses++;
      }
      resolved = true;
      addLog(`Signal ${pending.result} — both levels hit (${pending.result === "WIN" ? "TP/breakeven" : "SL"} closer)`);
    } else if (slHit) {
      /* SL hit: only count as WIN if stop locked in genuine profit (strictly above entry). */
      if (effectiveSL > trade.entry) {
        pending.result = "WIN";
        pending.exitPrice = effectiveSL;
        signalWins++;
        resolved = true;
        addLog(`Signal WIN — trailing stop hit at ${fmt(effectiveSL, 4)} (above entry, profit locked${partialTpHit ? " after partial TP alert" : ""})`);
      } else {
        pending.result = "LOSS";
        pending.exitPrice = effectiveSL;
        if (Math.abs(effectiveSL - trade.entry) < PRICE_EPSILON) {
          pending._breakeven = true;
          signalBreakevens++;
        } else {
          signalLosses++;
        }
        resolved = true;
        const exitNote = trailingSL != null ? " (trailing)" : "";
        addLog(`Signal ${pending._breakeven ? "BREAKEVEN" : "LOSS"} — price hit SL at ${fmt(effectiveSL, 4)}${exitNote}`);
      }
    } else if (tpHit) {
      pending.result = "WIN";
      pending.exitPrice = trade.tp;
      signalWins++;
      resolved = true;
      addLog(`Signal WIN — price hit TP at ${fmt(trade.tp, 4)}`);
    }
  } else {
    const slHit = atBreakeven ? candle.close >= effectiveSL : candle.high >= effectiveSL;
    const tpHit = !pureTrailingEnabled && trade.tp != null && candle.low <= trade.tp;
    if (slHit && tpHit) {
      pending.result = effectiveSL < trade.entry ? "WIN" : resolveBothHit({ entry: trade.entry, sl: effectiveSL, tp: trade.tp, partialTpHit: partialTpHit === true });
      pending.exitPrice = pending.result === "WIN" ? trade.tp : effectiveSL;
      if (pending.result === "WIN") {
        signalWins++;
      } else if (Math.abs(pending.exitPrice - trade.entry) < PRICE_EPSILON) {
        pending._breakeven = true;
        signalBreakevens++;
      } else {
        signalLosses++;
      }
      resolved = true;
      addLog(`Signal ${pending.result} — both levels hit (${pending.result === "WIN" ? "TP/breakeven" : "SL"} closer)`);
    } else if (slHit) {
      if (effectiveSL < trade.entry) {
        pending.result = "WIN";
        pending.exitPrice = effectiveSL;
        signalWins++;
        resolved = true;
        addLog(`Signal WIN — trailing stop hit at ${fmt(effectiveSL, 4)} (below entry, profit locked${partialTpHit ? " after partial TP alert" : ""})`);
      } else {
        pending.result = "LOSS";
        pending.exitPrice = effectiveSL;
        if (Math.abs(effectiveSL - trade.entry) < PRICE_EPSILON) {
          pending._breakeven = true;
          signalBreakevens++;
        } else {
          signalLosses++;
        }
        resolved = true;
        const exitNote = trailingSL != null ? " (trailing)" : "";
        addLog(`Signal ${pending._breakeven ? "BREAKEVEN" : "LOSS"} — price hit SL at ${fmt(effectiveSL, 4)}${exitNote}`);
      }
    } else if (tpHit) {
      pending.result = "WIN";
      pending.exitPrice = trade.tp;
      signalWins++;
      resolved = true;
      addLog(`Signal WIN — price hit TP at ${fmt(trade.tp, 4)}`);
    }
  }

  if (resolved) {
    pending.outcomeCandleIdx = currentIdx;
    monitoringTrade = false;
    persistSignalHistory();
    updateStatsUI();
    playPhaseAlert(pending.result === "WIN" ? "TRADE" : "RANGE");
    sendTradeOutcomeTelegram(pending);
    logSignalLifecycleEvent(pending.symbol || tradeSymbol, "Trade Closed", {
      signalId: pending.signalId || trade.signalId || null,
      result: pending.result,
      exitPrice: pending.exitPrice != null ? pending.exitPrice : null
    });
    /* Feature 13: record confluence factor outcome for adaptive weighting */
    if (adaptiveConfluenceEnabled && pending._confFactors && !pending._confRecorded) {
      if (recordConfluenceOutcome(pending._confFactors, pending.result, pending.adaptiveScopeKey)) {
        pending._confRecorded = true;
      }
    }
    if (!_historicalProcessing) rebuildWalkForwardProfilesFromHistory();
    logSignalEngineDebug("TRADE_CLOSE", {
      signalId: pending.signalId || trade.signalId || null,
      result: pending.result,
      symbol: pending.symbol || trade.symbol || getActiveSymbol(),
      exitPrice: pending.exitPrice != null ? pending.exitPrice : null
    });
    if (!_historicalProcessing && autoResetEnabled) {
      logSignalEngineDebug("SYMBOL_RELEASE", {
        signalId: pending.signalId || trade.signalId || null,
        reason: "trade_resolved_auto_reset",
        symbol: pending.symbol || trade.symbol || getActiveSymbol()
      });
      resetForNextSetup();
    } else {
      trade = null;
      trailingSL = null;
      partialTpHit = false;
      logSignalLifecycleEvent(pending.symbol || tradeSymbol, "State Reset Complete", {
        signalId: pending.signalId || null,
        reason: "trade_resolved"
      });
    }
    cleanupPendingSignalsForSymbol(pending.symbol || tradeSymbol, "breakout_retest", { keepSignalId: pending.signalId || null });
    const eligibleAfterClose = isSymbolEligibleForNewSignal(pending.symbol || getActiveSymbol(), "breakout_retest");
    logSignalEngineDebug("NEW_SIGNAL_ELIGIBILITY", {
      signalId: pending.signalId || null,
      symbol: pending.symbol || getActiveSymbol(),
      eligible: eligibleAfterClose
    });
  }
}

