      breakerBlockEnabled,
      autoTradeBreakerBlock,
      /* Strategy 17: OTE Golden Pocket */
      oteGoldenPocketEnabled,
      autoTradeOteGoldenPocket,
      /* Strategy 18: ORB */
      orbEnabled,
      autoTradeOrb,
      orbCandleConfirmation,
      /* Strategy 20: CRT + TBS */
      crtTbsEnabled,
      autoTradeCrtTbs,
      _crtStrictTbs,
      /* Feature settings */
      orderblockEnabled,
